function validatePaginationInputs(currentPageNumber, totalPageCount, displayWindowSize) {
  const integerArguments = [currentPageNumber, totalPageCount, displayWindowSize];
  const hasNonInteger = integerArguments.some((argumentValue) => !Number.isInteger(argumentValue));
  if (hasNonInteger) {
    throw new TypeError('pagination arguments must be integers');
  }
  if (totalPageCount < 1) {
    throw new RangeError('total_page_count must be at least 1');
  }
  if (displayWindowSize < 1) {
    throw new RangeError('display_window_size must be at least 1');
  }
  if (currentPageNumber < 1 || currentPageNumber > totalPageCount) {
    throw new RangeError('current_page_number is outside the available pages');
  }
}

function calculatePagination(currentPageNumber, totalPageCount, displayWindowSize) {
  validatePaginationInputs(currentPageNumber, totalPageCount, displayWindowSize);

  const halfWindowOffset = Math.floor(displayWindowSize / 2);
  let firstVisiblePage = currentPageNumber - halfWindowOffset;
  if (firstVisiblePage < 1) {
    firstVisiblePage = 1;
  }

  let lastVisiblePage = firstVisiblePage + displayWindowSize - 1;
  if (lastVisiblePage > totalPageCount) {
    lastVisiblePage = totalPageCount;
  }

  const leftOmittedCount = firstVisiblePage - 1;
  const rightOmittedCount = totalPageCount - lastVisiblePage;
  const hasPreviousPage = firstVisiblePage > 1;
  const hasNextPage = lastVisiblePage < totalPageCount;

  return {
    start: firstVisiblePage,
    end: lastVisiblePage,
    left: leftOmittedCount,
    right: rightOmittedCount,
    prev: hasPreviousPage,
    next: hasNextPage
  };
}

function buildPageLinkLabels(paginationResult, currentPageNumber) {
  const linkLabels = [];
  if (paginationResult.prev) {
    linkLabels.push(`< (${paginationResult.left} hidden)`);
  }
  for (let visiblePageNumber = paginationResult.start; visiblePageNumber <= paginationResult.end; visiblePageNumber += 1) {
    const isCurrentPage = visiblePageNumber === currentPageNumber;
    linkLabels.push(isCurrentPage ? `[${visiblePageNumber}]` : String(visiblePageNumber));
  }
  if (paginationResult.next) {
    linkLabels.push(`(${paginationResult.right} hidden) >`);
  }
  return linkLabels;
}

function main() {
  const requestedPageNumber = 7;
  const gridTotalPages = 20;
  const gridWindowSize = 5;
  const paginationResult = calculatePagination(requestedPageNumber, gridTotalPages, gridWindowSize);
  console.log(paginationResult);
  console.log(buildPageLinkLabels(paginationResult, requestedPageNumber).join(' '));
}

main();

