function simulateBouncingBall(initialDropHeight, bounceRestitutionMultiplier, minimumThresholdHeight) {
  if (bounceRestitutionMultiplier < 0 || bounceRestitutionMultiplier >= 1) {
    return [0, 0, 0];
  }

  let totalDistanceTraveled = 0;
  let currentPeakHeight = initialDropHeight;
  let totalBounceCount = 0;
  const maximumPeakHeight = initialDropHeight;

  while (currentPeakHeight > minimumThresholdHeight) {
    totalDistanceTraveled += currentPeakHeight;
    const newReboundHeight = currentPeakHeight * bounceRestitutionMultiplier;
    totalDistanceTraveled += newReboundHeight;
    currentPeakHeight = newReboundHeight;
    totalBounceCount += 1;
  }

  return [totalDistanceTraveled, totalBounceCount, maximumPeakHeight];
}

function validateSimulationInputs(initialDropHeight, minimumThresholdHeight) {
  if (!Number.isFinite(initialDropHeight) || initialDropHeight <= 0) {
    throw new RangeError('The drop height must be a positive finite number');
  }
  if (!Number.isFinite(minimumThresholdHeight) || minimumThresholdHeight <= 0) {
    throw new RangeError('The threshold height must be a positive finite number');
  }
}

function runBounceSimulation(initialDropHeight, bounceRestitutionMultiplier, minimumThresholdHeight) {
  validateSimulationInputs(initialDropHeight, minimumThresholdHeight);
  return simulateBouncingBall(initialDropHeight, bounceRestitutionMultiplier, minimumThresholdHeight);
}

function formatSimulationReport(simulationResult, bounceRestitutionMultiplier) {
  const [totalDistanceTraveled, totalBounceCount, maximumPeakHeight] = simulationResult;
  if (totalBounceCount === 0) {
    return `No bounces simulated (restitution ${bounceRestitutionMultiplier} rejected or ball at rest).`;
  }
  const roundedDistance = Math.round(totalDistanceTraveled * 1000) / 1000;
  const averageBounceDistance = Math.round((totalDistanceTraveled / totalBounceCount) * 1000) / 1000;
  const reportLines = [
    `Restitution multiplier: ${bounceRestitutionMultiplier}`,
    `Total distance traveled: ${roundedDistance}`,
    `Total bounce count: ${totalBounceCount}`,
    `Maximum peak height: ${maximumPeakHeight}`,
    `Average distance per bounce: ${averageBounceDistance}`
  ];
  return reportLines.join('\n');
}

function mainDriver() {
  const initialDropHeight = 10;
  const bounceRestitutionMultiplier = 0.75;
  const minimumThresholdHeight = 1;

  const simulationResult = runBounceSimulation(
    initialDropHeight,
    bounceRestitutionMultiplier,
    minimumThresholdHeight
  );

  console.log(simulationResult);
  console.log(formatSimulationReport(simulationResult, bounceRestitutionMultiplier));
}

mainDriver();

