function validateRawData(rawDataArray) {
  if (!Array.isArray(rawDataArray) || rawDataArray.length === 0) {
    throw new TypeError('input series must be a non-empty array of numbers');
  }
  rawDataArray.forEach(function (candidateValue, valueIndex) {
    if (typeof candidateValue !== 'number' || !Number.isFinite(candidateValue)) {
      throw new TypeError('value at index ' + valueIndex + ' is not a finite number');
    }
  });
}

function normalizeWindowSize(requestedWindowSize) {
  const truncatedWindowSize = Math.trunc(requestedWindowSize);
  if (!Number.isFinite(truncatedWindowSize) || truncatedWindowSize < 1) {
    throw new RangeError('window size must be a positive integer');
  }
  return truncatedWindowSize % 2 === 0 ? truncatedWindowSize + 1 : truncatedWindowSize;
}

function smoothDataArray(rawDataArray, slidingWindowSize) {
  validateRawData(rawDataArray);
  const effectiveWindowSize = normalizeWindowSize(slidingWindowSize);
  const halfWindowSpan = (effectiveWindowSize - 1) / 2;
  const lastValidIndex = rawDataArray.length - 1;
  const filteredResultArray = [];

  for (let currentIndex = 0; currentIndex <= lastValidIndex; currentIndex += 1) {
    const windowStartIndex = Math.max(0, currentIndex - halfWindowSpan);
    const windowEndIndex = Math.min(lastValidIndex, currentIndex + halfWindowSpan);
    let currentWindowSum = 0;
    for (let scanIndex = windowStartIndex; scanIndex <= windowEndIndex; scanIndex += 1) {
      currentWindowSum += rawDataArray[scanIndex];
    }
    const actualWindowLength = windowEndIndex - windowStartIndex + 1;
    const localAverageValue = currentWindowSum / actualWindowLength;
    filteredResultArray.push(localAverageValue);
  }

  const filteredTotalSum = filteredResultArray.reduce(function (runningSum, smoothedValue) {
    return runningSum + smoothedValue;
  }, 0);
  const overallAverageValue = filteredTotalSum / filteredResultArray.length;

  return [filteredResultArray, overallAverageValue];
}

function formatNumberList(numberList, decimalPlaces) {
  return numberList
    .map(function (numericValue) {
      return numericValue.toFixed(decimalPlaces);
    })
    .join(', ');
}

function buildSmoothingReport(rawDataArray, slidingWindowSize) {
  const [filteredResultArray, overallAverageValue] = smoothDataArray(rawDataArray, slidingWindowSize);
  const reportLines = [
    'input series      : [' + formatNumberList(rawDataArray, 2) + ']',
    'requested window  : ' + slidingWindowSize,
    'effective window  : ' + normalizeWindowSize(slidingWindowSize),
    'smoothed series   : [' + formatNumberList(filteredResultArray, 4) + ']',
    'overall average   : ' + overallAverageValue.toFixed(4)
  ];
  return reportLines.join('\n');
}

function main() {
  const sampleDataArray = [2, 4, 6, 8, 10];
  const sampleWindowSize = 3;
  console.log(buildSmoothingReport(sampleDataArray, sampleWindowSize));
}

main();

