function validateOrderInputs(itemPricesArray, exemptItemsArray, discountPercentageRate, stateTaxRate) {
  if (!Array.isArray(itemPricesArray) || !Array.isArray(exemptItemsArray)) {
    throw new TypeError('Prices and exemption flags must both be arrays.');
  }
  if (itemPricesArray.length !== exemptItemsArray.length) {
    throw new RangeError('Each price needs exactly one exemption flag.');
  }
  itemPricesArray.forEach((singleItemPrice, itemIndex) => {
    if (typeof singleItemPrice !== 'number' || !Number.isFinite(singleItemPrice) || singleItemPrice < 0) {
      throw new RangeError(`Price at index ${itemIndex} is not a valid amount.`);
    }
  });
  if (discountPercentageRate < 0 || discountPercentageRate > 100) {
    throw new RangeError('Discount percentage must fall between 0 and 100.');
  }
  if (stateTaxRate < 0) {
    throw new RangeError('State tax rate cannot be negative.');
  }
}

function computeOrderBill(itemPricesArray, exemptItemsArray, discountPercentageRate, stateTaxRate) {
  validateOrderInputs(itemPricesArray, exemptItemsArray, discountPercentageRate, stateTaxRate);

  let taxExemptSubtotal = 0;
  let taxableSubtotal = 0;

  for (let itemIndex = 0; itemIndex < itemPricesArray.length; itemIndex += 1) {
    const currentItemPrice = itemPricesArray[itemIndex];
    if (exemptItemsArray[itemIndex]) {
      taxExemptSubtotal += currentItemPrice;
    } else {
      taxableSubtotal += currentItemPrice;
    }
  }

  const grossSubtotalAmount = taxExemptSubtotal + taxableSubtotal;
  const remainingFraction = 1 - discountPercentageRate / 100;
  const discountedExemptAmount = taxExemptSubtotal * remainingFraction;
  const discountedTaxableAmount = taxableSubtotal * remainingFraction;
  const applicableTaxAmount = discountedTaxableAmount * (stateTaxRate / 100);
  const finalTotalPrice = discountedExemptAmount + discountedTaxableAmount + applicableTaxAmount;

  return [grossSubtotalAmount, applicableTaxAmount, finalTotalPrice];
}

function formatCurrencyValue(monetaryAmount) {
  return `$${monetaryAmount.toFixed(2)}`;
}

function buildBillReport(orderLabel, billResultArray) {
  const [grossSubtotalAmount, applicableTaxAmount, finalTotalPrice] = billResultArray;
  const reportLines = [
    `Order: ${orderLabel}`,
    `  Subtotal : ${formatCurrencyValue(grossSubtotalAmount)}`,
    `  Tax      : ${formatCurrencyValue(applicableTaxAmount)}`,
    `  Total    : ${formatCurrencyValue(finalTotalPrice)}`
  ];
  return reportLines.join('\n');
}

function runBillingDriver() {
  const groceryPricesArray = [12.5, 4.99, 30.0, 7.25];
  const groceryExemptFlags = [true, false, false, true];
  const groceryBillResult = computeOrderBill(groceryPricesArray, groceryExemptFlags, 10, 6.5);
  console.log(buildBillReport('Weekly groceries', groceryBillResult));

  const hardwarePricesArray = [199.99, 45.0, 15.75];
  const hardwareExemptFlags = [false, false, false];
  const hardwareBillResult = computeOrderBill(hardwarePricesArray, hardwareExemptFlags, 0, 8.25);
  console.log(buildBillReport('Hardware restock', hardwareBillResult));

  try {
    computeOrderBill([10.0, 20.0], [false], 5, 7);
  } catch (validationError) {
    console.log(`Rejected order: ${validationError.message}`);
  }
}

runBillingDriver();

