function validateHourNumber(hourNumber, hourLabel) {
  if (!Number.isInteger(hourNumber) || hourNumber < 0 || hourNumber > 23) {
    throw new RangeError(`${hourLabel} must be an integer hour between 0 and 23`);
  }
  return hourNumber;
}

function validateRateValue(rateValue, rateLabel) {
  if (typeof rateValue !== 'number' || Number.isNaN(rateValue) || rateValue < 0) {
    throw new RangeError(`${rateLabel} must be a non-negative number`);
  }
  return rateValue;
}

function calculateParkingFee(entryHourNumber, exitHourNumber, baseFlatRate, hourlyExtraRate, maximumDailyCap) {
  validateHourNumber(entryHourNumber, 'entry hour');
  validateHourNumber(exitHourNumber, 'exit hour');
  validateRateValue(baseFlatRate, 'flat rate');
  validateRateValue(hourlyExtraRate, 'hourly extra rate');
  validateRateValue(maximumDailyCap, 'daily cap');

  let adjustedExitHour = exitHourNumber;
  if (adjustedExitHour < entryHourNumber) {
    adjustedExitHour += 24;
  }

  let totalParkedHours = adjustedExitHour - entryHourNumber;
  if (totalParkedHours === 0) {
    totalParkedHours = 24;
  }

  let preliminaryTotalFee = baseFlatRate + hourlyExtraRate * totalParkedHours;
  if (totalParkedHours > 12) {
    const extendedStaySurcharge = 10;
    preliminaryTotalFee += extendedStaySurcharge;
  }

  const finalApprovedFee = Math.min(preliminaryTotalFee, maximumDailyCap);
  return finalApprovedFee;
}

function formatHourLabel(hourNumber) {
  const paddedHour = String(hourNumber).padStart(2, '0');
  return `${paddedHour}:00`;
}

function formatCurrencyAmount(amountValue) {
  return `$${amountValue.toFixed(2)}`;
}

function buildParkingReceipt(entryHourNumber, exitHourNumber, baseFlatRate, hourlyExtraRate, maximumDailyCap) {
