function validate_hour_number(hour_number, hour_label) {
  if (!Number.isInteger(hour_number) || hour_number < 0 || hour_number > 23) {
    throw new RangeError(`${hour_label} must be an integer hour between 0 and 23`);
  }
  return hour_number;
}

function validate_rate_value(rate_value, rate_label) {
  if (typeof rate_value !== 'number' || Number.isNaN(rate_value) || rate_value < 0) {
    throw new RangeError(`${rate_label} must be a non-negative number`);
  }
  return rate_value;
}

function calculate_parking_fee(entry_hour_number, exit_hour_number, base_flat_rate, hourly_extra_rate, maximum_daily_cap) {
  validate_hour_number(entry_hour_number, 'entry hour');
  validate_hour_number(exit_hour_number, 'exit hour');
  validate_rate_value(base_flat_rate, 'flat rate');
  validate_rate_value(hourly_extra_rate, 'hourly extra rate');
  validate_rate_value(maximum_daily_cap, 'daily cap');

  let adjusted_exit_hour = exit_hour_number;
  if (adjusted_exit_hour < entry_hour_number) {
    adjusted_exit_hour += 24;
  }

  let total_parked_hours = adjusted_exit_hour - entry_hour_number;
  if (total_parked_hours === 0) {
    total_parked_hours = 24;
  }

  let preliminary_total_fee = base_flat_rate + hourly_extra_rate * total_parked_hours;
  if (total_parked_hours > 12) {
    const extended_stay_surcharge = 10;
    preliminary_total_fee += extended_stay_surcharge;
  }

  const final_approved_fee = Math.min(preliminary_total_fee, maximum_daily_cap);
  return final_approved_fee;
}

