function normalizeExcludedWords(excludedWordsArray) {
  if (!Array.isArray(excludedWordsArray)) {
    return [];
  }
  return excludedWordsArray
    .filter((candidateWord) => typeof candidateWord === 'string')
    .map((candidateWord) => candidateWord.trim().toLowerCase())
    .filter((normalizedWord) => normalizedWord.length > 0);
}

function capitalizeFirstLetter(wordToken) {
  return wordToken.charAt(0).toUpperCase() + wordToken.slice(1);
}

function formatSentenceCase(rawInputSentence, excludedWordsArray) {
  const trimmedInputSentence = String(rawInputSentence).trim();
  if (trimmedInputSentence.length === 0) {
    return '';
  }

  const normalizedExclusions = normalizeExcludedWords(excludedWordsArray);
  const wordTokensArray = trimmedInputSentence.split(/\s+/);
  let capitalizedWordCount = 0;

  for (let currentWordIndex = 0; currentWordIndex < wordTokensArray.length; currentWordIndex += 1) {
    const lowercasedWordVersion = wordTokensArray[currentWordIndex].toLowerCase();
    if (currentWordIndex === 0 || !normalizedExclusions.includes(lowercasedWordVersion)) {
      const capitalizedWordVersion = capitalizeFirstLetter(wordTokensArray[currentWordIndex]);
      capitalizedWordCount += 1;
      wordTokensArray[currentWordIndex] = capitalizedWordVersion;
    }
  }

  const finalFormattedString = wordTokensArray.join(' ');
  if (capitalizedWordCount === 0) {
    return 'NONE';
  }
  return finalFormattedString;
}

function buildFormattingReport(rawInputSentence, excludedWordsArray) {
  const formattedSentenceResult = formatSentenceCase(rawInputSentence, excludedWordsArray);
  const reportLines = [];
  reportLines.push(`input   : "${rawInputSentence}"`);
  reportLines.push(`excluded: ${normalizeExcludedWords(excludedWordsArray).join(', ') || '(none)'}`);
  if (formattedSentenceResult.length === 0) {
    reportLines.push('output  : (empty sentence)');
  } else {
    reportLines.push(`output  : "${formattedSentenceResult}"`);
  }
  return reportLines.join('\n');
}

function runFormattingDriver() {
  const sampleSentenceList = [
    'the quick brown fox jumps over the lazy dog',
    '   a tale of two cities   ',
    '   '
  ];
  const commonExcludedWords = ['the', 'of', 'over', 'a', 'two'];

  sampleSentenceList.forEach((sampleSentence) => {
    console.log(buildFormattingReport(sampleSentence, commonExcludedWords));
    console.log('-'.repeat(40));
  });
}

