function padWithLeadingZero(numericValue) {
  return numericValue < 10 ? '0' + numericValue : String(numericValue);
}

function validateRawSeconds(totalRawSeconds) {
  if (typeof totalRawSeconds !== 'number' || !Number.isFinite(totalRawSeconds)) {
    throw new TypeError('the seconds count must be a finite number');
  }
  if (!Number.isInteger(totalRawSeconds)) {
    throw new RangeError('the seconds count must be a whole number');
  }
  if (totalRawSeconds < 0) {
    throw new RangeError('the seconds count must not be negative');
  }
  return totalRawSeconds;
}

function convertSecondsToClock(totalRawSeconds) {
  const validatedRawSeconds = validateRawSeconds(totalRawSeconds);

  const totalElapsedDays = Math.floor(validatedRawSeconds / 86400);
  const remainingSecondsAfterDays = validatedRawSeconds % 86400;

  const fullElapsedHours = Math.floor(remainingSecondsAfterDays / 3600);
  const remainingSecondsAfterHours = remainingSecondsAfterDays % 3600;

  const fullElapsedMinutes = Math.floor(remainingSecondsAfterHours / 60);
  const finalLeftoverSeconds = remainingSecondsAfterHours % 60;

  const paddedHoursString = padWithLeadingZero(fullElapsedHours);
  const paddedMinutesString = padWithLeadingZero(fullElapsedMinutes);
  const paddedSecondsString = padWithLeadingZero(finalLeftoverSeconds);

  const baseClockString = paddedHoursString + ':' + paddedMinutesString + ':' + paddedSecondsString;

  let finalClockString = baseClockString;
  if (totalElapsedDays > 0) {
    finalClockString = totalElapsedDays + ' days, ' + baseClockString;
  }

  return finalClockString;
}

function parseSecondsArgument(rawArgumentText) {
  const trimmedArgumentText = String(rawArgumentText).trim();
  const parsedSecondsValue = Number(trimmedArgumentText);
  if (trimmedArgumentText === '' || Number.isNaN(parsedSecondsValue)) {
    throw new TypeError('cannot parse "' + rawArgumentText + '" as a seconds count');
  }
  return parsedSecondsValue;
}

function buildClockReport(secondsInputList) {
  return secondsInputList
    .map(function (secondsInputItem) {
      const parsedSecondsValue = parseSecondsArgument(secondsInputItem);
      const renderedClockString = convertSecondsToClock(parsedSecondsValue);
      return parsedSecondsValue + ' -> ' + renderedClockString;
    })
    .join('\n');
}

function runMain() {
  const commandLineSeconds = process.argv.slice(2);
  if (commandLineSeconds.length > 0) {
    console.log(buildClockReport(commandLineSeconds));
    return;
  }
  console.log(convertSecondsToClock(90065));
}

runMain();

