function checkRectangleIntersection(
  firstRectX,
  firstRectY,
  firstRectWidth,
  firstRectHeight,
  secondRectX,
  secondRectY,
  secondRectWidth,
  secondRectHeight
) {
  if (firstRectWidth <= 0 || firstRectHeight <= 0) {
    return 0;
  }
  if (secondRectWidth <= 0 || secondRectHeight <= 0) {
    return 0;
  }

  const firstRightEdge = firstRectX + firstRectWidth;
  const firstBottomEdge = firstRectY + firstRectHeight;
  const secondRightEdge = secondRectX + secondRectWidth;
  const secondBottomEdge = secondRectY + secondRectHeight;

  const hasHorizontalOverlap =
    firstRightEdge > secondRectX && firstRectX < secondRightEdge;
  const hasVerticalOverlap =
    firstBottomEdge > secondRectY && firstRectY < secondBottomEdge;

  if (hasHorizontalOverlap && hasVerticalOverlap) {
    const overlapRegionWidth =
      Math.min(firstRightEdge, secondRightEdge) - Math.max(firstRectX, secondRectX);
    const overlapRegionHeight =
      Math.min(firstBottomEdge, secondBottomEdge) - Math.max(firstRectY, secondRectY);
    const overlapRegionArea = overlapRegionWidth * overlapRegionHeight;
    return overlapRegionArea;
  }

  return 0;
}

function intersectRectangleObjects(firstRectangle, secondRectangle) {
  return checkRectangleIntersection(
    firstRectangle.x,
    firstRectangle.y,
    firstRectangle.width,
    firstRectangle.height,
    secondRectangle.x,
    secondRectangle.y,
    secondRectangle.width,
    secondRectangle.height
  );
}

function formatRectangleLabel(screenRectangle) {
  const rightEdgeValue = screenRectangle.x + screenRectangle.width;
  const bottomEdgeValue = screenRectangle.y + screenRectangle.height;
  return `[(${screenRectangle.x},${screenRectangle.y}) -> (${rightEdgeValue},${bottomEdgeValue})]`;
}

function buildOverlapReport(firstRectangle, secondRectangle) {
  const overlapArea = intersectRectangleObjects(firstRectangle, secondRectangle);
  const firstLabel = formatRectangleLabel(firstRectangle);
  const secondLabel = formatRectangleLabel(secondRectangle);
  const verdictText = overlapArea > 0 ? "overlap" : "no overlap";
  return `${firstLabel} vs ${secondLabel}: ${verdictText}, area = ${overlapArea}`;
}

function runOverlapDemo() {
  const primaryWindowRect = { x: 10, y: 20, width: 120, height: 90 };
  const secondaryWindowRect = { x: 70, y: 50, width: 100, height: 100 };

  console.log(buildOverlapReport(primaryWindowRect, secondaryWindowRect));
}

runOverlapDemo();

