const maximumStackLimit = 20;

function normalizeDenominations(availableDenominationsArray) {
  const validDenominations = availableDenominationsArray.filter(
    (denominationValue) => Number.isInteger(denominationValue) && denominationValue > 0
  );
  return validDenominations.slice().sort((firstValue, secondValue) => secondValue - firstValue);
}

function dispenseAtmCash(requestedWithdrawalAmount, availableDenominationsArray) {
  const sortedDenominations = normalizeDenominations(availableDenominationsArray);
  let remainingWithdrawalBalance = requestedWithdrawalAmount;
  let totalBillsDispensed = 0;
  const dispensedCountsArray = [];

  for (const denominationValue of sortedDenominations) {
    const maximumFittingBills = Math.floor(remainingWithdrawalBalance / denominationValue);
    const cappedBillCount = Math.min(maximumFittingBills, maximumStackLimit);
    const deductedSubtotalValue = denominationValue * cappedBillCount;
    remainingWithdrawalBalance -= deductedSubtotalValue;
    totalBillsDispensed += cappedBillCount;
    dispensedCountsArray.push(cappedBillCount);
  }

  if (remainingWithdrawalBalance !== 0) {
    return [-1];
  }
  return [totalBillsDispensed, ...dispensedCountsArray];
}

function formatDispenseReport(requestedWithdrawalAmount, availableDenominationsArray) {
  const dispenseResult = dispenseAtmCash(requestedWithdrawalAmount, availableDenominationsArray);
  if (dispenseResult[0] === -1) {
    return `${requestedWithdrawalAmount}: cannot be dispensed -> [-1]`;
  }

  const sortedDenominations = normalizeDenominations(availableDenominationsArray);
  const perDenominationCounts = dispenseResult.slice(1);
  const breakdownParts = [];
  perDenominationCounts.forEach((billCount, denominationIndex) => {
    if (billCount > 0) {
      breakdownParts.push(`${billCount} x ${sortedDenominations[denominationIndex]}`);
    }
  });

  const billsHeadline = `${dispenseResult[0]} bills`;
  return `${requestedWithdrawalAmount}: ${billsHeadline} (${breakdownParts.join(', ')}) -> [${dispenseResult.join(', ')}]`;
}

function runAtmSimulation() {
  const standardDenominations = [100, 50, 20, 10, 5, 1];
  const largeBillOnlyMachine = [500, 100];
  const withdrawalTestAmounts = [1287, 40, 3, 0, 9999];

  withdrawalTestAmounts.forEach((requestedWithdrawalAmount) => {
    console.log(formatDispenseReport(requestedWithdrawalAmount, standardDenominations));
  });

  const awkwardRequestAmount = 250;
  console.log(formatDispenseReport(awkwardRequestAmount, largeBillOnlyMachine));

  const unsortedDenominations = [20, 1, 100, 5];
  console.log(formatDispenseReport(186, unsortedDenominations));

  const rawResultArray = dispenseAtmCash(1287, standardDenominations);
  console.log(`raw return value: [${rawResultArray.join(', ')}]`);
}

