const invalidVotesArray = ['NONE', 'VOID'];

function tallyElectionVotes(castVotesArray) {
  let totalRejectedVotes = 0;
  let highestVoteCount = 0;
  let leadingCandidateName = null;
  const voteTallyMap = {};

  for (let voteIndex = 0; voteIndex < castVotesArray.length; voteIndex += 1) {
    const currentCandidateName = castVotesArray[voteIndex];

    if (invalidVotesArray.includes(currentCandidateName)) {
      totalRejectedVotes += 1;
      continue;
    }

    voteTallyMap[currentCandidateName] = (voteTallyMap[currentCandidateName] || 0) + 1;
    const updatedCandidateScore = voteTallyMap[currentCandidateName];

    if (updatedCandidateScore > highestVoteCount) {
      highestVoteCount = updatedCandidateScore;
      leadingCandidateName = currentCandidateName;
    }
  }

  return [leadingCandidateName, highestVoteCount, totalRejectedVotes];
}

function normaliseCastVotes(rawBallotStrings) {
  return rawBallotStrings
    .map((rawBallotString) => rawBallotString.trim().toUpperCase())
    .filter((trimmedBallotString) => trimmedBallotString.length > 0);
}

function formatElectionReport(tallyResultArray, totalBallotsReceived) {
  const [winningCandidateName, winningVoteCount, rejectedBallotCount] = tallyResultArray;
  const acceptedBallotCount = totalBallotsReceived - rejectedBallotCount;
  const reportLines = [];

  if (winningCandidateName === null) {
    reportLines.push('No valid votes were cast.');
