    reportLines.push(`Votes for leader: ${winningVoteCount}`);
    reportLines.push(`Share of valid votes: ${winnerSharePercent.toFixed(1)}%`);
  }

  reportLines.push(`Valid ballots: ${acceptedBallotCount}`);
  reportLines.push(`Rejected ballots: ${rejectedBallotCount}`);
