function validateLoanInputs(principalLoanAmount, annualInterestRate, loanTermYears) {
  if (!Number.isFinite(principalLoanAmount) || principalLoanAmount <= 0) {
    throw new RangeError('principal loan amount must be a positive number');
  }
  if (!Number.isFinite(annualInterestRate) || annualInterestRate <= 0) {
    throw new RangeError('annual interest rate must be a positive decimal fraction');
  }
  if (!Number.isFinite(loanTermYears) || loanTermYears <= 0) {
    throw new RangeError('loan term years must be a positive number');
  }
}

function roundToCents(rawAmount) {
  return Math.round(rawAmount * 100) / 100;
}

function formatCurrencyAmount(rawAmount) {
  return '$' + roundToCents(rawAmount).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function calculateMortgagePayment(principalLoanAmount, annualInterestRate, loanTermYears) {
  validateLoanInputs(principalLoanAmount, annualInterestRate, loanTermYears);
  const monthlyInterestRate = annualInterestRate / 12;
  const totalPaymentPeriods = loanTermYears * 12;
  const compoundingMultiplierFactor = (1 + monthlyInterestRate) ** totalPaymentPeriods;
  const baseMonthlyPayment =
    (principalLoanAmount * monthlyInterestRate * compoundingMultiplierFactor) /
    (compoundingMultiplierFactor - 1);
  const formattedMonthlyPayment = baseMonthlyPayment.toFixed(2);
  const totalLifetimeInterest = baseMonthlyPayment * totalPaymentPeriods - principalLoanAmount;
  return {
    payment: formattedMonthlyPayment,
    interest: roundToCents(totalLifetimeInterest)
  };
}

function calculateRemainingBalance(principalLoanAmount, monthlyInterestRate, monthlyPaymentAmount, paymentsCompleted) {
  const balanceGrowthFactor = (1 + monthlyInterestRate) ** paymentsCompleted;
  const paidDownAmount = (monthlyPaymentAmount * (balanceGrowthFactor - 1)) / monthlyInterestRate;
  return Math.max(principalLoanAmount * balanceGrowthFactor - paidDownAmount, 0);
}

function buildMilestoneYearList(loanTermYears) {
  const candidateMilestones = [1, 5, 10, 20, 30];
  return candidateMilestones.filter(milestoneYear => milestoneYear <= loanTermYears);
}

function printMortgageSummary(principalLoanAmount, annualInterestRate, loanTermYears) {
  const mortgageDetails = calculateMortgagePayment(principalLoanAmount, annualInterestRate, loanTermYears);
  const monthlyPaymentAmount = Number(mortgageDetails.payment);
  const monthlyInterestRate = annualInterestRate / 12;
  const annualRatePercent = (annualInterestRate * 100).toFixed(2);

  console.log(mortgageDetails);
  console.log(`Loan: ${formatCurrencyAmount(principalLoanAmount)} at ${annualRatePercent}% over ${loanTermYears} years`);
  console.log(`Monthly payment: ${formatCurrencyAmount(monthlyPaymentAmount)}`);
  console.log(`Total interest paid: ${formatCurrencyAmount(mortgageDetails.interest)}`);
  console.log(`Total amount repaid: ${formatCurrencyAmount(principalLoanAmount + mortgageDetails.interest)}`);

  console.log('Remaining balance by year:');
  for (const milestoneYear of buildMilestoneYearList(loanTermYears)) {
    const remainingBalance = calculateRemainingBalance(
      principalLoanAmount,
      monthlyInterestRate,
      monthlyPaymentAmount,
      milestoneYear * 12
    );
    const equityBuiltUp = principalLoanAmount - remainingBalance;
    console.log(`  year ${String(milestoneYear).padStart(2)}: owes ${formatCurrencyAmount(remainingBalance)}, principal repaid ${formatCurrencyAmount(equityBuiltUp)}`);
  }
}

printMortgageSummary(200000, 0.05, 30);

