function validateSensorInput(sensorReadingsArray, baselineAverageValue, maximumAllowedVariance) {
  if (!Array.isArray(sensorReadingsArray) || sensorReadingsArray.length === 0) {
    throw new TypeError('sensor_readings_array must be a non-empty array');
  }
  const hasInvalidReading = sensorReadingsArray.some((readingCandidate) => typeof readingCandidate !== 'number' || Number.isNaN(readingCandidate));
  if (hasInvalidReading) {
    throw new TypeError('every sensor reading must be a finite number');
  }
  if (typeof baselineAverageValue !== 'number' || Number.isNaN(baselineAverageValue)) {
    throw new TypeError('baseline_average_value must be a number');
  }
  if (typeof maximumAllowedVariance !== 'number' || maximumAllowedVariance < 0) {
    throw new RangeError('maximum_allowed_variance must be a non-negative number');
  }
}

function detectSensorAnomalies(sensorReadingsArray, baselineAverageValue, maximumAllowedVariance) {
  validateSensorInput(sensorReadingsArray, baselineAverageValue, maximumAllowedVariance);

  let totalAnomaliesDetected = 0;
  let largestDeviationObserved = 0;
  let suddenSpikeCount = 0;

  for (let readingIndex = 0; readingIndex < sensorReadingsArray.length; readingIndex += 1) {
    const currentReadingValue = sensorReadingsArray[readingIndex];
    const absoluteDifferenceMagnitude = Math.abs(currentReadingValue - baselineAverageValue);

    if (absoluteDifferenceMagnitude > maximumAllowedVariance) {
      totalAnomaliesDetected += 1;
    }
    if (absoluteDifferenceMagnitude > largestDeviationObserved) {
      largestDeviationObserved = absoluteDifferenceMagnitude;
    }

    if (readingIndex >= 2) {
      const windowSum = currentReadingValue + sensorReadingsArray[readingIndex - 1] + sensorReadingsArray[readingIndex - 2];
      const rollingAverageValue = windowSum / 3;
      if (Math.abs(currentReadingValue - rollingAverageValue) > maximumAllowedVariance) {
        suddenSpikeCount += 1;
      }
    }
  }

  return [totalAnomaliesDetected, largestDeviationObserved, suddenSpikeCount];
}

function formatAnomalyReport(sensorLabelText, anomalyResultTuple) {
  const [anomalyCount, peakDeviation, spikeTotal] = anomalyResultTuple;
  const deviationText = peakDeviation.toFixed(2);
  return `${sensorLabelText}: anomalies=${anomalyCount}, largestDeviation=${deviationText}, suddenSpikes=${spikeTotal}`;
}

function runSensorDiagnostics(sensorRecordList) {
  return sensorRecordList.map((sensorRecord) => {
    const anomalyResultTuple = detectSensorAnomalies(sensorRecord.readings, sensorRecord.baseline, sensorRecord.variance);
    return formatAnomalyReport(sensorRecord.label, anomalyResultTuple);
  });
}

