function compressStringRuns(rawInputString) {
  const inputStringLength = rawInputString.length;
  if (inputStringLength === 0) {
    return '';
  }
  let currentTrackedCharacter = rawInputString[0];
  let currentRepetitionCount = 0;
  let finalCompressedOutput = '';
  for (let loopIndexPosition = 0; loopIndexPosition < inputStringLength; loopIndexPosition += 1) {
    const loopCharacterValue = rawInputString[loopIndexPosition];
    if (loopCharacterValue === currentTrackedCharacter) {
      currentRepetitionCount += 1;
    }
    if (loopCharacterValue !== currentTrackedCharacter || currentRepetitionCount === 9) {
      finalCompressedOutput += currentTrackedCharacter + currentRepetitionCount;
      if (loopCharacterValue !== currentTrackedCharacter) {
        currentTrackedCharacter = loopCharacterValue;
        currentRepetitionCount = 1;
      } else {
        currentRepetitionCount = 0;
      }
    }
  }
  if (currentRepetitionCount > 0) {
    finalCompressedOutput += currentTrackedCharacter + currentRepetitionCount;
  }
  return finalCompressedOutput;
}

function expandStringRuns(encodedRunString) {
  let expandedTextResult = '';
  for (let pairStartIndex = 0; pairStartIndex < encodedRunString.length; pairStartIndex += 2) {
    const encodedCharacterValue = encodedRunString[pairStartIndex];
    const repeatCountDigit = Number(encodedRunString[pairStartIndex + 1]);
    expandedTextResult += encodedCharacterValue.repeat(repeatCountDigit);
  }
  return expandedTextResult;
}

function buildCompressionReport(rawInputString) {
  const compressedRunString = compressStringRuns(rawInputString);
  const roundTripResult = expandStringRuns(compressedRunString);
  const isLosslessEncoding = roundTripResult === rawInputString;
  const originalLengthValue = rawInputString.length;
  const compressionRatioValue = originalLengthValue === 0
    ? 0
    : compressedRunString.length / originalLengthValue;
  const reportLineList = [
    `input:      ${rawInputString}`,
    `compressed: ${compressedRunString}`,
    `expanded:   ${roundTripResult}`,
    `lossless:   ${isLosslessEncoding}`,
    `ratio:      ${compressionRatioValue.toFixed(2)}`,
  ];
  return reportLineList.join('\n');
}

function runEncodingDriver(sampleInputString) {
  console.log(compressStringRuns(sampleInputString));
  console.log(buildCompressionReport(sampleInputString));
}

