    throw new TypeError(`Trip ${tripIndex} must be a [miles, isPeak] pair`);
  }
  const [tripDistance, isPeakHour] = singleTrip;
  if (typeof tripDistance !== 'number' || !Number.isFinite(tripDistance) || tripDistance < 0) {
