    const { tripDistance, isPeakHour } = validateTrip(singleTrip, tripIndex);
    cumulativeTotal += calculateTripCost(tripDistance, isPeakHour);
  });
  const cappedTotal = Math.min(roundToCents(cumulativeTotal), dailyFareCap);
  return cappedTotal;
}

