function splitIntoWords(text) {
  return text.split(/\s+/).filter(function (wordCandidate) {
    return wordCandidate.length > 0;
  });
}

function format(text, width) {
  if (typeof text !== 'string') {
    throw new TypeError('format expects the text argument to be a string');
  }
  const maximumWidth = Math.floor(width);
  if (!Number.isFinite(maximumWidth) || maximumWidth < 1) {
    throw new RangeError('format expects width to be a positive integer');
  }

  const wordList = splitIntoWords(text);
  const formattedLines = [];
  let currentLine = '';

  wordList.forEach(function (currentWord) {
    if (currentLine.length === 0) {
      currentLine = currentWord;
      return;
    }
    const projectedLength = currentLine.length + 1 + currentWord.length;
    if (projectedLength > maximumWidth) {
      formattedLines.push(currentLine);
      currentLine = currentWord;
    } else {
      currentLine += ' ' + currentWord;
    }
  });

  if (currentLine.length > 0) {
    formattedLines.push(currentLine);
  }
  return formattedLines;
}

function measureLongestLine(lineArray) {
  return lineArray.reduce(function (longestSoFar, singleLine) {
    return Math.max(longestSoFar, singleLine.length);
  }, 0);
}

function renderBoxedParagraph(text, width) {
  const wrappedLines = format(text, width);
  const boxInnerWidth = Math.max(measureLongestLine(wrappedLines), Math.floor(width));
  const horizontalBorder = '+' + '-'.repeat(boxInnerWidth + 2) + '+';
  const bodyRows = wrappedLines.map(function (paddedCandidate) {
    return '| ' + paddedCandidate.padEnd(boxInnerWidth, ' ') + ' |';
  });
  return [horizontalBorder].concat(bodyRows, [horizontalBorder]).join('\n');
}

function describeWrapResult(text, width) {
  const producedLines = format(text, width);
  const longestLineLength = measureLongestLine(producedLines);
  const oversizedWordCount = producedLines.filter(function (inspectedLine) {
    return inspectedLine.length > width;
  }).length;
  return 'lines: ' + producedLines.length +
    ', longest: ' + longestLineLength +
    ', oversized words: ' + oversizedWordCount;
}

const sampleSentence = 'The quick brown fox jumps over an extraordinarily lazy dog';
const narrowWidth = 10;

console.log(format(sampleSentence, narrowWidth));
console.log(renderBoxedParagraph(sampleSentence, 20));
console.log(describeWrapResult(sampleSentence, narrowWidth));

module.exports = { format, renderBoxedParagraph, describeWrapResult };

