const fileLetters = 'abcdefgh';
const boardSize = 8;

const knightOffsets = [
  [1, 2], [2, 1], [2, -1], [1, -2],
  [-1, -2], [-2, -1], [-2, 1], [-1, 2]
];

function parseSquare(squareName) {
  const normalizedSquare = String(squareName).trim().toLowerCase();
  if (normalizedSquare.length !== 2) {
    throw new Error(`invalid square: ${squareName}`);
  }
  const fileIndex = fileLetters.indexOf(normalizedSquare[0]);
  const rankIndex = Number(normalizedSquare[1]) - 1;
  if (fileIndex < 0 || !Number.isInteger(rankIndex) || rankIndex < 0 || rankIndex >= boardSize) {
    throw new Error(`invalid square: ${squareName}`);
  }
  return { fileIndex, rankIndex };
}

function formatSquare(fileIndex, rankIndex) {
  return `${fileLetters[fileIndex]}${rankIndex + 1}`;
}

function isOnBoard(fileIndex, rankIndex) {
  return fileIndex >= 0 && fileIndex < boardSize && rankIndex >= 0 && rankIndex < boardSize;
}

function moves(position) {
  const startingSquare = parseSquare(position);
  const validDestinations = [];
  for (const [fileOffset, rankOffset] of knightOffsets) {
    const targetFile = startingSquare.fileIndex + fileOffset;
    const targetRank = startingSquare.rankIndex + rankOffset;
    if (isOnBoard(targetFile, targetRank)) {
      validDestinations.push(formatSquare(targetFile, targetRank));
    }
  }
  return validDestinations.sort();
}

function describeMoves(position) {
  const destinationList = moves(position);
  const destinationCount = destinationList.length;
  return `${position}: ${destinationCount} move${destinationCount === 1 ? '' : 's'} -> ${destinationList.join(' ')}`;
}

function buildMobilityMap() {
  const mobilityMap = new Map();
  for (const fileLetter of fileLetters) {
    for (let rankNumber = 1; rankNumber <= boardSize; rankNumber += 1) {
      const squareName = `${fileLetter}${rankNumber}`;
      mobilityMap.set(squareName, moves(squareName).length);
    }
  }
  return mobilityMap;
}

function reportMostMobileSquares() {
  const mobilityMap = buildMobilityMap();
  const bestMoveCount = Math.max(...mobilityMap.values());
  const bestSquares = [...mobilityMap.keys()].filter((squareName) => mobilityMap.get(squareName) === bestMoveCount);
  return `best squares (${bestMoveCount} moves): ${bestSquares.sort().join(' ')}`;
}

function main() {
  const sampleSquares = ['a1', 'h8', 'd4', 'b1', 'e7'];
  for (const sampleSquare of sampleSquares) {
    console.log(describeMoves(sampleSquare));
  }
  console.log(reportMostMobileSquares());
}

main();

module.exports = { moves, describeMoves, buildMobilityMap, reportMostMobileSquares };

