  const frequencyMap = new Map();
  for (const currentCharacter of inputString) {
    frequencyMap.set(currentCharacter, (frequencyMap.get(currentCharacter) || 0) + 1);
  }
  return frequencyMap;
}

function countMatchingCharacters(targetCounts, windowCounts) {
  let matchingCount = 0;
  for (const [targetCharacter, targetFrequency] of targetCounts) {
    if (windowCounts.get(targetCharacter) === targetFrequency) {
      matchingCount += 1;
    }
  }
  return matchingCount;
}

function adjustWindowCount(windowCounts, characterToAdjust, deltaAmount) {
  const updatedFrequency = (windowCounts.get(characterToAdjust) || 0) + deltaAmount;
  if (updatedFrequency === 0) {
    windowCounts.delete(characterToAdjust);
  } else {
    windowCounts.set(characterToAdjust, updatedFrequency);
  }
}

function find(source, target) {
