function build_frequency_map(input_string) {
  const frequency_map = new Map();
  for (const current_character of input_string) {
    frequency_map.set(current_character, (frequency_map.get(current_character) || 0) + 1);
  }
  return frequency_map;
}

function count_matching_characters(target_counts, window_counts) {
  let matching_count = 0;
  for (const [target_character, target_frequency] of target_counts) {
    if (window_counts.get(target_character) === target_frequency) {
      matching_count += 1;
    }
  }
  return matching_count;
}

function adjust_window_count(window_counts, character_to_adjust, delta_amount) {
  const updated_frequency = (window_counts.get(character_to_adjust) || 0) + delta_amount;
  if (updated_frequency === 0) {
    window_counts.delete(character_to_adjust);
  } else {
    window_counts.set(character_to_adjust, updated_frequency);
  }
}

function find(source, target) {
  const matching_indices = [];
  const window_length = target.length;
  if (window_length === 0 || source.length < window_length) {
    return matching_indices;
  }
  const target_counts = build_frequency_map(target);
  const window_counts = build_frequency_map(source.slice(0, window_length));
  const distinct_target_characters = target_counts.size;
  if (count_matching_characters(target_counts, window_counts) === distinct_target_characters) {
    matching_indices.push(0);
  }
  for (let window_start = 1; window_start + window_length <= source.length; window_start += 1) {
    const outgoing_character = source[window_start - 1];
    const incoming_character = source[window_start + window_length - 1];
    adjust_window_count(window_counts, outgoing_character, -1);
    adjust_window_count(window_counts, incoming_character, 1);
    if (count_matching_characters(target_counts, window_counts) === distinct_target_characters) {
      matching_indices.push(window_start);
    }
  }
  return matching_indices;
}

function format_search_report(source_text, target_word) {
  const found_indices = find(source_text, target_word);
