const homeLabel = 'Home';
const rootPath = '/';

function toReadableLabel(urlSegment) {
  const spacedSegment = urlSegment.replace(/-/g, ' ');
  return spacedSegment.charAt(0).toUpperCase() + spacedSegment.slice(1);
}

function buildCumulativePath(pathSegments, currentIndex) {
  const segmentsSoFar = pathSegments.slice(0, currentIndex + 1);
  return rootPath + segmentsSoFar.join('/');
}

function normalizeSegments(rawPaths) {
  if (!Array.isArray(rawPaths)) {
    throw new TypeError('build(paths) expects an array of URL segments');
  }
  const cleanedSegments = [];
  rawPaths.forEach((rawSegment) => {
    if (typeof rawSegment !== 'string') {
      throw new TypeError(`Invalid URL segment: ${String(rawSegment)}`);
    }
    const trimmedSegment = rawSegment.replace(/^\/+|\/+$/g, '').trim();
    if (trimmedSegment.length > 0) {
      cleanedSegments.push(trimmedSegment);
    }
  });
  return cleanedSegments;
}

function build(paths) {
  const pathSegments = normalizeSegments(paths);
  const breadcrumbTrail = [[homeLabel, rootPath]];
  pathSegments.forEach((urlSegment, segmentIndex) => {
    const readableLabel = toReadableLabel(urlSegment);
    const cumulativePath = buildCumulativePath(pathSegments, segmentIndex);
    breadcrumbTrail.push([readableLabel, cumulativePath]);
  });
  return breadcrumbTrail;
}

function renderTrail(breadcrumbTrail, separatorText = ' > ') {
  const renderedSteps = breadcrumbTrail.map(([stepLabel, stepPath]) => `${stepLabel} (${stepPath})`);
  return renderedSteps.join(separatorText);
}

function renderTrailAsHtml(breadcrumbTrail) {
  const lastStepIndex = breadcrumbTrail.length - 1;
  const anchorMarkup = breadcrumbTrail.map(([stepLabel, stepPath], stepIndex) => {
    if (stepIndex === lastStepIndex) {
      return `<span class="current">${stepLabel}</span>`;
    }
    return `<a href="${stepPath}">${stepLabel}</a>`;
  });
  return `<nav class="breadcrumb">${anchorMarkup.join('<span class="sep">/</span>')}</nav>`;
}

function main() {
  const requestedPaths = ['store', 'new-items'];
  const navigationTrail = build(requestedPaths);
  navigationTrail.forEach(([stepLabel, stepPath]) => {
    console.log(`${stepLabel.padEnd(12)} -> ${stepPath}`);
  });
  console.log(renderTrail(navigationTrail));
  console.log(renderTrailAsHtml(navigationTrail));

  const messySegments = ['/blog/', 'long-form-essays', '', 'why-camel-case'];
  const essayTrail = build(messySegments);
  console.log(renderTrail(essayTrail, ' | '));
  console.log(`Depth of essay trail: ${essayTrail.length - 1}`);
}

main();

module.exports = { build, toReadableLabel, buildCumulativePath, renderTrail, renderTrailAsHtml };

