function isValidGridShape(gridCandidate) {
  if (!Array.isArray(gridCandidate) || gridCandidate.length !== 9) {
    return false;
  }
  return gridCandidate.every((rowValues) => Array.isArray(rowValues) && rowValues.length === 9);
}

function collectDuplicateValues(rowValues) {
  const seenDigitCounts = new Map();
  for (const cellValue of rowValues) {
    if (!Number.isInteger(cellValue) || cellValue < 0 || cellValue > 9) {
      throw new RangeError(`cell value out of range: ${cellValue}`);
    }
    if (cellValue === 0) {
      continue;
    }
    const previousCount = seenDigitCounts.get(cellValue) || 0;
    seenDigitCounts.set(cellValue, previousCount + 1);
  }
  const repeatedDigits = [];
  for (const [digitValue, occurrenceCount] of seenDigitCounts) {
    if (occurrenceCount > 1) {
      repeatedDigits.push(digitValue);
    }
  }
  return repeatedDigits.sort((firstDigit, secondDigit) => firstDigit - secondDigit);
}

function findInvalidRowIndexes(grid) {
  const brokenRowIndexes = [];
  grid.forEach((rowValues, rowIndex) => {
    if (collectDuplicateValues(rowValues).length > 0) {
      brokenRowIndexes.push(rowIndex);
    }
  });
  return brokenRowIndexes;
}

function verify(grid) {
  if (!isValidGridShape(grid)) {
    throw new TypeError('grid must be a nine by nine array of integers');
  }
  return findInvalidRowIndexes(grid).length === 0;
}

function describeGrid(gridLabel, grid) {
  const brokenRowIndexes = findInvalidRowIndexes(grid);
  if (brokenRowIndexes.length === 0) {
    return `${gridLabel}: valid (every row holds unique non-zero digits)`;
  }
  const failureDetails = brokenRowIndexes.map((rowIndex) => {
    const duplicateDigits = collectDuplicateValues(grid[rowIndex]);
    return `row ${rowIndex} repeats ${duplicateDigits.join(', ')}`;
  });
  return `${gridLabel}: invalid (${failureDetails.join('; ')})`;
}

function buildGridFromRows(rowStrings) {
  return rowStrings.map((rowString) => rowString.split('').map(Number));
}

const solvedPuzzleGrid = buildGridFromRows([
  '534678912', '672195348', '198342567',
  '859761423', '426853791', '713924856',
  '961537284', '287419635', '345286179',
]);

const partiallyFilledGrid = buildGridFromRows([
  '530070000', '600195000', '098000060',
  '800060003', '400803001', '700020006',
  '060000280', '000419005', '000080079',
]);

const duplicatedFiveGrid = buildGridFromRows([
  '530070500', '600195000', '098000060',
  '800060003', '400803001', '700020006',
  '060000280', '000419005', '000080079',
]);

for (const [gridLabel, candidateGrid] of [
