  ['partially filled', partiallyFilledGrid],
  ['duplicated five', duplicatedFiveGrid],
]) {
  console.log(`${describeGrid(gridLabel, candidateGrid)} -> verify returns ${verify(candidateGrid)}`);
}

module.exports = { verify, collectDuplicateValues, findInvalidRowIndexes, describeGrid, buildGridFromRows };

