function validateRequests(requestedFloors) {
  if (!Array.isArray(requestedFloors)) {
    throw new TypeError('requests must be an array of floor numbers');
  }
  return requestedFloors.map((rawFloor, floorPosition) => {
    const parsedFloor = Number(rawFloor);
    if (!Number.isInteger(parsedFloor)) {
      throw new TypeError(`request at index ${floorPosition} is not an integer floor`);
    }
    return parsedFloor;
  });
}

function findClosestRequestIndex(pendingFloors, currentFloor) {
  let bestIndex = 0;
  let bestDistance = Math.abs(pendingFloors[0] - currentFloor);
  let bestIsUpward = pendingFloors[0] >= currentFloor;
  for (let scanIndex = 1; scanIndex < pendingFloors.length; scanIndex += 1) {
    const candidateFloor = pendingFloors[scanIndex];
    const candidateDistance = Math.abs(candidateFloor - currentFloor);
    const candidateIsUpward = candidateFloor >= currentFloor;
    const tieBrokenByDirection = candidateDistance === bestDistance && candidateIsUpward && !bestIsUpward;
    if (candidateDistance < bestDistance || tieBrokenByDirection) {
      bestIndex = scanIndex;
      bestDistance = candidateDistance;
      bestIsUpward = candidateIsUpward;
    }
  }
  return bestIndex;
}

function schedule(requests, start) {
  const pendingFloors = validateRequests(requests);
  const startingFloor = Number(start);
  if (!Number.isInteger(startingFloor)) {
    throw new TypeError('start must be an integer floor');
  }
  const visitedFloors = [];
  let currentFloor = startingFloor;
  let totalDistanceTraveled = 0;
  while (pendingFloors.length > 0) {
    const closestIndex = findClosestRequestIndex(pendingFloors, currentFloor);
    const nextFloor = pendingFloors.splice(closestIndex, 1)[0];
    totalDistanceTraveled += Math.abs(nextFloor - currentFloor);
    visitedFloors.push(nextFloor);
    currentFloor = nextFloor;
  }
  return [visitedFloors, totalDistanceTraveled];
}

function formatScheduleReport(startingFloor, visitedFloors, totalDistanceTraveled) {
  const routeDescription = [startingFloor, ...visitedFloors].join(' -> ');
  return `start ${startingFloor}: ${routeDescription} (${totalDistanceTraveled} floors)`;
}

function runElevatorSimulations(simulationCases) {
  return simulationCases.map((simulationCase) => {
    const [visitedFloors, totalDistanceTraveled] = schedule(simulationCase.requests, simulationCase.start);
    return formatScheduleReport(simulationCase.start, visitedFloors, totalDistanceTraveled);
  });
}

const simulationCases = [
  { requests: [2, 6], start: 5 },
  { requests: [4, 1, 9, 4], start: 3 },
  { requests: [7, -2, 0, 12, 7], start: 0 },
];

for (const reportLine of runElevatorSimulations(simulationCases)) {
  console.log(reportLine);
}

module.exports = { schedule, findClosestRequestIndex, formatScheduleReport, runElevatorSimulations };

