function overlap(meetings) {
  const sortedMeetings = meetings
    .map(function (meetingInterval) {
      return [meetingInterval[0], meetingInterval[1]];
    })
    .sort(function (firstMeeting, secondMeeting) {
      return firstMeeting[0] - secondMeeting[0];
    });

  const mergedMeetings = [];
  sortedMeetings.forEach(function (currentMeeting) {
    const previousMeeting = mergedMeetings[mergedMeetings.length - 1];
    if (previousMeeting && currentMeeting[0] <= previousMeeting[1]) {
      previousMeeting[1] = Math.max(previousMeeting[1], currentMeeting[1]);
    } else {
      mergedMeetings.push(currentMeeting);
    }
  });
  return mergedMeetings;
}

function validateSchedule(meetings) {
  if (!Array.isArray(meetings)) {
    throw new TypeError('schedule must be an array of intervals');
  }
  meetings.forEach(function (meetingInterval, meetingIndex) {
    if (!Array.isArray(meetingInterval) || meetingInterval.length !== 2) {
      throw new TypeError('interval ' + meetingIndex + ' must have two entries');
    }
    const [startMinute, endMinute] = meetingInterval;
    if (!Number.isInteger(startMinute) || !Number.isInteger(endMinute)) {
      throw new TypeError('interval ' + meetingIndex + ' must hold integers');
    }
    if (endMinute < startMinute) {
      throw new RangeError('interval ' + meetingIndex + ' ends before it starts');
    }
  });
}

function formatClockTime(totalMinutes) {
  const hourPart = Math.floor(totalMinutes / 60);
  const minutePart = totalMinutes % 60;
  return String(hourPart).padStart(2, '0') + ':' + String(minutePart).padStart(2, '0');
}

function describeSchedule(meetings) {
  return meetings
    .map(function (meetingInterval) {
      const [blockStart, blockEnd] = meetingInterval;
      const blockDuration = blockEnd - blockStart;
      return formatClockTime(blockStart) + '-' + formatClockTime(blockEnd) + ' (' + blockDuration + ' min)';
    })
    .join(', ');
}

function consolidateWorkday(rawMeetings) {
  validateSchedule(rawMeetings);
  const condensedBlocks = overlap(rawMeetings);
  const bookedMinutes = condensedBlocks.reduce(function (runningTotal, meetingInterval) {
    return runningTotal + (meetingInterval[1] - meetingInterval[0]);
  }, 0);
  return { condensedBlocks, bookedMinutes };
}

function main() {
