function overlap(meetings) {
  const sorted_meetings = meetings
    .map(function (meeting_interval) {
      return [meeting_interval[0], meeting_interval[1]];
    })
    .sort(function (first_meeting, second_meeting) {
      return first_meeting[0] - second_meeting[0];
    });

  const merged_meetings = [];
  sorted_meetings.forEach(function (current_meeting) {
    const previous_meeting = merged_meetings[merged_meetings.length - 1];
    if (previous_meeting && current_meeting[0] <= previous_meeting[1]) {
      previous_meeting[1] = Math.max(previous_meeting[1], current_meeting[1]);
    } else {
      merged_meetings.push(current_meeting);
    }
  });
  return merged_meetings;
}

function validate_schedule(meetings) {
  if (!Array.isArray(meetings)) {
    throw new TypeError('schedule must be an array of intervals');
  }
  meetings.forEach(function (meeting_interval, meeting_index) {
    if (!Array.isArray(meeting_interval) || meeting_interval.length !== 2) {
      throw new TypeError('interval ' + meeting_index + ' must have two entries');
    }
    const [start_minute, end_minute] = meeting_interval;
    if (!Number.isInteger(start_minute) || !Number.isInteger(end_minute)) {
      throw new TypeError('interval ' + meeting_index + ' must hold integers');
    }
    if (end_minute < start_minute) {
      throw new RangeError('interval ' + meeting_index + ' ends before it starts');
    }
  });
}

function format_clock_time(total_minutes) {
  const hour_part = Math.floor(total_minutes / 60);
  const minute_part = total_minutes % 60;
  return String(hour_part).padStart(2, '0') + ':' + String(minute_part).padStart(2, '0');
}

function describe_schedule(meetings) {
  return meetings
    .map(function (meeting_interval) {
      const [block_start, block_end] = meeting_interval;
      const block_duration = block_end - block_start;
      return format_clock_time(block_start) + '-' + format_clock_time(block_end) + ' (' + block_duration + ' min)';
    })
    .join(', ');
}

function consolidate_workday(raw_meetings) {
  validate_schedule(raw_meetings);
  const condensed_blocks = overlap(raw_meetings);
  const booked_minutes = condensed_blocks.reduce(function (running_total, meeting_interval) {
    return running_total + (meeting_interval[1] - meeting_interval[0]);
  }, 0);
  return { condensed_blocks, booked_minutes };
}

function main() {
  const daily_schedule = [
    [540, 600],
    [570, 630],
    [660, 720],
    [720, 750],
    [900, 960],
  ];
  const { condensed_blocks, booked_minutes } = consolidate_workday(daily_schedule);
  console.log('merged intervals:', JSON.stringify(condensed_blocks));
  console.log('readable schedule:', describe_schedule(condensed_blocks));
  console.log('total booked minutes:', booked_minutes);
}

main();

