const coinDenominations = [25, 10, 5, 1];
const coinNames = ['quarter', 'dime', 'nickel', 'penny'];
const pluralCoinNames = ['quarters', 'dimes', 'nickels', 'pennies'];

function validateTransaction(itemPrice, amountPaid) {
  if (!Number.isInteger(itemPrice) || !Number.isInteger(amountPaid)) {
    throw new TypeError('price and paid must be integer cents');
  }
  if (itemPrice < 0) {
    throw new RangeError('price cannot be negative');
  }
  if (amountPaid < itemPrice) {
    throw new RangeError(`insufficient payment: ${amountPaid} < ${itemPrice}`);
  }
}

function change(price, paid) {
  validateTransaction(price, paid);
  let remainingCents = paid - price;
  const coinCounts = [];
  for (const denominationValue of coinDenominations) {
    const coinsForDenomination = Math.floor(remainingCents / denominationValue);
    coinCounts.push(coinsForDenomination);
    remainingCents -= coinsForDenomination * denominationValue;
  }
  return coinCounts;
}

function formatCents(centsAmount) {
  const dollarPart = Math.floor(centsAmount / 100);
  const centPart = centsAmount % 100;
  return `$${dollarPart}.${String(centPart).padStart(2, '0')}`;
}

function describeCoins(coinCounts) {
  const spokenParts = coinCounts
    .map((coinQuantity, denominationIndex) => {
      if (coinQuantity === 0) {
        return null;
      }
      const coinLabel =
        coinQuantity === 1 ? coinNames[denominationIndex] : pluralCoinNames[denominationIndex];
      return `${coinQuantity} ${coinLabel}`;
    })
    .filter((spokenPart) => spokenPart !== null);
  return spokenParts.length === 0 ? 'no change' : spokenParts.join(', ');
}

function buildReceiptLine(price, paid) {
  const coinCounts = change(price, paid);
  const changeDue = paid - price;
  const totalCoinCount = coinCounts.reduce((runningTotal, count) => runningTotal + count, 0);
  return (
    `${formatCents(price)} paid with ${formatCents(paid)} -> ` +
    `${formatCents(changeDue)} in ${totalCoinCount} coin(s): ${describeCoins(coinCounts)}`
  );
}

function main() {
  const sampleTransactions = [
    [59, 100],
    [100, 100],
    [1234, 2000],
    [3, 44],
  ];
  for (const [itemPrice, amountTendered] of sampleTransactions) {
    console.log(buildReceiptLine(itemPrice, amountTendered));
  }
}

main();

