function isWholeNumber(numericValue) {
  return Number.isFinite(numericValue) && Math.abs(numericValue % 1) < Number.EPSILON;
}

function roundToTwoDecimals(numericValue) {
  return Math.round((numericValue + Number.EPSILON) * 100) / 100;
}

function normalizeQuantity(rawQuantity) {
  if (isWholeNumber(rawQuantity)) {
    return rawQuantity;
  }
  return roundToTwoDecimals(rawQuantity);
}

function validateIngredientEntry(ingredientEntry, entryIndex) {
  if (!Array.isArray(ingredientEntry) || ingredientEntry.length !== 2) {
    throw new TypeError(`Ingredient at index ${entryIndex} must be a [name, quantity] pair`);
  }
  const [ingredientName, originalQuantity] = ingredientEntry;
  if (typeof ingredientName !== 'string' || ingredientName.length === 0) {
    throw new TypeError(`Ingredient at index ${entryIndex} must have a non-empty name`);
  }
  if (typeof originalQuantity !== 'number' || !Number.isFinite(originalQuantity)) {
    throw new TypeError(`Ingredient "${ingredientName}" must have a finite numeric quantity`);
  }
}

function scale(ingredients, factor) {
  if (!Array.isArray(ingredients)) {
    throw new TypeError('ingredients must be an array of [name, quantity] pairs');
  }
  if (typeof factor !== 'number' || !Number.isFinite(factor)) {
    throw new TypeError('factor must be a finite number');
  }
  return ingredients.map((ingredientEntry, entryIndex) => {
    validateIngredientEntry(ingredientEntry, entryIndex);
    const [ingredientName, originalQuantity] = ingredientEntry;
    const scaledQuantity = normalizeQuantity(originalQuantity * factor);
    return [ingredientName, scaledQuantity];
  });
}

function scaleToServings(ingredients, originalServings, desiredServings) {
  if (typeof originalServings !== 'number' || originalServings <= 0) {
    throw new RangeError('original_servings must be a positive number');
  }
  return scale(ingredients, desiredServings / originalServings);
}

function formatIngredientLine([ingredientName, ingredientQuantity]) {
  const paddedName = ingredientName.padEnd(14, ' ');
  return `  ${paddedName}${ingredientQuantity}`;
}

function buildRecipeReport(recipeTitle, scaledIngredients, servingCount) {
  const headerLine = `${recipeTitle} (serves ${servingCount})`;
  return [headerLine, ...scaledIngredients.map(formatIngredientLine)].join('\n');
}

function main() {
  const pancakeIngredients = [
    ['flour', 2],
    ['milk', 1.5],
    ['eggs', 3],
    ['baking powder', 0.75],
    ['salt', 0.125]
  ];
  const baseServings = 4;
  const partyServings = 10;
  const partyIngredients = scaleToServings(pancakeIngredients, baseServings, partyServings);
  const halvedIngredients = scale(pancakeIngredients, 0.5);
  console.log(buildRecipeReport('Pancakes', partyIngredients, partyServings));
  console.log(buildRecipeReport('Pancakes', halvedIngredients, baseServings / 2));
}

main();

module.exports = { scale, scaleToServings, buildRecipeReport };

