const invalidAddressMessage = 'invalid';
const bracketedPeriodToken = '[.]';
const expectedSegmentCount = 4;
const numericSegmentPattern = /^[0-9]+$/;

function splitAddressSegments(addressText) {
  return addressText.split('.');
}

function isNumericSegment(segmentText) {
  return numericSegmentPattern.test(segmentText);
}

function hasExpectedSegmentCount(addressSegments) {
  return addressSegments.length === expectedSegmentCount;
}

function everySegmentIsNumeric(addressSegments) {
  return addressSegments.every(isNumericSegment);
}

function defang(address) {
  if (typeof address !== 'string') {
    return invalidAddressMessage;
  }
  const addressSegments = splitAddressSegments(address);
  if (!hasExpectedSegmentCount(addressSegments) || !everySegmentIsNumeric(addressSegments)) {
    return invalidAddressMessage;
  }
  return addressSegments.join(bracketedPeriodToken);
}

function measureWidestAddress(addressList) {
  return addressList.reduce((widestSoFar, currentAddress) => {
    const currentWidth = String(currentAddress).length;
    return currentWidth > widestSoFar ? currentWidth : widestSoFar;
  }, 0);
}

function formatDefangReportLine(originalAddress, columnWidth) {
  const displayedInput = String(originalAddress).padEnd(columnWidth, ' ');
  const defangedResult = defang(originalAddress);
  return `${displayedInput} -> ${defangedResult}`;
}

function buildDefangReport(addressList) {
  const columnWidth = measureWidestAddress(addressList);
  return addressList.map((candidateAddress) => formatDefangReportLine(candidateAddress, columnWidth));
}

function countInvalidAddresses(addressList) {
  return addressList.filter((candidateAddress) => defang(candidateAddress) === invalidAddressMessage).length;
}

