const basePairMap = {
  A: 'T',
  T: 'A',
  C: 'G',
  G: 'C'
};

function normalizeBase(rawCharacter) {
  return rawCharacter.toUpperCase();
}

function isRecognizedBase(candidateCharacter) {
  return Object.prototype.hasOwnProperty.call(basePairMap, normalizeBase(candidateCharacter));
}

function complement(strand) {
  const pairedCharacters = [];
  for (const currentCharacter of strand) {
    const upperCaseBase = normalizeBase(currentCharacter);
    if (isRecognizedBase(upperCaseBase)) {
      pairedCharacters.push(basePairMap[upperCaseBase]);
    }
  }
  return pairedCharacters.reverse().join('');
}

function collectSkippedCharacters(strand) {
  const skippedCharacters = [];
  for (const currentCharacter of strand) {
    if (!isRecognizedBase(currentCharacter)) {
      skippedCharacters.push(currentCharacter);
    }
  }
  return skippedCharacters;
}

function countBaseOccurrences(strand) {
  const occurrenceTally = { A: 0, T: 0, C: 0, G: 0 };
  for (const currentCharacter of strand) {
    const upperCaseBase = normalizeBase(currentCharacter);
    if (isRecognizedBase(upperCaseBase)) {
      occurrenceTally[upperCaseBase] += 1;
    }
  }
  return occurrenceTally;
}

function formatStrandReport(strand) {
  const complementedStrand = complement(strand);
  const discardedCharacters = collectSkippedCharacters(strand);
  const baseCounts = countBaseOccurrences(strand);
  const tallySummary = Object.keys(baseCounts)
    .map((baseLetter) => `${baseLetter}=${baseCounts[baseLetter]}`)
    .join(' ');
  const discardedSummary = discardedCharacters.length > 0
    ? discardedCharacters.join('')
    : '(none)';
  return [
    `input:      ${strand}`,
    `complement: ${complementedStrand}`,
    `counts:     ${tallySummary}`,
    `skipped:    ${discardedSummary}`
  ].join('\n');
}

function runStrandReports(strandCollection) {
  const reportBlocks = strandCollection.map(formatStrandReport);
  return reportBlocks.join('\n\n');
}

const sampleStrands = ['ATCG', 'gattaca', 'AC-GT?N', ''];
console.log(runStrandReports(sampleStrands));

module.exports = { complement, formatStrandReport, runStrandReports };

