function splitPathSegments(rawPath) {
  return String(rawPath).split('/');
}

function isCurrentDirectory(pathSegment) {
  return pathSegment === '' || pathSegment === '.';
}

function isParentDirectory(pathSegment) {
  return pathSegment === '..';
}

function normalize(path) {
  const rawSegments = splitPathSegments(path);
  const resolvedStack = [];
  for (const currentSegment of rawSegments) {
    if (isCurrentDirectory(currentSegment)) {
      continue;
    }
    if (isParentDirectory(currentSegment)) {
      resolvedStack.pop();
      continue;
    }
    resolvedStack.push(currentSegment);
  }
  return '/' + resolvedStack.join('/');
}

function resolveAgainstBase(basePath, relativePath) {
  const normalizedBase = normalize(basePath);
  const joinedPath = normalizedBase + '/' + relativePath;
  return normalize(joinedPath);
}

function countUpwardMoves(rawPath) {
  return splitPathSegments(rawPath).filter(isParentDirectory).length;
}

function describeDepth(absolutePath) {
