function split_path_segments(raw_path) {
  return String(raw_path).split('/');
}

function is_current_directory(path_segment) {
  return path_segment === '' || path_segment === '.';
}

function is_parent_directory(path_segment) {
  return path_segment === '..';
}

function normalize(path) {
  const raw_segments = split_path_segments(path);
  const resolved_stack = [];
  for (const current_segment of raw_segments) {
    if (is_current_directory(current_segment)) {
      continue;
    }
    if (is_parent_directory(current_segment)) {
      resolved_stack.pop();
      continue;
    }
    resolved_stack.push(current_segment);
  }
  return '/' + resolved_stack.join('/');
}

function resolve_against_base(base_path, relative_path) {
  const normalized_base = normalize(base_path);
  const joined_path = normalized_base + '/' + relative_path;
  return normalize(joined_path);
}

function count_upward_moves(raw_path) {
  return split_path_segments(raw_path).filter(is_parent_directory).length;
}

function describe_depth(absolute_path) {
  const meaningful_segments = split_path_segments(absolute_path).filter(function (path_segment) {
    return !is_current_directory(path_segment);
  });
  return meaningful_segments.length;
}

function format_normalization_report(raw_path) {
  const normalized_path = normalize(raw_path);
  const upward_move_count = count_upward_moves(raw_path);
  const final_depth = describe_depth(normalized_path);
  return [
    'input:  ' + raw_path,
    'output: ' + normalized_path,
    'moved up ' + upward_move_count + ' time(s), final depth ' + final_depth
  ].join('\n');
}

