function extractDomainPart(emailAddress) {
  if (typeof emailAddress !== 'string') {
    throw new TypeError('each contact entry must be a string');
  }
  const atSymbolIndex = emailAddress.indexOf('@');
  if (atSymbolIndex === -1 || atSymbolIndex === emailAddress.length - 1) {
    return null;
  }
  const rawDomain = emailAddress.slice(atSymbolIndex + 1);
  return rawDomain.trim().toLowerCase();
}

function tallyHostFrequencies(emails) {
  const frequencyMap = new Map();
  for (const contactEntry of emails) {
    const hostDomain = extractDomainPart(contactEntry);
    if (hostDomain === null || hostDomain.length === 0) {
      continue;
    }
    const previousCount = frequencyMap.get(hostDomain) || 0;
    frequencyMap.set(hostDomain, previousCount + 1);
  }
  return frequencyMap;
}

function extract(emails) {
  if (!Array.isArray(emails)) {
    throw new TypeError('extract expects an array of email addresses');
  }
  const frequencyMap = tallyHostFrequencies(emails);
  const domainPairs = Array.from(frequencyMap.entries());
  domainPairs.sort((firstPair, secondPair) => {
    const countDifference = secondPair[1] - firstPair[1];
    if (countDifference !== 0) {
      return countDifference;
    }
    return firstPair[0].localeCompare(secondPair[0]);
  });
  return domainPairs;
}

function formatFrequencyReport(sortedPairs) {
  if (sortedPairs.length === 0) {
    return 'no host platforms found';
  }
  const widestDomainLength = sortedPairs.reduce((currentWidest, pair) => {
    return Math.max(currentWidest, pair[0].length);
  }, 0);
  const reportLines = sortedPairs.map(([domainName, occurrenceCount]) => {
    const paddedDomain = domainName.padEnd(widestDomainLength, ' ');
    const countLabel = occurrenceCount === 1 ? 'contact' : 'contacts';
    return `${paddedDomain}  ${occurrenceCount} ${countLabel}`;
  });
  return reportLines.join('\n');
}

function summarizeContactList(emails) {
  const sortedPairs = extract(emails);
  const totalCounted = sortedPairs.reduce((runningTotal, pair) => runningTotal + pair[1], 0);
  const skippedEntries = emails.length - totalCounted;
  const headerLine = `${totalCounted} valid addresses across ${sortedPairs.length} hosts`;
  const footerLine = skippedEntries > 0 ? `\n(${skippedEntries} malformed entries ignored)` : '';
  return `${headerLine}\n${formatFrequencyReport(sortedPairs)}${footerLine}`;
}

function main() {
  const contactList = [
    'ana@Gmail.com',
    'bruno@gmail.COM',
    'carla@gmail.com',
    'dan@Outlook.com',
    'eve@outlook.com',
    'frank@protonmail.ch',
    'broken-address',
  ];
  console.log(summarizeContactList(contactList));
}

main();

module.exports = { extract, extractDomainPart, tallyHostFrequencies, summarizeContactList };

