function isAlphanumericCharacter(singleCharacter) {
  const characterCode = singleCharacter.charCodeAt(0);
  const isDigitCharacter = characterCode >= 48 && characterCode <= 57;
  const isUpperCaseLetter = characterCode >= 65 && characterCode <= 90;
  const isLowerCaseLetter = characterCode >= 97 && characterCode <= 122;
  return isDigitCharacter || isUpperCaseLetter || isLowerCaseLetter;
}

function cleanSentence(sentence) {
  if (typeof sentence !== 'string') {
    throw new TypeError('check expects a plain string');
  }
  const retainedCharacters = [];
  for (const currentCharacter of sentence) {
    if (isAlphanumericCharacter(currentCharacter)) {
      retainedCharacters.push(currentCharacter.toLowerCase());
    }
  }
  return retainedCharacters;
}

function check(sentence) {
  const cleanedCharacters = cleanSentence(sentence);
  let leftIndex = 0;
  let rightIndex = cleanedCharacters.length - 1;
  while (leftIndex < rightIndex) {
    const leftCharacter = cleanedCharacters[leftIndex];
    const rightCharacter = cleanedCharacters[rightIndex];
    if (leftCharacter !== rightCharacter) {
      return false;
    }
    leftIndex += 1;
    rightIndex -= 1;
  }
  return true;
}

function describeResult(sentence, isPalindrome) {
  const verdictLabel = isPalindrome ? 'palindrome' : 'not a palindrome';
  const cleanedPreview = cleanSentence(sentence).join('');
  const displayedSentence = sentence.trim().length === 0 ? '(empty input)' : sentence.trim();
  return `${displayedSentence} -> ${verdictLabel} [cleaned: "${cleanedPreview}"]`;
}

function buildPalindromeReport(sentenceList) {
  return sentenceList.map((currentSentence) => describeResult(currentSentence, check(currentSentence)));
}

function runCommandLineReport(commandLineArguments) {
  if (commandLineArguments.length === 0) {
    process.stderr.write('usage: node palindrome.js "<phrase>" ["<phrase>" ...]\n');
    return 1;
  }
  const reportLines = buildPalindromeReport(commandLineArguments);
  for (const reportLine of reportLines) {
    process.stdout.write(`${reportLine}\n`);
  }
  const failedCount = commandLineArguments.filter((candidateSentence) => !check(candidateSentence)).length;
  process.stdout.write(`${commandLineArguments.length - failedCount} of ${commandLineArguments.length} phrases are palindromes\n`);
  return failedCount === 0 ? 0 : 2;
}

const suppliedArguments = process.argv.slice(2);
process.exitCode = runCommandLineReport(suppliedArguments);

module.exports = { check, cleanSentence, describeResult, buildPalindromeReport };

