const minimumSupportedValue = 1;
const maximumSupportedValue = 3999;

const romanNumeralMappings = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I']
];

function validateInputNumber(candidateNumber) {
  if (!Number.isInteger(candidateNumber)) {
    throw new TypeError(`convert expects an integer, received: ${candidateNumber}`);
  }
  if (candidateNumber < minimumSupportedValue || candidateNumber > maximumSupportedValue) {
    throw new RangeError(
      `convert supports ${minimumSupportedValue}..${maximumSupportedValue}, received: ${candidateNumber}`
    );
  }
  return candidateNumber;
}

function collectConversionSteps(number) {
  let remainingValue = validateInputNumber(number);
  const appendedSymbols = [];
  for (const [mappingValue, mappingSymbol] of romanNumeralMappings) {
    while (remainingValue >= mappingValue) {
      appendedSymbols.push(mappingSymbol);
      remainingValue -= mappingValue;
    }
  }
  return appendedSymbols;
}

function convert(number) {
  return collectConversionSteps(number).join('');
}

function computeNumberColumnWidth(numberList) {
  return numberList.reduce(
    (widestSoFar, currentNumber) => Math.max(widestSoFar, String(currentNumber).length),
    0
  );
}

function formatConversionLine(sourceNumber, numberColumnWidth) {
  const paddedNumber = String(sourceNumber).padStart(numberColumnWidth, ' ');
  const romanSymbols = convert(sourceNumber);
  const stepBreakdown = collectConversionSteps(sourceNumber).join(' + ');
  return `${paddedNumber} -> ${romanSymbols}  (${stepBreakdown})`;
}

function buildConversionReport(numberList) {
  const numberColumnWidth = computeNumberColumnWidth(numberList);
  const reportLines = numberList.map((reportedNumber) =>
    formatConversionLine(reportedNumber, numberColumnWidth)
  );
  return reportLines.join('\n');
}

const sampleNumbers = [1, 4, 9, 14, 40, 90, 400, 1990, 2024, 3999];
console.log(buildConversionReport(sampleNumbers));

module.exports = { convert, collectConversionSteps, buildConversionReport };

