function parseLogEntry(rawLogLine) {
  if (typeof rawLogLine !== 'string') {
    return null;
  }
  const timestampEnd = rawLogLine.indexOf(']');
  if (timestampEnd === -1) {
    return null;
  }
  const levelStart = rawLogLine.indexOf('[', timestampEnd + 1);
  const levelEnd = levelStart === -1 ? -1 : rawLogLine.indexOf(']', levelStart + 1);
  if (levelEnd === -1) {
    return null;
  }
  const colonIndex = rawLogLine.indexOf(':', levelEnd + 1);
  if (colonIndex === -1) {
    return null;
  }
  const severityLevel = rawLogLine.slice(levelStart + 1, levelEnd).trim();
  const messagePayload = rawLogLine.slice(colonIndex + 1).trim();
  return { severityLevel, messagePayload };
}

function filter(logs, level) {
  if (!Array.isArray(logs)) {
    throw new TypeError('logs must be an array of raw log strings');
  }
  if (typeof level !== 'string') {
    throw new TypeError('level must be a severity string');
  }
  const targetSeverity = level.trim();
  const filteredMessages = [];
  for (const rawLogLine of logs) {
    const parsedEntry = parseLogEntry(rawLogLine);
    if (parsedEntry === null) {
      continue;
    }
    if (parsedEntry.severityLevel === targetSeverity) {
      filteredMessages.push(parsedEntry.messagePayload);
    }
  }
  return filteredMessages;
}

function summarizeSeverityCounts(logs) {
  const severityCounts = new Map();
  for (const rawLogLine of logs) {
    const parsedEntry = parseLogEntry(rawLogLine);
    if (parsedEntry === null) {
      continue;
    }
    const currentCount = severityCounts.get(parsedEntry.severityLevel) || 0;
    severityCounts.set(parsedEntry.severityLevel, currentCount + 1);
  }
  return severityCounts;
}

function formatFilteredReport(targetSeverity, filteredMessages, severityCounts) {
  const totalParsedLines = [...severityCounts.values()].reduce((runningTotal, count) => runningTotal + count, 0);
  const reportLines = [`${targetSeverity}: ${filteredMessages.length} of ${totalParsedLines} parsed entries`];
  filteredMessages.forEach((messagePayload, messageIndex) => {
    reportLines.push(`  ${messageIndex + 1}. ${messagePayload}`);
  });
  const sortedSeverities = [...severityCounts.keys()].sort();
  for (const severityName of sortedSeverities) {
    reportLines.push(`  [${severityName}] x${severityCounts.get(severityName)}`);
  }
  return reportLines.join('\n');
}

const sampleLogLines = [
  '[2024-03-01 08:14:02] [INFO]: service started on port 8080',
  '[2024-03-01 08:14:59] [ERROR]: database connection refused',
  '[2024-03-01 08:15:10] [WARN]: retrying connection in 5s',
  '[2024-03-01 08:15:16] [ERROR]: database connection refused again',
  'malformed line without any brackets',
  '[2024-03-01 08:16:00] [INFO]: connection pool restored'
];

const requestedSeverity = process.argv[2] || 'ERROR';
const matchedMessages = filter(sampleLogLines, requestedSeverity);
const severityTotals = summarizeSeverityCounts(sampleLogLines);
console.log(formatFilteredReport(requestedSeverity, matchedMessages, severityTotals));

