function normalizeTeamNames(rawTeamList) {
  return rawTeamList.map(function (teamName) {
    return String(teamName).trim();
  }).filter(function (trimmedName) {
    return trimmedName.length > 0;
  });
}

function bracket(teams) {
  if (!Array.isArray(teams)) {
    throw new TypeError('bracket expects an array of team names');
  }
  const participantList = normalizeTeamNames(teams);
  if (participantList.length % 2 !== 0) {
    participantList.push('bye');
  }
  const scheduledMatches = [];
  let headIndex = 0;
  let tailIndex = participantList.length - 1;
  while (headIndex < tailIndex) {
    const homeTeam = participantList[headIndex];
    const awayTeam = participantList[tailIndex];
    scheduledMatches.push([homeTeam, awayTeam]);
    headIndex += 1;
    tailIndex -= 1;
  }
  return scheduledMatches;
}

function countRealMatchups(matchList) {
  return matchList.filter(function (matchPair) {
    return matchPair.indexOf('bye') === -1;
  }).length;
}

function formatMatchLine(matchPair, matchNumber) {
  const [firstSeed, secondSeed] = matchPair;
  const labelPrefix = 'Match ' + matchNumber + ':';
  if (secondSeed === 'bye') {
    return labelPrefix + ' ' + firstSeed + ' advances (bye)';
  }
  return labelPrefix + ' ' + firstSeed + ' vs ' + secondSeed;
}

function buildRoundReport(roundLabel, matchList) {
  const reportLines = [roundLabel + ' — ' + matchList.length + ' match(es)'];
  matchList.forEach(function (matchPair, matchIndex) {
    reportLines.push(formatMatchLine(matchPair, matchIndex + 1));
  });
  const playedMatchCount = countRealMatchups(matchList);
  const byeCount = matchList.length - playedMatchCount;
  reportLines.push('Contested: ' + playedMatchCount + ', byes granted: ' + byeCount);
