const dailyGoalThreshold = 10000;
const minimumCountedSteps = 5000;

function normalizeStepEntries(rawSteps) {
  if (!Array.isArray(rawSteps)) {
    throw new TypeError('stats expects an array of daily step counts');
  }
  return rawSteps.map(function (rawEntry, dayIndex) {
    const parsedStepCount = typeof rawEntry === 'string' ? Number(rawEntry.trim()) : rawEntry;
    if (!Number.isFinite(parsedStepCount) || parsedStepCount < 0) {
      throw new RangeError('Invalid step count on day ' + (dayIndex + 1) + ': ' + rawEntry);
    }
    return Math.round(parsedStepCount);
  });
}

function stats(steps) {
  const normalizedSteps = normalizeStepEntries(steps);
  let longestGoalStreak = 0;
  let currentGoalStreak = 0;
  let countedStepsTotal = 0;
  let countedDayTally = 0;

  normalizedSteps.forEach(function (stepCount) {
    if (stepCount >= dailyGoalThreshold) {
      currentGoalStreak += 1;
      if (currentGoalStreak > longestGoalStreak) {
        longestGoalStreak = currentGoalStreak;
      }
    } else {
      currentGoalStreak = 0;
    }
    if (stepCount >= minimumCountedSteps) {
      countedStepsTotal += stepCount;
      countedDayTally += 1;
    }
  });

  const validDayAverage = countedDayTally === 0 ? 0 : Math.trunc(countedStepsTotal / countedDayTally);
  return [longestGoalStreak, validDayAverage];
}

function formatStatsReport(weekLabel, steps) {
  const [longestGoalStreak, validDayAverage] = stats(steps);
  const streakWording = longestGoalStreak === 1 ? 'day' : 'days';
  return weekLabel + ': longest 10k streak ' + longestGoalStreak + ' ' + streakWording +
    ', average over 5k days ' + validDayAverage;
}

function buildWeeklySummary(weeklyStepLog) {
  return Object.keys(weeklyStepLog).map(function (weekLabel) {
    return formatStatsReport(weekLabel, weeklyStepLog[weekLabel]);
  });
}

const weeklyStepLog = {
  'Week 1': [12000, 11000, 4000, 14000],
  'Week 2': [3000, 4200, 900, 0, 4999, 100, 2500],
  'Week 3': ['10000', '10500', ' 9800 ', '18000', '20000', '6000', '4000']
};

buildWeeklySummary(weeklyStepLog).forEach(function (reportLine) {
  console.log(reportLine);
});

const overallStepHistory = Object.values(weeklyStepLog).reduce(function (mergedLog, weekSteps) {
  return mergedLog.concat(weekSteps);
}, []);
console.log(formatStatsReport('All weeks', overallStepHistory));

