const testDurationMinutes = 2;
const charactersPerWord = 5;

function isTypedCorrectly(targetWord, typedWord) {
  return targetWord === typedWord;
}

function validateWordPair(wordPair, pairIndex) {
  if (!Array.isArray(wordPair) || wordPair.length !== 2) {
    throw new TypeError(`entry ${pairIndex} must be a [target, typed] pair`);
  }
  const [targetWord, typedWord] = wordPair;
  if (typeof targetWord !== 'string' || typeof typedWord !== 'string') {
    throw new TypeError(`entry ${pairIndex} must contain two strings`);
  }
  return { targetWord, typedWord };
}

function collectCorrectWords(words) {
  const correctWords = [];
  words.forEach((wordPair, pairIndex) => {
    const { targetWord, typedWord } = validateWordPair(wordPair, pairIndex);
    if (isTypedCorrectly(targetWord, typedWord)) {
      correctWords.push(typedWord);
    }
  });
  return correctWords;
}

function countCorrectCharacters(correctWords) {
  return correctWords.reduce((runningTotal, correctWord) => runningTotal + correctWord.length, 0);
}

function computeWordsPerMinute(characterCount) {
  const normalisedWordCount = characterCount / charactersPerWord;
  return Math.trunc(normalisedWordCount / testDurationMinutes);
}

function computeAccuracyPercentage(correctWordCount, totalWordCount) {
  if (totalWordCount === 0) {
    return 0;
  }
  return Math.round((correctWordCount / totalWordCount) * 100);
}

function score(words) {
  if (!Array.isArray(words)) {
    throw new TypeError('score expects an array of word pairs');
  }
  const correctWords = collectCorrectWords(words);
  const correctCharacterCount = countCorrectCharacters(correctWords);
  const typingSpeed = computeWordsPerMinute(correctCharacterCount);
  const accuracyPercentage = computeAccuracyPercentage(correctWords.length, words.length);
  return [typingSpeed, accuracyPercentage];
}

function formatScoreReport(words) {
  const [typingSpeed, accuracyPercentage] = score(words);
  return `${typingSpeed} wpm at ${accuracyPercentage}% accuracy`;
}

const firstTestAttempt = [
  ['alpha', 'alpha'],
  ['bravo', 'bravo'],
  ['charlie', 'charlie'],
  ['delta', 'delta'],
  ['echo', 'ecko'],
];

const secondTestAttempt = [
  ['keyboard', 'keyboard'],
  ['monitor', 'moniter'],
  ['mouse', 'mouse'],
];

[firstTestAttempt, secondTestAttempt].forEach((typingAttempt, attemptNumber) => {
  console.log(`attempt ${attemptNumber + 1}: ${formatScoreReport(typingAttempt)}`);
});

module.exports = { score, formatScoreReport, isTypedCorrectly };

