function analyze(prices) {
  let minimumPriceSoFar = prices[0];
  let maximumPriceSoFar = prices[0];
  let maximumProfit = 0;
  let maximumDrawdown = 0;

  for (let dayIndex = 1; dayIndex < prices.length; dayIndex += 1) {
    const currentPrice = prices[dayIndex];
    const profitIfSoldToday = currentPrice - minimumPriceSoFar;
    if (profitIfSoldToday > maximumProfit) {
      maximumProfit = profitIfSoldToday;
    }
    const drawdownIfSoldToday = maximumPriceSoFar - currentPrice;
    if (drawdownIfSoldToday > maximumDrawdown) {
      maximumDrawdown = drawdownIfSoldToday;
    }
    if (currentPrice < minimumPriceSoFar) {
      minimumPriceSoFar = currentPrice;
    }
    if (currentPrice > maximumPriceSoFar) {
      maximumPriceSoFar = currentPrice;
    }
  }

  return [maximumProfit, maximumDrawdown];
}

function validatePriceSeries(rawPrices) {
  if (!Array.isArray(rawPrices) || rawPrices.length === 0) {
    throw new TypeError('price series must be a non-empty array');
  }
  return rawPrices.map((rawValue, valueIndex) => {
    const numericPrice = Number(rawValue);
    if (!Number.isFinite(numericPrice)) {
      throw new TypeError(`price at index ${valueIndex} is not a finite number`);
    }
    return numericPrice;
  });
}

function parsePriceLine(priceLine) {
  const rawFields = priceLine.split(/[\s,]+/).filter((fieldText) => fieldText.length > 0);
  return validatePriceSeries(rawFields);
}

function formatAnalysisReport(seriesLabel, dailyPrices) {
  const [bestProfit, worstDrawdown] = analyze(dailyPrices);
  const priceSummary = `${dailyPrices.length} days, ${dailyPrices[0]} -> ${dailyPrices[dailyPrices.length - 1]}`;
  return `${seriesLabel}: ${priceSummary} | max profit ${bestProfit} | max drawdown ${worstDrawdown}`;
}

function runReport(labelledLines) {
  const reportLines = [];
  for (const [seriesLabel, priceLine] of labelledLines) {
    try {
      const parsedPrices = parsePriceLine(priceLine);
      reportLines.push(formatAnalysisReport(seriesLabel, parsedPrices));
    } catch (validationError) {
      reportLines.push(`${seriesLabel}: skipped (${validationError.message})`);
    }
  }
  return reportLines.join('\n');
}

const inputSeries = [
  ['ACME', '10 12 8 15'],
  ['DESCENDING', '20, 18, 17, 9'],
  ['FLAT', '5 5 5 5'],
  ['BROKEN', '11 x 13'],
];

console.log(runReport(inputSeries));

