function validateSeatingRow(seatingRow) {
  if (!Array.isArray(seatingRow)) {
    throw new TypeError('the seating row must be an array of zeroes and ones');
  }
  seatingRow.forEach((seatMarker, seatIndex) => {
    if (seatMarker !== 0 && seatMarker !== 1) {
      throw new RangeError(`unexpected seat marker ${seatMarker} at index ${seatIndex}`);
    }
  });
}

function allocate(row, needed) {
  validateSeatingRow(row);
  if (!Number.isInteger(needed) || needed <= 0) {
    return -1;
  }
  let consecutiveEmptyCount = 0;
  for (let seatIndex = 0; seatIndex < row.length; seatIndex += 1) {
    consecutiveEmptyCount = row[seatIndex] === 0 ? consecutiveEmptyCount + 1 : 0;
    if (consecutiveEmptyCount === needed) {
      return seatIndex - needed + 1;
    }
  }
  return -1;
}

function applyAllocation(row, startIndex, seatsNeeded) {
  const updatedRow = row.slice();
  for (let offset = 0; offset < seatsNeeded; offset += 1) {
    updatedRow[startIndex + offset] = 1;
  }
  return updatedRow;
}

function formatRowDisplay(row, startIndex, seatsNeeded) {
  return row
    .map((seatMarker, seatIndex) => {
      const isInsideAllocation =
        startIndex >= 0 && seatIndex >= startIndex && seatIndex < startIndex + seatsNeeded;
      if (isInsideAllocation) {
        return 'X';
      }
      return seatMarker === 1 ? '#' : '.';
    })
    .join('');
}

function describeAllocation(row, seatsNeeded, startIndex) {
  const rowDisplay = formatRowDisplay(row, startIndex, seatsNeeded);
  if (startIndex < 0) {
    return `${rowDisplay}  request for ${seatsNeeded} seat(s) refused -> -1`;
  }
  const lastSeatIndex = startIndex + seatsNeeded - 1;
  return `${rowDisplay}  seats ${startIndex}-${lastSeatIndex} assigned -> ${startIndex}`;
}

function runBoxOffice(initialRow, bookingRequests) {
  let currentRowState = initialRow.slice();
  bookingRequests.forEach((requestedSeatCount) => {
    const allocationStart = allocate(currentRowState, requestedSeatCount);
    console.log(describeAllocation(currentRowState, requestedSeatCount, allocationStart));
    if (allocationStart >= 0) {
      currentRowState = applyAllocation(currentRowState, allocationStart, requestedSeatCount);
    }
  });
  return currentRowState;
}

const theaterRowLayout = [1, 0, 0, 1, 0, 0, 0, 1];
const groupSizeRequests = [3, 2, 1, 4];
const finalRowState = runBoxOffice(theaterRowLayout, groupSizeRequests);
const remainingEmptySeats = finalRowState.filter((seatMarker) => seatMarker === 0).length;
console.log(`final row: ${formatRowDisplay(finalRowState, -1, 0)}`);
console.log(`empty seats left: ${remainingEmptySeats}`);

