function apply_allocation(row, start_index, seats_needed) {
  const updated_row = row.slice();
  for (let offset = 0; offset < seats_needed; offset += 1) {
    updated_row[start_index + offset] = 1;
  }
  return updated_row;
}

function format_row_display(row, start_index, seats_needed) {
  return row
    .map((seat_marker, seat_index) => {
      const is_inside_allocation =
        start_index >= 0 && seat_index >= start_index && seat_index < start_index + seats_needed;
      if (is_inside_allocation) {
        return 'X';
      }
      return seat_marker === 1 ? '#' : '.';
    })
    .join('');
}

function describe_allocation(row, seats_needed, start_index) {
  const row_display = format_row_display(row, start_index, seats_needed);
  if (start_index < 0) {
    return `${row_display}  request for ${seats_needed} seat(s) refused -> -1`;
  }
  const last_seat_index = start_index + seats_needed - 1;
  return `${row_display}  seats ${start_index}-${last_seat_index} assigned -> ${start_index}`;
}

function run_box_office(initial_row, booking_requests) {
  let current_row_state = initial_row.slice();
  booking_requests.forEach((requested_seat_count) => {
    const allocation_start = allocate(current_row_state, requested_seat_count);
    console.log(describe_allocation(current_row_state, requested_seat_count, allocation_start));
    if (allocation_start >= 0) {
      current_row_state = apply_allocation(current_row_state, allocation_start, requested_seat_count);
    }
  });
  return current_row_state;
}

const theater_row_layout = [1, 0, 0, 1, 0, 0, 0, 1];
const group_size_requests = [3, 2, 1, 4];
const final_row_state = run_box_office(theater_row_layout, group_size_requests);
const remaining_empty_seats = final_row_state.filter((seat_marker) => seat_marker === 0).length;
console.log(`final row: ${format_row_display(final_row_state, -1, 0)}`);
console.log(`empty seats left: ${remaining_empty_seats}`);

