function tokenizeWords(inputText) {
  return inputText
    .split(' ')
    .map(function stripSentencePunctuation(rawToken) {
      return rawToken.replace(/\./g, '');
    })
    .filter(function keepNonEmpty(cleanToken) {
      return cleanToken.length > 0;
    });
}

function countLetterCharacters(wordList) {
  return wordList.reduce(function addWordLength(runningTotal, singleWord) {
    return runningTotal + singleWord.length;
  }, 0);
}

function countSentences(inputText) {
  const trimmedText = inputText.trim();
  if (trimmedText.length === 0) {
    return 0;
  }
  const periodCount = (trimmedText.match(/\./g) || []).length;
  const endsWithPeriod = trimmedText.endsWith('.');
  return endsWithPeriod ? periodCount : periodCount + 1;
}

function readability(text) {
  const wordList = tokenizeWords(text);
  const totalWordCount = wordList.length;
  if (totalWordCount === 0) {
    return 0;
  }
  const totalCharacterCount = countLetterCharacters(wordList);
  const totalSentenceCount = countSentences(text);
  const averageWordLength = totalCharacterCount / totalWordCount;
  const averageSentenceLength = totalWordCount / totalSentenceCount;
  return Math.round(5 * averageWordLength + 2 * averageSentenceLength);
}

function describeReadingLevel(readabilityScore) {
  if (readabilityScore < 30) {
    return 'very easy';
  }
  if (readabilityScore < 40) {
    return 'moderate';
  }
  if (readabilityScore < 50) {
    return 'challenging';
  }
  return 'very difficult';
}

function formatReadabilityReport(sampleText) {
  const wordList = tokenizeWords(sampleText);
  const sentenceTotal = countSentences(sampleText);
  const characterTotal = countLetterCharacters(wordList);
  const computedScore = readability(sampleText);
  const levelDescription = describeReadingLevel(computedScore);
  const countSummary = wordList.length + ' words, ' + characterTotal + ' chars, ' + sentenceTotal + ' sentences';
  return countSummary + ' -> score ' + computedScore + ' (' + levelDescription + ')';
}

function runReadabilityDriver(sampleTextList) {
