  'extraordinarily complicated terminology frequently obscures otherwise straightforward explanations.',
  'we run. we jump. we play.'
];

runReadabilityDriver(sampleTextList);

module.exports = { readability, tokenizeWords, countSentences, describeReadingLevel, formatReadabilityReport };

