const exposureMultipliers = { 1: 0.9, 2: 1.0, 3: 1.2 };

const exposureLabels = { 1: 'shade', 2: 'partial sun', 3: 'full sun' };

function validatePlantEntry(plantEntry, entryIndex) {
  if (!Array.isArray(plantEntry) || plantEntry.length !== 3) {
    throw new TypeError(`plant ${entryIndex} must be a triple of numbers`);
  }
  const [baseVolume, daysSinceWatered, exposureCode] = plantEntry;
  if (!Number.isFinite(baseVolume) || baseVolume < 0) {
    throw new RangeError(`plant ${entryIndex} has an invalid base volume`);
  }
  if (!Number.isInteger(daysSinceWatered) || daysSinceWatered < 0) {
    throw new RangeError(`plant ${entryIndex} has an invalid day count`);
  }
  if (!Object.prototype.hasOwnProperty.call(exposureMultipliers, exposureCode)) {
    throw new RangeError(`plant ${entryIndex} has an unknown exposure code`);
  }
}

function plantWaterVolume(plantEntry) {
  const [baseVolume, daysSinceWatered, exposureCode] = plantEntry;
  return baseVolume * daysSinceWatered * exposureMultipliers[exposureCode];
}

function irrigate(plants) {
  if (!Array.isArray(plants)) {
    throw new TypeError('plants must be an array of triples');
  }
  let totalVolume = 0;
  plants.forEach((plantEntry, entryIndex) => {
    validatePlantEntry(plantEntry, entryIndex);
    totalVolume += plantWaterVolume(plantEntry);
  });
  return Math.floor(totalVolume);
}

function describePlant(plantEntry, plantNumber) {
  const exposureCode = plantEntry[2];
  const exposureName = exposureLabels[exposureCode];
  const roundedVolume = Math.floor(plantWaterVolume(plantEntry));
  return `Plant ${plantNumber} (${exposureName}): ${roundedVolume} ml`;
}

function buildIrrigationReport(plants) {
  const reportLines = plants.map((plantEntry, entryIndex) => {
    validatePlantEntry(plantEntry, entryIndex);
    return describePlant(plantEntry, entryIndex + 1);
  });
  const requiredTotal = irrigate(plants);
  const wateringCanCount = Math.ceil(requiredTotal / 1000);
  reportLines.push(`Total: ${requiredTotal} ml (${wateringCanCount} cans)`);
  return reportLines.join('\n');
}

function main() {
  const greenhousePlants = [
    [100, 2, 3],
    [250, 1, 1],
    [80, 3, 2],
    [120, 4, 3],
  ];
  console.log(buildIrrigationReport(greenhousePlants));

  const droughtStressedPlants = greenhousePlants.filter(
    ([, daysSinceWatered]) => daysSinceWatered >= 3
  );
  const droughtWaterNeeded = irrigate(droughtStressedPlants);
  console.log(`Urgent watering needs ${droughtWaterNeeded} ml`);
}

main();

module.exports = { irrigate, buildIrrigationReport, plantWaterVolume };

