const baseLevelScore = 500;
const actionCodeEnemyDefeated = 1;
const actionCodeItemCollected = 2;
const actionCodeDamageTaken = 3;

const pointsPerAction = {
  [actionCodeEnemyDefeated]: 100,
  [actionCodeItemCollected]: 50,
  [actionCodeDamageTaken]: -20
};

const actionLabels = {
  [actionCodeEnemyDefeated]: 'enemy defeated',
  [actionCodeItemCollected]: 'item collected',
  [actionCodeDamageTaken]: 'damage taken'
};

function validateActionEntry(actionEntry, entryIndex) {
  if (!Array.isArray(actionEntry) || actionEntry.length !== 2) {
    throw new TypeError(`action at index ${entryIndex} must be a pair`);
  }
  const actionCode = actionEntry[0];
  const actionValue = actionEntry[1];
  if (!Object.prototype.hasOwnProperty.call(pointsPerAction, actionCode)) {
    throw new RangeError(`unknown action code ${actionCode} at index ${entryIndex}`);
  }
  if (typeof actionValue !== 'number' || !Number.isFinite(actionValue)) {
    throw new TypeError(`action value at index ${entryIndex} must be a finite number`);
  }
}

function actionPointDelta(actionEntry) {
  const actionCode = actionEntry[0];
  const actionValue = actionEntry[1];
  return pointsPerAction[actionCode] * actionValue;
}

function evaluate(actions) {
  if (!Array.isArray(actions)) {
    throw new TypeError('actions must be an array of pairs');
  }
  let runningScore = baseLevelScore;
  actions.forEach((actionEntry, entryIndex) => {
    validateActionEntry(actionEntry, entryIndex);
    runningScore += actionPointDelta(actionEntry);
  });
  return runningScore < 0 ? 0 : runningScore;
}

function buildScoreBreakdown(actions) {
  const breakdownRows = [`base score: ${baseLevelScore}`];
  actions.forEach((actionEntry, entryIndex) => {
    validateActionEntry(actionEntry, entryIndex);
    const actionName = actionLabels[actionEntry[0]];
    const pointDelta = actionPointDelta(actionEntry);
    const signedDelta = pointDelta >= 0 ? `+${pointDelta}` : `${pointDelta}`;
    breakdownRows.push(`${actionName} (value ${actionEntry[1]}): ${signedDelta}`);
  });
  return breakdownRows;
}

function formatLevelReport(levelName, actions) {
  const finalScore = evaluate(actions);
  const reportLines = [`--- ${levelName} ---`, ...buildScoreBreakdown(actions)];
  const rawTotal = actions.reduce((total, actionEntry) => total + actionPointDelta(actionEntry), baseLevelScore);
  if (rawTotal < 0) {
    reportLines.push(`raw total ${rawTotal} capped at zero`);
  }
  reportLines.push(`final score: ${finalScore}`);
  return reportLines.join('\n');
}

function main() {
  const exampleLevelActions = [[2, 10], [3, 40]];
  const brutalLevelActions = [[1, 2], [3, 100]];
  console.log(formatLevelReport('Sunken Grotto', exampleLevelActions));
  console.log(formatLevelReport('Collapsing Spire', brutalLevelActions));
}

main();

module.exports = { evaluate, formatLevelReport, buildScoreBreakdown };

