const minimumHeatTemperature = 80;
const humidityBaseline = 50;
const humidityWeightFactor = 0.2;

function validateReading(weatherReading, readingIndex) {
  if (!Array.isArray(weatherReading) || weatherReading.length !== 2) {
    throw new TypeError(`reading ${readingIndex} must be a [temperature, humidity] pair`);
  }
  const [actualTemperature, relativeHumidity] = weatherReading;
  if (!Number.isFinite(actualTemperature) || !Number.isFinite(relativeHumidity)) {
    throw new TypeError(`reading ${readingIndex} must contain two finite numbers`);
  }
  if (relativeHumidity < 0 || relativeHumidity > 100) {
    throw new RangeError(`reading ${readingIndex} has humidity outside 0-100`);
  }
  return { actualTemperature, relativeHumidity };
}

function computeHeatIndex(actualTemperature, relativeHumidity) {
  if (actualTemperature < minimumHeatTemperature || relativeHumidity <= humidityBaseline) {
    return actualTemperature;
  }
  const excessHumidity = relativeHumidity - humidityBaseline;
  return actualTemperature + humidityWeightFactor * excessHumidity;
}

function heat(weather) {
  if (!Array.isArray(weather)) {
    throw new TypeError('weather must be an array of temperature/humidity pairs');
  }
  return weather.map((weatherReading, readingIndex) => {
    const { actualTemperature, relativeHumidity } = validateReading(weatherReading, readingIndex);
    return Math.round(computeHeatIndex(actualTemperature, relativeHumidity));
  });
}

function describeReading(weatherReading, perceivedTemperature) {
  const [actualTemperature, relativeHumidity] = weatherReading;
  const feelsWarmer = perceivedTemperature > actualTemperature;
  const comfortNote = feelsWarmer
    ? `feels ${perceivedTemperature - actualTemperature}F warmer`
    : 'feels like the actual temperature';
  return `${actualTemperature}F at ${relativeHumidity}% humidity -> ${perceivedTemperature}F (${comfortNote})`;
}

function formatHeatReport(weather) {
  const heatIndices = heat(weather);
  const reportLines = weather.map((weatherReading, readingIndex) =>
    describeReading(weatherReading, heatIndices[readingIndex]));
  const hottestPerceived = heatIndices.reduce(
    (highestSoFar, currentIndex) => Math.max(highestSoFar, currentIndex),
    -Infinity);
  const averagePerceived = heatIndices.reduce(
    (runningTotal, currentIndex) => runningTotal + currentIndex, 0) / heatIndices.length;
  reportLines.push(`peak perceived temperature: ${hottestPerceived}F`);
  reportLines.push(`average perceived temperature: ${averagePerceived.toFixed(1)}F`);
  return reportLines.join('\n');
}

function main() {
  const dailyWeatherReadings = [
    [80, 70],
    [95, 90],
    [79, 100],
    [88, 50],
    [103, 63],
  ];
  console.log(heat(dailyWeatherReadings).join(' '));
  console.log(formatHeatReport(dailyWeatherReadings));
}

main();

module.exports = { heat, computeHeatIndex, formatHeatReport };

