const shelfMaximumWidth = 90;
const maximumBookHeight = 30;

function isValidBookPair(bookPair) {
  if (!Array.isArray(bookPair) || bookPair.length !== 2) {
    return false;
  }
  const [bookThickness, bookHeight] = bookPair;
  return Number.isFinite(bookThickness) && Number.isFinite(bookHeight) &&
    bookThickness > 0 && bookThickness <= shelfMaximumWidth && bookHeight > 0;
}

function selectShelvableBooks(books) {
  const shelvableBooks = [];
