const roastLossRates = { 1: 0.12, 2: 0.15, 3: 0.2 };

const roastTypeNames = { 1: 'light', 2: 'medium', 3: 'dark' };

function validateBatchEntry(batchEntry, batchIndex) {
  if (!Array.isArray(batchEntry) || batchEntry.length !== 2) {
    throw new TypeError(`batch ${batchIndex} must be a [weight, roastType] pair`);
  }
  const [greenBeanWeight, roastTypeCode] = batchEntry;
  if (typeof greenBeanWeight !== 'number' || !Number.isFinite(greenBeanWeight) || greenBeanWeight < 0) {
    throw new RangeError(`batch ${batchIndex} has an invalid green bean weight: ${greenBeanWeight}`);
  }
  if (!Object.prototype.hasOwnProperty.call(roastLossRates, roastTypeCode)) {
    throw new RangeError(`batch ${batchIndex} has an unknown roast type code: ${roastTypeCode}`);
  }
  return { greenBeanWeight, roastTypeCode };
}

function roastedWeightOf(greenBeanWeight, roastTypeCode) {
  const weightLossRate = roastLossRates[roastTypeCode];
  return greenBeanWeight * (1 - weightLossRate);
}

function roast(batches) {
  if (!Array.isArray(batches)) {
    throw new TypeError('batches must be an array of [weight, roastType] pairs');
  }
  const totalRoastedWeight = batches.reduce((runningTotal, batchEntry, batchIndex) => {
    const { greenBeanWeight, roastTypeCode } = validateBatchEntry(batchEntry, batchIndex);
    return runningTotal + roastedWeightOf(greenBeanWeight, roastTypeCode);
  }, 0);
  return Math.round(totalRoastedWeight);
}

function describeBatch(batchEntry, batchIndex) {
  const { greenBeanWeight, roastTypeCode } = validateBatchEntry(batchEntry, batchIndex);
  const roastedWeight = roastedWeightOf(greenBeanWeight, roastTypeCode);
  const shrinkagePercent = roastLossRates[roastTypeCode] * 100;
  return `${greenBeanWeight.toFixed(1)} lb ${roastTypeNames[roastTypeCode]} `
    + `-${shrinkagePercent.toFixed(0)}% -> ${roastedWeight.toFixed(2)} lb`;
}

function buildRoastReport(batches) {
  const reportLines = batches.map(describeBatch);
  const greenWeightTotal = batches.reduce((accumulatedGreen, [greenBeanWeight]) => accumulatedGreen + greenBeanWeight, 0);
  const finalRoastedTotal = roast(batches);
  reportLines.push(`green in: ${greenWeightTotal.toFixed(1)} lb`);
  reportLines.push(`roasted out: ${finalRoastedTotal} lb`);
  return reportLines.join('\n');
}

function main() {
  const morningProductionRun = [[100, 1], [100, 3]];
  const specialtyProductionRun = [[12.5, 2], [40, 1], [7.25, 3], [60, 2]];
  console.log(buildRoastReport(morningProductionRun));
  console.log('');
  console.log(buildRoastReport(specialtyProductionRun));
}

main();

module.exports = { roast, buildRoastReport, describeBatch };

