const adultDailyRate = 80;
const childDailyRate = 40;
const seniorDailyRate = 50;
const childAgeLimit = 12;
const seniorAgeThreshold = 65;
const discountDayThreshold = 3;
const multiDayDiscountRate = 0.1;

function dailyRateForAge(skierAge) {
  if (skierAge < childAgeLimit) {
    return childDailyRate;
  }
  if (skierAge >= seniorAgeThreshold) {
    return seniorDailyRate;
  }
  return adultDailyRate;
}

function applyMultiDayDiscount(baseTotal, skiDayCount) {
  if (skiDayCount >= discountDayThreshold) {
    return baseTotal - baseTotal * multiDayDiscountRate;
  }
  return baseTotal;
}

function costForSkier(skierAge, skiDayCount) {
  if (!Number.isFinite(skierAge) || skierAge < 0) {
    throw new RangeError(`invalid skier age: ${skierAge}`);
  }
  if (!Number.isInteger(skiDayCount) || skiDayCount < 0) {
    throw new RangeError(`invalid day count: ${skiDayCount}`);
  }
  const perDayPrice = dailyRateForAge(skierAge);
  const undiscountedTotal = perDayPrice * skiDayCount;
  return applyMultiDayDiscount(undiscountedTotal, skiDayCount);
}

function passes(skiers) {
  const groupTotalCost = skiers.reduce((runningTotal, skierEntry) => {
    const [skierAge, skiDayCount] = skierEntry;
    return runningTotal + costForSkier(skierAge, skiDayCount);
  }, 0);
  return Math.round(groupTotalCost);
}

function describeSkierLine(skierAge, skiDayCount) {
  const individualCost = costForSkier(skierAge, skiDayCount);
  const dayWord = skiDayCount === 1 ? 'day' : 'days';
  const discountNote = skiDayCount >= discountDayThreshold ? ' (10% off)' : '';
  return `age ${skierAge}, ${skiDayCount} ${dayWord}: $${individualCost.toFixed(2)}${discountNote}`;
}

function buildGroupReport(skiers) {
  const reportLines = skiers.map(([skierAge, skiDayCount]) =>
    describeSkierLine(skierAge, skiDayCount)
  );
  reportLines.push(`group total: $${passes(skiers)}`);
  return reportLines.join('\n');
}

function main() {
  const skiGroupBookings = [
    [10, 4],
    [34, 2],
    [70, 5],
    [12, 3],
  ];
  console.log(buildGroupReport(skiGroupBookings));
}

main();

module.exports = { passes, costForSkier, buildGroupReport };

