const marathonDistanceMiles = 26.2;

function toTotalMinutes(finishHours, finishMinutes) {
  return finishHours * 60 + finishMinutes;
}

function validateFinishTime(finishPair, runnerIndex) {
  if (!Array.isArray(finishPair) || finishPair.length !== 2) {
    throw new TypeError(`Runner ${runnerIndex}: expected a [hours, minutes] pair`);
  }
  const [finishHours, finishMinutes] = finishPair;
  if (!Number.isFinite(finishHours) || !Number.isFinite(finishMinutes)) {
    throw new TypeError(`Runner ${runnerIndex}: hours and minutes must be numbers`);
  }
  if (finishHours < 0 || finishMinutes < 0) {
    throw new RangeError(`Runner ${runnerIndex}: hours and minutes must not be negative`);
  }
  return [finishHours, finishMinutes];
}

function pace(times) {
  if (!Array.isArray(times)) {
    throw new TypeError('pace expects an array of [hours, minutes] pairs');
  }
  return times.map((finishPair, runnerIndex) => {
    const [finishHours, finishMinutes] = validateFinishTime(finishPair, runnerIndex);
    const totalMinutes = toTotalMinutes(finishHours, finishMinutes);
    return Math.round(totalMinutes / marathonDistanceMiles);
  });
}

function formatPaceLabel(paceMinutes) {
  return `${paceMinutes} min/mile`;
}

function formatFinishTime(finishHours, finishMinutes) {
  const paddedMinutes = String(finishMinutes).padStart(2, '0');
  return `${finishHours}:${paddedMinutes}`;
}

function buildPaceReport(times, roundedPaces) {
  return roundedPaces.map((paceMinutes, runnerIndex) => {
    const [finishHours, finishMinutes] = times[runnerIndex];
    const finishLabel = formatFinishTime(finishHours, finishMinutes);
    return `Runner ${runnerIndex + 1}: ${finishLabel} -> ${formatPaceLabel(paceMinutes)}`;
  });
}

function findFastestIndex(roundedPaces) {
  let fastestIndex = 0;
  for (let currentIndex = 1; currentIndex < roundedPaces.length; currentIndex += 1) {
    if (roundedPaces[currentIndex] < roundedPaces[fastestIndex]) {
      fastestIndex = currentIndex;
    }
  }
  return fastestIndex;
}

function main() {
  const finishTimes = [[4, 22], [3, 30], [5, 45], [2, 58]];
  const roundedPaces = pace(finishTimes);
  buildPaceReport(finishTimes, roundedPaces).forEach((reportLine) => console.log(reportLine));
  const fastestIndex = findFastestIndex(roundedPaces);
  const fastestLabel = formatPaceLabel(roundedPaces[fastestIndex]);
  console.log(`Fastest: runner ${fastestIndex + 1} at ${fastestLabel}`);
  console.log(`Paces: ${roundedPaces.join(', ')}`);
}

main();

