const baseBatteryCapacity = 100;
const highDrawThreshold = 50;
const efficiencyLossFactor = 1.2;

function validateUsagePeriod(usagePeriod, periodIndex) {
  if (!Array.isArray(usagePeriod) || usagePeriod.length !== 2) {
    throw new TypeError(`usage period ${periodIndex} must be a pair of [amps, minutes]`);
  }
  const [currentDraw, durationMinutes] = usagePeriod;
  if (!Number.isFinite(currentDraw) || !Number.isFinite(durationMinutes)) {
    throw new TypeError(`usage period ${periodIndex} must contain finite numbers`);
  }
  if (currentDraw < 0 || durationMinutes < 0) {
    throw new RangeError(`usage period ${periodIndex} must not contain negative values`);
  }
  return { currentDraw, durationMinutes };
}

function computePeriodConsumption(currentDraw, durationMinutes) {
  const durationHours = durationMinutes / 60;
  const rawConsumption = currentDraw * durationHours;
  if (currentDraw > highDrawThreshold) {
    return rawConsumption * efficiencyLossFactor;
  }
  return rawConsumption;
}

function estimate(usage) {
  if (!Array.isArray(usage)) {
    throw new TypeError('usage must be an array of [amps, minutes] pairs');
  }
  let remainingCapacity = baseBatteryCapacity;
  usage.forEach((usagePeriod, periodIndex) => {
    const { currentDraw, durationMinutes } = validateUsagePeriod(usagePeriod, periodIndex);
    remainingCapacity -= computePeriodConsumption(currentDraw, durationMinutes);
  });
  return remainingCapacity < 0 ? 0 : remainingCapacity;
}

function buildDepletionTimeline(usage) {
  let runningCapacity = baseBatteryCapacity;
  return usage.map((usagePeriod, periodIndex) => {
    const { currentDraw, durationMinutes } = validateUsagePeriod(usagePeriod, periodIndex);
    const consumedCapacity = computePeriodConsumption(currentDraw, durationMinutes);
    runningCapacity = Math.max(0, runningCapacity - consumedCapacity);
    return { currentDraw, durationMinutes, consumedCapacity, runningCapacity };
  });
}

function formatTimelineRow(timelineEntry, rowNumber) {
  const drawLabel = `${timelineEntry.currentDraw}A for ${timelineEntry.durationMinutes}min`;
  const consumedLabel = timelineEntry.consumedCapacity.toFixed(2).padStart(7);
  const remainingLabel = timelineEntry.runningCapacity.toFixed(2).padStart(7);
  return `${String(rowNumber).padStart(2)}. ${drawLabel.padEnd(22)} used ${consumedLabel} Ah -> ${remainingLabel} Ah left`;
}

function reportUsageEstimate(usage) {
  const depletionTimeline = buildDepletionTimeline(usage);
  const reportLines = depletionTimeline.map((timelineEntry, entryIndex) =>
    formatTimelineRow(timelineEntry, entryIndex + 1));
  const finalCapacity = estimate(usage);
  reportLines.push(`Remaining capacity: ${finalCapacity.toFixed(2)} Ah`);
  return reportLines.join('\n');
}

function main() {
  const sampleUsageProfile = [[40, 60], [60, 30]];
  const heavyUsageProfile = [[80, 45], [20, 120], [55, 90], [10, 300]];
  console.log(reportUsageEstimate(sampleUsageProfile));
  console.log('');
  console.log(reportUsageEstimate(heavyUsageProfile));
}

main();

module.exports = { estimate, buildDepletionTimeline, reportUsageEstimate };

