  const raw_consumption = current_draw * duration_hours;
  if (current_draw > high_draw_threshold) {
    return raw_consumption * efficiency_loss_factor;
  }
  return raw_consumption;
}

function estimate(usage) {
  if (!Array.isArray(usage)) {
    throw new TypeError('usage must be an array of [amps, minutes] pairs');
  }
  let remaining_capacity = base_battery_capacity;
  usage.forEach((usage_period, period_index) => {
    const { current_draw, duration_minutes } = validate_usage_period(usage_period, period_index);
    remaining_capacity -= compute_period_consumption(current_draw, duration_minutes);
  });
  return remaining_capacity < 0 ? 0 : remaining_capacity;
}

function build_depletion_timeline(usage) {
  let running_capacity = base_battery_capacity;
  return usage.map((usage_period, period_index) => {
    const { current_draw, duration_minutes } = validate_usage_period(usage_period, period_index);
    const consumed_capacity = compute_period_consumption(current_draw, duration_minutes);
    running_capacity = Math.max(0, running_capacity - consumed_capacity);
    return { current_draw, duration_minutes, consumed_capacity, running_capacity };
  });
}

function format_timeline_row(timeline_entry, row_number) {
  const draw_label = `${timeline_entry.current_draw}A for ${timeline_entry.duration_minutes}min`;
  const consumed_label = timeline_entry.consumed_capacity.toFixed(2).padStart(7);
  const remaining_label = timeline_entry.running_capacity.toFixed(2).padStart(7);
  return `${String(row_number).padStart(2)}. ${draw_label.padEnd(22)} used ${consumed_label} Ah -> ${remaining_label} Ah left`;
}

function report_usage_estimate(usage) {
  const depletion_timeline = build_depletion_timeline(usage);
  const report_lines = depletion_timeline.map((timeline_entry, entry_index) =>
    format_timeline_row(timeline_entry, entry_index + 1));
  const final_capacity = estimate(usage);
  report_lines.push(`Remaining capacity: ${final_capacity.toFixed(2)} Ah`);
  return report_lines.join('\n');
}

function main() {
  const sample_usage_profile = [[40, 60], [60, 30]];
  const heavy_usage_profile = [[80, 45], [20, 120], [55, 90], [10, 300]];
  console.log(report_usage_estimate(sample_usage_profile));
  console.log('');
  console.log(report_usage_estimate(heavy_usage_profile));
}

main();

module.exports = { estimate, build_depletion_timeline, report_usage_estimate };

