const maximumCarCapacity = 12;

function validateGroupSizes(groupSizes) {
  if (!Array.isArray(groupSizes)) {
    throw new TypeError('group sizes must be provided as an array');
  }
  return groupSizes.map((rawGroupSize, groupIndex) => {
    const groupSize = Number(rawGroupSize);
    if (!Number.isInteger(groupSize) || groupSize <= 0) {
      throw new RangeError(`group at position ${groupIndex} is not a positive whole number`);
    }
    if (groupSize > maximumCarCapacity) {
      throw new RangeError(`group of ${groupSize} cannot fit in a car holding ${maximumCarCapacity}`);
    }
    return groupSize;
  });
}

function assignGroupsToCars(groupSizes) {
  const carManifest = [];
  let currentCarGroups = [];
  let currentCarLoad = 0;
  groupSizes.forEach((groupSize) => {
    if (currentCarGroups.length === 0) {
      currentCarGroups.push(groupSize);
      currentCarLoad = groupSize;
      return;
    }
    if (currentCarLoad + groupSize <= maximumCarCapacity) {
      currentCarGroups.push(groupSize);
      currentCarLoad += groupSize;
      return;
    }
    carManifest.push(currentCarGroups);
    currentCarGroups = [groupSize];
    currentCarLoad = groupSize;
  });
  if (currentCarGroups.length > 0) {
    carManifest.push(currentCarGroups);
  }
  return carManifest;
}

function evaluate(groups) {
  return assignGroupsToCars(validateGroupSizes(groups)).length;
}

function describeCarManifest(carManifest) {
  return carManifest.map((boardedGroups, carNumber) => {
    const occupiedSeats = boardedGroups.reduce((runningTotal, groupSize) => runningTotal + groupSize, 0);
    const emptySeats = maximumCarCapacity - occupiedSeats;
    return `car ${carNumber + 1}: groups [${boardedGroups.join(', ')}] -> ${occupiedSeats} riders, ${emptySeats} seats free`;
  });
}

function reportBoardingPlan(groups) {
  const validatedGroups = validateGroupSizes(groups);
  const carManifest = assignGroupsToCars(validatedGroups);
  const totalPassengers = validatedGroups.reduce((runningTotal, groupSize) => runningTotal + groupSize, 0);
  const headerLine = `queue [${validatedGroups.join(', ')}] needs ${carManifest.length} car(s) for ${totalPassengers} passenger(s)`;
  return [headerLine, ...describeCarManifest(carManifest)].join('\n');
}

function runBoardingDemo(queuedRides) {
  queuedRides.forEach((waitingGroups) => {
    console.log(reportBoardingPlan(waitingGroups));
    console.log('');
  });
}

runBoardingDemo([[4, 5, 5, 2], [12, 1, 11, 3, 9], [1, 1, 1], [7, 6, 6, 1]]);
console.log(`evaluate([4, 5, 5, 2]) = ${evaluate([4, 5, 5, 2])}`);

module.exports = { evaluate, assignGroupsToCars, reportBoardingPlan, validateGroupSizes };

