const colorPageCents = 15;
const blackWhitePageCents = 5;
const discountPageThreshold = 100;
const discountRate = 0.1;

function validateJobEntry(jobEntry, jobIndex) {
  if (!Array.isArray(jobEntry) || jobEntry.length !== 2) {
    throw new TypeError(`job ${jobIndex} must be an array of two page counts`);
  }
  const [colorPageCount, blackWhitePageCount] = jobEntry;
  if (!Number.isInteger(colorPageCount) || !Number.isInteger(blackWhitePageCount)) {
    throw new TypeError(`job ${jobIndex} must contain integer page counts`);
  }
  if (colorPageCount < 0 || blackWhitePageCount < 0) {
    throw new RangeError(`job ${jobIndex} must not contain negative page counts`);
  }
  return { colorPageCount, blackWhitePageCount };
}

function computeJobCents(colorPageCount, blackWhitePageCount) {
  const totalPageCount = colorPageCount + blackWhitePageCount;
  const grossCents = colorPageCount * colorPageCents + blackWhitePageCount * blackWhitePageCents;
  if (totalPageCount > discountPageThreshold) {
    return Math.round(grossCents * (1 - discountRate));
  }
  return grossCents;
}

function compute(jobs) {
  if (!Array.isArray(jobs)) {
    throw new TypeError('jobs must be an array of print jobs');
  }
  const totalCents = jobs.reduce((runningCents, jobEntry, jobIndex) => {
    const { colorPageCount, blackWhitePageCount } = validateJobEntry(jobEntry, jobIndex);
    return runningCents + computeJobCents(colorPageCount, blackWhitePageCount);
  }, 0);
  return totalCents / 100;
}

function formatDollarAmount(centsAmount) {
  const dollarValue = centsAmount / 100;
  return `$${dollarValue.toFixed(2)}`;
}

function buildReceiptLines(jobs) {
  return jobs.map((jobEntry, jobIndex) => {
    const { colorPageCount, blackWhitePageCount } = validateJobEntry(jobEntry, jobIndex);
    const jobCents = computeJobCents(colorPageCount, blackWhitePageCount);
    const totalPageCount = colorPageCount + blackWhitePageCount;
    const discountMarker = totalPageCount > discountPageThreshold ? ' (bulk discount applied)' : '';
    const jobLabel = `Job ${jobIndex + 1}`;
    const pageSummary = `${colorPageCount} color + ${blackWhitePageCount} b/w`;
    return `${jobLabel}: ${pageSummary} = ${formatDollarAmount(jobCents)}${discountMarker}`;
  });
}

function printReceipt(jobs) {
  const receiptLines = buildReceiptLines(jobs);
  const grandTotalDollars = compute(jobs);
  receiptLines.forEach((receiptLine) => console.log(receiptLine));
  console.log(`Total due: $${grandTotalDollars.toFixed(2)}`);
  return grandTotalDollars;
}

const customerJobQueue = [[50, 60], [10, 20], [0, 300], [7, 0]];
printReceipt(customerJobQueue);

module.exports = { compute, computeJobCents, buildReceiptLines, formatDollarAmount, printReceipt };

