const serverCount = 4;
const overloadThreshold = 1000;

function validateRequestLoads(requests) {
  if (!Array.isArray(requests)) {
    throw new TypeError('requests must be an array of numbers');
  }
  requests.forEach((requestLoad, requestIndex) => {
    if (typeof requestLoad !== 'number' || !Number.isFinite(requestLoad)) {
      throw new TypeError(`request at index ${requestIndex} is not a finite number`);
    }
  });
}

function distributeRoundRobin(requests) {
  const serverLoads = new Array(serverCount).fill(0);
  requests.forEach((requestLoad, requestIndex) => {
    const targetServer = requestIndex % serverCount;
    serverLoads[targetServer] += requestLoad;
  });
  return serverLoads;
}

function countOverloadedServers(serverLoads) {
  return serverLoads.filter((totalLoad) => totalLoad > overloadThreshold).length;
}

function findPeakLoad(serverLoads) {
  return serverLoads.reduce((peakLoad, totalLoad) => Math.max(peakLoad, totalLoad), 0);
}

function balance(requests) {
  validateRequestLoads(requests);
  const serverLoads = distributeRoundRobin(requests);
  const overloadedCount = countOverloadedServers(serverLoads);
  if (overloadedCount > 0) {
    return overloadedCount;
  }
  return findPeakLoad(serverLoads);
}

function describeDistribution(requests) {
  const serverLoads = distributeRoundRobin(requests);
  const loadSummary = serverLoads
    .map((totalLoad, serverIndex) => `server${serverIndex}=${totalLoad}`)
    .join(', ');
  const overloadedCount = countOverloadedServers(serverLoads);
  const verdictText = overloadedCount > 0
    ? `${overloadedCount} overloaded server(s)`
    : `peak load ${findPeakLoad(serverLoads)}`;
  return `[${loadSummary}] -> ${verdictText}`;
}

function runBalanceReport(requestBatches) {
  return requestBatches.map((requestBatch, batchIndex) => {
    const batchLabel = `batch #${batchIndex + 1}`;
    const balanceResult = balance(requestBatch);
    return `${batchLabel}: ${describeDistribution(requestBatch)} (balance=${balanceResult})`;
  });
}

const incomingBatches = [
  [300, 400, 500, 200, 800],
  [100, 100, 100, 100],
  [],
  [1200, 1300, 50, 60, 70],
];

runBalanceReport(incomingBatches).forEach((reportLine) => console.log(reportLine));

module.exports = { balance, distributeRoundRobin, describeDistribution, runBalanceReport };

