const excellentThreshold = -50;
const goodThreshold = -70;

function validateSignalReadings(signalReadings) {
  if (!Array.isArray(signalReadings)) {
    throw new TypeError('signal readings must be provided as an array');
  }
  signalReadings.forEach((readingValue, readingIndex) => {
    if (typeof readingValue !== 'number' || Number.isNaN(readingValue)) {
      throw new TypeError(`reading at index ${readingIndex} is not a number`);
    }
    if (readingValue >= 0) {
      throw new RangeError(`reading at index ${readingIndex} must be negative`);
    }
  });
  return signalReadings;
}

function evaluate(signals) {
  const categoryCounts = [0, 0, 0];
  validateSignalReadings(signals).forEach((signalStrength) => {
    if (signalStrength >= excellentThreshold) {
      categoryCounts[0] += 1;
    } else if (signalStrength >= goodThreshold) {
      categoryCounts[1] += 1;
    } else {
      categoryCounts[2] += 1;
    }
  });
  return categoryCounts;
}

function classifySingleSignal(signalStrength) {
  if (signalStrength >= excellentThreshold) {
    return 'excellent';
  }
  return signalStrength >= goodThreshold ? 'good' : 'poor';
}

function summarizeConnectionQuality(signals) {
  const [excellentCount, goodCount, poorCount] = evaluate(signals);
  const totalSignalCount = excellentCount + goodCount + poorCount;
  const usableSignalCount = excellentCount + goodCount;
  const usablePercentage = totalSignalCount === 0
    ? 0
    : (usableSignalCount / totalSignalCount) * 100;
  return {
    excellentCount,
    goodCount,
    poorCount,
    totalSignalCount,
    usablePercentage: Math.round(usablePercentage * 10) / 10,
  };
}

function formatQualityReport(connectionLabel, signals) {
  const qualitySummary = summarizeConnectionQuality(signals);
  const headerLine = `${connectionLabel}: ${qualitySummary.totalSignalCount} readings`;
  const countsLine = `  excellent=${qualitySummary.excellentCount}`
    + ` good=${qualitySummary.goodCount}`
    + ` poor=${qualitySummary.poorCount}`;
  const usabilityLine = `  usable: ${qualitySummary.usablePercentage}%`;
  const worstReading = signals.length === 0 ? null : Math.min(...signals);
  const worstReadingLine = worstReading === null
    ? '  worst: none recorded'
    : `  worst: ${worstReading} dB (${classifySingleSignal(worstReading)})`;
  return [headerLine, countsLine, usabilityLine, worstReadingLine].join('\n');
}

function runDiagnostics(measuredConnections) {
  return Object.keys(measuredConnections)
    .map((connectionLabel) => formatQualityReport(connectionLabel, measuredConnections[connectionLabel]))
    .join('\n');
}

const measuredConnections = {
  'office-wifi': [-45, -60, -80, -40],
  'warehouse-mesh': [-72, -85, -91, -68, -55],
  'roaming-uplink': [-48, -49, -50],
};

console.log(runDiagnostics(measuredConnections));

module.exports = { evaluate, classifySingleSignal, summarizeConnectionQuality, formatQualityReport };

