const standardCleanMinutes = 15;
const deepCleanMinutes = 30;

function normalizeRoomStatus(roomStatus) {
  if (typeof roomStatus !== 'string') {
    throw new TypeError('Each room status must be a string');
  }
  return roomStatus.trim().toLowerCase();
}

function cleaningMinutesFor(roomStatus) {
  const normalizedStatus = normalizeRoomStatus(roomStatus);
  if (normalizedStatus === 'dirty') {
    return standardCleanMinutes;
  }
  if (normalizedStatus === 'checkout') {
    return deepCleanMinutes;
  }
  if (normalizedStatus === 'occupied') {
    return 0;
  }
  throw new RangeError(`Unknown room status: ${roomStatus}`);
}

function schedule(rooms) {
  if (!Array.isArray(rooms)) {
    throw new TypeError('rooms must be an array of status strings');
  }
  let totalCleaningTime = 0;
  let cleanedRoomCount = 0;
  for (const currentRoomStatus of rooms) {
    const requiredMinutes = cleaningMinutesFor(currentRoomStatus);
    if (requiredMinutes > 0) {
      totalCleaningTime += requiredMinutes;
      cleanedRoomCount += 1;
    }
  }
  return [totalCleaningTime, cleanedRoomCount];
}

function formatDuration(totalMinutes) {
  const wholeHours = Math.floor(totalMinutes / 60);
  const leftoverMinutes = totalMinutes % 60;
  if (wholeHours === 0) {
    return `${leftoverMinutes}m`;
  }
  return `${wholeHours}h ${leftoverMinutes}m`;
}

function buildShiftReport(floorName, rooms) {
  const [scheduledMinutes, roomsToClean] = schedule(rooms);
  const skippedRoomCount = rooms.length - roomsToClean;
  const averagePerRoom = roomsToClean === 0 ? 0 : scheduledMinutes / roomsToClean;
  return [
    `Floor ${floorName}: ${roomsToClean} room(s) to clean, ${skippedRoomCount} skipped`,
    `  Total time: ${formatDuration(scheduledMinutes)} (avg ${averagePerRoom.toFixed(1)}m per room)`,
  ].join('\n');
}

function runHousekeepingPlanner(floorAssignments) {
  const reportLines = [];
  let hotelWideMinutes = 0;
  for (const [floorName, roomStatuses] of Object.entries(floorAssignments)) {
    reportLines.push(buildShiftReport(floorName, roomStatuses));
    hotelWideMinutes += schedule(roomStatuses)[0];
  }
  reportLines.push(`Hotel total: ${formatDuration(hotelWideMinutes)}`);
  return reportLines.join('\n');
}

const dailyFloorAssignments = {
  '1': ['dirty', 'occupied', 'checkout'],
  '2': ['checkout', 'checkout', 'dirty', 'dirty', 'occupied'],
  '3': ['occupied', 'occupied'],
};

console.log(runHousekeepingPlanner(dailyFloorAssignments));

module.exports = { schedule, cleaningMinutesFor, buildShiftReport, runHousekeepingPlanner };

