const highTurbidityThreshold = 10;
const criticalTurbidityThreshold = 25;
const consecutiveDaysLimit = 3;

function validateReadings(rawReadings) {
  if (!Array.isArray(rawReadings)) {
    throw new TypeError('turbidity must be an array of numbers');
  }
  return rawReadings.map((singleReading, dayIndex) => {
    const numericReading = Number(singleReading);
    if (!Number.isFinite(numericReading) || numericReading < 0) {
      throw new RangeError(`invalid turbidity reading on day ${dayIndex + 1}`);
    }
    return numericReading;
  });
}

function monitor(turbidity) {
  const dailyReadings = validateReadings(turbidity);
  let consecutiveHighDays = 0;
  for (const dailyReading of dailyReadings) {
    if (dailyReading > criticalTurbidityThreshold) {
      return 'change';
    }
    if (dailyReading > highTurbidityThreshold) {
      consecutiveHighDays += 1;
      if (consecutiveHighDays >= consecutiveDaysLimit) {
        return 'change';
      }
    } else {
      consecutiveHighDays = 0;
    }
  }
  return 'normal';
}

function summariseReadings(turbidity) {
  const dailyReadings = validateReadings(turbidity);
  const readingCount = dailyReadings.length;
  const totalTurbidity = dailyReadings.reduce((runningTotal, value) => runningTotal + value, 0);
  const averageTurbidity = readingCount === 0 ? 0 : totalTurbidity / readingCount;
  const peakTurbidity = readingCount === 0 ? 0 : Math.max(...dailyReadings);
  const highDayCount = dailyReadings.filter((value) => value > highTurbidityThreshold).length;
  return { readingCount, averageTurbidity, peakTurbidity, highDayCount };
}

function formatReport(tankName, turbidity) {
  const filterStatus = monitor(turbidity);
  const readingSummary = summariseReadings(turbidity);
  const averageText = readingSummary.averageTurbidity.toFixed(1);
  const statusText = filterStatus === 'change' ? 'FILTER CHANGE REQUIRED' : 'water quality normal';
  return `${tankName}: ${readingSummary.readingCount} days, avg ${averageText}, `
    + `peak ${readingSummary.peakTurbidity}, ${readingSummary.highDayCount} day(s) over `
    + `${highTurbidityThreshold} -> ${statusText}`;
}

function runMonitoringReport(tankReadingLog) {
  const reportLines = [];
  for (const [tankName, weeklyReadings] of Object.entries(tankReadingLog)) {
    reportLines.push(formatReport(tankName, weeklyReadings));
  }
  return reportLines.join('\n');
}

const aquariumReadingLog = {
  'Reef Tank': [5, 12, 14, 11, 8],
  'Goldfish Bowl': [3, 4, 2, 9, 10, 7],
  'Quarantine Tank': [6, 8, 27, 4, 5],
  'Shrimp Tank': [11, 9, 12, 13, 6, 14],
};

console.log(runMonitoringReport(aquariumReadingLog));

module.exports = { monitor, summariseReadings, formatReport, runMonitoringReport };

