const baseNightlyRate = 20;
const hookupNightlySurcharge = 5;
const longStayNightThreshold = 7;
const longStayDiscountRate = 0.1;

function validateStayEntry(stayEntry, entryIndex) {
  if (!Array.isArray(stayEntry) || stayEntry.length !== 2) {
    throw new TypeError(`stay ${entryIndex} must be an array of [nights, hookup]`);
  }
  const [nightCount, needsElectricalHookup] = stayEntry;
  if (!Number.isInteger(nightCount) || nightCount <= 0) {
    throw new RangeError(`stay ${entryIndex} has an invalid night count: ${nightCount}`);
  }
  if (typeof needsElectricalHookup !== 'boolean') {
    throw new TypeError(`stay ${entryIndex} must state the hookup requirement as a boolean`);
  }
  return { nightCount, needsElectricalHookup };
}

function computeStayCost(nightCount, needsElectricalHookup) {
  const nightlyRate = baseNightlyRate + (needsElectricalHookup ? hookupNightlySurcharge : 0);
  const grossStayCost = nightlyRate * nightCount;
  const discountAmount = nightCount >= longStayNightThreshold
    ? grossStayCost * longStayDiscountRate
    : 0;
  return grossStayCost - discountAmount;
}

function charge(stays) {
  if (!Array.isArray(stays)) {
    throw new TypeError('charge expects an array of stays');
  }
  return stays.reduce((runningRevenue, stayEntry, entryIndex) => {
    const { nightCount, needsElectricalHookup } = validateStayEntry(stayEntry, entryIndex);
    return runningRevenue + computeStayCost(nightCount, needsElectricalHookup);
  }, 0);
}

function formatCurrencyAmount(dollarAmount) {
  return `$${dollarAmount.toFixed(2)}`;
}

function describeStay(stayEntry, entryIndex) {
  const { nightCount, needsElectricalHookup } = validateStayEntry(stayEntry, entryIndex);
  const hookupLabel = needsElectricalHookup ? 'with hookup' : 'no hookup';
  const discountLabel = nightCount >= longStayNightThreshold ? ', long-stay discount' : '';
  const stayCost = computeStayCost(nightCount, needsElectricalHookup);
  const nightLabel = nightCount === 1 ? 'night' : 'nights';
  return `${nightCount} ${nightLabel} (${hookupLabel}${discountLabel}): ${formatCurrencyAmount(stayCost)}`;
}

function buildBillingReport(stays) {
  const totalRevenue = charge(stays);
  return stays
    .map((stayEntry, entryIndex) => describeStay(stayEntry, entryIndex))
    .concat(`Total revenue: ${formatCurrencyAmount(totalRevenue)}`)
    .join('\n');
}

function main() {
  const bookedStays = [[3, false], [10, true], [7, false], [1, true]];
  console.log(buildBillingReport(bookedStays));
}

main();

module.exports = { charge, computeStayCost, buildBillingReport, formatCurrencyAmount };

