const startingEnergy = 100;
const slowModeThreshold = 20;
const normalDrainRatio = 0.5;
const slowModeDrainRatio = 0.25;

function validateImpacts(impactList) {
  if (!Array.isArray(impactList)) {
    throw new TypeError('impacts must be an array of impact speeds');
  }
  impactList.forEach((impactSpeed, impactIndex) => {
    if (typeof impactSpeed !== 'number' || !Number.isFinite(impactSpeed)) {
      throw new TypeError(`impact at index ${impactIndex} is not a finite number`);
    }
    if (impactSpeed < 0) {
      throw new RangeError(`impact at index ${impactIndex} has a negative speed`);
    }
  });
  return impactList;
}

function drainForImpact(currentEnergy, impactSpeed) {
  const activeDrainRatio = currentEnergy < slowModeThreshold ? slowModeDrainRatio : normalDrainRatio;
  return impactSpeed * activeDrainRatio;
}

function applyImpact(currentEnergy, impactSpeed) {
  return Math.max(0, currentEnergy - drainForImpact(currentEnergy, impactSpeed));
}

function simulate(impacts) {
  const validatedImpacts = validateImpacts(impacts);
  return validatedImpacts.reduce(applyImpact, startingEnergy);
}

function formatImpactLine(lineIndex, impactSpeed, energyBeforeImpact, energyAfterImpact) {
  const modeLabel = energyBeforeImpact < slowModeThreshold ? 'slow' : 'normal';
  const drainedText = (energyBeforeImpact - energyAfterImpact).toFixed(2);
  return `#${lineIndex + 1} speed ${impactSpeed} (${modeLabel}): -${drainedText} -> ${energyAfterImpact.toFixed(2)}`;
}

function buildEnergyReport(impacts) {
  const validatedImpacts = validateImpacts(impacts);
  const reportLines = [];
  let remainingEnergy = startingEnergy;
  validatedImpacts.forEach((impactSpeed, impactIndex) => {
    const energyBeforeImpact = remainingEnergy;
    remainingEnergy = applyImpact(energyBeforeImpact, impactSpeed);
    reportLines.push(formatImpactLine(impactIndex, impactSpeed, energyBeforeImpact, remainingEnergy));
  });
  reportLines.push(`final energy: ${remainingEnergy.toFixed(2)}`);
  return reportLines.join('\n');
}

function runDriver(impactScenarios) {
  impactScenarios.forEach((scenarioImpacts, scenarioIndex) => {
    console.log(`scenario ${scenarioIndex + 1}: [${scenarioImpacts.join(', ')}]`);
    console.log(buildEnergyReport(scenarioImpacts));
  });
}

runDriver([[100, 70, 20], [40, 40, 40, 40, 40, 40], []]);

module.exports = { simulate };

