const conePriceDollars = 3;
const baseManufacturingCost = 1;
const coolingCostPerCone = 0.5;
const highTemperatureThreshold = 90;

function validateDailyRecord(dailyRecord, dayIndex) {
  if (!Array.isArray(dailyRecord) || dailyRecord.length !== 2) {
    throw new TypeError(`Day ${dayIndex + 1}: expected a [cones, temperature] pair`);
  }
  const [conesSold, highTemperature] = dailyRecord;
  if (!Number.isFinite(conesSold) || conesSold < 0) {
    throw new RangeError(`Day ${dayIndex + 1}: cone count must be a non-negative number`);
  }
  if (!Number.isFinite(highTemperature)) {
    throw new TypeError(`Day ${dayIndex + 1}: temperature must be a number`);
  }
  return { conesSold, highTemperature };
}

function manufacturingCostPerCone(highTemperature) {
  if (highTemperature > highTemperatureThreshold) {
    return baseManufacturingCost + coolingCostPerCone;
  }
  return baseManufacturingCost;
}

function computeDailyProfit(conesSold, highTemperature) {
  const dailyRevenue = conesSold * conePriceDollars;
  const dailyCost = conesSold * manufacturingCostPerCone(highTemperature);
  return dailyRevenue - dailyCost;
}

function calculate(data) {
  if (!Array.isArray(data)) {
    throw new TypeError('calculate expects an array of [cones, temperature] pairs');
  }
  return data.reduce((runningProfitTotal, dailyRecord, dayIndex) => {
    const { conesSold, highTemperature } = validateDailyRecord(dailyRecord, dayIndex);
    return runningProfitTotal + computeDailyProfit(conesSold, highTemperature);
  }, 0);
}

function formatDollarAmount(amountInDollars) {
  return `$${amountInDollars.toFixed(2)}`;
}

function buildProfitReport(data) {
  const dailyLines = data.map((dailyRecord, dayIndex) => {
    const { conesSold, highTemperature } = validateDailyRecord(dailyRecord, dayIndex);
    const dailyProfit = computeDailyProfit(conesSold, highTemperature);
    const coolingNotice = highTemperature > highTemperatureThreshold ? ' (cooling surcharge applied)' : '';
    return `Day ${dayIndex + 1}: ${conesSold} cones at ${highTemperature}\u00B0 -> ${formatDollarAmount(dailyProfit)}${coolingNotice}`;
  });
  const totalProfitDollars = calculate(data);
  dailyLines.push(`Total profit: ${formatDollarAmount(totalProfitDollars)}`);
  return dailyLines.join('\n');
}

function runStandReport() {
  const weeklySalesData = [
    [100, 85],
    [100, 95],
    [42, 91],
    [0, 78],
  ];
  console.log(buildProfitReport(weeklySalesData));
}

runStandReport();

module.exports = { calculate, computeDailyProfit, buildProfitReport };

