    throw new TypeError(`Day ${day_index + 1}: temperature must be a number`);
  }
  return { cones_sold, high_temperature };
}

function manufacturing_cost_per_cone(high_temperature) {
  if (high_temperature > high_temperature_threshold) {
    return base_manufacturing_cost + cooling_cost_per_cone;
  }
  return base_manufacturing_cost;
}

function compute_daily_profit(cones_sold, high_temperature) {
  const daily_revenue = cones_sold * cone_price_dollars;
  const daily_cost = cones_sold * manufacturing_cost_per_cone(high_temperature);
  return daily_revenue - daily_cost;
}

function calculate(data) {
  if (!Array.isArray(data)) {
    throw new TypeError('calculate expects an array of [cones, temperature] pairs');
  }
  return data.reduce((running_profit_total, daily_record, day_index) => {
    const { cones_sold, high_temperature } = validate_daily_record(daily_record, day_index);
    return running_profit_total + compute_daily_profit(cones_sold, high_temperature);
  }, 0);
}

function format_dollar_amount(amount_in_dollars) {
  return `$${amount_in_dollars.toFixed(2)}`;
}

function build_profit_report(data) {
  const daily_lines = data.map((daily_record, day_index) => {
    const { cones_sold, high_temperature } = validate_daily_record(daily_record, day_index);
    const daily_profit = compute_daily_profit(cones_sold, high_temperature);
    const cooling_notice = high_temperature > high_temperature_threshold ? ' (cooling surcharge applied)' : '';
    return `Day ${day_index + 1}: ${cones_sold} cones at ${high_temperature}\u00B0 -> ${format_dollar_amount(daily_profit)}${cooling_notice}`;
  });
  const total_profit_dollars = calculate(data);
  daily_lines.push(`Total profit: ${format_dollar_amount(total_profit_dollars)}`);
  return daily_lines.join('\n');
}

function run_stand_report() {
  const weekly_sales_data = [
    [100, 85],
    [100, 95],
    [42, 91],
    [0, 78],
  ];
  console.log(build_profit_report(weekly_sales_data));
}

run_stand_report();

module.exports = { calculate, compute_daily_profit, build_profit_report };

