const caloriesPerMinuteByActivity = {
  running: 10,
  cycling: 8,
  walking: 5
};

const enduranceThresholdMinutes = 45;
const enduranceBonusCalories = 50;

function normalizeActivityName(rawActivityName) {
  return String(rawActivityName).trim().toLowerCase();
}

function validateActivityEntry(activityEntry) {
  if (!Array.isArray(activityEntry) || activityEntry.length < 2) {
    throw new TypeError('Each activity must be an [name, minutes] pair');
  }
  const activityName = normalizeActivityName(activityEntry[0]);
  const durationMinutes = activityEntry[1];
  if (typeof durationMinutes !== 'number' || !Number.isFinite(durationMinutes) || durationMinutes < 0) {
    throw new RangeError(`Invalid duration for "${activityName}": ${activityEntry[1]}`);
  }
  if (!Object.prototype.hasOwnProperty.call(caloriesPerMinuteByActivity, activityName)) {
    throw new Error(`Unknown activity: "${activityName}"`);
  }
  return { activityName, durationMinutes };
}

function caloriesForActivity(activityName, durationMinutes) {
  const burnRatePerMinute = caloriesPerMinuteByActivity[activityName];
  const baseCalories = burnRatePerMinute * durationMinutes;
  const bonusCalories = durationMinutes > enduranceThresholdMinutes ? enduranceBonusCalories : 0;
  return baseCalories + bonusCalories;
}

function buildActivityBreakdown(activities) {
  if (!Array.isArray(activities)) {
    throw new TypeError('activities must be an array of [name, minutes] pairs');
  }
  return activities.map(function (activityEntry) {
    const { activityName, durationMinutes } = validateActivityEntry(activityEntry);
    const caloriesBurned = caloriesForActivity(activityName, durationMinutes);
    const earnedEnduranceBonus = durationMinutes > enduranceThresholdMinutes;
    return { activityName, durationMinutes, caloriesBurned, earnedEnduranceBonus };
  });
}

function evaluate(activities) {
  return buildActivityBreakdown(activities).reduce(function (runningTotal, breakdownRow) {
    return runningTotal + breakdownRow.caloriesBurned;
  }, 0);
}

function formatWorkoutReport(activities) {
  const breakdownRows = buildActivityBreakdown(activities);
  const totalMinutes = breakdownRows.reduce(function (minuteSum, breakdownRow) {
    return minuteSum + breakdownRow.durationMinutes;
  }, 0);
