    return `${breakdownRow.activityName.padEnd(8)} ${String(breakdownRow.durationMinutes).padStart(4)} min -> ` +
      `${breakdownRow.caloriesBurned} cal${bonusMarker}`;
  });
  reportLines.push(`total: ${totalMinutes} min, ${evaluate(activities)} cal`);
  return reportLines.join('\n');
}

