const overtimeThresholdHours = 6;
const overtimeBonusRate = 0.5;

function adjustedShiftHours(shiftHours) {
  if (shiftHours <= overtimeThresholdHours) {
    return shiftHours;
  }
  const overtimeHours = shiftHours - overtimeThresholdHours;
  return shiftHours + overtimeHours * overtimeBonusRate;
}

function totalAdjustedHours(shiftList) {
  return shiftList.reduce(
    (runningTotal, shiftHours) => runningTotal + adjustedShiftHours(shiftHours),
    0
  );
}

function validateGratuityInput(shiftList, tipPool) {
  if (!Array.isArray(shiftList)) {
    throw new TypeError('shifts must be an array of hours worked');
  }
  shiftList.forEach((shiftHours, serverIndex) => {
    if (typeof shiftHours !== 'number' || !Number.isFinite(shiftHours) || shiftHours < 0) {
      throw new RangeError(`invalid hours for server ${serverIndex}: ${shiftHours}`);
    }
  });
  if (typeof tipPool !== 'number' || !Number.isFinite(tipPool) || tipPool < 0) {
    throw new RangeError(`invalid tip pool: ${tipPool}`);
  }
}

function gratuity(shifts, pool) {
  validateGratuityInput(shifts, pool);
  const adjustedHoursTotal = totalAdjustedHours(shifts);
  if (adjustedHoursTotal === 0) {
    return shifts.map(() => 0);
  }
  const tipValuePerHour = pool / adjustedHoursTotal;
  return shifts.map((shiftHours) => Math.floor(adjustedShiftHours(shiftHours) * tipValuePerHour));
}

function formatCurrencyAmount(amountInWholeUnits) {
  return `$${amountInWholeUnits.toFixed(2)}`;
}

function formatPayoutReport(shifts, pool) {
  const payoutAmounts = gratuity(shifts, pool);
  const adjustedHoursTotal = totalAdjustedHours(shifts);
  const tipValuePerHour = adjustedHoursTotal === 0 ? 0 : pool / adjustedHoursTotal;
  const reportLines = shifts.map((shiftHours, serverIndex) => {
    const serverLabel = `Server ${serverIndex + 1}`;
    const creditedHours = adjustedShiftHours(shiftHours);
    return `${serverLabel}: ${shiftHours}h worked, ${creditedHours}h credited -> ${formatCurrencyAmount(payoutAmounts[serverIndex])}`;
  });
  const distributedTotal = payoutAmounts.reduce((sum, amount) => sum + amount, 0);
  const unallocatedRemainder = pool - distributedTotal;
  reportLines.push(`Adjusted hours: ${adjustedHoursTotal}, rate ${formatCurrencyAmount(tipValuePerHour)}/h`);
  reportLines.push(
    `Distributed ${formatCurrencyAmount(distributedTotal)}, left in pool ${formatCurrencyAmount(unallocatedRemainder)}`
  );
  return reportLines.join('\n');
}

function main() {
  const eveningShiftHours = [4, 8];
  const eveningTipPool = 100;
  console.log(formatPayoutReport(eveningShiftHours, eveningTipPool));

  const weekendShiftHours = [6, 7.5, 10, 3];
  const weekendTipPool = 420;
  console.log(formatPayoutReport(weekendShiftHours, weekendTipPool));

  const closingCrewShares = gratuity([9, 9, 6], 250);
  console.log(`Closing crew shares: ${closingCrewShares.join(', ')}`);
}

main();

module.exports = { gratuity, adjustedShiftHours, totalAdjustedHours, formatPayoutReport };

