const yieldPerAcre = 40;
const yieldPerFertilizerPound = 1.5;
const maxYieldPerAcre = 60;

function validatePlotEntry(plotEntry, plotPosition) {
  if (!Array.isArray(plotEntry) || plotEntry.length !== 2) {
    throw new TypeError(`plot ${plotPosition} must be a [area, fertilizer] pair`);
  }
  const [plotArea, fertilizerPounds] = plotEntry;
  if (typeof plotArea !== 'number' || typeof fertilizerPounds !== 'number') {
    throw new TypeError(`plot ${plotPosition} must contain numbers`);
  }
  if (plotArea < 0 || fertilizerPounds < 0) {
    throw new RangeError(`plot ${plotPosition} cannot have negative values`);
  }
}

function computePlotYield(plotEntry) {
  const [plotArea, fertilizerPounds] = plotEntry;
  const rawYield = plotArea * yieldPerAcre + fertilizerPounds * yieldPerFertilizerPound;
  const yieldCeiling = plotArea * maxYieldPerAcre;
  return Math.min(rawYield, yieldCeiling);
}

function computePlotEfficiency(plotEntry) {
  const fertilizerPounds = plotEntry[1];
  const estimatedYield = computePlotYield(plotEntry);
  if (fertilizerPounds === 0) {
    return estimatedYield > 0 ? Infinity : 0;
  }
  return estimatedYield / fertilizerPounds;
}

function harvest(plots) {
  let totalEstimatedYield = 0;
  let bestEfficiencySoFar = -Infinity;
  let mostEfficientPlotIndex = 0;
  plots.forEach((plotEntry, arrayIndex) => {
    const oneBasedIndex = arrayIndex + 1;
    validatePlotEntry(plotEntry, oneBasedIndex);
    totalEstimatedYield += computePlotYield(plotEntry);
    const plotEfficiency = computePlotEfficiency(plotEntry);
    if (plotEfficiency > bestEfficiencySoFar) {
      bestEfficiencySoFar = plotEfficiency;
      mostEfficientPlotIndex = oneBasedIndex;
    }
  });
  return [Math.floor(totalEstimatedYield), mostEfficientPlotIndex];
}

function describePlotLine(plotEntry, oneBasedIndex) {
  const [plotArea, fertilizerPounds] = plotEntry;
  const estimatedYield = computePlotYield(plotEntry);
  const plotEfficiency = computePlotEfficiency(plotEntry);
  const efficiencyText = Number.isFinite(plotEfficiency) ? plotEfficiency.toFixed(2) : 'unlimited';
  return `Plot ${oneBasedIndex}: ${plotArea} acres, ${fertilizerPounds} lb fertilizer ` +
    `-> ${estimatedYield.toFixed(1)} bushels (efficiency ${efficiencyText})`;
}

function formatHarvestReport(plots) {
  const [totalYield, bestPlotIndex] = harvest(plots);
  const reportLines = plots.map((plotEntry, arrayIndex) => describePlotLine(plotEntry, arrayIndex + 1));
  reportLines.push(`Total estimated yield: ${totalYield} bushels`);
  if (bestPlotIndex === 0) {
    reportLines.push('No plots were evaluated.');
  } else {
    reportLines.push(`Most efficient plot: ${bestPlotIndex}`);
  }
  return reportLines.join('\n');
}

function main() {
  const farmPlots = [[10, 200], [5, 400], [2, 0], [8, 150]];
  console.log(formatHarvestReport(farmPlots));
  const harvestSummary = harvest(farmPlots);
  console.log(`harvest() returned [${harvestSummary.join(', ')}]`);
}

main();

module.exports = { harvest, computePlotYield, computePlotEfficiency, formatHarvestReport };

