const highIntensityThreshold = 50;

function validateIntensities(intensityReadings) {
  if (!Array.isArray(intensityReadings)) {
    throw new TypeError('intensity readings must be provided as an array');
  }
  intensityReadings.forEach((readingValue, readingIndex) => {
    if (!Number.isInteger(readingValue)) {
      throw new TypeError(`reading at index ${readingIndex} is not an integer: ${readingValue}`);
    }
  });
  return intensityReadings;
}

function flares(intensities) {
  const validatedReadings = validateIntensities(intensities);
  let peakIntensity = 0;
  let highIntensityCount = 0;
  let totalThreatScore = 0;
  let consecutiveMultiplier = 1;

  validatedReadings.forEach((currentIntensity) => {
    if (currentIntensity > peakIntensity) {
      peakIntensity = currentIntensity;
    }
    if (currentIntensity > highIntensityThreshold) {
      highIntensityCount += 1;
      totalThreatScore += currentIntensity * consecutiveMultiplier;
      consecutiveMultiplier += 1;
    } else {
      consecutiveMultiplier = 1;
    }
  });

  return [peakIntensity, highIntensityCount, totalThreatScore];
}

function longestHighIntensityStreak(intensityReadings) {
  let longestStreakLength = 0;
  let currentStreakLength = 0;
  intensityReadings.forEach((currentIntensity) => {
    if (currentIntensity > highIntensityThreshold) {
      currentStreakLength += 1;
      if (currentStreakLength > longestStreakLength) {
        longestStreakLength = currentStreakLength;
      }
    } else {
      currentStreakLength = 0;
    }
  });
  return longestStreakLength;
}

function formatActivityReport(observationLabel, intensityReadings) {
  const [peakIntensity, highIntensityCount, totalThreatScore] = flares(intensityReadings);
  const streakLength = longestHighIntensityStreak(intensityReadings);
  const reportLines = [
    `Observation window: ${observationLabel}`,
    `Days recorded: ${intensityReadings.length}`,
    `Peak intensity: ${peakIntensity}`,
    `Flares above ${highIntensityThreshold}: ${highIntensityCount}`,
    `Longest consecutive high streak: ${streakLength}`,
    `Threat score: ${totalThreatScore}`,
  ];
  return reportLines.join('\n');
}

function runObservatoryAnalysis(observationLog) {
  return Object.entries(observationLog)
    .map(([observationLabel, intensityReadings]) => formatActivityReport(observationLabel, intensityReadings))
    .join('\n\n');
}

