const minimumPayableDownloads = 10000;
const bonusThresholdDownloads = 50000;
const bonusRateMultiplier = 1.5;

function assertValidRate(baseRate) {
  if (typeof baseRate !== 'number' || !Number.isFinite(baseRate) || baseRate < 0) {
    throw new TypeError('rate must be a non-negative finite number');
  }
}

function normalizeDownloadCount(rawCount, episodeIndex) {
  if (typeof rawCount !== 'number' || !Number.isFinite(rawCount) || rawCount < 0) {
    throw new TypeError(`episode ${episodeIndex + 1} has an invalid download count`);
  }
  return Math.floor(rawCount);
}

function episodeEarnings(episodeDownloads, baseRate) {
  if (episodeDownloads < minimumPayableDownloads) {
    return 0;
  }
  const ratePerThousand = baseRate / 1000;
  if (episodeDownloads <= bonusThresholdDownloads) {
    return episodeDownloads * ratePerThousand;
  }
  const bonusDownloads = episodeDownloads - bonusThresholdDownloads;
  const baseEarnings = bonusThresholdDownloads * ratePerThousand;
  const bonusEarnings = bonusDownloads * ratePerThousand * bonusRateMultiplier;
  return baseEarnings + bonusEarnings;
}

function sponsor(downloads, rate) {
  if (!Array.isArray(downloads)) {
    throw new TypeError('downloads must be an array of episode download counts');
  }
  assertValidRate(rate);
  const totalEarnings = downloads.reduce((runningTotal, rawCount, episodeIndex) => {
    const cleanCount = normalizeDownloadCount(rawCount, episodeIndex);
    return runningTotal + episodeEarnings(cleanCount, rate);
  }, 0);
  return Math.floor(totalEarnings);
}

function describeEpisode(episodeDownloads, baseRate, episodeIndex) {
  const earnedAmount = episodeEarnings(episodeDownloads, baseRate);
  const episodeLabel = `Episode ${String(episodeIndex + 1).padStart(2, '0')}`;
  const downloadLabel = episodeDownloads.toLocaleString('en-US');
  const payoutLabel = earnedAmount.toFixed(2);
  return `${episodeLabel}: ${downloadLabel} downloads -> $${payoutLabel}`;
}

function buildEarningsReport(downloads, rate) {
  const reportLines = downloads.map((rawCount, episodeIndex) => {
    const cleanCount = normalizeDownloadCount(rawCount, episodeIndex);
    return describeEpisode(cleanCount, rate, episodeIndex);
  });
  const grandTotal = sponsor(downloads, rate);
  reportLines.push(`Total (rounded down): $${grandTotal}`);
  return reportLines.join('\n');
}

function runSeasonSummary() {
  const seasonDownloads = [8200, 10000, 33500, 50000, 74800, 125000];
  const baseSponsorRate = 25;
  console.log(buildEarningsReport(seasonDownloads, baseSponsorRate));

  const reruns = [9999, 51000];
  const rerunRate = 12.5;
  const rerunEarnings = sponsor(reruns, rerunRate);
  console.log(`Rerun earnings at $${rerunRate}/1k: $${rerunEarnings}`);
}

runSeasonSummary();

module.exports = { sponsor, episodeEarnings, buildEarningsReport };

