const baseConsumptionRate = 0.2;
const cruiseConsumptionRate = 0.15;
const cruiseDistanceThreshold = 500;

function legFuelCost(legDistance) {
  const consumptionRate =
    legDistance > cruiseDistanceThreshold ? cruiseConsumptionRate : baseConsumptionRate;
  return legDistance * consumptionRate;
}

function validateVoyageInput(legs, fuel) {
  if (!Array.isArray(legs)) {
    throw new TypeError('legs must be an array of nautical mile distances');
  }
  const invalidLegIndex = legs.findIndex(
    (legDistance) => typeof legDistance !== 'number' || !Number.isFinite(legDistance) || legDistance < 0
  );
  if (invalidLegIndex !== -1) {
    throw new RangeError(`leg ${invalidLegIndex} is not a valid distance`);
  }
  if (typeof fuel !== 'number' || !Number.isFinite(fuel)) {
    throw new TypeError('fuel must be a finite number of tons');
  }
}

function voyage(legs, fuel) {
  validateVoyageInput(legs, fuel);
  let remainingFuel = fuel;
  for (const legDistance of legs) {
    remainingFuel -= legFuelCost(legDistance);
    if (remainingFuel < 0) {
      return [0, Math.floor(remainingFuel)];
    }
  }
  return [1, Math.floor(remainingFuel)];
}

function formatLogbook(legs, fuel) {
  let fuelOnBoard = fuel;
  const logLines = [];
  legs.forEach((legDistance, legIndex) => {
    const fuelBurned = legFuelCost(legDistance);
    fuelOnBoard -= fuelBurned;
    const legNumber = legIndex + 1;
    const statusLabel = fuelOnBoard < 0 ? 'STRANDED' : 'under way';
    const burnedTons = fuelBurned.toFixed(2);
    const onBoardTons = fuelOnBoard.toFixed(2);
    logLines.push(
      `Leg ${legNumber}: ${legDistance} nm, burned ${burnedTons} t, ` +
        `${onBoardTons} t aboard (${statusLabel})`
    );
  });
  return logLines.join('\n');
}

function reportVoyage(routeName, legs, fuel) {
  const [completionFlag, fuelRemaining] = voyage(legs, fuel);
  const outcomeText = completionFlag === 1 ? 'route completed' : 'ship stranded';
  const logbookText = formatLogbook(legs, fuel);
  return `${routeName}: ${outcomeText}, ${fuelRemaining} t left\n${logbookText}`;
}

const northAtlanticRoute = [320, 640, 180];
const southPacificRoute = [700, 520, 480, 610];

console.log(reportVoyage('North Atlantic', northAtlanticRoute, 300));
console.log(reportVoyage('South Pacific', southPacificRoute, 250));

