const minimumStreakInches = 1;
const heavySnowThreshold = 6;

function validateDailyMeasurements(daily) {
  if (!Array.isArray(daily)) {
    throw new TypeError('snowfall expects an array of daily measurements');
  }
  return daily.map((rawMeasurement, dayIndex) => {
    const parsedMeasurement = typeof rawMeasurement === 'string'
      ? Number.parseFloat(rawMeasurement)
      : rawMeasurement;
    if (typeof parsedMeasurement !== 'number' || Number.isNaN(parsedMeasurement)) {
      throw new TypeError(`Measurement for day ${dayIndex + 1} is not a number`);
    }
    if (parsedMeasurement < 0) {
      throw new RangeError(`Measurement for day ${dayIndex + 1} is negative`);
    }
    return parsedMeasurement;
  });
}

function snowfall(daily) {
  const cleanMeasurements = validateDailyMeasurements(daily);
  let totalSnowfall = 0;
  let longestSnowStreak = 0;
  let currentSnowStreak = 0;
  let heavySnowDays = 0;

  for (const dailyInches of cleanMeasurements) {
    totalSnowfall += dailyInches;
    if (dailyInches >= minimumStreakInches) {
      currentSnowStreak += 1;
      if (currentSnowStreak > longestSnowStreak) {
        longestSnowStreak = currentSnowStreak;
      }
    } else {
      currentSnowStreak = 0;
    }
    if (dailyInches > heavySnowThreshold) {
      heavySnowDays += 1;
    }
  }

  return [Number(totalSnowfall.toFixed(2)), longestSnowStreak, heavySnowDays];
}

function averageDailySnowfall(daily) {
  const [totalSnowfall] = snowfall(daily);
  if (daily.length === 0) {
    return 0;
  }
  return Number((totalSnowfall / daily.length).toFixed(2));
}

function formatSeasonReport(seasonName, daily) {
  const [totalSnowfall, longestSnowStreak, heavySnowDays] = snowfall(daily);
  const dailyAverage = averageDailySnowfall(daily);
  const reportLines = [
    `Season: ${seasonName}`,
    `Total snowfall: ${totalSnowfall} in over ${daily.length} days`,
    `Longest streak of snow days: ${longestSnowStreak}`,
    `Heavy snow days (> ${heavySnowThreshold} in): ${heavySnowDays}`,
    `Average per day: ${dailyAverage} in`,
  ];
  return reportLines.join('\n');
}

const winterMeasurements = [0, 2.5, 3, 1, 0.5, 8, 7.2, 1.1, 0, 4, 6.5, 2];
const springMeasurements = ['1.0', '0.2', 12, 6.1, 0, 0.9, 3.4];

console.log(formatSeasonReport('Winter', winterMeasurements));
console.log('');
console.log(formatSeasonReport('Spring', springMeasurements));

const combinedMeasurements = winterMeasurements.concat(
  springMeasurements.map(Number),
);
const [seasonTotal, seasonStreak, seasonHeavyDays] = snowfall(combinedMeasurements);
console.log(`\nFull season: ${seasonTotal} in, streak ${seasonStreak}, heavy ${seasonHeavyDays}`);

