const fuelPerFlightMinute = 2;
const hoistFuelPerMission = 5;
const reserveFuelGallons = 20;

function missionFuelRequirement(flightMinutes) {
  return flightMinutes * fuelPerFlightMinute + hoistFuelPerMission;
}

function validateMissionList(missionList) {
  if (!Array.isArray(missionList)) {
    throw new TypeError('missions must be an array of flight times in minutes');
  }
  missionList.forEach((flightMinutes, missionIndex) => {
    if (typeof flightMinutes !== 'number' || !Number.isFinite(flightMinutes) || flightMinutes < 0) {
      throw new RangeError(`mission ${missionIndex + 1} has an invalid flight time: ${flightMinutes}`);
    }
  });
}

function rescue(missions, fuel) {
  validateMissionList(missions);
  if (typeof fuel !== 'number' || !Number.isFinite(fuel)) {
    throw new TypeError('fuel must be a finite number of gallons');
  }
  let remainingFuel = fuel;
  let completedMissions = 0;
  for (const flightMinutes of missions) {
    const requiredFuel = missionFuelRequirement(flightMinutes);
    if (remainingFuel - requiredFuel < reserveFuelGallons) {
      break;
    }
    remainingFuel -= requiredFuel;
    completedMissions += 1;
  }
  return [completedMissions, remainingFuel];
}

function formatRescueReport(missionList, startingFuel) {
  const [completedMissions, remainingFuel] = rescue(missionList, startingFuel);
  const abortedMissions = missionList.length - completedMissions;
  const deployableFuel = Math.max(remainingFuel - reserveFuelGallons, 0);
  const reportLines = [
    `Missions requested: ${missionList.length}`,
    `Missions completed: ${completedMissions}`,
    `Missions aborted:   ${abortedMissions}`,
    `Fuel remaining:     ${remainingFuel} gal`,
    `Above reserve:      ${deployableFuel} gal`
  ];
  if (abortedMissions > 0) {
    const firstAbortedIndex = completedMissions;
    const shortfallGallons =
      missionFuelRequirement(missionList[firstAbortedIndex]) - (remainingFuel - reserveFuelGallons);
    reportLines.push(`Returned to base short ${shortfallGallons} gal for mission ${firstAbortedIndex + 1}`);
  }
  return reportLines.join('\n');
}

function parseFlightPlan(commandLineArgs) {
  const [fuelArgument, ...missionArguments] = commandLineArgs;
  const startingFuel = Number(fuelArgument);
  if (!Number.isFinite(startingFuel)) {
    throw new RangeError(`initial fuel "${fuelArgument}" is not a number of gallons`);
  }
  const missionList = missionArguments.map((minutesArgument) => Number(minutesArgument));
  validateMissionList(missionList);
  return { startingFuel, missionList };
}

function main() {
  const commandLineArgs = process.argv.slice(2);
  if (commandLineArgs.length === 0) {
    console.error('usage: node rescue.js <fuelGallons> <missionMinutes...>');
    process.exitCode = 1;
    return;
  }
  const { startingFuel, missionList } = parseFlightPlan(commandLineArgs);
  console.log(formatRescueReport(missionList, startingFuel));
}

main();

module.exports = { rescue, missionFuelRequirement, formatRescueReport, parseFlightPlan };

