const basePaperPrice = 2.0;
const bulkPaperPrice = 1.5;
const bulkDiscountThreshold = 50;
const smallRouteThreshold = 10;
const smallRouteSurcharge = 5.0;

function validateRouteList(routes) {
  if (!Array.isArray(routes)) {
    throw new TypeError('deliver expects an array of subscriber counts');
  }
  routes.forEach((subscriberCount, routeIndex) => {
    if (typeof subscriberCount !== 'number' || !Number.isInteger(subscriberCount)) {
      throw new TypeError(`route ${routeIndex} has a non-integer subscriber count`);
    }
    if (subscriberCount < 0) {
      throw new RangeError(`route ${routeIndex} cannot have a negative subscriber count`);
    }
  });
  return routes;
}

function unitPriceForRoute(subscriberCount) {
  return subscriberCount > bulkDiscountThreshold ? bulkPaperPrice : basePaperPrice;
}

function surchargeForRoute(subscriberCount) {
  return subscriberCount < smallRouteThreshold ? smallRouteSurcharge : 0;
}

function routeRevenue(subscriberCount) {
  const perPaperPrice = unitPriceForRoute(subscriberCount);
  const deliverySurcharge = surchargeForRoute(subscriberCount);
  return subscriberCount * perPaperPrice + deliverySurcharge;
}

function deliver(routes) {
  const validatedRoutes = validateRouteList(routes);
  const rawDailyRevenue = validatedRoutes.reduce(
    (runningTotal, subscriberCount) => runningTotal + routeRevenue(subscriberCount),
    0
  );
  return Math.floor(rawDailyRevenue);
}

function buildRouteBreakdown(routes) {
  return validateRouteList(routes).map((subscriberCount, routeIndex) => {
    const appliedUnitPrice = unitPriceForRoute(subscriberCount);
    return {
      label: `route-${routeIndex + 1}`,
      subscribers: subscriberCount,
      unitPrice: appliedUnitPrice,
      bulkDiscounted: appliedUnitPrice === bulkPaperPrice,
      surcharge: surchargeForRoute(subscriberCount),
      revenue: routeRevenue(subscriberCount)
    };
  });
}

function formatBreakdownReport(routes) {
  const breakdownRows = buildRouteBreakdown(routes);
  const reportLines = breakdownRows.map((routeSummary) => {
    const priceNote = routeSummary.bulkDiscounted ? 'bulk' : 'base';
    const surchargeNote = routeSummary.surcharge > 0 ? ' +$5 surcharge' : '';
    return `${routeSummary.label}: ${routeSummary.subscribers} papers @ $${routeSummary.unitPrice.toFixed(2)} (${priceNote})${surchargeNote} => $${routeSummary.revenue.toFixed(2)}`;
  });
  reportLines.push(`daily revenue (rounded down): $${deliver(routes)}`);
  return reportLines.join('\n');
}

function main() {
  const todaysRoutes = [65, 12, 4, 50, 51, 9];
  console.log(formatBreakdownReport(todaysRoutes));
}

main();

module.exports = { deliver, routeRevenue, buildRouteBreakdown, formatBreakdownReport };

