const maxWeightCapacity = 5000;
const maxDeckSpace = 20;

function validateVehicleEntry(vehicleEntry, entryIndex) {
  if (!Array.isArray(vehicleEntry) || vehicleEntry.length !== 2) {
    throw new TypeError(`vehicle at index ${entryIndex} must be [weight, length]`);
  }
  const [vehicleWeight, vehicleLength] = vehicleEntry;
  if (typeof vehicleWeight !== 'number' || typeof vehicleLength !== 'number') {
    throw new TypeError(`vehicle at index ${entryIndex} has non-numeric measurements`);
  }
  if (vehicleWeight <= 0 || vehicleLength <= 0) {
    throw new RangeError(`vehicle at index ${entryIndex} must have positive measurements`);
  }
  return { vehicleWeight, vehicleLength };
}

function ferry(vehicles) {
  if (!Array.isArray(vehicles)) {
    throw new TypeError('vehicles must be an array');
  }
  let loadedWeight = 0;
  let occupiedSpace = 0;
  let loadedCount = 0;
  for (let vehicleIndex = 0; vehicleIndex < vehicles.length; vehicleIndex += 1) {
    const { vehicleWeight, vehicleLength } = validateVehicleEntry(vehicles[vehicleIndex], vehicleIndex);
    if (loadedWeight + vehicleWeight > maxWeightCapacity) break;
    if (occupiedSpace + vehicleLength > maxDeckSpace) break;
    loadedWeight += vehicleWeight;
    occupiedSpace += vehicleLength;
    loadedCount += 1;
  }
  const leftBehindCount = vehicles.length - loadedCount;
  return [loadedWeight, leftBehindCount];
}

function describeCrossing(vehicles) {
  const [loadedWeight, leftBehindCount] = ferry(vehicles);
  const remainingCapacity = maxWeightCapacity - loadedWeight;
  const vehiclesLoaded = vehicles.length - leftBehindCount;
  const weightLine = `loaded ${vehiclesLoaded} vehicle(s) weighing ${loadedWeight} kg`;
  const spareLine = `${remainingCapacity} kg of capacity to spare`;
  const dockLine = leftBehindCount === 0
    ? 'the dock is empty'
    : `${leftBehindCount} vehicle(s) left at the dock`;
  return `${weightLine}, ${spareLine}; ${dockLine}`;
}

function runFerrySchedule(waitingQueues) {
  return waitingQueues.map((queuedVehicles, queueIndex) => {
    const crossingNumber = queueIndex + 1;
    return `Crossing ${crossingNumber}: ${describeCrossing(queuedVehicles)}`;
  });
}

const morningQueue = [[1200, 4], [900, 3.5], [2500, 6], [1500, 5]];
const afternoonQueue = [[800, 3], [750, 3], [820, 3], [900, 3.5], [680, 3], [1100, 4.5]];
const eveningQueue = [[4800, 8], [300, 2]];

const scheduleReport = runFerrySchedule([morningQueue, afternoonQueue, eveningQueue]);
scheduleReport.forEach((reportLine) => console.log(reportLine));

const [eveningWeight, eveningLeftBehind] = ferry(eveningQueue);
console.log(`Evening result array: [${eveningWeight}, ${eveningLeftBehind}]`);

module.exports = { ferry, describeCrossing, runFerrySchedule };

