const minutesPerDegree = 15;
const kilowattsPerHour = 2;
const minutesPerHour = 60;

function validateReadings(temperatures, target) {
  if (!Array.isArray(temperatures)) {
    throw new TypeError('temperatures must be an array of hourly readings');
  }
  if (typeof target !== 'number' || Number.isNaN(target)) {
    throw new TypeError('target must be a number');
  }
  temperatures.forEach(function (hourlyReading, hourIndex) {
    if (typeof hourlyReading !== 'number' || Number.isNaN(hourlyReading)) {
      throw new TypeError('reading at hour ' + hourIndex + ' is not a number');
    }
  });
}

function computeRunMinutes(roomTemperature, targetTemperature) {
  const degreesAboveTarget = roomTemperature - targetTemperature;
  if (degreesAboveTarget <= 0) {
    return 0;
  }
  return degreesAboveTarget * minutesPerDegree;
}

function regulate(temperatures, target) {
  validateReadings(temperatures, target);
  let accumulatedMinutes = 0;
  temperatures.forEach(function (hourlyReading) {
    accumulatedMinutes += computeRunMinutes(hourlyReading, target);
  });
  const energyConsumed = (accumulatedMinutes / minutesPerHour) * kilowattsPerHour;
  return [accumulatedMinutes, energyConsumed];
}

function buildHourlyReport(temperatures, target) {
  validateReadings(temperatures, target);
  return temperatures.map(function (hourlyReading, hourIndex) {
    const runMinutes = computeRunMinutes(hourlyReading, target);
    const systemState = runMinutes > 0 ? 'cooling' : 'idle';
    const hourLabel = String(hourIndex).padStart(2, '0') + ':00';
    return hourLabel + '  ' + hourlyReading + 'C  ' + systemState + '  ' + runMinutes + ' min';
  });
}

function formatSummary(totalMinutes, totalKilowatts) {
  const wholeHours = Math.floor(totalMinutes / minutesPerHour);
  const leftoverMinutes = totalMinutes % minutesPerHour;
  const runtimeText = wholeHours + 'h ' + leftoverMinutes + 'm';
  return 'Runtime: ' + totalMinutes + ' min (' + runtimeText + ')  Energy: ' +
    totalKilowatts.toFixed(2) + ' kW';
}

function main() {
  const dailyReadings = [18, 21, 24, 25, 23, 22, 20, 19];
  const targetTemperature = 21;
  buildHourlyReport(dailyReadings, targetTemperature).forEach(function (reportLine) {
    console.log(reportLine);
  });
  const regulationResult = regulate(dailyReadings, targetTemperature);
  const totalRunMinutes = regulationResult[0];
  const totalKilowatts = regulationResult[1];
  console.log(formatSummary(totalRunMinutes, totalKilowatts));
}

main();

module.exports = { regulate, computeRunMinutes, buildHourlyReport, formatSummary };

