function validateEventEntry(eventEntry, eventIndex) {
  if (!Array.isArray(eventEntry) || eventEntry.length !== 3) {
    throw new TypeError(`event ${eventIndex} must be an array of three numbers`);
  }
  eventEntry.forEach((fieldValue, fieldIndex) => {
    if (typeof fieldValue !== 'number' || !Number.isFinite(fieldValue) || fieldValue < 0) {
      throw new RangeError(`event ${eventIndex} field ${fieldIndex} must be a non-negative number`);
    }
  });
}

function computeBaseChallengePoints(puzzleDifficulty) {
  return puzzleDifficulty * 20;
}

function computeTimePenalty(secondsElapsed) {
  return Math.floor(secondsElapsed / 30);
}

function computeHintDeduction(hintsRequested) {
  return hintsRequested * 5;
}

function computeEventNetScore(eventEntry) {
  const [puzzleDifficulty, secondsElapsed, hintsRequested] = eventEntry;
  const baseChallengePoints = computeBaseChallengePoints(puzzleDifficulty);
  const timePenalty = computeTimePenalty(secondsElapsed);
  const hintDeduction = computeHintDeduction(hintsRequested);
  const rawNetScore = baseChallengePoints - timePenalty - hintDeduction;
  return rawNetScore < 0 ? 0 : rawNetScore;
}

function score(events) {
  if (!Array.isArray(events)) {
    throw new TypeError('events must be an array of event arrays');
  }
  return events.reduce((accumulatedTotalScore, eventEntry, eventIndex) => {
    validateEventEntry(eventEntry, eventIndex);
    return accumulatedTotalScore + computeEventNetScore(eventEntry);
  }, 0);
}

function buildEventReportLine(eventEntry, eventIndex) {
  validateEventEntry(eventEntry, eventIndex);
  const [puzzleDifficulty, secondsElapsed, hintsRequested] = eventEntry;
  const eventNetScore = computeEventNetScore(eventEntry);
  const penaltySummary = `-${computeTimePenalty(secondsElapsed)}t -${computeHintDeduction(hintsRequested)}h`;
  const labelColumn = `event ${eventIndex + 1}`.padEnd(9, ' ');
  return `${labelColumn} d=${puzzleDifficulty} base=${computeBaseChallengePoints(puzzleDifficulty)} ${penaltySummary} => ${eventNetScore}`;
}

function buildScoreReport(events) {
  const reportLines = events.map(buildEventReportLine);
  const accumulatedTotalScore = score(events);
  reportLines.push(`total    ${accumulatedTotalScore}`);
  return reportLines.join('\n');
}

function main() {
  const sampleEventLog = [[5, 120, 1], [3, 300, 2]];
  const hardEventLog = [[1, 900, 4], [8, 45, 0], [2, 60, 6]];
  console.log(buildScoreReport(sampleEventLog));
  console.log('');
  console.log(buildScoreReport(hardEventLog));
}

main();

module.exports = { score, computeEventNetScore, buildScoreReport };

