  }
  event_entry.forEach((field_value, field_index) => {
    if (typeof field_value !== 'number' || !Number.isFinite(field_value) || field_value < 0) {
      throw new RangeError(`event ${event_index} field ${field_index} must be a non-negative number`);
    }
  });
}

function compute_base_challenge_points(puzzle_difficulty) {
  return puzzle_difficulty * 20;
}

function compute_time_penalty(seconds_elapsed) {
  return Math.floor(seconds_elapsed / 30);
}

function compute_hint_deduction(hints_requested) {
  return hints_requested * 5;
}

function compute_event_net_score(event_entry) {
  const [puzzle_difficulty, seconds_elapsed, hints_requested] = event_entry;
  const base_challenge_points = compute_base_challenge_points(puzzle_difficulty);
  const time_penalty = compute_time_penalty(seconds_elapsed);
  const hint_deduction = compute_hint_deduction(hints_requested);
  const raw_net_score = base_challenge_points - time_penalty - hint_deduction;
  return raw_net_score < 0 ? 0 : raw_net_score;
}

function score(events) {
  if (!Array.isArray(events)) {
    throw new TypeError('events must be an array of event arrays');
  }
  return events.reduce((accumulated_total_score, event_entry, event_index) => {
    validate_event_entry(event_entry, event_index);
    return accumulated_total_score + compute_event_net_score(event_entry);
  }, 0);
}

function build_event_report_line(event_entry, event_index) {
  validate_event_entry(event_entry, event_index);
  const [puzzle_difficulty, seconds_elapsed, hints_requested] = event_entry;
  const event_net_score = compute_event_net_score(event_entry);
  const penalty_summary = `-${compute_time_penalty(seconds_elapsed)}t -${compute_hint_deduction(hints_requested)}h`;
  const label_column = `event ${event_index + 1}`.padEnd(9, ' ');
  return `${label_column} d=${puzzle_difficulty} base=${compute_base_challenge_points(puzzle_difficulty)} ${penalty_summary} => ${event_net_score}`;
}

function build_score_report(events) {
  const report_lines = events.map(build_event_report_line);
  const accumulated_total_score = score(events);
  report_lines.push(`total    ${accumulated_total_score}`);
  return report_lines.join('\n');
}

function main() {
  const sample_event_log = [[5, 120, 1], [3, 300, 2]];
  const hard_event_log = [[1, 900, 4], [8, 45, 0], [2, 60, 6]];
  console.log(build_score_report(sample_event_log));
  console.log('');
  console.log(build_score_report(hard_event_log));
}

main();

module.exports = { score, compute_event_net_score, build_score_report };

