function parseJamRecord(jamRecord) {
  if (!Array.isArray(jamRecord) || jamRecord.length !== 4) {
    throw new TypeError('each jam must be an array of four entries');
  }
  const [initialPasses, lapPasses, leadJammerStatus, blockerPenalties] = jamRecord;
  if (!Number.isInteger(initialPasses) || initialPasses < 0) {
    throw new RangeError('initial passes must be a non-negative integer');
  }
  if (!Number.isInteger(lapPasses) || lapPasses < 0) {
    throw new RangeError('lap passes must be a non-negative integer');
  }
  if (typeof leadJammerStatus !== 'boolean') {
    throw new TypeError('lead jammer status must be a boolean');
  }
  if (!Number.isInteger(blockerPenalties) || blockerPenalties < 0) {
    throw new RangeError('blocker penalties must be a non-negative integer');
  }
  return { initialPasses, lapPasses, leadJammerStatus, blockerPenalties };
}

function scoreJam(jamRecord) {
  const parsedJam = parseJamRecord(jamRecord);
  const lapPoints = parsedJam.lapPasses * 4;
  const leadJammerBonus = parsedJam.leadJammerStatus ? 5 : 0;
  const penaltyDeduction = parsedJam.blockerPenalties * 2;
  const rawJamPoints = lapPoints + leadJammerBonus - penaltyDeduction;
  const jamTotalPoints = rawJamPoints < 0 ? 0 : rawJamPoints;
  return { lapPoints, leadJammerBonus, penaltyDeduction, jamTotalPoints };
}

function tally(jams) {
  if (!Array.isArray(jams)) {
    throw new TypeError('jams must be an array of jam records');
  }
  return jams.reduce((runningTally, jamRecord) => runningTally + scoreJam(jamRecord).jamTotalPoints, 0);
}

function buildMatchReport(jams) {
  const jamLines = jams.map((jamRecord, jamIndex) => {
    const jamBreakdown = scoreJam(jamRecord);
    const jamLabel = `Jam ${jamIndex + 1}`;
    const bonusNote = jamBreakdown.leadJammerBonus > 0 ? 'lead' : 'no lead';
    return `${jamLabel}: ${jamBreakdown.lapPoints} lap pts, ${bonusNote}, ` +
      `-${jamBreakdown.penaltyDeduction} penalty => ${jamBreakdown.jamTotalPoints}`;
  });
  const matchFinalTally = tally(jams);
  jamLines.push(`Final tally: ${matchFinalTally}`);
  return jamLines.join('\n');
}

function runMatchSummary(matchName, jams) {
  const reportBody = buildMatchReport(jams);
  return `${matchName}\n${reportBody}`;
}

