const WATER_TO_CEMENT_RATIO = 0.4;
const EVAPORATION_MULTIPLIER = 2;
const HUMIDITY_PIVOT_PERCENTAGE = 50;
const SLUMP_WATER_FACTOR = 5;

function parseBatchEntry(batchEntry, batchPosition) {
  if (!Array.isArray(batchEntry) || batchEntry.length !== 3) {
    throw new TypeError(`batch ${batchPosition} must hold exactly three readings`);
  }
  const dryCementMass = Number(batchEntry[0]);
  const ambientHumidityPercentage = Number(batchEntry[1]);
  const requiredSlumpIndex = Number(batchEntry[2]);
  if (!Number.isFinite(dryCementMass) || dryCementMass < 0) {
    throw new RangeError(`batch ${batchPosition} has an invalid dry cement mass`);
  }
  if (!Number.isFinite(ambientHumidityPercentage)) {
    throw new RangeError(`batch ${batchPosition} has an invalid ambient humidity percentage`);
  }
  if (!Number.isFinite(requiredSlumpIndex)) {
    throw new RangeError(`batch ${batchPosition} has an invalid required slump index`);
  }
  return { dryCementMass, ambientHumidityPercentage, requiredSlumpIndex };
}

function computeBaseWaterRequirement(dryCementMass) {
  return dryCementMass * WATER_TO_CEMENT_RATIO;
}

function computeHumidityEvaporationOffset(ambientHumidityPercentage) {
  const offsetMagnitude = ambientHumidityPercentage * EVAPORATION_MULTIPLIER;
  return ambientHumidityPercentage > HUMIDITY_PIVOT_PERCENTAGE ? -offsetMagnitude : offsetMagnitude;
}

function computeTargetMixtureVolume(parsedBatch) {
  const baseWaterRequirement = computeBaseWaterRequirement(parsedBatch.dryCementMass);
  const humidityEvaporationOffset = computeHumidityEvaporationOffset(parsedBatch.ambientHumidityPercentage);
  const slumpWaterAllowance = parsedBatch.requiredSlumpIndex * SLUMP_WATER_FACTOR;
  return baseWaterRequirement + humidityEvaporationOffset + slumpWaterAllowance;
}

function hydrate(batches) {
  if (!Array.isArray(batches)) {
    throw new TypeError('batches must be an array of batch readings');
  }
  let overallProjectWaterVolume = 0;
  batches.forEach((batchEntry, batchIndex) => {
    const parsedBatch = parseBatchEntry(batchEntry, batchIndex + 1);
    overallProjectWaterVolume += computeTargetMixtureVolume(parsedBatch);
  });
  return Math.floor(overallProjectWaterVolume);
}

function formatVolumeLabel(volumeInLitres) {
  return `${volumeInLitres.toFixed(1)} L`;
}

function describeBatch(batchEntry, batchIndex) {
  const parsedBatch = parseBatchEntry(batchEntry, batchIndex + 1);
  const targetMixtureVolume = computeTargetMixtureVolume(parsedBatch);
  const humidityEvaporationOffset = computeHumidityEvaporationOffset(parsedBatch.ambientHumidityPercentage);
  return `batch ${batchIndex + 1}: cement ${parsedBatch.dryCementMass} kg, `
    + `humidity ${parsedBatch.ambientHumidityPercentage}% (offset ${humidityEvaporationOffset}), `
    + `slump ${parsedBatch.requiredSlumpIndex} -> ${formatVolumeLabel(targetMixtureVolume)}`;
}

function buildHydrationReport(batches) {
  const reportLines = batches.map((batchEntry, batchIndex) => describeBatch(batchEntry, batchIndex));
  reportLines.push(`overall project water volume: ${hydrate(batches)} L`);
  return reportLines;
}

const sampleBatches = [[100, 60, 3], [50, 40, 2]];
buildHydrationReport(sampleBatches).forEach((reportLine) => console.log(reportLine));

module.exports = { hydrate, buildHydrationReport, computeTargetMixtureVolume };

