function validateLensSetup(lensSetup, setupIndex) {
  if (!Array.isArray(lensSetup) || lensSetup.length !== 3) {
    throw new TypeError(`setup ${setupIndex} must list aperture, focal ratio and eyepiece length`);
  }
  const [primaryMirrorAperture, focalRatio, eyepieceFocalLength] = lensSetup;
  if (![primaryMirrorAperture, focalRatio, eyepieceFocalLength].every(Number.isFinite)) {
    throw new TypeError(`setup ${setupIndex} contains a non-numeric measurement`);
  }
  if (eyepieceFocalLength <= 0) {
    throw new RangeError(`setup ${setupIndex} has a non-positive eyepiece focal length`);
  }
  return { primaryMirrorAperture, focalRatio, eyepieceFocalLength };
}

function computeObjectiveFocalLength(primaryMirrorAperture, focalRatio) {
  return primaryMirrorAperture * focalRatio;
}

function computeViewingMagnification(objectiveFocalLength, eyepieceFocalLength) {
  return Math.floor(objectiveFocalLength / eyepieceFocalLength);
}

function describeLensSetup(lensSetup, setupIndex) {
  const { primaryMirrorAperture, focalRatio, eyepieceFocalLength } = validateLensSetup(lensSetup, setupIndex);
  const objectiveFocalLength = computeObjectiveFocalLength(primaryMirrorAperture, focalRatio);
  const viewingMagnification = computeViewingMagnification(objectiveFocalLength, eyepieceFocalLength);
  return { primaryMirrorAperture, eyepieceFocalLength, objectiveFocalLength, viewingMagnification };
}

function magnify(lenses) {
  if (!Array.isArray(lenses) || lenses.length === 0) {
    throw new TypeError('magnify expects a non-empty array of optical setups');
  }
  let highestMagnification = -Infinity;
  lenses.forEach((lensSetup, setupIndex) => {
    const { viewingMagnification } = describeLensSetup(lensSetup, setupIndex);
    if (viewingMagnification > highestMagnification) {
      highestMagnification = viewingMagnification;
    }
  });
  return highestMagnification;
}

function formatSetupReport(lenses) {
  const reportLines = lenses.map((lensSetup, setupIndex) => {
    const setupDetails = describeLensSetup(lensSetup, setupIndex);
    const aperturePart = `${setupDetails.primaryMirrorAperture}mm f/${lensSetup[1]}`;
    const focalPart = `objective ${setupDetails.objectiveFocalLength}mm`;
    const eyepiecePart = `eyepiece ${setupDetails.eyepieceFocalLength}mm`;
    return `${aperturePart} -> ${focalPart}, ${eyepiecePart} = ${setupDetails.viewingMagnification}x`;
  });
  return reportLines.join('\n');
}

function runObservatoryPlanner(opticalSetupList) {
  const setupReport = formatSetupReport(opticalSetupList);
  const bestViewingPower = magnify(opticalSetupList);
  return `${setupReport}\nbest viewing power: ${bestViewingPower}x`;
}

const telescopeInventory = [[150, 6, 10], [200, 5, 25], [114, 8, 7.5]];
console.log(runObservatoryPlanner(telescopeInventory));

module.exports = {
  magnify,
  computeObjectiveFocalLength,
  computeViewingMagnification,
  formatSetupReport,
  runObservatoryPlanner
};

