const overheadRate = 0.15;

function validateRackEntry(rackEntry, rackIndex) {
  if (!Array.isArray(rackEntry) || rackEntry.length !== 3) {
    throw new TypeError(`rack ${rackIndex} must be an array of three numbers`);
  }
  const [totalServerCount, averageWattsPerServer, coolingUnitThreshold] = rackEntry;
  const numericFields = [totalServerCount, averageWattsPerServer, coolingUnitThreshold];
  for (const fieldValue of numericFields) {
    if (typeof fieldValue !== 'number' || !Number.isFinite(fieldValue) || fieldValue < 0) {
      throw new RangeError(`rack ${rackIndex} contains an invalid measurement: ${fieldValue}`);
    }
  }
  return { totalServerCount, averageWattsPerServer, coolingUnitThreshold };
}

function computeBaseHeatOutput(totalServerCount, averageWattsPerServer) {
  return totalServerCount * averageWattsPerServer;
}

function computeOperatingOverheadFactor(baseHeatOutput) {
  return baseHeatOutput * overheadRate;
}

function computeTotalThermalLoad(totalServerCount, averageWattsPerServer) {
  const baseHeatOutput = computeBaseHeatOutput(totalServerCount, averageWattsPerServer);
  const operatingOverheadFactor = computeOperatingOverheadFactor(baseHeatOutput);
  return baseHeatOutput + operatingOverheadFactor;
}

function evaluate(racks) {
  if (!Array.isArray(racks)) {
    throw new TypeError('racks must be an array of rack descriptions');
  }
  for (let rackIndex = 0; rackIndex < racks.length; rackIndex += 1) {
    const rackReading = validateRackEntry(racks[rackIndex], rackIndex);
    const totalThermalLoad = computeTotalThermalLoad(
      rackReading.totalServerCount,
      rackReading.averageWattsPerServer,
    );
    if (totalThermalLoad > rackReading.coolingUnitThreshold) {
      return rackIndex;
    }
  }
  return -1;
}

function buildRackReport(racks) {
  return racks.map((rackEntry, rackIndex) => {
    const rackReading = validateRackEntry(rackEntry, rackIndex);
    const totalThermalLoad = computeTotalThermalLoad(
      rackReading.totalServerCount,
      rackReading.averageWattsPerServer,
    );
    const headroomWatts = rackReading.coolingUnitThreshold - totalThermalLoad;
    return { rackIndex, totalThermalLoad, headroomWatts };
  });
}

function formatReportLine(reportRow) {
  const loadText = `${reportRow.totalThermalLoad.toFixed(1)} W`;
  const headroomText = `${reportRow.headroomWatts.toFixed(1)} W headroom`;
  const statusLabel = reportRow.headroomWatts < 0 ? 'OVERHEATING' : 'cooled';
  return `rack ${reportRow.rackIndex}: ${loadText}, ${headroomText} -> ${statusLabel}`;
}

function main() {
  const rackInventory = [[10, 500, 7000], [20, 400, 9000]];
  for (const reportRow of buildRackReport(rackInventory)) {
    console.log(formatReportLine(reportRow));
  }
  const firstFailingIndex = evaluate(rackInventory);
  const verdictMessage = firstFailingIndex === -1
    ? 'all racks are adequately cooled'
    : `first rack exceeding its cooling threshold: ${firstFailingIndex}`;
  console.log(verdictMessage);
}

main();

module.exports = { evaluate, computeTotalThermalLoad, buildRackReport, formatReportLine };

