function validate_rack_entry(rack_entry, rack_index) {
  if (!Array.isArray(rack_entry) || rack_entry.length !== 3) {
    throw new TypeError(`rack ${rack_index} must be an array of three numbers`);
  }
  const [total_server_count, average_watts_per_server, cooling_unit_threshold] = rack_entry;
  const numeric_fields = [total_server_count, average_watts_per_server, cooling_unit_threshold];
  for (const field_value of numeric_fields) {
    if (typeof field_value !== 'number' || !Number.isFinite(field_value) || field_value < 0) {
      throw new RangeError(`rack ${rack_index} contains an invalid measurement: ${field_value}`);
    }
  }
  return { total_server_count, average_watts_per_server, cooling_unit_threshold };
}

function compute_base_heat_output(total_server_count, average_watts_per_server) {
  return total_server_count * average_watts_per_server;
}

function compute_operating_overhead_factor(base_heat_output) {
  return base_heat_output * overhead_rate;
}

function compute_total_thermal_load(total_server_count, average_watts_per_server) {
  const base_heat_output = compute_base_heat_output(total_server_count, average_watts_per_server);
  const operating_overhead_factor = compute_operating_overhead_factor(base_heat_output);
  return base_heat_output + operating_overhead_factor;
}

function evaluate(racks) {
  if (!Array.isArray(racks)) {
    throw new TypeError('racks must be an array of rack descriptions');
  }
  for (let rack_index = 0; rack_index < racks.length; rack_index += 1) {
    const rack_reading = validate_rack_entry(racks[rack_index], rack_index);
    const total_thermal_load = compute_total_thermal_load(
      rack_reading.total_server_count,
      rack_reading.average_watts_per_server,
    );
    if (total_thermal_load > rack_reading.cooling_unit_threshold) {
      return rack_index;
    }
  }
  return -1;
}

function build_rack_report(racks) {
  return racks.map((rack_entry, rack_index) => {
    const rack_reading = validate_rack_entry(rack_entry, rack_index);
    const total_thermal_load = compute_total_thermal_load(
      rack_reading.total_server_count,
      rack_reading.average_watts_per_server,
    );
    const headroom_watts = rack_reading.cooling_unit_threshold - total_thermal_load;
    return { rack_index, total_thermal_load, headroom_watts };
  });
}

function format_report_line(report_row) {
  const load_text = `${report_row.total_thermal_load.toFixed(1)} W`;
  const headroom_text = `${report_row.headroom_watts.toFixed(1)} W headroom`;
  const status_label = report_row.headroom_watts < 0 ? 'OVERHEATING' : 'cooled';
  return `rack ${report_row.rack_index}: ${load_text}, ${headroom_text} -> ${status_label}`;
}

function main() {
  const rack_inventory = [[10, 500, 7000], [20, 400, 9000]];
  for (const report_row of build_rack_report(rack_inventory)) {
    console.log(format_report_line(report_row));
  }
  const first_failing_index = evaluate(rack_inventory);
  const verdict_message = first_failing_index === -1
    ? 'all racks are adequately cooled'
    : `first rack exceeding its cooling threshold: ${first_failing_index}`;
  console.log(verdict_message);
}

main();

module.exports = { evaluate, compute_total_thermal_load, build_rack_report, format_report_line };

