const phLowerBound = 5.5;
const phUpperBound = 6.5;
const temperatureLowerBound = 18;
const temperatureUpperBound = 24;
const conductivityLowerBound = 1.2;
const conductivityUpperBound = 2.0;
const dissolvedOxygenThreshold = 80;

function isWithinInclusiveRange(measuredValue, lowerBound, upperBound) {
  return measuredValue >= lowerBound && measuredValue <= upperBound;
}

function parseReservoirReading(reservoirRow) {
  const [potentialHydrogenLevel, solutionTemperature, conductivityReading, dissolvedOxygenPercentage] = reservoirRow;
  return { potentialHydrogenLevel, solutionTemperature, conductivityReading, dissolvedOxygenPercentage };
}

function isReservoirBalanced(reservoirRow) {
  const reading = parseReservoirReading(reservoirRow);
  return (
    isWithinInclusiveRange(reading.potentialHydrogenLevel, phLowerBound, phUpperBound) &&
    isWithinInclusiveRange(reading.solutionTemperature, temperatureLowerBound, temperatureUpperBound) &&
    isWithinInclusiveRange(reading.conductivityReading, conductivityLowerBound, conductivityUpperBound) &&
    reading.dissolvedOxygenPercentage > dissolvedOxygenThreshold
  );
}

function balance(reservoirs) {
  let healthySystemCount = 0;
  for (const reservoirRow of reservoirs) {
    if (isReservoirBalanced(reservoirRow)) {
      healthySystemCount += 1;
    }
  }
  return healthySystemCount;
}

function describeFailedConditions(reservoirRow) {
  const reading = parseReservoirReading(reservoirRow);
  const failedConditionNames = [];
  if (!isWithinInclusiveRange(reading.potentialHydrogenLevel, phLowerBound, phUpperBound)) {
    failedConditionNames.push('pH');
  }
  if (!isWithinInclusiveRange(reading.solutionTemperature, temperatureLowerBound, temperatureUpperBound)) {
    failedConditionNames.push('temperature');
  }
  if (!isWithinInclusiveRange(reading.conductivityReading, conductivityLowerBound, conductivityUpperBound)) {
    failedConditionNames.push('conductivity');
  }
  if (!(reading.dissolvedOxygenPercentage > dissolvedOxygenThreshold)) {
    failedConditionNames.push('dissolved oxygen');
  }
  return failedConditionNames;
}

function buildReservoirReport(reservoirs) {
  const reportLines = reservoirs.map((reservoirRow, reservoirIndex) => {
    const failedConditionNames = describeFailedConditions(reservoirRow);
    const statusText = failedConditionNames.length === 0
      ? 'balanced'
      : `out of range: ${failedConditionNames.join(', ')}`;
    return `Reservoir ${reservoirIndex + 1} [${reservoirRow.join(', ')}] -> ${statusText}`;
  });
  const balancedTotal = balance(reservoirs);
  reportLines.push(`Balanced reservoirs: ${balancedTotal} of ${reservoirs.length}`);
  return reportLines.join('\n');
}

const sampleReservoirBatch = [
  [6.0, 20, 1.5, 85],
  [7.0, 25, 2.5, 90],
  [5.5, 24, 1.2, 80.5],
  [6.5, 18, 2.0, 79],
];

console.log(buildReservoirReport(sampleReservoirBatch));

module.exports = { balance, isReservoirBalanced, buildReservoirReport };

