function validateCombination(combinationEntry, entryIndex) {
  if (!Array.isArray(combinationEntry) || combinationEntry.length !== 3) {
    throw new TypeError(`setup at index ${entryIndex} must list exactly three numbers`);
  }
  const [frontChainringTeeth, rearCogTeeth, rearWheelCircumference] = combinationEntry;
  const everyValueIsFinite = combinationEntry.every((teethOrLength) => Number.isFinite(teethOrLength));
  if (!everyValueIsFinite) {
    throw new TypeError(`setup at index ${entryIndex} contains a non-numeric value`);
  }
  if (frontChainringTeeth <= 0 || rearCogTeeth <= 0 || rearWheelCircumference <= 0) {
    throw new RangeError(`setup at index ${entryIndex} must use positive measurements`);
  }
  return { frontChainringTeeth, rearCogTeeth, rearWheelCircumference };
}

function computeMechanicalRatio(frontChainringTeeth, rearCogTeeth) {
  return frontChainringTeeth / rearCogTeeth;
}

function computeDevelopmentDistance(mechanicalRatio, rearWheelCircumference) {
  return mechanicalRatio * rearWheelCircumference;
}

function gears(combinations) {
  if (!Array.isArray(combinations)) {
    throw new TypeError('combinations must be an array of drivetrain setups');
  }
  return combinations.map((combinationEntry, entryIndex) => {
    const { frontChainringTeeth, rearCogTeeth, rearWheelCircumference } = validateCombination(combinationEntry, entryIndex);
    const mechanicalRatio = computeMechanicalRatio(frontChainringTeeth, rearCogTeeth);
    return Math.floor(computeDevelopmentDistance(mechanicalRatio, rearWheelCircumference));
  });
}

function describeSetup(combinationEntry, developmentDistance) {
  const { frontChainringTeeth, rearCogTeeth, rearWheelCircumference } = validateCombination(combinationEntry, 0);
  const mechanicalRatio = computeMechanicalRatio(frontChainringTeeth, rearCogTeeth);
  const ratioLabel = mechanicalRatio.toFixed(2);
  return `${frontChainringTeeth}t x ${rearCogTeeth}t (ratio ${ratioLabel}) on a ${rearWheelCircumference}in wheel rolls ${developmentDistance}in per crank turn`;
}

function buildDrivetrainReport(combinations) {
  const developmentDistances = gears(combinations);
  const reportLines = combinations.map((combinationEntry, entryIndex) =>
    describeSetup(combinationEntry, developmentDistances[entryIndex]));
  const longestDistance = developmentDistances.reduce((bestSoFar, candidateDistance) =>
    Math.max(bestSoFar, candidateDistance), 0);
  const tallestGearIndex = developmentDistances.indexOf(longestDistance);
  reportLines.push(`tallest gear: setup #${tallestGearIndex + 1} at ${longestDistance}in`);
  return reportLines.join('\n');
}

function runDrivetrainDemo() {
  const sampleCombinations = [[32, 16, 29], [30, 50, 27], [48, 11, 83]];
  console.log(gears(sampleCombinations).join(', '));
  console.log(buildDrivetrainReport(sampleCombinations));
  try {
    gears([[40, 0, 26]]);
  } catch (validationError) {
    console.log(`rejected: ${validationError.message}`);
  }
}

runDrivetrainDemo();

module.exports = { gears, buildDrivetrainReport, describeSetup };

