const GRAVITY_ACCELERATION = 9.80665;
const BUOYANCY_THRESHOLD_NEWTONS = 500;
const FLOATING_STATE = 1;
const SINKING_STATE = -1;
const NEUTRAL_STATE = 0;

function validateVesselRecord(vesselRecord, recordIndex) {
  if (!Array.isArray(vesselRecord) || vesselRecord.length !== 3) {
    throw new TypeError(`vessel ${recordIndex} must be an array of three numbers`);
  }
  const [displacementVolume, totalDryMass, waterDensity] = vesselRecord;
  const measuredFields = [displacementVolume, totalDryMass, waterDensity];
  const hasInvalidField = measuredFields.some(
    (fieldValue) => typeof fieldValue !== 'number' || !Number.isFinite(fieldValue) || fieldValue < 0
  );
  if (hasInvalidField) {
    throw new RangeError(`vessel ${recordIndex} has a non-finite or negative measurement`);
  }
  return { displacementVolume, totalDryMass, waterDensity };
}

function computeForceMargin(displacementVolume, totalDryMass, waterDensity) {
  const displacedWaterMass = displacementVolume * waterDensity;
  const upwardBuoyantForce = displacedWaterMass * GRAVITY_ACCELERATION;
  const downwardGravityForce = totalDryMass * GRAVITY_ACCELERATION;
  return upwardBuoyantForce - downwardGravityForce;
}

function classifyForceMargin(forceMargin) {
  if (forceMargin > BUOYANCY_THRESHOLD_NEWTONS) {
    return FLOATING_STATE;
  }
  if (-forceMargin > BUOYANCY_THRESHOLD_NEWTONS) {
    return SINKING_STATE;
  }
  return NEUTRAL_STATE;
}

function buoyancy(vessels) {
  if (!Array.isArray(vessels)) {
    throw new TypeError('vessels must be an array of vessel records');
  }
  return vessels.map((vesselRecord, recordIndex) => {
    const { displacementVolume, totalDryMass, waterDensity } = validateVesselRecord(vesselRecord, recordIndex);
    return classifyForceMargin(computeForceMargin(displacementVolume, totalDryMass, waterDensity));
  });
}

function describeVesselState(stateCode) {
  if (stateCode === FLOATING_STATE) {
    return 'floating';
  }
  if (stateCode === SINKING_STATE) {
    return 'sinking';
  }
  return 'neutrally buoyant';
}

function formatBuoyancyReport(vessels) {
  const stateCodes = buoyancy(vessels);
  const reportLines = stateCodes.map((stateCode, vesselIndex) => {
    const [displacementVolume, totalDryMass, waterDensity] = vessels[vesselIndex];
    const forceMargin = computeForceMargin(displacementVolume, totalDryMass, waterDensity);
    const marginLabel = `${forceMargin >= 0 ? '+' : ''}${forceMargin.toFixed(1)} N`;
    return `vessel ${vesselIndex + 1}: ${describeVesselState(stateCode)} (${marginLabel})`;
  });
  return reportLines.join('\n');
}

function runBuoyancyDriver() {
  const submersibleFleet = [
    [10, 10000, 1025],
    [10, 11000, 1000],
    [12, 12300, 1025],
  ];
  console.log(JSON.stringify(buoyancy(submersibleFleet)));
  console.log(formatBuoyancyReport(submersibleFleet));
}

runBuoyancyDriver();

module.exports = { buoyancy, formatBuoyancyReport, describeVesselState };

