const graceperiodDays = 7;

function validateViolationRecord(violationRecord, recordIndex) {
  if (!Array.isArray(violationRecord) || violationRecord.length !== 3) {
    throw new TypeError(`Inspection record ${recordIndex} must hold exactly three numeric fields`);
  }
  const [overdueDaysCount, severityLevelInteger, priorWarningCount] = violationRecord;
  const fieldLabels = ['overdue days count', 'severity level integer', 'prior warning count'];
  [overdueDaysCount, severityLevelInteger, priorWarningCount].forEach((fieldValue, fieldPosition) => {
    if (typeof fieldValue !== 'number' || !Number.isFinite(fieldValue) || fieldValue < 0) {
      throw new RangeError(`Inspection record ${recordIndex}: ${fieldLabels[fieldPosition]} must be a non-negative finite number`);
    }
  });
}

function computeTimeDiscrepancy(overdueDaysCount) {
  if (overdueDaysCount <= graceperiodDays) {
    return 0;
  }
  return overdueDaysCount - graceperiodDays;
}

function computeBaseCitationFee(overdueDaysCount, severityLevelInteger) {
  const timeDiscrepancy = computeTimeDiscrepancy(overdueDaysCount);
  if (timeDiscrepancy === 0) {
    return 0;
  }
  return timeDiscrepancy * severityLevelInteger;
}

function applyRepeatOffenderMultiplier(baseCitationFee, priorWarningCount) {
  if (priorWarningCount > 0) {
    return baseCitationFee * (priorWarningCount + 1);
  }
  return baseCitationFee;
}

function penalize(violations) {
  if (!Array.isArray(violations)) {
    throw new TypeError('violations must be an array of inspection records');
  }
  return violations.map((violationRecord, recordIndex) => {
    validateViolationRecord(violationRecord, recordIndex);
    const [overdueDaysCount, severityLevelInteger, priorWarningCount] = violationRecord;
    const baseCitationFee = computeBaseCitationFee(overdueDaysCount, severityLevelInteger);
    return applyRepeatOffenderMultiplier(baseCitationFee, priorWarningCount);
  });
}

function formatFeeReportLine(violationRecord, finalCalculatedFee) {
  const [overdueDaysCount, severityLevelInteger, priorWarningCount] = violationRecord;
  const repeatOffenderNote = priorWarningCount > 0
    ? `repeat offender (x${priorWarningCount + 1})`
    : 'first notice';
  return `${String(overdueDaysCount).padStart(3)} days | severity ${String(severityLevelInteger).padStart(4)}`
    + ` | ${repeatOffenderNote.padEnd(22)} | fee ${finalCalculatedFee}`;
}

function buildInspectionReport(violations) {
  const finalCalculatedFees = penalize(violations);
  const reportLines = violations.map((violationRecord, recordIndex) =>
    formatFeeReportLine(violationRecord, finalCalculatedFees[recordIndex]));
  const totalAssessedFees = finalCalculatedFees.reduce((runningTotal, feeAmount) => runningTotal + feeAmount, 0);
  reportLines.push(`Total assessed fees: ${totalAssessedFees}`);
  return reportLines.join('\n');
}

function mainDriver() {
