const graceperiod_days = 7;

function validate_violation_record(violation_record, record_index) {
  if (!Array.isArray(violation_record) || violation_record.length !== 3) {
    throw new TypeError(`Inspection record ${record_index} must hold exactly three numeric fields`);
  }
  const [overdue_days_count, severity_level_integer, prior_warning_count] = violation_record;
  const field_labels = ['overdue days count', 'severity level integer', 'prior warning count'];
  [overdue_days_count, severity_level_integer, prior_warning_count].forEach((field_value, field_position) => {
    if (typeof field_value !== 'number' || !Number.isFinite(field_value) || field_value < 0) {
      throw new RangeError(`Inspection record ${record_index}: ${field_labels[field_position]} must be a non-negative finite number`);
    }
  });
}

function compute_time_discrepancy(overdue_days_count) {
  if (overdue_days_count <= graceperiod_days) {
    return 0;
  }
  return overdue_days_count - graceperiod_days;
}

function compute_base_citation_fee(overdue_days_count, severity_level_integer) {
  const time_discrepancy = compute_time_discrepancy(overdue_days_count);
  if (time_discrepancy === 0) {
    return 0;
  }
  return time_discrepancy * severity_level_integer;
}

function apply_repeat_offender_multiplier(base_citation_fee, prior_warning_count) {
  if (prior_warning_count > 0) {
    return base_citation_fee * (prior_warning_count + 1);
  }
  return base_citation_fee;
}

function penalize(violations) {
  if (!Array.isArray(violations)) {
    throw new TypeError('violations must be an array of inspection records');
  }
  return violations.map((violation_record, record_index) => {
    validate_violation_record(violation_record, record_index);
    const [overdue_days_count, severity_level_integer, prior_warning_count] = violation_record;
    const base_citation_fee = compute_base_citation_fee(overdue_days_count, severity_level_integer);
    return apply_repeat_offender_multiplier(base_citation_fee, prior_warning_count);
  });
}

function format_fee_report_line(violation_record, final_calculated_fee) {
  const [overdue_days_count, severity_level_integer, prior_warning_count] = violation_record;
  const repeat_offender_note = prior_warning_count > 0
    ? `repeat offender (x${prior_warning_count + 1})`
    : 'first notice';
  return `${String(overdue_days_count).padStart(3)} days | severity ${String(severity_level_integer).padStart(4)}`
    + ` | ${repeat_offender_note.padEnd(22)} | fee ${final_calculated_fee}`;
}

function build_inspection_report(violations) {
  const final_calculated_fees = penalize(violations);
  const report_lines = violations.map((violation_record, record_index) =>
    format_fee_report_line(violation_record, final_calculated_fees[record_index]));
  const total_assessed_fees = final_calculated_fees.reduce((running_total, fee_amount) => running_total + fee_amount, 0);
  report_lines.push(`Total assessed fees: ${total_assessed_fees}`);
  return report_lines.join('\n');
}

function main_driver() {
  const community_inspections = [[10, 50, 1], [5, 100, 0], [30, 25, 3], [8, 75, 0]];
  console.log(build_inspection_report(community_inspections));
  console.log(`Fees array: ${JSON.stringify(penalize(community_inspections))}`);
}

main_driver();

module.exports = { penalize, compute_time_discrepancy, compute_base_citation_fee, apply_repeat_offender_multiplier, build_inspection_report };

