const volumeDiscountThreshold = 50;
const volumeDiscountRate = 0.15;
const premiumSupportRate = 0.2;

function validateClientRecord(clientRecord, recordIndex) {
  if (!Array.isArray(clientRecord) || clientRecord.length !== 3) {
    throw new TypeError(`Client at index ${recordIndex} must be [seats, pricePerSeat, support]`);
  }
  const [totalUserSeats, basePricePerSeat, enterpriseSupportFlag] = clientRecord;
  if (!Number.isFinite(totalUserSeats) || totalUserSeats < 0) {
    throw new RangeError(`Client at index ${recordIndex} has invalid total user seats`);
  }
  if (!Number.isFinite(basePricePerSeat) || basePricePerSeat < 0) {
    throw new RangeError(`Client at index ${recordIndex} has invalid base price per seat`);
  }
  if (typeof enterpriseSupportFlag !== 'boolean') {
    throw new TypeError(`Client at index ${recordIndex} has a non-boolean support flag`);
  }
  return { totalUserSeats, basePricePerSeat, enterpriseSupportFlag };
}

function computeVolumeDiscount(initialContractSubtotal, totalUserSeats) {
  if (totalUserSeats >= volumeDiscountThreshold) {
    return initialContractSubtotal * volumeDiscountRate;
  }
  return 0;
}

function buildContractBreakdown(clientRecord, recordIndex) {
  const { totalUserSeats, basePricePerSeat, enterpriseSupportFlag } = validateClientRecord(clientRecord, recordIndex);
  const initialContractSubtotal = totalUserSeats * basePricePerSeat;
  const volumeDiscountAmount = computeVolumeDiscount(initialContractSubtotal, totalUserSeats);
  const discountedRunningTotal = initialContractSubtotal - volumeDiscountAmount;
  const premiumSupportFee = enterpriseSupportFlag ? discountedRunningTotal * premiumSupportRate : 0;
  const finalContractPrice = Math.floor(discountedRunningTotal + premiumSupportFee);
  return {
    initialContractSubtotal,
    volumeDiscountAmount,
    premiumSupportFee,
    finalContractPrice,
  };
}

function price(clients) {
  if (!Array.isArray(clients)) {
    throw new TypeError('clients must be an array of client records');
  }
  return clients.map((clientRecord, recordIndex) => buildContractBreakdown(clientRecord, recordIndex).finalContractPrice);
}

function formatContractReport(clients) {
  const reportLines = clients.map((clientRecord, recordIndex) => {
    const contractBreakdown = buildContractBreakdown(clientRecord, recordIndex);
    const discountLabel = contractBreakdown.volumeDiscountAmount > 0
      ? `-${contractBreakdown.volumeDiscountAmount.toFixed(2)}`
      : 'none';
    const supportLabel = contractBreakdown.premiumSupportFee > 0
      ? `+${contractBreakdown.premiumSupportFee.toFixed(2)}`
      : 'none';
    return [
      `client #${recordIndex + 1}`,
      `subtotal ${contractBreakdown.initialContractSubtotal.toFixed(2)}`,
      `volume discount ${discountLabel}`,
      `premium support ${supportLabel}`,
      `final ${contractBreakdown.finalContractPrice}`,
    ].join(' | ');
  });
  return reportLines.join('\n');
}

const enterpriseClientBatch = [[60, 20, true], [20, 15, false], [50, 12, false], [120, 9.5, true]];
const finalContractPrices = price(enterpriseClientBatch);
console.log(finalContractPrices.join(', '));
console.log(formatContractReport(enterpriseClientBatch));

module.exports = { price, formatContractReport, buildContractBreakdown };

