const propellantSafetyFactor = 1.5;

function computeStaticMass(structuralMass, payloadMass) {
  return structuralMass + payloadMass;
}

function computeManeuverMassRatio(deltaVelocity, exhaustVelocity) {
  if (exhaustVelocity === 0) {
    throw new Error('engine exhaust velocity must be non-zero');
  }
  return deltaVelocity / exhaustVelocity;
}

function computePropellantMass(stageDescriptor) {
  const [structuralMass, payloadMass, deltaVelocity, exhaustVelocity] = stageDescriptor;
  const initialStaticMass = computeStaticMass(structuralMass, payloadMass);
  const maneuverMassRatio = computeManeuverMassRatio(deltaVelocity, exhaustVelocity);
  return initialStaticMass * maneuverMassRatio * propellantSafetyFactor;
}

function validateStage(stageDescriptor, stageIndex) {
  if (!Array.isArray(stageDescriptor) || stageDescriptor.length !== 4) {
    throw new Error(`stage ${stageIndex} must list four numeric values`);
  }
  stageDescriptor.forEach((stageValue, valueIndex) => {
    if (typeof stageValue !== 'number' || !Number.isFinite(stageValue)) {
      throw new Error(`stage ${stageIndex}, field ${valueIndex} is not a finite number`);
    }
  });
}

function fuel(stages) {
  if (!Array.isArray(stages)) {
    throw new Error('stages must be an array of stage descriptors');
  }
  return stages.map((stageDescriptor, stageIndex) => {
    validateStage(stageDescriptor, stageIndex);
    return Math.floor(computePropellantMass(stageDescriptor));
  });
}

function formatStageLine(stageDescriptor, propellantMass, stageIndex) {
  const [structuralMass, payloadMass, deltaVelocity, exhaustVelocity] = stageDescriptor;
  const initialStaticMass = computeStaticMass(structuralMass, payloadMass);
  const maneuverMassRatio = computeManeuverMassRatio(deltaVelocity, exhaustVelocity);
  return `stage ${stageIndex + 1}: static ${initialStaticMass} kg, ` +
    `ratio ${maneuverMassRatio.toFixed(3)}, propellant ${propellantMass} kg`;
}

function buildFuelReport(stages) {
  const propellantMasses = fuel(stages);
  const stageLines = stages.map((stageDescriptor, stageIndex) =>
    formatStageLine(stageDescriptor, propellantMasses[stageIndex], stageIndex));
  const totalPropellantMass = propellantMasses.reduce(
    (runningTotal, stageMass) => runningTotal + stageMass, 0);
  return stageLines.concat(`total propellant: ${totalPropellantMass} kg`);
}

function main() {
  const rocketStages = [[1000, 500, 3000, 3000], [500, 200, 2000, 4000]];
  console.log(fuel(rocketStages).join(', '));
  buildFuelReport(rocketStages).forEach((reportLine) => console.log(reportLine));
}

main();

