function validateTradePath(tradePath, pathIndex) {
  if (!Array.isArray(tradePath) || tradePath.length !== 4) {
    throw new TypeError(`path ${pathIndex} must contain exactly four numbers`);
  }
  return tradePath.map((rawValue, valueIndex) => {
    const numericValue = Number(rawValue);
    if (!Number.isFinite(numericValue)) {
      throw new TypeError(`path ${pathIndex}, entry ${valueIndex} is not a finite number`);
    }
    return numericValue;
  });
}

function computeCycleStages(tradePath) {
  const [startingCapital, firstExchangeRate, secondExchangeRate, thirdExchangeRate] = tradePath;
  const intermediateCapital = startingCapital * firstExchangeRate;
  const secondaryCapital = intermediateCapital * secondExchangeRate;
  const finalReturnedCapital = secondaryCapital * thirdExchangeRate;
  const grossProfitMargin = finalReturnedCapital - startingCapital;
  return {
    startingCapital,
    intermediateCapital,
    secondaryCapital,
    finalReturnedCapital,
    grossProfitMargin: grossProfitMargin < 0 ? 0 : grossProfitMargin
  };
}

function arbitrage(paths) {
  if (!Array.isArray(paths)) {
    throw new TypeError('paths must be an array of trade cycles');
  }
  return paths.map((rawPath, pathIndex) => {
    const cleanedPath = validateTradePath(rawPath, pathIndex);
    const cycleStages = computeCycleStages(cleanedPath);
    return Math.floor(cycleStages.grossProfitMargin);
  });
}

function describeCycle(tradePath, pathIndex) {
  const cycleStages = computeCycleStages(validateTradePath(tradePath, pathIndex));
  const roundedProfit = Math.floor(cycleStages.grossProfitMargin);
  const profitVerdict = roundedProfit > 0 ? 'profitable' : 'no arbitrage';
  const capitalTrail = [
    cycleStages.intermediateCapital,
    cycleStages.secondaryCapital,
    cycleStages.finalReturnedCapital
  ]
    .map((capitalStage) => capitalStage.toFixed(2))
    .join(' -> ');
  return `#${pathIndex}: ${cycleStages.startingCapital.toFixed(2)} -> ${capitalTrail} `
    + `| profit ${roundedProfit} (${profitVerdict})`;
}

function buildArbitrageReport(paths) {
  const profitList = arbitrage(paths);
  const cycleLines = paths.map((tradePath, pathIndex) => describeCycle(tradePath, pathIndex));
  const totalFloorProfit = profitList.reduce((runningTotal, profit) => runningTotal + profit, 0);
  const bestPathIndex = profitList.reduce(
    (bestSoFar, profit, currentIndex) => (profit > profitList[bestSoFar] ? currentIndex : bestSoFar),
    0
  );
  cycleLines.push(`total floored profit: ${totalFloorProfit}`);
  cycleLines.push(`best path: #${bestPathIndex} with ${profitList[bestPathIndex]}`);
  return cycleLines.join('\n');
}

function main() {
  const candidatePaths = [
    [100, 1.2, 0.9, 1.0],
    [250, 0.85, 1.1, 1.05],
    [1000, 0.5, 0.5, 0.5]
  ];
  console.log(arbitrage(candidatePaths).join(', '));
  console.log(buildArbitrageReport(candidatePaths));
}

main();

module.exports = { arbitrage, buildArbitrageReport, describeCycle, computeCycleStages };

