function validateTransmissionRecord(transmissionRecord, recordIndex) {
  if (!Array.isArray(transmissionRecord) || transmissionRecord.length !== 3) {
    throw new TypeError(`Transmission record ${recordIndex} must hold exactly three numbers`);
  }
  const [totalSymbolsSent, misinterpretedSignals, durationInSeconds] = transmissionRecord;
  if (![totalSymbolsSent, misinterpretedSignals, durationInSeconds].every(Number.isFinite)) {
    throw new TypeError(`Transmission record ${recordIndex} contains a non-numeric field`);
  }
  if (durationInSeconds <= 0) {
    throw new RangeError(`Transmission record ${recordIndex} needs a positive duration`);
  }
  return { totalSymbolsSent, misinterpretedSignals, durationInSeconds };
}

function grossTransmissionVolume(totalSymbolsSent) {
  return totalSymbolsSent / 5;
}

function netTransmissionVolume(totalSymbolsSent, misinterpretedSignals) {
  return grossTransmissionVolume(totalSymbolsSent) - misinterpretedSignals;
}

function elapsedTimeInMinutes(durationInSeconds) {
  return durationInSeconds / 60;
}

function signalingSpeedForRecord(transmissionRecord, recordIndex) {
  const validatedRecord = validateTransmissionRecord(transmissionRecord, recordIndex);
  const netVolume = netTransmissionVolume(
    validatedRecord.totalSymbolsSent,
    validatedRecord.misinterpretedSignals
  );
  const minutesElapsed = elapsedTimeInMinutes(validatedRecord.durationInSeconds);
  const rawSignalingSpeed = netVolume / minutesElapsed;
  if (rawSignalingSpeed < 0) {
    return 0;
  }
  return Math.floor(rawSignalingSpeed);
}

function speed(transmissions) {
  if (!Array.isArray(transmissions)) {
    throw new TypeError('speed expects an array of transmission records');
  }
  return transmissions.map(signalingSpeedForRecord);
}

function formatOperatorReport(transmissions) {
  const signalingSpeeds = speed(transmissions);
  const reportLines = signalingSpeeds.map((operatorSpeed, operatorIndex) => {
    const [totalSymbolsSent, misinterpretedSignals, durationInSeconds] = transmissions[operatorIndex];
    const operatorLabel = `Operator ${operatorIndex + 1}`;
    const symbolSummary = `${totalSymbolsSent} symbols, ${misinterpretedSignals} errors, ${durationInSeconds}s`;
    return `${operatorLabel}: ${symbolSummary} -> ${operatorSpeed} wpm`;
  });
  const fastestSpeed = Math.max(...signalingSpeeds);
  reportLines.push(`Fastest recorded speed: ${fastestSpeed} wpm`);
  return reportLines.join('\n');
}

const measuredTransmissions = [[250, 5, 60], [300, 10, 120], [100, 40, 90]];
console.log(speed(measuredTransmissions).join(', '));
console.log(formatOperatorReport(measuredTransmissions));

module.exports = { speed, formatOperatorReport };

