  const [total_symbols_sent, misinterpreted_signals, duration_in_seconds] = transmission_record;
  if (![total_symbols_sent, misinterpreted_signals, duration_in_seconds].every(Number.isFinite)) {
    throw new TypeError(`Transmission record ${record_index} contains a non-numeric field`);
  }
  if (duration_in_seconds <= 0) {
    throw new RangeError(`Transmission record ${record_index} needs a positive duration`);
  }
  return { total_symbols_sent, misinterpreted_signals, duration_in_seconds };
}

function gross_transmission_volume(total_symbols_sent) {
  return total_symbols_sent / 5;
}

function net_transmission_volume(total_symbols_sent, misinterpreted_signals) {
  return gross_transmission_volume(total_symbols_sent) - misinterpreted_signals;
}

function elapsed_time_in_minutes(duration_in_seconds) {
  return duration_in_seconds / 60;
}

function signaling_speed_for_record(transmission_record, record_index) {
  const validated_record = validate_transmission_record(transmission_record, record_index);
  const net_volume = net_transmission_volume(
    validated_record.total_symbols_sent,
    validated_record.misinterpreted_signals
  );
  const minutes_elapsed = elapsed_time_in_minutes(validated_record.duration_in_seconds);
  const raw_signaling_speed = net_volume / minutes_elapsed;
  if (raw_signaling_speed < 0) {
    return 0;
  }
  return Math.floor(raw_signaling_speed);
}

function speed(transmissions) {
  if (!Array.isArray(transmissions)) {
    throw new TypeError('speed expects an array of transmission records');
  }
  return transmissions.map(signaling_speed_for_record);
}

function format_operator_report(transmissions) {
  const signaling_speeds = speed(transmissions);
  const report_lines = signaling_speeds.map((operator_speed, operator_index) => {
    const [total_symbols_sent, misinterpreted_signals, duration_in_seconds] = transmissions[operator_index];
    const operator_label = `Operator ${operator_index + 1}`;
    const symbol_summary = `${total_symbols_sent} symbols, ${misinterpreted_signals} errors, ${duration_in_seconds}s`;
    return `${operator_label}: ${symbol_summary} -> ${operator_speed} wpm`;
  });
  const fastest_speed = Math.max(...signaling_speeds);
  report_lines.push(`Fastest recorded speed: ${fastest_speed} wpm`);
  return report_lines.join('\n');
}

