const snowDepthThreshold = 10;
const timePerKilometer = 5;
const penaltyPerExtraCentimeter = 2;
const delayPerParkedCar = 1;

function validateStreetRecord(streetRecord, recordIndex) {
  if (!Array.isArray(streetRecord) || streetRecord.length !== 3) {
    throw new TypeError(`street ${recordIndex} must be [length, snowDepth, parkedCars]`);
  }
  streetRecord.forEach((fieldValue, fieldIndex) => {
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError(`street ${recordIndex}, field ${fieldIndex} is not a number`);
    }
    if (fieldValue < 0) {
      throw new RangeError(`street ${recordIndex}, field ${fieldIndex} must not be negative`);
    }
  });
}

function computeBaseClearingTime(streetLengthKm) {
  return streetLengthKm * timePerKilometer;
}

function computeHeavySnowPenalty(snowAccumulationDepth) {
  const excessSnowDepth = snowAccumulationDepth - snowDepthThreshold;
  return excessSnowDepth > 0 ? excessSnowDepth * penaltyPerExtraCentimeter : 0;
}

function computeParkedCarDelay(parkedCarCount) {
  return parkedCarCount * delayPerParkedCar;
}

function computeStreetPlowTime(streetLengthKm, snowAccumulationDepth, parkedCarCount) {
  const baseClearingTime = computeBaseClearingTime(streetLengthKm);
  const heavySnowPenalty = computeHeavySnowPenalty(snowAccumulationDepth);
  const parkedCarDelay = computeParkedCarDelay(parkedCarCount);
  return baseClearingTime + heavySnowPenalty + parkedCarDelay;
}

function plow(streets) {
  if (!Array.isArray(streets)) {
    throw new TypeError('streets must be an array of street records');
  }
  return streets.map((streetRecord, recordIndex) => {
    validateStreetRecord(streetRecord, recordIndex);
    const [streetLengthKm, snowAccumulationDepth, parkedCarCount] = streetRecord;
    return computeStreetPlowTime(streetLengthKm, snowAccumulationDepth, parkedCarCount);
  });
}

function formatPlowReport(streets) {
  const plowingTimes = plow(streets);
  const reportLines = plowingTimes.map((totalPlowingTime, streetIndex) => {
    const [streetLengthKm, snowAccumulationDepth, parkedCarCount] = streets[streetIndex];
    return `Street ${streetIndex + 1}: ${streetLengthKm} km, ${snowAccumulationDepth} cm snow, ` +
      `${parkedCarCount} cars -> ${totalPlowingTime} min`;
  });
  const totalFleetTime = plowingTimes.reduce((runningTotal, currentTime) => runningTotal + currentTime, 0);
  reportLines.push(`Total fleet time: ${totalFleetTime} min`);
  return reportLines.join('\n');
}

