const bullseyeRegion = 25;
const maxMatchScore = 301;
const consecutiveTripleBonus = 10;

const ringMultipliers = { single: 1, double: 2, triple: 3 };

function isValidRegion(regionValue) {
  if (regionValue === bullseyeRegion) {
    return true;
  }
  return Number.isInteger(regionValue) && regionValue >= 1 && regionValue <= 20;
}

function scoreSingleThrow(dartThrow) {
  const { region, ring } = dartThrow;
  if (!isValidRegion(region) || !Object.prototype.hasOwnProperty.call(ringMultipliers, ring)) {
    throw new Error(`invalid throw: region ${region}, ring ${ring}`);
  }
  if (region === bullseyeRegion) {
    return ring === 'triple' ? 0 : region * ringMultipliers[ring];
  }
  return region * ringMultipliers[ring];
}

function score(throws) {
  if (!Array.isArray(throws)) {
    throw new TypeError('throws must be an array of throw objects');
  }
  let runningTotal = 0;
  let previousWasTriple = false;
  throws.forEach((currentThrow) => {
    const throwIsTriple = currentThrow.ring === 'triple';
    runningTotal += scoreSingleThrow(currentThrow);
    if (throwIsTriple && previousWasTriple) {
      runningTotal += consecutiveTripleBonus;
    }
    previousWasTriple = throwIsTriple;
  });
  return runningTotal > maxMatchScore ? 0 : runningTotal;
}

function describeThrow(dartThrow) {
  const regionLabel = dartThrow.region === bullseyeRegion ? 'bull' : String(dartThrow.region);
  return `${dartThrow.ring} ${regionLabel}`;
}

function formatMatchReport(matchName, throws) {
  const throwDescriptions = throws.map(describeThrow).join(', ');
  const finalScore = score(throws);
  const bustSuffix = finalScore === 0 && throws.length > 0 ? ' (bust or no points)' : '';
  return `${matchName}: [${throwDescriptions}] => ${finalScore}${bustSuffix}`;
}

function runSampleMatches() {
  const doubleTripleMatch = [
    { region: 20, ring: 'triple' },
    { region: 20, ring: 'triple' },
  ];
  const bullseyeMatch = [
    { region: bullseyeRegion, ring: 'double' },
    { region: bullseyeRegion, ring: 'triple' },
    { region: 19, ring: 'single' },
  ];
  const bustingMatch = [
    { region: 20, ring: 'triple' },
    { region: 20, ring: 'triple' },
    { region: 20, ring: 'triple' },
    { region: 20, ring: 'triple' },
    { region: 20, ring: 'triple' },
    { region: 20, ring: 'triple' },
  ];
  const matchReports = [
    formatMatchReport('two triple twenties', doubleTripleMatch),
    formatMatchReport('bullseye mix', bullseyeMatch),
    formatMatchReport('over the limit', bustingMatch),
  ];
  matchReports.forEach((reportLine) => console.log(reportLine));
}

runSampleMatches();

module.exports = { score, scoreSingleThrow, formatMatchReport };

