function isDueForReview(flashCard, currentDay) {
  return flashCard.level < 5 && currentDay - flashCard.last >= flashCard.level * flashCard.level;
}

function reviewSingleCard(flashCard, currentDay) {
  const updatedLevel = flashCard.level + 1;
  flashCard.level = updatedLevel;
  flashCard.last = currentDay;
  return updatedLevel >= 5;
}

function review(cards, day) {
  const graduatedWords = [];
  const stillLearningWords = [];
  cards.forEach(function (flashCard) {
    if (!isDueForReview(flashCard, day)) {
      return;
    }
    const hasGraduated = reviewSingleCard(flashCard, day);
    if (hasGraduated) {
      graduatedWords.push(flashCard.word);
    } else {
      stillLearningWords.push(flashCard.word);
    }
  });
  graduatedWords.sort();
  stillLearningWords.sort();
  return [graduatedWords, stillLearningWords];
}

function buildDeck(wordList) {
  return wordList.map(function (singleWord) {
    return { word: singleWord, level: 1, last: 0 };
  });
}

function countRemainingCards(deck) {
  return deck.filter(function (flashCard) {
    return flashCard.level < 5;
  }).length;
}

function formatSessionReport(dayNumber, reviewResult, deck) {
  const graduatedToday = reviewResult[0];
  const reviewedToday = reviewResult[1];
  const reportLines = ['Day ' + dayNumber + ':'];
  if (graduatedToday.length === 0 && reviewedToday.length === 0) {
    reportLines.push('  nothing due');
  } else {
    if (reviewedToday.length > 0) {
      reportLines.push('  reviewed: ' + reviewedToday.join(', '));
    }
    if (graduatedToday.length > 0) {
      reportLines.push('  graduated: ' + graduatedToday.join(', '));
    }
  }
  reportLines.push('  cards left in rotation: ' + countRemainingCards(deck));
  return reportLines.join('\n');
}

function runStudySchedule(deck, totalDays) {
  const sessionReports = [];
  for (let dayNumber = 1; dayNumber <= totalDays; dayNumber += 1) {
    const dailyResult = review(deck, dayNumber);
    sessionReports.push(formatSessionReport(dayNumber, dailyResult, deck));
  }
  return sessionReports;
}

const practiceDeck = buildDeck(['tortuga', 'ballena', 'delfin', 'cangrejo']);
const scheduleReports = runStudySchedule(practiceDeck, 32);
scheduleReports.forEach(function (singleReport) {
  console.log(singleReport);
});

