const ageMultiplierTable = [
  { maxAge: 1, weightMultiplier: 2, inclusive: false },
  { maxAge: 5, weightMultiplier: 1.5, inclusive: true }
];

const defaultWeightMultiplier = 1.2;

const speciesSurchargeTable = {
  cat: 0.2,
  dog: 0.1
};

function resolveWeightMultiplier(petAge) {
  for (const multiplierRule of ageMultiplierTable) {
    const withinRange = multiplierRule.inclusive
      ? petAge <= multiplierRule.maxAge
      : petAge < multiplierRule.maxAge;
    if (withinRange) {
      return multiplierRule.weightMultiplier;
    }
  }
  return defaultWeightMultiplier;
}

function computeBaseRation(petWeight, petAge) {
  return petWeight * resolveWeightMultiplier(petAge);
}

function applySpeciesSurcharge(baseRation, petSpecies) {
  const normalizedSpecies = String(petSpecies).trim().toLowerCase();
  const surchargeRate = speciesSurchargeTable[normalizedSpecies] || 0;
  return baseRation * (1 + surchargeRate);
}

function dailyFoodRequirement(pet) {
  const baseRation = computeBaseRation(pet.weight, pet.age);
  return applySpeciesSurcharge(baseRation, pet.species);
}

function roundToOneDecimal(rawValue) {
  return Math.round(rawValue * 10) / 10;
}

function feed(pets, stock) {
  let remainingStock = stock;
  let petsFullyFed = 0;
  for (const currentPet of pets) {
    const requiredAmount = dailyFoodRequirement(currentPet);
    if (requiredAmount > remainingStock) {
      break;
    }
    remainingStock -= requiredAmount;
    petsFullyFed += 1;
  }
  return [petsFullyFed, roundToOneDecimal(remainingStock)];
}

function describeFeedingRound(pets, stock) {
  const [fedCount, leftoverStock] = feed(pets, stock);
  const unfedCount = pets.length - fedCount;
  const totalNeeded = pets.reduce((runningTotal, pet) => runningTotal + dailyFoodRequirement(pet), 0);
  const shortfallAmount = roundToOneDecimal(Math.max(0, totalNeeded - stock));
  const statusLine = unfedCount === 0
    ? `all ${fedCount} pets fed, ${leftoverStock} oz left`
    : `${fedCount} fed, ${unfedCount} hungry, short by ${shortfallAmount} oz`;
  return statusLine;
}

const kennelResidents = [
  { species: 'cat', weight: 9, age: 0.5 },
  { species: 'dog', weight: 40, age: 3 },
  { species: 'rabbit', weight: 5, age: 7 },
  { species: 'dog', weight: 60, age: 6 }
];

const availableStock = 120;
console.log(feed(kennelResidents, availableStock));
console.log(describeFeedingRound(kennelResidents, availableStock));
console.log(describeFeedingRound(kennelResidents, 200));

