const wetHydrationThreshold = 0.7;

function validateDough(candidateDough, doughIndex) {
  const requiredFields = ['flour', 'water', 'yeast', 'temperature'];
  requiredFields.forEach(function (fieldName) {
    const fieldValue = candidateDough[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError('Dough ' + doughIndex + ' has an invalid ' + fieldName);
    }
  });
  if (candidateDough.flour <= 0) {
    throw new RangeError('Dough ' + doughIndex + ' must contain a positive flour weight');
  }
}

function calculateHydrationRatio(waterGrams, flourGrams) {
  return waterGrams / flourGrams;
}

function temperatureAdjustment(doughTemperature) {
  return (referenceTemperature - doughTemperature) * 5;
}

function yeastAdjustment(yeastGrams) {
  const excessYeast = yeastGrams - yeastThresholdGrams;
  return excessYeast > 0 ? -10 * excessYeast : 0;
}

function hydrationAdjustment(hydrationRatio) {
  return hydrationRatio > wetHydrationThreshold ? -15 : 0;
}

function risingTimeForDough(singleDough) {
  const hydrationRatio = calculateHydrationRatio(singleDough.water, singleDough.flour);
  const adjustedTime = baseRisingTime
    + temperatureAdjustment(singleDough.temperature)
    + yeastAdjustment(singleDough.yeast)
    + hydrationAdjustment(hydrationRatio);
  return Math.max(adjustedTime, minimumRisingTime);
}

function proof(doughs) {
  if (!Array.isArray(doughs) || doughs.length === 0) {
    throw new RangeError('At least one dough is required to compute a proofing time');
  }
  const risingTimes = doughs.map(function (currentDough, doughIndex) {
    validateDough(currentDough, doughIndex);
    return risingTimeForDough(currentDough);
  });
  return risingTimes.reduce(function (shortestTime, currentTime) {
    return currentTime < shortestTime ? currentTime : shortestTime;
  });
}

function describeDough(someDough) {
  const hydrationPercent = (calculateHydrationRatio(someDough.water, someDough.flour) * 100).toFixed(1);
  return someDough.flour + 'g flour at ' + hydrationPercent + '% hydration, '
    + someDough.yeast + 'g yeast, ' + someDough.temperature + 'F -> '
    + risingTimeForDough(someDough) + ' min';
}

