const surfaceLightIntensity = 1000;
const lightLossPerInch = 50;
const surplusLightThreshold = 200;
const maximumCoralHealth = 10;
const minimumCoralHealth = 1;

const lightRequirementsByType = {
  stony: 500,
  soft: 200
};

function computeLightAtDepth(depthInInches) {
  const remainingLight = surfaceLightIntensity - lightLossPerInch * depthInInches;
  return remainingLight > 0 ? remainingLight : 0;
}

function getLightRequirement(coralType) {
  const normalizedType = String(coralType).trim().toLowerCase();
  const requiredLight = lightRequirementsByType[normalizedType];
  if (requiredLight === undefined) {
    throw new Error(`unknown coral type: ${coralType}`);
  }
  return requiredLight;
}

function validateCoralRecord(coralRecord) {
  const { depth: coralDepth, health: currentHealth } = coralRecord;
  if (typeof coralDepth !== 'number' || coralDepth < 0) {
    throw new Error(`invalid depth: ${coralDepth}`);
  }
  if (typeof currentHealth !== 'number' || currentHealth < minimumCoralHealth || currentHealth > maximumCoralHealth) {
    throw new Error(`invalid health: ${currentHealth}`);
  }
}

function adjustCoralHealth(coralRecord) {
  validateCoralRecord(coralRecord);
  const receivedLight = computeLightAtDepth(coralRecord.depth);
  const requiredLight = getLightRequirement(coralRecord.type);
  const startingHealth = coralRecord.health;
  if (receivedLight < requiredLight) {
    return startingHealth - 1;
  }
  if (receivedLight > requiredLight + surplusLightThreshold) {
    return Math.min(startingHealth + 1, maximumCoralHealth);
  }
  return startingHealth;
}

function illuminate(corals) {
  return corals.reduce((healthTotal, coralRecord) => healthTotal + adjustCoralHealth(coralRecord), 0);
}

function buildReefReport(corals) {
  const coralLines = corals.map((coralRecord, coralIndex) => {
    const receivedLight = computeLightAtDepth(coralRecord.depth);
    const requiredLight = getLightRequirement(coralRecord.type);
    const adjustedHealth = adjustCoralHealth(coralRecord);
    const healthDelta = adjustedHealth - coralRecord.health;
    const deltaLabel = healthDelta > 0 ? `+${healthDelta}` : String(healthDelta);
    return `#${coralIndex + 1} ${coralRecord.type} @ ${coralRecord.depth}in: ` +
      `light ${receivedLight}/${requiredLight}, health ${adjustedHealth} (${deltaLabel})`;
  });
  const totalTankHealth = illuminate(corals);
  return coralLines.concat(`total tank health: ${totalTankHealth}`).join('\n');
}

function main() {
  const tankInhabitants = [
    { depth: 4, type: 'stony', health: 7 },
    { depth: 12, type: 'stony', health: 5 },
    { depth: 2, type: 'soft', health: 10 },
    { depth: 16, type: 'soft', health: 6 },
    { depth: 18, type: 'soft', health: 3 }
  ];
  console.log(buildReefReport(tankInhabitants));
}

main();

