const sawBladeAllowance = 1;

function canAccommodatePiece(boardLength, pieceLength) {
  if (boardLength === pieceLength) {
    return true;
  }
  return boardLength >= pieceLength + sawBladeAllowance;
}

function findShortestUsableBoard(availableBoards, pieceLength) {
  let bestIndex = -1;
  let bestLength = Infinity;
  for (let currentIndex = 0; currentIndex < availableBoards.length; currentIndex += 1) {
    const boardLength = availableBoards[currentIndex];
    if (canAccommodatePiece(boardLength, pieceLength) && boardLength < bestLength) {
      bestIndex = currentIndex;
      bestLength = boardLength;
    }
  }
  return bestIndex;
}

function consumeBoardLength(availableBoards, boardIndex, pieceLength) {
  const chosenLength = availableBoards[boardIndex];
  const allowanceUsed = chosenLength === pieceLength ? 0 : sawBladeAllowance;
  availableBoards[boardIndex] = chosenLength - pieceLength - allowanceUsed;
}

function cut(boards, plans) {
  const sortedPlans = [...plans].sort((firstLength, secondLength) => secondLength - firstLength);
  let failureCount = 0;
  for (const pieceLength of sortedPlans) {
    const boardIndex = findShortestUsableBoard(boards, pieceLength);
    if (boardIndex === -1) {
      failureCount += 1;
    } else {
      consumeBoardLength(boards, boardIndex, pieceLength);
    }
  }
  return failureCount;
}

function validateLengthList(lengthValues, listLabel) {
  if (!Array.isArray(lengthValues)) {
    throw new TypeError(`${listLabel} must be an array of lengths in inches`);
  }
  lengthValues.forEach((lengthValue, valuePosition) => {
    if (typeof lengthValue !== 'number' || !Number.isFinite(lengthValue) || lengthValue <= 0) {
      throw new RangeError(`${listLabel}[${valuePosition}] must be a positive length in inches`);
    }
  });
}

function formatCutReport(remainingBoards, failureCount) {
  const totalLeftover = remainingBoards.reduce((runningTotal, boardLength) => runningTotal + boardLength, 0);
  const leftoverListing = remainingBoards.map((boardLength) => `${boardLength}"`).join(', ');
  const reportLines = [
    `Pieces that could not be cut: ${failureCount}`,
    `Remaining board lengths: ${leftoverListing}`,
    `Total leftover wood: ${totalLeftover}"`,
  ];
  return reportLines.join('\n');
}

