function validatePlayerEntry(playerEntry, entryIndex) {
  const requiredNumericFields = ['age', 'experience', 'roll'];
  if (typeof playerEntry !== 'object' || playerEntry === null) {
    throw new TypeError(`Player at index ${entryIndex} is not an object`);
  }
  if (typeof playerEntry.name !== 'string' || playerEntry.name.trim() === '') {
    throw new TypeError(`Player at index ${entryIndex} has no usable name`);
  }
  requiredNumericFields.forEach((fieldName) => {
    const fieldValue = playerEntry[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError(`Player "${playerEntry.name}" has an invalid ${fieldName}`);
    }
  });
}

function comparePlayersForTurnOrder(firstPlayer, secondPlayer) {
  const rollDifference = secondPlayer.roll - firstPlayer.roll;
  if (rollDifference !== 0) {
    return rollDifference;
  }
  const experienceDifference = firstPlayer.experience - secondPlayer.experience;
  if (experienceDifference !== 0) {
    return experienceDifference;
  }
  const ageDifference = firstPlayer.age - secondPlayer.age;
  if (ageDifference !== 0) {
    return ageDifference;
  }
  return firstPlayer.name.localeCompare(secondPlayer.name);
}

function buildTurnOrder(players) {
  players.forEach(validatePlayerEntry);
  return players.slice().sort(comparePlayersForTurnOrder);
}

function pairIntoTeams(orderedPlayers) {
  const teamRoster = [];
  for (let seatIndex = 0; seatIndex < orderedPlayers.length; seatIndex += 2) {
    const firstTeammate = orderedPlayers[seatIndex];
    const secondTeammate = orderedPlayers[seatIndex + 1];
    if (secondTeammate === undefined) {
      teamRoster.push([firstTeammate.name]);
    } else {
      teamRoster.push([firstTeammate.name, secondTeammate.name]);
    }
  }
  return teamRoster;
}

function sort(players) {
  return pairIntoTeams(buildTurnOrder(players));
}

function formatSeatingReport(players) {
  const orderedPlayers = buildTurnOrder(players);
  const turnOrderLines = orderedPlayers.map((currentPlayer, seatNumber) => {
    const seatLabel = `Seat ${seatNumber + 1}`;
    return `${seatLabel}: ${currentPlayer.name} (roll ${currentPlayer.roll}, ` +
      `${currentPlayer.experience}y exp, age ${currentPlayer.age})`;
  });
  const teamLines = pairIntoTeams(orderedPlayers).map((teamMembers, teamIndex) => {
    const teamDescription = teamMembers.join(' & ');
    return `Team ${teamIndex + 1}: ${teamDescription}`;
  });
  return turnOrderLines.concat(teamLines).join('\n');
}

