const gravityConversionFactor = 386.4;

function validateStringSpec(stringSpec, stringIndex) {
  if (stringSpec === null || typeof stringSpec !== 'object') {
    throw new TypeError(`string ${stringIndex} is not a specification object`);
  }
  const requiredFields = ['weight', 'scale', 'frequency'];
  requiredFields.forEach(function (fieldName) {
    const fieldValue = stringSpec[fieldName];
    if (typeof fieldValue !== 'number' || !Number.isFinite(fieldValue) || fieldValue <= 0) {
      throw new RangeError(`string ${stringIndex} has an invalid ${fieldName}: ${fieldValue}`);
    }
  });
}

function computeStringTension(stringSpec) {
  const { weight: unitWeight, scale: scaleLength, frequency: pitchFrequency } = stringSpec;
  return (unitWeight * scaleLength * scaleLength * pitchFrequency * pitchFrequency) / gravityConversionFactor;
}

function tension(strings) {
  if (!Array.isArray(strings)) {
    throw new TypeError('strings must be an array of string specifications');
  }
  let totalNeckTension = 0;
  let maximumStringTension = 0;
  strings.forEach(function (stringSpec, stringIndex) {
    validateStringSpec(stringSpec, stringIndex);
