const minimumSailingAngle = 45;
const tackingSpeedLimit = 5;
const directSailingSpeed = 8;
const tackingDistanceFactor = 1.4;

function angularDifference(headingDegrees, windDegrees) {
  const rawDifference = Math.abs(headingDegrees - windDegrees) % 360;
  return rawDifference > 180 ? 360 - rawDifference : rawDifference;
}

function mustTack(headingDegrees, windDegrees) {
  return angularDifference(headingDegrees, windDegrees) < minimumSailingAngle;
}

function validateLeg(sailingLeg, legIndex) {
  ['distance', 'heading', 'wind'].forEach((fieldName) => {
    const fieldValue = sailingLeg[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError(`leg ${legIndex}: ${fieldName} must be a number`);
    }
  });
  if (sailingLeg.distance < 0) {
    throw new RangeError(`leg ${legIndex}: distance must not be negative`);
  }
}

function effectiveDistance(sailingLeg) {
  return mustTack(sailingLeg.heading, sailingLeg.wind)
    ? sailingLeg.distance * tackingDistanceFactor
    : sailingLeg.distance;
}

function boatSpeed(sailingLeg) {
  return mustTack(sailingLeg.heading, sailingLeg.wind)
    ? tackingSpeedLimit
    : directSailingSpeed;
}

function legTravelHours(sailingLeg, legIndex) {
  validateLeg(sailingLeg, legIndex);
  return effectiveDistance(sailingLeg) / boatSpeed(sailingLeg);
}

function tack(route) {
  if (!Array.isArray(route)) {
    throw new TypeError('route must be an array of legs');
  }
  const totalHours = route.reduce(
    (runningTotal, sailingLeg, legIndex) =>
      runningTotal + legTravelHours(sailingLeg, legIndex),
    0,
  );
  return Math.round(totalHours * 10) / 10;
}

function buildRouteReport(route) {
  const reportLines = route.map((sailingLeg, legIndex) => {
    const travelHours = legTravelHours(sailingLeg, legIndex);
    const pointOfSail = mustTack(sailingLeg.heading, sailingLeg.wind)
      ? 'tacking'
      : 'on course';
    const distanceText = effectiveDistance(sailingLeg).toFixed(1);
    return `Leg ${legIndex + 1}: ${pointOfSail}, ${distanceText} mi at `
      + `${boatSpeed(sailingLeg)} mph = ${travelHours.toFixed(2)} h`;
  });
  reportLines.push(`Total: ${tack(route).toFixed(1)} hours`);
  return reportLines.join('\n');
}

