const longChapterThreshold = 5000;
const shortChapterThreshold = 1000;
const narratorBreakMinutes = 5;
const shortChapterPauseMinutes = 1;

function validateChapterList(chapters) {
  if (!Array.isArray(chapters)) {
    throw new TypeError('chapters must be an array of word counts');
  }
  chapters.forEach((wordCount, chapterIndex) => {
    if (typeof wordCount !== 'number' || !Number.isFinite(wordCount) || wordCount < 0) {
      throw new RangeError(`chapter ${chapterIndex + 1} has an invalid word count: ${wordCount}`);
    }
  });
}

function validateSpeakingRate(speed) {
  if (typeof speed !== 'number' || !Number.isFinite(speed) || speed <= 0) {
    throw new RangeError(`speed must be a positive number of words per minute, got ${speed}`);
  }
}

function chapterDuration(wordCount, speed) {
  const baseListeningTime = wordCount / speed;
  if (wordCount > longChapterThreshold) {
    return baseListeningTime + narratorBreakMinutes;
  }
  if (wordCount < shortChapterThreshold) {
    return baseListeningTime + shortChapterPauseMinutes;
  }
  return baseListeningTime;
}

function pace(chapters, speed) {
  validateChapterList(chapters);
  validateSpeakingRate(speed);
  const totalMinutes = chapters.reduce(
    (runningTotal, wordCount) => runningTotal + chapterDuration(wordCount, speed),
    0
  );
  const totalHours = Math.floor(totalMinutes / 60);
  const remainingMinutes = Math.floor(totalMinutes - totalHours * 60);
  return [totalHours, remainingMinutes];
}

function formatDuration(hoursAndMinutes) {
  const [hourPart, minutePart] = hoursAndMinutes;
  return `${hourPart}h ${String(minutePart).padStart(2, '0')}m`;
}

function buildChapterReport(chapters, speed) {
  return chapters.map((wordCount, chapterIndex) => {
    const minutesForChapter = chapterDuration(wordCount, speed);
    const chapterLabel = `Chapter ${chapterIndex + 1}`;
    return `${chapterLabel}: ${wordCount} words -> ${minutesForChapter.toFixed(1)} min`;
  });
}

function main() {
  const narrationSpeed = 150;
  const bookChapters = [5200, 980, 3000, 7400, 450, 2600];
  const reportLines = buildChapterReport(bookChapters, narrationSpeed);
  reportLines.forEach((reportLine) => console.log(reportLine));

  const totalPlaybackTime = pace(bookChapters, narrationSpeed);
  console.log(`Total playback: ${formatDuration(totalPlaybackTime)}`);

