const standardTimeLimit = 15;
const pointsPerElimination = 5;
const flagCaptureBonus = 50;
const speedBonusPerMinute = 2;
const missedCapturePenalty = 10;

function validateMatchEntry(matchEntry, matchIndex) {
  if (matchEntry === null || typeof matchEntry !== 'object') {
    throw new TypeError(`Match ${matchIndex} is not a match object`);
  }
  const { eliminations, captured, time } = matchEntry;
  if (typeof eliminations !== 'number' || !Number.isFinite(eliminations) || eliminations < 0) {
    throw new RangeError(`Match ${matchIndex} has an invalid elimination count`);
  }
  if (typeof captured !== 'boolean') {
    throw new TypeError(`Match ${matchIndex} has an invalid capture flag`);
  }
  if (typeof time !== 'number' || !Number.isFinite(time) || time < 0) {
    throw new RangeError(`Match ${matchIndex} has an invalid time played`);
  }
}

function calculateEliminationPoints(eliminationCount) {
  return eliminationCount * pointsPerElimination;
}

function calculateSpeedBonus(minutesPlayed) {
  const minutesRemaining = Math.max(standardTimeLimit - minutesPlayed, 0);
  return minutesRemaining * speedBonusPerMinute;
}

function scoreSingleMatch(matchEntry) {
  const basePoints = calculateEliminationPoints(matchEntry.eliminations);
  if (matchEntry.captured) {
    return basePoints + flagCaptureBonus + calculateSpeedBonus(matchEntry.time);
  }
  return Math.max(basePoints - missedCapturePenalty, 0);
}

function capture(matches) {
  if (!Array.isArray(matches)) {
    throw new TypeError('capture expects an array of matches');
  }
  return matches.reduce((runningTotal, matchEntry, matchIndex) => {
    validateMatchEntry(matchEntry, matchIndex);
    return runningTotal + scoreSingleMatch(matchEntry);
  }, 0);
}

function describeMatchOutcome(matchEntry) {
  const captureLabel = matchEntry.captured ? 'flag captured' : 'flag lost';
  return `${matchEntry.eliminations} elims, ${captureLabel}, ${matchEntry.time} min`;
}

function buildTournamentReport(matches) {
  const reportLines = matches.map((matchEntry, matchIndex) => {
    validateMatchEntry(matchEntry, matchIndex);
    const matchScore = scoreSingleMatch(matchEntry);
    const roundNumber = matchIndex + 1;
    return `Round ${roundNumber}: ${describeMatchOutcome(matchEntry)} -> ${matchScore} pts`;
  });
  reportLines.push(`Tournament total: ${capture(matches)} pts`);
  return reportLines.join('\n');
}

function runTournamentSummary() {
  const tournamentMatches = [
    { eliminations: 4, captured: true, time: 9 },
    { eliminations: 1, captured: false, time: 15 },
    { eliminations: 7, captured: true, time: 14.5 },
    { eliminations: 0, captured: false, time: 12 },
  ];
  console.log(buildTournamentReport(tournamentMatches));
}

runTournamentSummary();

module.exports = { capture, scoreSingleMatch, buildTournamentReport };

