function validateWaypoints(waypointList) {
  if (!Array.isArray(waypointList)) {
    throw new TypeError('waypoints must be an array');
  }
  waypointList.forEach((currentWaypoint, waypointIndex) => {
    const hasValidNorth = typeof currentWaypoint.north === 'number' && Number.isFinite(currentWaypoint.north);
    const hasValidEast = typeof currentWaypoint.east === 'number' && Number.isFinite(currentWaypoint.east);
    if (!hasValidNorth || !hasValidEast) {
      throw new TypeError(`waypoint ${waypointIndex} needs finite north and east coordinates`);
    }
  });
}

const longLegThreshold = 100;
const fatiguePenalty = 10;

function legDistance(fromWaypoint, toWaypoint) {
  const northDelta = toWaypoint.north - fromWaypoint.north;
  const eastDelta = toWaypoint.east - fromWaypoint.east;
  return Math.sqrt(northDelta * northDelta + eastDelta * eastDelta);
}

function navigate(waypoints) {
  validateWaypoints(waypoints);
  let runningTotal = 0;
  for (let legIndex = 1; legIndex < waypoints.length; legIndex += 1) {
    const currentLegDistance = legDistance(waypoints[legIndex - 1], waypoints[legIndex]);
    runningTotal += currentLegDistance;
    if (currentLegDistance > longLegThreshold) {
      runningTotal += fatiguePenalty;
    }
  }
  return Math.round(runningTotal);
}

function describeTrail(trailName, waypoints) {
  validateWaypoints(waypoints);
  const reportLines = [`Trail: ${trailName}`];
  let penalizedLegCount = 0;
  for (let legIndex = 1; legIndex < waypoints.length; legIndex += 1) {
    const startWaypoint = waypoints[legIndex - 1];
    const endWaypoint = waypoints[legIndex];
    const rawLegDistance = legDistance(startWaypoint, endWaypoint);
    let penaltyNote = '';
    if (rawLegDistance > longLegThreshold) {
      penalizedLegCount += 1;
      penaltyNote = ` (+${fatiguePenalty} fatigue)`;
    }
    const legLabel = `(${startWaypoint.north}, ${startWaypoint.east}) -> (${endWaypoint.north}, ${endWaypoint.east})`;
    reportLines.push(`  leg ${legIndex} ${legLabel} = ${rawLegDistance.toFixed(2)}${penaltyNote}`);
  }
  reportLines.push(`  penalized legs: ${penalizedLegCount}`);
  reportLines.push(`  adjusted total: ${navigate(waypoints)} units`);
  return reportLines.join('\n');
}

function main() {
  const shortLoopTrail = [
    { north: 0, east: 0 },
    { north: 3, east: 4 },
    { north: 3, east: 14 },
    { north: 0, east: 0 },
  ];
