function validate_waypoints(waypoint_list) {
  if (!Array.isArray(waypoint_list)) {
    throw new TypeError('waypoints must be an array');
  }
  waypoint_list.forEach((current_waypoint, waypoint_index) => {
    const has_valid_north = typeof current_waypoint.north === 'number' && Number.isFinite(current_waypoint.north);
    const has_valid_east = typeof current_waypoint.east === 'number' && Number.isFinite(current_waypoint.east);
    if (!has_valid_north || !has_valid_east) {
      throw new TypeError(`waypoint ${waypoint_index} needs finite north and east coordinates`);
    }
  });
}

const long_leg_threshold = 100;
const fatigue_penalty = 10;

function leg_distance(from_waypoint, to_waypoint) {
  const north_delta = to_waypoint.north - from_waypoint.north;
  const east_delta = to_waypoint.east - from_waypoint.east;
  return Math.sqrt(north_delta * north_delta + east_delta * east_delta);
}

function navigate(waypoints) {
  validate_waypoints(waypoints);
  let running_total = 0;
  for (let leg_index = 1; leg_index < waypoints.length; leg_index += 1) {
    const current_leg_distance = leg_distance(waypoints[leg_index - 1], waypoints[leg_index]);
    running_total += current_leg_distance;
    if (current_leg_distance > long_leg_threshold) {
      running_total += fatigue_penalty;
    }
  }
  return Math.round(running_total);
}

function describe_trail(trail_name, waypoints) {
  validate_waypoints(waypoints);
  const report_lines = [`Trail: ${trail_name}`];
  let penalized_leg_count = 0;
  for (let leg_index = 1; leg_index < waypoints.length; leg_index += 1) {
    const start_waypoint = waypoints[leg_index - 1];
    const end_waypoint = waypoints[leg_index];
    const raw_leg_distance = leg_distance(start_waypoint, end_waypoint);
    let penalty_note = '';
    if (raw_leg_distance > long_leg_threshold) {
      penalized_leg_count += 1;
      penalty_note = ` (+${fatigue_penalty} fatigue)`;
    }
    const leg_label = `(${start_waypoint.north}, ${start_waypoint.east}) -> (${end_waypoint.north}, ${end_waypoint.east})`;
    report_lines.push(`  leg ${leg_index} ${leg_label} = ${raw_leg_distance.toFixed(2)}${penalty_note}`);
  }
  report_lines.push(`  penalized legs: ${penalized_leg_count}`);
  report_lines.push(`  adjusted total: ${navigate(waypoints)} units`);
  return report_lines.join('\n');
}

function main() {
  const short_loop_trail = [
    { north: 0, east: 0 },
    { north: 3, east: 4 },
    { north: 3, east: 14 },
    { north: 0, east: 0 },
  ];
  const mountain_ridge_trail = [
    { north: 10, east: 10 },
    { north: 110, east: 90 },
    { north: 120, east: 95 },
    { north: 20, east: 200 },
  ];
  console.log(describe_trail('Short Loop', short_loop_trail));
  console.log(describe_trail('Mountain Ridge', mountain_ridge_trail));
}

main();

module.exports = { navigate, leg_distance, describe_trail, validate_waypoints };

