const overhangThresholdDegrees = 90;
const overhangPointsPerDegree = 2;
const scoreScalingFactor = 10;
const supportingPitchWeight = 0.1;

function validatePitchDescriptor(pitchDescriptor, pitchIndex) {
  const positionLabel = `pitch ${pitchIndex + 1}`;
  if (pitchDescriptor === null || typeof pitchDescriptor !== 'object') {
    throw new TypeError(`${positionLabel} must be an object`);
  }
  const requiredFieldNames = ['steepness', 'holds', 'length'];
  requiredFieldNames.forEach(function (fieldName) {
    const fieldValue = pitchDescriptor[fieldName];
    if (typeof fieldValue !== 'number' || !Number.isFinite(fieldValue)) {
      throw new TypeError(`${positionLabel} has an invalid ${fieldName}`);
    }
  });
  if (pitchDescriptor.holds < 0 || pitchDescriptor.length < 0) {
    throw new RangeError(`${positionLabel} cannot have negative holds or length`);
  }
}

function computePitchScore(pitchDescriptor) {
  let baseScore = pitchDescriptor.length;
  if (pitchDescriptor.steepness > overhangThresholdDegrees) {
    const degreesOverhanging = pitchDescriptor.steepness - overhangThresholdDegrees;
    baseScore += overhangPointsPerDegree * degreesOverhanging;
  }
  const effectiveHoldCount = pitchDescriptor.holds === 0 ? 1 : pitchDescriptor.holds;
  return (baseScore * scoreScalingFactor) / effectiveHoldCount;
}

function grade(pitches) {
  if (!Array.isArray(pitches)) {
    throw new TypeError('pitches must be an array');
  }
  if (pitches.length === 0) {
    return 0;
  }
  pitches.forEach(validatePitchDescriptor);
  const pitchScores = pitches.map(computePitchScore);
  const hardestPitchScore = pitchScores.reduce(function (runningMax, currentScore) {
    return currentScore > runningMax ? currentScore : runningMax;
  }, pitchScores[0]);
  const totalOfAllScores = pitchScores.reduce(function (runningSum, currentScore) {
    return runningSum + currentScore;
  }, 0);
  const supportingScoreSum = totalOfAllScores - hardestPitchScore;
  return Math.floor(hardestPitchScore + supportingPitchWeight * supportingScoreSum);
}

function formatRouteReport(routeName, pitches) {
  const reportLines = [`Route: ${routeName}`];
  pitches.forEach(function (pitchDescriptor, pitchIndex) {
    const pitchScore = computePitchScore(pitchDescriptor);
    const steepnessLabel = pitchDescriptor.steepness > overhangThresholdDegrees ? 'overhanging' : 'slab or vertical';
    reportLines.push(
      `  Pitch ${pitchIndex + 1}: ${pitchDescriptor.length}m, ${pitchDescriptor.holds} holds, ` +
        `${steepnessLabel} (${pitchDescriptor.steepness}deg) -> score ${pitchScore.toFixed(2)}`
    );
  });
  reportLines.push(`  Overall difficulty: ${grade(pitches)}`);
  return reportLines.join('\n');
}

