const STEAM_TEMPERATURE_THRESHOLD = 100;
const STEAM_BONUS_MULTIPLIER = 1.2;
const PRESSURE_FLOW_FACTOR = 10;
const DEPTH_ENERGY_COST = 0.5;
const HIGH_YIELD_THRESHOLD = 50;

function validateWell(wellRecord, wellIndex) {
  const requiredFields = ['depth', 'temperature', 'pressure'];
  requiredFields.forEach(function (fieldName) {
    const fieldValue = wellRecord[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError(
        'Well ' + wellIndex + ' has an invalid ' + fieldName + ': ' + fieldValue
      );
    }
  });
}

function computeBaseFlowRate(wellPressure) {
  return wellPressure * PRESSURE_FLOW_FACTOR;
}

function applyDepthPenalty(baseFlowRate, wellDepth) {
  return baseFlowRate - wellDepth * DEPTH_ENERGY_COST;
}

function applySteamBonus(currentFlowRate, waterTemperature) {
  if (waterTemperature > STEAM_TEMPERATURE_THRESHOLD) {
    return currentFlowRate * STEAM_BONUS_MULTIPLIER;
  }
  return currentFlowRate;
}

function computeWellFlowRate(wellRecord) {
  const baseFlowRate = computeBaseFlowRate(wellRecord.pressure);
  const liftedFlowRate = applySteamBonus(
    applyDepthPenalty(baseFlowRate, wellRecord.depth),
    wellRecord.temperature
  );
  return liftedFlowRate < 0 ? 0 : liftedFlowRate;
}

function pump(wells) {
  let totalFlowRate = 0;
  let highYieldCount = 0;
  wells.forEach(function (wellRecord, wellIndex) {
    validateWell(wellRecord, wellIndex);
    const wellFlowRate = computeWellFlowRate(wellRecord);
    totalFlowRate += wellFlowRate;
    if (wellFlowRate > HIGH_YIELD_THRESHOLD) {
      highYieldCount += 1;
    }
  });
  return [totalFlowRate, highYieldCount];
}

function formatPlantReport(wells) {
  const [totalFlowRate, highYieldCount] = pump(wells);
  const wellLines = wells.map(function (wellRecord, wellIndex) {
    const wellFlowRate = computeWellFlowRate(wellRecord);
    return (
      'Well ' + (wellIndex + 1) + ': depth=' + wellRecord.depth + 'm' +
      ', temp=' + wellRecord.temperature + 'C' +
      ', flow=' + wellFlowRate.toFixed(2)
    );
  });
  const summaryLine =
    'Total flow: ' + totalFlowRate.toFixed(2) +
    ' | High-yield wells: ' + highYieldCount + '/' + wells.length;
  return wellLines.concat(summaryLine).join('\n');
}

