const idealHumidity = 85;
const lowerHumidityBound = 80;
const upperHumidityBound = 90;
const ruinStreakThreshold = 3;

function validateReadings(readings) {
  if (!Array.isArray(readings)) {
    throw new TypeError('readings must be an array of humidity percentages');
  }
  readings.forEach((dailyReading, dayIndex) => {
    if (typeof dailyReading !== 'number' || Number.isNaN(dailyReading)) {
      throw new TypeError(`reading for day ${dayIndex + 1} is not a number`);
    }
  });
  return readings;
}

function isExtremeReading(dailyReading) {
  return dailyReading < lowerHumidityBound || dailyReading > upperHumidityBound;
}

function longestExtremeStreak(readings) {
  let currentStreakLength = 0;
  let longestStreakLength = 0;
  readings.forEach((dailyReading) => {
    currentStreakLength = isExtremeReading(dailyReading) ? currentStreakLength + 1 : 0;
    if (currentStreakLength > longestStreakLength) {
      longestStreakLength = currentStreakLength;
    }
  });
  return longestStreakLength;
}

function roundToOneDecimal(rawValue) {
  return Math.round(rawValue * 10) / 10;
}

function averageHumidity(readings) {
  if (readings.length === 0) {
    return 0;
  }
  const humiditySum = readings.reduce((runningTotal, dailyReading) => runningTotal + dailyReading, 0);
  return roundToOneDecimal(humiditySum / readings.length);
}

function age(readings) {
  const checkedReadings = validateReadings(readings);
  const batchIsRuined = longestExtremeStreak(checkedReadings) >= ruinStreakThreshold;
  return [batchIsRuined, averageHumidity(checkedReadings)];
}

function formatAgingReport(caveName, readings) {
  const [batchIsRuined, meanHumidity] = age(readings);
  const humidityDrift = roundToOneDecimal(meanHumidity - idealHumidity);
  const driftDirection = humidityDrift >= 0 ? 'above' : 'below';
  const extremeDayCount = readings.filter(isExtremeReading).length;
  const batchVerdict = batchIsRuined ? 'RUINED' : 'sellable';
  return `${caveName}: ${batchVerdict}, mean ${meanHumidity}% ` +
    `(${Math.abs(humidityDrift)}% ${driftDirection} ideal), ` +
    `${extremeDayCount} extreme day(s) over ${readings.length} day(s)`;
}

function runQualityControl(caveReadingsByName) {
  return Object.entries(caveReadingsByName).map(([caveName, caveReadings]) =>
    formatAgingReport(caveName, caveReadings));
}

const monitoredCaves = {
  'North Cellar': [85, 84, 86, 85, 87, 83, 85],
  'South Cellar': [85, 79, 78, 77, 86, 85, 84],
  'Deep Vault': [92, 84, 79, 85, 91, 85, 86],
};

runQualityControl(monitoredCaves).forEach((reportLine) => console.log(reportLine));

module.exports = { age, isExtremeReading, longestExtremeStreak, averageHumidity, formatAgingReport };

