const dailyConsumptionRate = 0.005;
const sweetThreshold = 0.05;
const sourThreshold = 0.02;

function validateBatch(rawBatch, batchIndex) {
  const { sugar: sugarGrams, tea: teaMilliliters, days: fermentationDays } = rawBatch;
  if (!Number.isFinite(sugarGrams) || sugarGrams < 0) {
    throw new RangeError(`batch ${batchIndex}: sugar must be a non-negative number`);
  }
  if (!Number.isFinite(teaMilliliters) || teaMilliliters <= 0) {
    throw new RangeError(`batch ${batchIndex}: tea must be a positive number`);
  }
  if (!Number.isFinite(fermentationDays) || fermentationDays < 0) {
    throw new RangeError(`batch ${batchIndex}: days must be a non-negative number`);
  }
  return { sugarGrams, teaMilliliters, fermentationDays };
}

function initialConcentration(sugarGrams, teaMilliliters) {
  return sugarGrams / teaMilliliters;
}

function finalConcentration(startingConcentration, fermentationDays) {
  const consumedFraction = dailyConsumptionRate * fermentationDays;
  const remainingFraction = 1 - consumedFraction;
  return remainingFraction > 0 ? startingConcentration * remainingFraction : 0;
}

function classifyConcentration(concentrationValue) {
  if (concentrationValue > sweetThreshold) return 'sweet';
  if (concentrationValue >= sourThreshold) return 'perfect';
  return 'sour';
}

function ferment(batches) {
  const tasteCounts = { sweet: 0, perfect: 0, sour: 0 };
  batches.forEach((rawBatch, batchIndex) => {
    const { sugarGrams, teaMilliliters, fermentationDays } = validateBatch(rawBatch, batchIndex);
    const startingConcentration = initialConcentration(sugarGrams, teaMilliliters);
    const endingConcentration = finalConcentration(startingConcentration, fermentationDays);
    const tasteProfile = classifyConcentration(endingConcentration);
    tasteCounts[tasteProfile] += 1;
  });
  return [tasteCounts.sweet, tasteCounts.perfect, tasteCounts.sour];
}

function describeBatch(rawBatch) {
  const { sugarGrams, teaMilliliters, fermentationDays } = validateBatch(rawBatch, 0);
  const endingConcentration = finalConcentration(
    initialConcentration(sugarGrams, teaMilliliters),
    fermentationDays
  );
  const roundedConcentration = endingConcentration.toFixed(4);
  return `${sugarGrams}g / ${teaMilliliters}ml for ${fermentationDays}d -> ` +
    `${roundedConcentration} (${classifyConcentration(endingConcentration)})`;
}

function formatTasteReport(batches) {
  const [sweetCount, perfectCount, sourCount] = ferment(batches);
  const batchLines = batches.map(describeBatch);
  const summaryLine = `sweet: ${sweetCount}, perfect: ${perfectCount}, sour: ${sourCount}`;
  return batchLines.concat(summaryLine).join('\n');
}

function main() {
  const brewingBatches = [
    { sugar: 100, tea: 1000, days: 10 },
    { sugar: 60, tea: 1000, days: 20 },
    { sugar: 30, tea: 1000, days: 40 },
    { sugar: 25, tea: 1000, days: 100 },
    { sugar: 80, tea: 2000, days: 5 }
  ];
  console.log(formatTasteReport(brewingBatches));
}

main();

module.exports = { ferment, formatTasteReport };

