    throw new RangeError(`batch ${batch_index}: tea must be a positive number`);
  }
  if (!Number.isFinite(fermentation_days) || fermentation_days < 0) {
    throw new RangeError(`batch ${batch_index}: days must be a non-negative number`);
  }
  return { sugar_grams, tea_milliliters, fermentation_days };
}

function initial_concentration(sugar_grams, tea_milliliters) {
  return sugar_grams / tea_milliliters;
}

function final_concentration(starting_concentration, fermentation_days) {
  const consumed_fraction = daily_consumption_rate * fermentation_days;
  const remaining_fraction = 1 - consumed_fraction;
  return remaining_fraction > 0 ? starting_concentration * remaining_fraction : 0;
}

function classify_concentration(concentration_value) {
  if (concentration_value > sweet_threshold) return 'sweet';
  if (concentration_value >= sour_threshold) return 'perfect';
  return 'sour';
}

function ferment(batches) {
  const taste_counts = { sweet: 0, perfect: 0, sour: 0 };
  batches.forEach((raw_batch, batch_index) => {
    const { sugar_grams, tea_milliliters, fermentation_days } = validate_batch(raw_batch, batch_index);
    const starting_concentration = initial_concentration(sugar_grams, tea_milliliters);
    const ending_concentration = final_concentration(starting_concentration, fermentation_days);
    const taste_profile = classify_concentration(ending_concentration);
    taste_counts[taste_profile] += 1;
  });
  return [taste_counts.sweet, taste_counts.perfect, taste_counts.sour];
}

function describe_batch(raw_batch) {
  const { sugar_grams, tea_milliliters, fermentation_days } = validate_batch(raw_batch, 0);
  const ending_concentration = final_concentration(
    initial_concentration(sugar_grams, tea_milliliters),
    fermentation_days
  );
  const rounded_concentration = ending_concentration.toFixed(4);
  return `${sugar_grams}g / ${tea_milliliters}ml for ${fermentation_days}d -> ` +
    `${rounded_concentration} (${classify_concentration(ending_concentration)})`;
}

function format_taste_report(batches) {
  const [sweet_count, perfect_count, sour_count] = ferment(batches);
  const batch_lines = batches.map(describe_batch);
  const summary_line = `sweet: ${sweet_count}, perfect: ${perfect_count}, sour: ${sour_count}`;
  return batch_lines.concat(summary_line).join('\n');
}

function main() {
  const brewing_batches = [
    { sugar: 100, tea: 1000, days: 10 },
    { sugar: 60, tea: 1000, days: 20 },
    { sugar: 30, tea: 1000, days: 40 },
    { sugar: 25, tea: 1000, days: 100 },
    { sugar: 80, tea: 2000, days: 5 }
  ];
  console.log(format_taste_report(brewing_batches));
}

