const baseMinutesPerSquareMeter = 2;
const minutesPerBarnacleDensity = 0.5;
const curvedSurfaceMultiplier = 1.5;
const batteryLifeMinutes = 120;
const batterySwapMinutes = 30;

function validateSection(rawSection, sectionIndex) {
  if (rawSection === null || typeof rawSection !== 'object') {
    throw new TypeError(`Section ${sectionIndex} must be an object`);
  }
  const { area: sectionArea, density: barnacleDensity, curved: isCurved } = rawSection;
  if (typeof sectionArea !== 'number' || !Number.isFinite(sectionArea) || sectionArea < 0) {
    throw new RangeError(`Section ${sectionIndex} has an invalid area: ${sectionArea}`);
  }
  if (typeof barnacleDensity !== 'number' || !Number.isFinite(barnacleDensity) || barnacleDensity < 0) {
    throw new RangeError(`Section ${sectionIndex} has an invalid density: ${barnacleDensity}`);
  }
  return { sectionArea, barnacleDensity, isCurved: Boolean(isCurved) };
}

function computeSectionTime(sectionArea, barnacleDensity, isCurved) {
  const effectiveRate = baseMinutesPerSquareMeter + barnacleDensity * minutesPerBarnacleDensity;
  const scrubbingTime = sectionArea * effectiveRate;
  return isCurved ? scrubbingTime * curvedSurfaceMultiplier : scrubbingTime;
}

function countBatterySwaps(totalCleaningTime) {
  if (totalCleaningTime <= 0) {
    return 0;
  }
  return Math.ceil(totalCleaningTime / batteryLifeMinutes) - 1;
}

function sumCleaningTime(sections) {
  if (!Array.isArray(sections)) {
    throw new TypeError('clean(sections) expects an array of section objects');
  }
  return sections.reduce((runningTotal, rawSection, sectionIndex) => {
    const { sectionArea, barnacleDensity, isCurved } = validateSection(rawSection, sectionIndex);
    return runningTotal + computeSectionTime(sectionArea, barnacleDensity, isCurved);
  }, 0);
}

function clean(sections) {
  const totalCleaningTime = sumCleaningTime(sections);
  return totalCleaningTime + countBatterySwaps(totalCleaningTime) * batterySwapMinutes;
}

function describeSchedule(sections) {
  const scheduleLines = sections.map((rawSection, sectionIndex) => {
    const { sectionArea, barnacleDensity, isCurved } = validateSection(rawSection, sectionIndex);
    const sectionTime = computeSectionTime(sectionArea, barnacleDensity, isCurved);
    const shapeLabel = isCurved ? 'curved' : 'flat';
    return `  section ${sectionIndex + 1}: ${sectionArea} m2, ${barnacleDensity}/m2, ${shapeLabel} -> ${sectionTime.toFixed(1)} min`;
  });
  const scrubbingOnlyTime = sumCleaningTime(sections);
  const swapCount = countBatterySwaps(scrubbingOnlyTime);
  scheduleLines.push(`  cleaning time: ${scrubbingOnlyTime.toFixed(1)} min`);
  scheduleLines.push(`  battery swaps: ${swapCount} (${swapCount * batterySwapMinutes} min)`);
  scheduleLines.push(`  total elapsed: ${(scrubbingOnlyTime + swapCount * batterySwapMinutes).toFixed(1)} min`);
  return scheduleLines.join('\n');
}

function main() {
  const hullSections = [
    { area: 20, density: 4, curved: false },
    { area: 12, density: 0, curved: true },
    { area: 35, density: 7, curved: true }
