const idealMoisturePercent = 20;
const collapsePenaltyPoints = 10;

function validateLayerShape(candidateLayer, layerIndex) {
  const requiredFields = ['width', 'height', 'moisture'];
  requiredFields.forEach(function (fieldName) {
    const fieldValue = candidateLayer[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError('Layer ' + layerIndex + ' has an invalid ' + fieldName);
    }
  });
}

function computeMoisturePenalty(layerMoisture) {
  return Math.abs(layerMoisture - idealMoisturePercent);
}

function computeBaseScore(layerWidth, layerHeight) {
  return layerWidth * layerHeight;
}

function isLayerUnstable(currentLayer, layerBeneath) {
  return layerBeneath !== undefined && currentLayer.width >= layerBeneath.width;
}

function inspectLayers(layers) {
  return layers.map(function (currentLayer, layerIndex) {
    validateLayerShape(currentLayer, layerIndex);
    const layerBeneath = layers[layerIndex - 1];
    const baseScore = computeBaseScore(currentLayer.width, currentLayer.height);
    const moisturePenalty = computeMoisturePenalty(currentLayer.moisture);
    const unstableLayer = isLayerUnstable(currentLayer, layerBeneath);
    return {
      index: layerIndex,
      base: baseScore,
      moisture: moisturePenalty,
      collapse: unstableLayer ? collapsePenaltyPoints : 0,
      adjusted: baseScore - moisturePenalty
    };
  });
}

function build(layers) {
  if (!Array.isArray(layers)) {
    throw new TypeError('build expects an array of layers');
  }
  const inspectedLayers = inspectLayers(layers);
  return inspectedLayers.reduce(function (runningScore, layerReport) {
    return runningScore + layerReport.adjusted - layerReport.collapse;
  }, 0);
}

function formatContestReport(layers) {
  const inspectedLayers = inspectLayers(layers);
  const reportLines = inspectedLayers.map(function (layerReport) {
    const stabilityNote = layerReport.collapse > 0 ? 'COLLAPSE' : 'stable';
    return 'Layer ' + layerReport.index + ': base ' + layerReport.base +
      ', moisture -' + layerReport.moisture +
      ', ' + stabilityNote;
  });
  const finalStructureScore = build(layers);
  reportLines.push('Final structure score: ' + finalStructureScore);
  return reportLines.join('\n');
}

