const rotationPeriodSeconds = 15;
const angularVelocity = (2 * Math.PI) / rotationPeriodSeconds;

function roundToOneDecimal(rawValue) {
  return Math.round(rawValue * 10) / 10;
}

function linearSpeedOf(horseEntry) {
  return angularVelocity * horseEntry.distance;
}

function centrifugalForceOf(horseEntry) {
  const horseLinearSpeed = linearSpeedOf(horseEntry);
  return (horseEntry.weight * horseLinearSpeed * horseLinearSpeed) / horseEntry.distance;
}

function validateHorseList(horses) {
  if (!Array.isArray(horses) || horses.length === 0) {
    throw new Error('spin requires a non-empty array of horses');
  }
  horses.forEach((horseEntry, horseIndex) => {
    const hasValidDistance = typeof horseEntry.distance === 'number' && horseEntry.distance > 0;
    const hasValidWeight = typeof horseEntry.weight === 'number' && horseEntry.weight > 0;
    if (!hasValidDistance || !hasValidWeight) {
      throw new Error(`horse at index ${horseIndex} needs a positive distance and weight`);
    }
  });
}

function findOutermostHorse(horses) {
  return horses.reduce((currentOutermost, horseEntry) =>
    horseEntry.distance > currentOutermost.distance ? horseEntry : currentOutermost
  );
}

function spin(horses, duration) {
  validateHorseList(horses);
  if (typeof duration !== 'number' || duration < 0) {
    throw new Error('duration must be a non-negative number of seconds');
  }
  const maximumForce = horses.reduce(
    (highestSoFar, horseEntry) => Math.max(highestSoFar, centrifugalForceOf(horseEntry)),
    0
  );
  const outermostHorse = findOutermostHorse(horses);
  const outerDistanceTravelled = linearSpeedOf(outermostHorse) * duration;
  return [roundToOneDecimal(maximumForce), roundToOneDecimal(outerDistanceTravelled)];
}

function describeRide(horses, duration) {
  const [maximumForce, outerDistance] = spin(horses, duration);
  const rotationCount = roundToOneDecimal(duration / rotationPeriodSeconds);
  return [
    `Riders: ${horses.length}`,
    `Rotations in ${duration}s: ${rotationCount}`,
    `Peak centrifugal force: ${maximumForce} N`,
    `Outer horse path length: ${outerDistance} m`
  ].join('\n');
}

function main() {
  const carouselHorses = [
    { distance: 3, weight: 70 },
    { distance: 5.5, weight: 45 },
    { distance: 4.2, weight: 90 }
  ];
  const rideDuration = 90;
  console.log(describeRide(carouselHorses, rideDuration));

  const soloHorseSetup = [{ distance: 6, weight: 60 }];
  const shortRideDuration = 7.5;
  console.log(describeRide(soloHorseSetup, shortRideDuration));
}

main();

