  horses.forEach((horse_entry, horse_index) => {
    const has_valid_distance = typeof horse_entry.distance === 'number' && horse_entry.distance > 0;
    const has_valid_weight = typeof horse_entry.weight === 'number' && horse_entry.weight > 0;
    if (!has_valid_distance || !has_valid_weight) {
      throw new Error(`horse at index ${horse_index} needs a positive distance and weight`);
    }
  });
}

function find_outermost_horse(horses) {
  return horses.reduce((current_outermost, horse_entry) =>
    horse_entry.distance > current_outermost.distance ? horse_entry : current_outermost
  );
}

function spin(horses, duration) {
  validate_horse_list(horses);
  if (typeof duration !== 'number' || duration < 0) {
    throw new Error('duration must be a non-negative number of seconds');
  }
  const maximum_force = horses.reduce(
    (highest_so_far, horse_entry) => Math.max(highest_so_far, centrifugal_force_of(horse_entry)),
    0
  );
  const outermost_horse = find_outermost_horse(horses);
  const outer_distance_travelled = linear_speed_of(outermost_horse) * duration;
  return [round_to_one_decimal(maximum_force), round_to_one_decimal(outer_distance_travelled)];
}

function describe_ride(horses, duration) {
  const [maximum_force, outer_distance] = spin(horses, duration);
  const rotation_count = round_to_one_decimal(duration / rotation_period_seconds);
  return [
    `Riders: ${horses.length}`,
    `Rotations in ${duration}s: ${rotation_count}`,
    `Peak centrifugal force: ${maximum_force} N`,
    `Outer horse path length: ${outer_distance} m`
  ].join('\n');
}

function main() {
  const carousel_horses = [
    { distance: 3, weight: 70 },
    { distance: 5.5, weight: 45 },
    { distance: 4.2, weight: 90 }
  ];
  const ride_duration = 90;
