const baseCharge = 5;
const congestionFee = 3;
const perMileRate = 2;
const perMinuteRate = 0.5;
const congestionZone = 1;

function validateTrip(tripRecord) {
  if (!Array.isArray(tripRecord) || tripRecord.length !== 4) {
    throw new Error('each trip needs start zone, end zone, minutes and miles');
  }
  const [startZone, endZone, travelMinutes, tripDistance] = tripRecord;
  const hasBadNumber = [startZone, endZone, travelMinutes, tripDistance]
    .some((tripValue) => typeof tripValue !== 'number' || Number.isNaN(tripValue));
  if (hasBadNumber) {
    throw new Error(`invalid trip values: ${tripRecord.join(', ')}`);
  }
  if (travelMinutes < 0 || tripDistance < 0) {
    throw new Error('travel time and distance must not be negative');
  }
  return { startZone, endZone, travelMinutes, tripDistance };
}

function entersCongestionZone(startZone, endZone) {
  return startZone === congestionZone || endZone === congestionZone;
}

function singleTripFare(tripRecord) {
  const { startZone, endZone, travelMinutes, tripDistance } = validateTrip(tripRecord);
  const distanceCost = tripDistance * perMileRate;
  const timeCost = travelMinutes * perMinuteRate;
  const meteredCost = distanceCost + timeCost;
  let tripTotal = meteredCost < baseCharge ? baseCharge : meteredCost;
  const chargedCongestion = entersCongestionZone(startZone, endZone);
  if (chargedCongestion) {
    tripTotal += congestionFee;
  }
  return { tripTotal, chargedCongestion };
}

function fare(trips) {
  let totalRevenue = 0;
  let maximumFare = 0;
  let congestionTripCount = 0;
