const absorptionFactorPerAcrePercent = 300;
const minimumDeficitThreshold = 5;

function parseSensorReading(sensorReading) {
  const [sectorIdentifier, currentMoistureLevel, targetMoistureLevel, sectorAreaAcres] = sensorReading;
  if (typeof sectorIdentifier === 'undefined' || sectorIdentifier === null) {
    throw new Error('sensor reading is missing a sector identifier');
  }
  const numericCurrentLevel = Number(currentMoistureLevel);
  const numericTargetLevel = Number(targetMoistureLevel);
  const numericSectorArea = Number(sectorAreaAcres);
  if ([numericCurrentLevel, numericTargetLevel, numericSectorArea].some(Number.isNaN)) {
    throw new Error(`sector ${sectorIdentifier} has non-numeric readings`);
  }
  return [sectorIdentifier, numericCurrentLevel, numericTargetLevel, numericSectorArea];
}

function computeMoistureDeficit(currentMoistureLevel, targetMoistureLevel) {
  return targetMoistureLevel - currentMoistureLevel;
}

function computeWaterVolume(moistureDeficit, sectorAreaAcres) {
  if (moistureDeficit < minimumDeficitThreshold) {
    return 0;
  }
  return moistureDeficit * sectorAreaAcres * absorptionFactorPerAcrePercent;
}

function irrigate(sensors) {
  let totalWaterVolume = 0;
  let largestDeficitSector = null;
  let largestDeficitValue = -Infinity;
  let thirstySectorCount = 0;
  let thirstyDeficitSum = 0;

  sensors.forEach((sensorReading) => {
    const [sectorIdentifier, currentMoistureLevel, targetMoistureLevel, sectorAreaAcres] =
      parseSensorReading(sensorReading);
    const moistureDeficit = computeMoistureDeficit(currentMoistureLevel, targetMoistureLevel);
    if (moistureDeficit > largestDeficitValue) {
      largestDeficitValue = moistureDeficit;
      largestDeficitSector = sectorIdentifier;
    }
    const sectorWaterVolume = computeWaterVolume(moistureDeficit, sectorAreaAcres);
    if (sectorWaterVolume > 0) {
      thirstySectorCount += 1;
      thirstyDeficitSum += moistureDeficit;
      totalWaterVolume += sectorWaterVolume;
    }
  });

  const averageThirstyDeficit = thirstySectorCount === 0 ? 0 : thirstyDeficitSum / thirstySectorCount;
  return [totalWaterVolume, largestDeficitSector, averageThirstyDeficit];
}

function formatIrrigationReport(irrigationResult) {
  const [totalWaterVolume, largestDeficitSector, averageThirstyDeficit] = irrigationResult;
  const reportLines = [
    `total water needed: ${totalWaterVolume} gallons`,
    `driest sector: ${largestDeficitSector === null ? 'none' : largestDeficitSector}`,
    `average deficit among watered sectors: ${averageThirstyDeficit.toFixed(2)}%`,
  ];
  return reportLines.join('\n');
}

function runIrrigationCycle(sensorReadings) {
  const irrigationResult = irrigate(sensorReadings);
  console.log(formatIrrigationReport(irrigationResult));
  return irrigationResult;
}

