const faultWarningThreshold = 5;
const highStressDayLimit = 3;
const overhaulCycleLimit = 10000;
const routineCycleLimit = 5000;

function validateDailyRecord(dailyRecord, recordIndex) {
  if (!Array.isArray(dailyRecord) || dailyRecord.length !== 3) {
    throw new TypeError(`log entry ${recordIndex} must hold three numeric fields`);
  }
  const [dispatchCycles, dispatchInterval, faultWarnings] = dailyRecord;
  if (![dispatchCycles, dispatchInterval, faultWarnings].every(Number.isFinite)) {
    throw new TypeError(`log entry ${recordIndex} contains a non-numeric field`);
  }
  if (dispatchCycles < 0 || dispatchInterval < 0 || faultWarnings < 0) {
    throw new RangeError(`log entry ${recordIndex} contains a negative field`);
  }
  return { dispatchCycles, dispatchInterval, faultWarnings };
}

function inspect(logs) {
  if (!Array.isArray(logs)) {
    throw new TypeError('logs must be an array of daily records');
  }
  let totalCycles = 0;
  let totalOperatingTime = 0;
  let highStressDays = 0;

  logs.forEach((dailyRecord, recordIndex) => {
    const { dispatchCycles, dispatchInterval, faultWarnings } = validateDailyRecord(dailyRecord, recordIndex);
    const dailyOperatingTime = dispatchCycles * dispatchInterval;
    if (faultWarnings > faultWarningThreshold) {
      highStressDays += 1;
    }
    totalCycles += dispatchCycles;
    totalOperatingTime += dailyOperatingTime;
  });

  let recommendedAction = 'none';
  if (totalCycles > overhaulCycleLimit || highStressDays >= highStressDayLimit) {
    recommendedAction = 'overhaul';
  } else if (totalCycles > routineCycleLimit) {
    recommendedAction = 'routine';
  }

  return [recommendedAction, totalCycles, highStressDays, totalOperatingTime];
}

function formatOperatingHours(operatingSeconds) {
  const wholeHours = Math.floor(operatingSeconds / 3600);
  const remainingMinutes = Math.round((operatingSeconds % 3600) / 60);
  return `${wholeHours}h ${remainingMinutes}m`;
}

function buildMaintenanceReport(rideName, logs) {
  const [recommendedAction, totalCycles, highStressDays, totalOperatingTime] = inspect(logs);
  const reportLines = [
    `Ride: ${rideName}`,
    `Total dispatch cycles: ${totalCycles}`,
    `High stress days: ${highStressDays}`,
    `Total operating time: ${formatOperatingHours(totalOperatingTime)}`,
    `Recommended action: ${recommendedAction}`,
  ];
  return reportLines.join('\n');
}

