const idealLowerBound = 18;
const idealUpperBound = 22;
const offFlavorThreshold = 24;

function temperatureDeviation(measuredTemperature) {
  if (measuredTemperature < idealLowerBound) {
    return idealLowerBound - measuredTemperature;
  }
  if (measuredTemperature > idealUpperBound) {
    return measuredTemperature - idealUpperBound;
  }
  return 0;
}

function validateReading(singleReading, readingIndex) {
  if (!Array.isArray(singleReading) || singleReading.length < 3) {
    throw new TypeError(`reading ${readingIndex} must be [hour, celsius, activity]`);
  }
  const [hourMark, measuredTemperature, yeastActivity] = singleReading;
  if (![hourMark, measuredTemperature, yeastActivity].every(Number.isFinite)) {
    throw new TypeError(`reading ${readingIndex} contains a non numeric field`);
  }
  return { hourMark, measuredTemperature, yeastActivity };
}

function ferment(readings) {
  if (!Array.isArray(readings)) {
    throw new TypeError('readings must be an array of logged measurements');
  }
  let totalStressFactor = 0;
  let highestTemperature = readings.length ? -Infinity : 0;
  let offFlavorHours = 0;
  readings.forEach((singleReading, readingIndex) => {
    const { measuredTemperature, yeastActivity } = validateReading(singleReading, readingIndex);
    const deviationAmount = temperatureDeviation(measuredTemperature);
    if (deviationAmount > 0) {
      totalStressFactor += deviationAmount * yeastActivity;
    }
    if (measuredTemperature > highestTemperature) {
      highestTemperature = measuredTemperature;
    }
    if (measuredTemperature > offFlavorThreshold) {
      offFlavorHours += 1;
    }
  });
  return [totalStressFactor, highestTemperature, offFlavorHours];
}

function describeRisk(stressFactor, riskyHourCount) {
  if (riskyHourCount > 0) {
    return `batch risks off flavors across ${riskyHourCount} hour(s)`;
  }
  return stressFactor > 0 ? 'batch drifted but stayed below the off flavor threshold' : 'batch held the ideal range';
}

function formatFermentationReport(readings) {
  const [totalStressFactor, highestTemperature, offFlavorHours] = ferment(readings);
  const hoursLogged = readings.length;
  const reportLines = [
    `hours logged: ${hoursLogged}`,
    `total stress factor: ${totalStressFactor.toFixed(1)}`,
    `highest recorded temperature: ${highestTemperature} C`,
    `hours above ${offFlavorThreshold} C: ${offFlavorHours}`,
    describeRisk(totalStressFactor, offFlavorHours),
  ];
  return reportLines.join('\n');
}

