function calculateTotalVolume(flightDuration, flowRate) {
    return flightDuration * flowRate;
}

function calculateApplicationDensity(totalVolume, fieldArea) {
    return totalVolume / fieldArea;
}

function isUnderSprayed(applicationDensity) {
    const minimumOptimalDensity = 15;
    return applicationDensity < minimumOptimalDensity;
}

function isOverSprayed(applicationDensity) {
    const maximumOptimalDensity = 20;
    return applicationDensity > maximumOptimalDensity;
}

function validateFlightData(flightDataArray) {
    if (!Array.isArray(flightDataArray)) {
        throw new Error("Flight data must be an array");
    }
    const expectedElementCount = 3;
    if (flightDataArray.length !== expectedElementCount) {
        throw new Error("Each flight must have exactly three data points");
    }
    const flightDurationMinutes = flightDataArray[0];
    const flowRateLitersPerMinute = flightDataArray[1];
    const fieldAreaHectares = flightDataArray[2];

    if (flightDurationMinutes <= 0 || flowRateLitersPerMinute <= 0 || fieldAreaHectares <= 0) {
        throw new Error("All flight parameters must be strictly positive numbers");
    }
}

function spray(agriculturalFlights) {
    let totalPesticideVolume = 0;
    let underSprayedFlightCount = 0;
    let overSprayedFlightCount = 0;

    for (let flightIndex = 0; flightIndex < agriculturalFlights.length; flightIndex++) {
        const currentFlightData = agriculturalFlights[flightIndex];
        validateFlightData(currentFlightData);

        const flightDurationMinutes = currentFlightData[0];
        const flowRateLitersPerMinute = currentFlightData[1];
        const fieldAreaHectares = currentFlightData[2];

        const currentFlightVolume = calculateTotalVolume(
            flightDurationMinutes,
            flowRateLitersPerMinute
        );

        totalPesticideVolume += currentFlightVolume;

        const currentApplicationDensity = calculateApplicationDensity(
            currentFlightVolume,
            fieldAreaHectares
        );

        if (isUnderSprayed(currentApplicationDensity)) {
            underSprayedFlightCount++;
        } else if (isOverSprayed(currentApplicationDensity)) {
            overSprayedFlightCount++;
        }
    }

    return [
        totalPesticideVolume,
        underSprayedFlightCount,
        overSprayedFlightCount
    ];
}

