function validateSegments(segments) {
  if (!Array.isArray(segments)) {
    throw new TypeError('segments must be an array of [mass, speed] pairs');
  }
  segments.forEach(function (segmentPair, segmentIndex) {
    if (!Array.isArray(segmentPair) || segmentPair.length !== 2) {
      throw new TypeError('segment ' + segmentIndex + ' must be a [mass, speed] pair');
    }
    const oreMass = segmentPair[0];
    const beltSpeed = segmentPair[1];
    if (typeof oreMass !== 'number' || typeof beltSpeed !== 'number') {
      throw new TypeError('segment ' + segmentIndex + ' must contain numbers');
    }
    if (oreMass < 0 || beltSpeed < 0) {
      throw new RangeError('segment ' + segmentIndex + ' must not contain negative values');
    }
  });
}

const overloadThreshold = 50;

function analyseSegments(segments) {
  return segments.map(function (segmentPair, segmentIndex) {
    const oreMass = segmentPair[0];
    const beltSpeed = segmentPair[1];
    const flowRate = oreMass * beltSpeed;
    return {
      index: segmentIndex,
      mass: oreMass,
      speed: beltSpeed,
      flow: flowRate,
      overloaded: flowRate > overloadThreshold
    };
  });
}

function summariseShift(segmentReports) {
  let totalOreMass = 0;
  let totalFlowRate = 0;
  let overloadedCount = 0;
  let maximumFlowRate = 0;
  segmentReports.forEach(function (segmentReport) {
    totalOreMass += segmentReport.mass;
    totalFlowRate += segmentReport.flow;
    if (segmentReport.overloaded) {
      overloadedCount += 1;
    }
    if (segmentReport.flow > maximumFlowRate) {
      maximumFlowRate = segmentReport.flow;
    }
  });
  const averageFlowRate = segmentReports.length === 0 ? 0 : totalFlowRate / segmentReports.length;
  return {
    total: totalOreMass,
    overloads: overloadedCount,
    peak: maximumFlowRate,
    average: averageFlowRate
  };
}

function formatShiftReport(segmentReports, shiftSummary) {
  const segmentLines = segmentReports.map(function (segmentReport) {
    const overloadMarker = segmentReport.overloaded ? 'OVERLOAD' : 'ok';
    return 'segment ' + segmentReport.index + ': ' + segmentReport.mass + ' t @ ' +
      segmentReport.speed + ' m/s -> ' + segmentReport.flow.toFixed(1) +
      ' t*m/s (' + overloadMarker + ')';
  });
  const summaryLine = 'shift: ' + shiftSummary.total.toFixed(1) + ' t total, average flow ' +
    shiftSummary.average.toFixed(1) + ' t*m/s, peak flow ' + shiftSummary.peak.toFixed(1) +
    ' t*m/s, ' + shiftSummary.overloads + ' overloaded';
  return segmentLines.concat(summaryLine).join('\n');
}

function convey(segments) {
  validateSegments(segments);
  const shiftSummary = summariseShift(analyseSegments(segments));
  return [shiftSummary.total, shiftSummary.overloads, shiftSummary.peak];
}

function main() {
  const shiftSegments = [[30, 2], [12, 3], [40, 1.2], [25, 2.5], [18, 0.8]];
  const segmentReports = analyseSegments(shiftSegments);
  console.log(formatShiftReport(segmentReports, summariseShift(segmentReports)));
  console.log('convey() -> [' + convey(shiftSegments).join(', ') + ']');
}

main();

