const ALIGNMENT_ANGLE_THRESHOLD = 5;
const OPPOSITE_ANGLE_THRESHOLD = 355;
const SIMULTANEOUS_ALIGNMENT_LIMIT = 3;

function validateBodyEntry(bodyEntry) {
  if (!Array.isArray(bodyEntry) || bodyEntry.length < 3) {
    throw new TypeError('each celestial body needs an identifier, a radius and an angle');
  }
  const [bodyIdentifier, orbitalRadius, currentAngle] = bodyEntry;
  if (typeof bodyIdentifier !== 'string' || bodyIdentifier.length === 0) {
    throw new TypeError('body identifier must be a non-empty string');
  }
  if (!Number.isFinite(orbitalRadius) || orbitalRadius <= 0) {
    throw new RangeError(`orbital radius of ${bodyIdentifier} must be a positive number of astronomical units`);
  }
  if (!Number.isFinite(currentAngle)) {
    throw new RangeError(`current angle of ${bodyIdentifier} must be a finite number of degrees`);
  }
  return [bodyIdentifier, orbitalRadius, currentAngle];
}

function isAlignedPair(firstAngle, secondAngle) {
  const angularSeparation = Math.abs(firstAngle - secondAngle);
  return angularSeparation < ALIGNMENT_ANGLE_THRESHOLD || angularSeparation > OPPOSITE_ANGLE_THRESHOLD;
}

function gravitationalResonance(firstRadius, secondRadius) {
  return 1 / (firstRadius + secondRadius);
}

function align(planets) {
  if (!Array.isArray(planets)) {
    throw new TypeError('align expects an array of celestial body records');
  }
  const celestialBodies = planets.map(validateBodyEntry);
  let alignmentCount = 0;
  let totalResonance = 0;
  for (let outerIndex = 0; outerIndex < celestialBodies.length; outerIndex += 1) {
    const [, firstRadius, firstAngle] = celestialBodies[outerIndex];
    for (let innerIndex = outerIndex + 1; innerIndex < celestialBodies.length; innerIndex += 1) {
      const [, secondRadius, secondAngle] = celestialBodies[innerIndex];
      if (isAlignedPair(firstAngle, secondAngle)) {
        alignmentCount += 1;
        totalResonance += gravitationalResonance(firstRadius, secondRadius);
      }
    }
  }
  const roundedResonance = Math.round(totalResonance * 100) / 100;
  return [alignmentCount, roundedResonance, alignmentCount > SIMULTANEOUS_ALIGNMENT_LIMIT];
}

function formatAlignmentReport(systemName, alignmentResult) {
  const [alignmentCount, resonanceTotal, isRareConjunction] = alignmentResult;
  const conjunctionNote = isRareConjunction ? 'rare multiple conjunction' : 'no rare conjunction';
  return `${systemName}: ${alignmentCount} alignment(s), resonance ${resonanceTotal.toFixed(2)}, ${conjunctionNote}`;
}

function runAlignmentSurvey(observedSystems) {
  return Object.keys(observedSystems).map((systemName) =>
    formatAlignmentReport(systemName, align(observedSystems[systemName])));
}

