const CROWDING_THRESHOLD = 0.8;

function parseZone(zoneEntry) {
  const [roomIdentifier, visitorCount, maximumCapacity, floorArea] = zoneEntry;
  if (typeof roomIdentifier !== 'string' || roomIdentifier.length === 0) {
    throw new TypeError('each zone needs a room identifier');
  }
  if (!Number.isFinite(visitorCount) || visitorCount < 0) {
    throw new RangeError(`visitor count for ${roomIdentifier} must be a non-negative number`);
  }
  if (!Number.isFinite(maximumCapacity) || maximumCapacity <= 0) {
    throw new RangeError(`capacity for ${roomIdentifier} must be positive`);
  }
  if (!Number.isFinite(floorArea) || floorArea <= 0) {
    throw new RangeError(`floor area for ${roomIdentifier} must be positive`);
  }
  return { roomIdentifier, visitorCount, maximumCapacity, floorArea };
}

function measureRoom(zoneEntry) {
  const parsedRoom = parseZone(zoneEntry);
  const crowdingRatio = parsedRoom.visitorCount / parsedRoom.maximumCapacity;
  const spacePerPerson = parsedRoom.visitorCount === 0
    ? Infinity
    : parsedRoom.floorArea / parsedRoom.visitorCount;
  return {
    roomIdentifier: parsedRoom.roomIdentifier,
    visitorCount: parsedRoom.visitorCount,
    crowdingRatio,
    spacePerPerson,
    isRestricted: crowdingRatio > CROWDING_THRESHOLD
  };
}

function crowd(zones) {
  let totalVisitors = 0;
  let restrictedRooms = 0;
  let tightestSpacePerPerson = Infinity;
  for (const zoneEntry of zones) {
    const roomMetrics = measureRoom(zoneEntry);
    totalVisitors += roomMetrics.visitorCount;
    if (roomMetrics.isRestricted) {
      restrictedRooms += 1;
    }
    if (roomMetrics.spacePerPerson < tightestSpacePerPerson) {
      tightestSpacePerPerson = roomMetrics.spacePerPerson;
    }
  }
  return [totalVisitors, restrictedRooms, tightestSpacePerPerson];
}

function formatRoomLine(roomMetrics) {
  const percentageLabel = `${(roomMetrics.crowdingRatio * 100).toFixed(1)}%`;
  const spaceLabel = Number.isFinite(roomMetrics.spacePerPerson)
    ? `${roomMetrics.spacePerPerson.toFixed(2)} m2/person`
    : 'empty room';
  const statusLabel = roomMetrics.isRestricted ? 'RESTRICTED' : 'open';
  return `${roomMetrics.roomIdentifier.padEnd(14)} ${percentageLabel.padStart(6)}  ${spaceLabel.padEnd(18)} ${statusLabel}`;
}

function buildMuseumReport(zones) {
  const roomLines = zones.map((zoneEntry) => formatRoomLine(measureRoom(zoneEntry)));
  const [totalVisitors, restrictedRooms, tightestSpacePerPerson] = crowd(zones);
  const summaryLine = `visitors=${totalVisitors} restricted=${restrictedRooms} tightest=${tightestSpacePerPerson.toFixed(2)} m2/person`;
  return roomLines.concat(summaryLine).join('\n');
}

const museumZones = [
  ['Impressionists', 80, 100, 200],
  ['Sculpture Hall', 95, 110, 340],
  ['Modern Wing', 12, 60, 150],
  ['Print Cabinet', 0, 25, 40]
];

console.log(buildMuseumReport(museumZones));

