  const [palletIdentifier, rawWeight, rawHeight] = palletRecord;
  const palletWeightKg = Number(rawWeight);
  const palletHeightCm = Number(rawHeight);
  if (!Number.isFinite(palletWeightKg) || !Number.isFinite(palletHeightCm)) {
    throw new TypeError(`pallet ${palletIdentifier} has non-numeric dimensions`);
  }
  return { palletIdentifier, palletWeightKg, palletHeightCm };
}

function exceedsRackLimits(parsedPallet) {
  return parsedPallet.palletWeightKg > maxRackWeightKg
    || parsedPallet.palletHeightCm > maxRackHeightCm;
}

function computeStorageEfficiency(acceptedWeightTotal, acceptedHeightTotal) {
  if (acceptedHeightTotal === 0) {
    return 0;
  }
  return acceptedWeightTotal / acceptedHeightTotal;
}

function stack(pallets) {
  let acceptedWeightTotal = 0;
  let acceptedHeightTotal = 0;
  let rejectedPalletCount = 0;
  for (const palletRecord of pallets) {
    const parsedPallet = parsePalletRecord(palletRecord);
    if (exceedsRackLimits(parsedPallet)) {
      rejectedPalletCount += 1;
    } else {
      acceptedWeightTotal += parsedPallet.palletWeightKg;
      acceptedHeightTotal += parsedPallet.palletHeightCm;
    }
  }
  const storageEfficiency = computeStorageEfficiency(acceptedWeightTotal, acceptedHeightTotal);
  return [acceptedWeightTotal, rejectedPalletCount, storageEfficiency];
}

function listRejectedIdentifiers(pallets) {
  return pallets
    .map(parsePalletRecord)
    .filter(exceedsRackLimits)
    .map((rejectedPallet) => rejectedPallet.palletIdentifier);
}

function formatStackReport(pallets) {
  const [acceptedWeightTotal, rejectedPalletCount, storageEfficiency] = stack(pallets);
  const rejectedIdentifiers = listRejectedIdentifiers(pallets);
  const reportLines = [
    `accepted weight: ${acceptedWeightTotal} kg`,
    `rejected pallets: ${rejectedPalletCount}`,
    `storage efficiency: ${storageEfficiency.toFixed(2)} kg/cm`,
  ];
  if (rejectedIdentifiers.length > 0) {
    reportLines.push(`rejected ids: ${rejectedIdentifiers.join(', ')}`);
  }
  return reportLines.join('\n');
}

function main() {
  const incomingFreight = [
    ['PLT-001', 500, 100],
    ['PLT-002', 1200, 150],
    ['PLT-003', 300, 220],
    ['PLT-004', 250, 80],
  ];
  console.log(formatStackReport(incomingFreight));
}

main();

module.exports = { stack, computeStorageEfficiency, formatStackReport, listRejectedIdentifiers };

