const roomVolume = 10000;
const sabineConstant = 0.161;
const highAbsorptionThreshold = 0.5;

function validateMaterialEntry(materialEntry, entryIndex) {
  if (!Array.isArray(materialEntry) || materialEntry.length !== 2) {
    throw new Error(`Material at index ${entryIndex} must be [area, coefficient]`);
  }
  const [surfaceArea, absorptionCoefficient] = materialEntry;
  if (typeof surfaceArea !== 'number' || Number.isNaN(surfaceArea) || surfaceArea < 0) {
    throw new Error(`Invalid surface area at index ${entryIndex}`);
  }
  if (typeof absorptionCoefficient !== 'number' || absorptionCoefficient < 0 || absorptionCoefficient > 1) {
    throw new Error(`Absorption coefficient at index ${entryIndex} must lie in [0, 1]`);
  }
  return { surfaceArea, absorptionCoefficient };
}

function equivalentAbsorptionArea(surfaceArea, absorptionCoefficient) {
  return surfaceArea * absorptionCoefficient;
}

function acoustics(materials) {
  if (!Array.isArray(materials) || materials.length === 0) {
    throw new Error('materials must be a non-empty array');
  }
  let totalAbsorptionArea = 0;
  let highlyAbsorptiveCount = 0;
  materials.forEach((materialEntry, entryIndex) => {
    const { surfaceArea, absorptionCoefficient } = validateMaterialEntry(materialEntry, entryIndex);
    totalAbsorptionArea += equivalentAbsorptionArea(surfaceArea, absorptionCoefficient);
    if (absorptionCoefficient > highAbsorptionThreshold) {
      highlyAbsorptiveCount += 1;
    }
  });
  if (totalAbsorptionArea === 0) {
    throw new Error('Total absorption is zero; reverberation time is undefined');
  }
  const reverberationTime = (sabineConstant * roomVolume) / totalAbsorptionArea;
  return [totalAbsorptionArea, reverberationTime, highlyAbsorptiveCount];
}

function classifyHallCharacter(reverberationTime) {
  if (reverberationTime < 1.2) return 'dry';
  if (reverberationTime <= 2.2) return 'balanced for orchestral music';
  return 'overly reverberant';
}

function formatAcousticReport(hallName, materials) {
  const [totalAbsorptionArea, reverberationTime, highlyAbsorptiveCount] = acoustics(materials);
  const totalSurfaceArea = materials.reduce((runningArea, [surfaceArea]) => runningArea + surfaceArea, 0);
  const averageCoefficient = totalAbsorptionArea / totalSurfaceArea;
  const hallCharacter = classifyHallCharacter(reverberationTime);
  return [
    `${hallName}`,
    `  total surface area:      ${totalSurfaceArea.toFixed(1)} m2`,
    `  total absorption area:   ${totalAbsorptionArea.toFixed(2)} m2 sabine`,
    `  average coefficient:     ${averageCoefficient.toFixed(3)}`,
    `  reverberation time:      ${reverberationTime.toFixed(2)} s (${hallCharacter})`,
    `  strong absorbers used:   ${highlyAbsorptiveCount} of ${materials.length}`,
  ].join('\n');
}

function main() {
  const plasterAndSeatingHall = [[1200, 0.03], [900, 0.25], [450, 0.62], [300, 0.85]];
  const heavilyTreatedHall = [[1000, 0.55], [800, 0.7], [600, 0.9], [200, 0.4]];
  console.log(formatAcousticReport('Grand Hall (classic finishes)', plasterAndSeatingHall));
  console.log(formatAcousticReport('Studio Hall (absorptive finishes)', heavilyTreatedHall));
}

main();

module.exports = { acoustics, formatAcousticReport, classifyHallCharacter };

