const gravityConstant = 9.8;
const wattsPerMegawatt = 1e6;
const maintenancePowerThreshold = 5;
const maintenanceFlowThreshold = 10;

function calculateTurbinePower(headHeight, flowRate, efficiencyPercent) {
  const efficiencyFraction = efficiencyPercent / 100;
  const powerInWatts = headHeight * flowRate * efficiencyFraction * gravityConstant;
  return powerInWatts / wattsPerMegawatt;
}

function requiresMaintenance(powerInMegawatts, flowRate) {
  return powerInMegawatts < maintenancePowerThreshold && flowRate > maintenanceFlowThreshold;
}

function validateTurbineRecord(turbineRecord, recordIndex) {
  if (!Array.isArray(turbineRecord) || turbineRecord.length !== 3) {
    throw new TypeError(`Turbine ${recordIndex} must be an array of three numbers`);
  }
  turbineRecord.forEach((measuredValue, valueIndex) => {
    if (typeof measuredValue !== 'number' || Number.isNaN(measuredValue)) {
      throw new TypeError(`Turbine ${recordIndex}, value ${valueIndex} is not a number`);
    }
  });
}

function hydro(turbines) {
  let totalPowerGenerated = 0;
  let maintenanceCount = 0;
  let highestEfficiency = 0;

  turbines.forEach((turbineRecord, turbineIndex) => {
    validateTurbineRecord(turbineRecord, turbineIndex);
    const [headHeight, flowRate, efficiencyPercent] = turbineRecord;
    const turbinePower = calculateTurbinePower(headHeight, flowRate, efficiencyPercent);

    totalPowerGenerated += turbinePower;
    if (requiresMaintenance(turbinePower, flowRate)) {
      maintenanceCount += 1;
    }
    if (efficiencyPercent > highestEfficiency) {
      highestEfficiency = efficiencyPercent;
    }
  });

  return [totalPowerGenerated, maintenanceCount, highestEfficiency];
}

function formatPlantReport(turbines) {
  const [totalPowerGenerated, maintenanceCount, highestEfficiency] = hydro(turbines);
  const reportLines = [
    `Turbines surveyed: ${turbines.length}`,
    `Total power generated: ${totalPowerGenerated.toFixed(3)} MW`,
    `Turbines flagged for maintenance: ${maintenanceCount}`,
    `Highest efficiency recorded: ${highestEfficiency}%`
  ];
  return reportLines.join('\n');
}

function main() {
  const plantTurbineData = [
    [120, 45, 90],
    [15, 25, 80],
    [200, 60, 94],
    [8, 12, 75],
    [95, 9, 88]
  ];
  console.log(formatPlantReport(plantTurbineData));
}

main();

