const baselineDragFactor = 0.05;
const anomalyThresholdRatio = 1.2;

function predictDailyDrop(solarFluxIndex) {
  return solarFluxIndex * baselineDragFactor;
}

function isAnomalousDrag(measuredDrop, predictedDrop) {
  return measuredDrop > predictedDrop * anomalyThresholdRatio;
}

function validateTelemetryRow(telemetryRow, rowIndex) {
  if (!Array.isArray(telemetryRow) || telemetryRow.length < 3) {
    throw new Error(`Telemetry row ${rowIndex} must contain day, flux and drop`);
  }
  const [dayNumber, solarFluxIndex, measuredDrop] = telemetryRow;
  if (![dayNumber, solarFluxIndex, measuredDrop].every(Number.isFinite)) {
    throw new Error(`Telemetry row ${rowIndex} contains non-numeric values`);
  }
  return { dayNumber, solarFluxIndex, measuredDrop };
}

function decay(telemetry) {
  let totalAltitudeDrop = 0;
  let anomalousEventCount = 0;
  let largestSingleDayDrop = 0;

  telemetry.forEach((telemetryRow, rowIndex) => {
    const { solarFluxIndex, measuredDrop } = validateTelemetryRow(telemetryRow, rowIndex);
    const predictedDrop = predictDailyDrop(solarFluxIndex);

    if (isAnomalousDrag(measuredDrop, predictedDrop)) {
      anomalousEventCount += 1;
    }
    totalAltitudeDrop += measuredDrop;
    if (measuredDrop > largestSingleDayDrop) {
      largestSingleDayDrop = measuredDrop;
    }
  });

  return [totalAltitudeDrop, anomalousEventCount, largestSingleDayDrop];
}

function averageDailyDrop(totalAltitudeDrop, observedDayCount) {
  return observedDayCount === 0 ? 0 : totalAltitudeDrop / observedDayCount;
}

function formatDecayReport(telemetry) {
  const [totalAltitudeDrop, anomalousEventCount, largestSingleDayDrop] = decay(telemetry);
  const meanDailyDrop = averageDailyDrop(totalAltitudeDrop, telemetry.length);
  const reportLines = [
    `Days analysed:        ${telemetry.length}`,
    `Total altitude drop:  ${totalAltitudeDrop.toFixed(2)} m`,
    `Average daily drop:   ${meanDailyDrop.toFixed(2)} m`,
    `Anomalous drag events: ${anomalousEventCount}`,
    `Largest single day:   ${largestSingleDayDrop.toFixed(2)} m`
  ];
  return reportLines.join('\n');
}

const measuredTelemetry = [
  [1, 120, 6.1],
  [2, 135, 9.4],
  [3, 150, 7.4],
  [4, 190, 12.8],
  [5, 205, 10.1],
  [6, 240, 18.6],
  [7, 260, 13.0]
];

console.log(formatDecayReport(measuredTelemetry));

