const iceDensityKgPerCubicMeter = 900;
const meltRateFactorPerDegree = 0.5;
const heavyLossThresholdKg = 1000;

function validateFragmentRecord(fragmentRecord, fragmentIndex) {
  if (!Array.isArray(fragmentRecord) || fragmentRecord.length !== 4) {
    throw new Error(`fragment ${fragmentIndex} must have length, width, height and temperature`);
  }
  fragmentRecord.forEach((measuredValue) => {
    if (typeof measuredValue !== 'number' || !Number.isFinite(measuredValue)) {
      throw new Error(`fragment ${fragmentIndex} contains a non-numeric measurement`);
    }
  });
  const [fragmentLength, fragmentWidth, fragmentHeight] = fragmentRecord;
  if (fragmentLength <= 0 || fragmentWidth <= 0 || fragmentHeight <= 0) {
    throw new Error(`fragment ${fragmentIndex} must have positive dimensions`);
  }
}

function computeInitialMass(fragmentLength, fragmentWidth, fragmentHeight) {
  return fragmentLength * fragmentWidth * fragmentHeight * iceDensityKgPerCubicMeter;
}

function computeDailyMeltFraction(waterTemperature) {
  const meltPercentage = waterTemperature * meltRateFactorPerDegree;
  return meltPercentage > 0 ? meltPercentage / 100 : 0;
}

function describeFragment(fragmentRecord, fragmentIndex) {
  const [fragmentLength, fragmentWidth, fragmentHeight, waterTemperature] = fragmentRecord;
  const initialMassKg = computeInitialMass(fragmentLength, fragmentWidth, fragmentHeight);
  const dailyMeltFraction = computeDailyMeltFraction(waterTemperature);
  const massLostKg = initialMassKg * dailyMeltFraction;
  return { fragmentIndex, initialMassKg, massLostKg };
}

function iceberg(fragments) {
  if (!Array.isArray(fragments)) {
    throw new Error('fragments must be an array of measurement arrays');
  }
  let totalInitialMass = 0;
  let totalMassLost = 0;
  let heavyLossCount = 0;
  fragments.forEach((fragmentRecord, fragmentIndex) => {
    validateFragmentRecord(fragmentRecord, fragmentIndex);
    const fragmentSummary = describeFragment(fragmentRecord, fragmentIndex);
    totalInitialMass += fragmentSummary.initialMassKg;
    totalMassLost += fragmentSummary.massLostKg;
    if (fragmentSummary.massLostKg > heavyLossThresholdKg) {
      heavyLossCount += 1;
    }
  });
  return [totalInitialMass, totalMassLost, heavyLossCount];
}

function formatIcebergReport(fragments) {
  const [totalInitialMass, totalMassLost, heavyLossCount] = iceberg(fragments);
  const survivingMass = totalInitialMass - totalMassLost;
  const lossPercentage = totalInitialMass === 0 ? 0 : (totalMassLost / totalInitialMass) * 100;
  const reportLines = [
    `fragments surveyed: ${fragments.length}`,
    `total initial mass: ${totalInitialMass.toFixed(2)} kg`,
    `mass lost in one day: ${totalMassLost.toFixed(2)} kg (${lossPercentage.toFixed(2)}%)`,
    `mass remaining: ${survivingMass.toFixed(2)} kg`,
    `fragments losing over ${heavyLossThresholdKg} kg: ${heavyLossCount}`,
  ];
  return reportLines.join('\n');
}

const surveyedFragments = [
  [12, 8, 5, 4],
  [3, 2, 1.5, 9],
  [20, 15, 10, 0],
  [6, 4, 2, 2.5],
];

console.log(formatIcebergReport(surveyedFragments));

module.exports = { iceberg, formatIcebergReport };

