const ice_density_kg_per_cubic_meter = 900;
const melt_rate_factor_per_degree = 0.5;
const heavy_loss_threshold_kg = 1000;

function validate_fragment_record(fragment_record, fragment_index) {
  if (!Array.isArray(fragment_record) || fragment_record.length !== 4) {
    throw new Error(`fragment ${fragment_index} must have length, width, height and temperature`);
  }
  fragment_record.forEach((measured_value) => {
    if (typeof measured_value !== 'number' || !Number.isFinite(measured_value)) {
      throw new Error(`fragment ${fragment_index} contains a non-numeric measurement`);
    }
  });
  const [fragment_length, fragment_width, fragment_height] = fragment_record;
  if (fragment_length <= 0 || fragment_width <= 0 || fragment_height <= 0) {
    throw new Error(`fragment ${fragment_index} must have positive dimensions`);
  }
}

function compute_initial_mass(fragment_length, fragment_width, fragment_height) {
  return fragment_length * fragment_width * fragment_height * ice_density_kg_per_cubic_meter;
}

function compute_daily_melt_fraction(water_temperature) {
  const melt_percentage = water_temperature * melt_rate_factor_per_degree;
  return melt_percentage > 0 ? melt_percentage / 100 : 0;
}

function describe_fragment(fragment_record, fragment_index) {
  const [fragment_length, fragment_width, fragment_height, water_temperature] = fragment_record;
  const initial_mass_kg = compute_initial_mass(fragment_length, fragment_width, fragment_height);
  const daily_melt_fraction = compute_daily_melt_fraction(water_temperature);
  const mass_lost_kg = initial_mass_kg * daily_melt_fraction;
  return { fragment_index, initial_mass_kg, mass_lost_kg };
}

function iceberg(fragments) {
  if (!Array.isArray(fragments)) {
    throw new Error('fragments must be an array of measurement arrays');
  }
  let total_initial_mass = 0;
  let total_mass_lost = 0;
  let heavy_loss_count = 0;
  fragments.forEach((fragment_record, fragment_index) => {
    validate_fragment_record(fragment_record, fragment_index);
    const fragment_summary = describe_fragment(fragment_record, fragment_index);
    total_initial_mass += fragment_summary.initial_mass_kg;
    total_mass_lost += fragment_summary.mass_lost_kg;
    if (fragment_summary.mass_lost_kg > heavy_loss_threshold_kg) {
      heavy_loss_count += 1;
    }
  });
  return [total_initial_mass, total_mass_lost, heavy_loss_count];
}

function format_iceberg_report(fragments) {
  const [total_initial_mass, total_mass_lost, heavy_loss_count] = iceberg(fragments);
  const surviving_mass = total_initial_mass - total_mass_lost;
  const loss_percentage = total_initial_mass === 0 ? 0 : (total_mass_lost / total_initial_mass) * 100;
  const report_lines = [
    `fragments surveyed: ${fragments.length}`,
    `total initial mass: ${total_initial_mass.toFixed(2)} kg`,
    `mass lost in one day: ${total_mass_lost.toFixed(2)} kg (${loss_percentage.toFixed(2)}%)`,
    `mass remaining: ${surviving_mass.toFixed(2)} kg`,
    `fragments losing over ${heavy_loss_threshold_kg} kg: ${heavy_loss_count}`,
  ];
  return report_lines.join('\n');
}

const surveyed_fragments = [
  [12, 8, 5, 4],
  [3, 2, 1.5, 9],
  [20, 15, 10, 0],
  [6, 4, 2, 2.5],
];

console.log(format_iceberg_report(surveyed_fragments));

module.exports = { iceberg, format_iceberg_report };

