const standardCabinCapacity = 2;
const familyCabinCapacity = 4;
const suiteCapacity = 6;

function partySizeOf(bookingRecord) {
  const [, adultCount, childCount] = bookingRecord;
  return adultCount + childCount;
}

function determineCabinType(partySize) {
  if (partySize <= standardCabinCapacity) {
    return 'standard';
  }
  if (partySize <= familyCabinCapacity) {
    return 'family';
  }
  if (partySize <= suiteCapacity) {
    return 'suite';
  }
  return 'multipleSuites';
}

function suitesRequiredFor(partySize) {
  return Math.ceil(partySize / suiteCapacity);
}

function cruise(bookings) {
  let totalPassengers = 0;
  let familyCabinCount = 0;
  let multipleSuiteBookings = 0;

  bookings.forEach((bookingRecord) => {
    const partySize = partySizeOf(bookingRecord);
    totalPassengers += partySize;
    const cabinType = determineCabinType(partySize);
    if (cabinType === 'family') {
      familyCabinCount += 1;
    } else if (cabinType === 'multipleSuites') {
      multipleSuiteBookings += 1;
    }
  });

  return [totalPassengers, familyCabinCount, multipleSuiteBookings];
}

function describeBooking(bookingRecord) {
  const [bookingReference] = bookingRecord;
  const partySize = partySizeOf(bookingRecord);
  const cabinType = determineCabinType(partySize);
  if (cabinType === 'multipleSuites') {
    const suiteCount = suitesRequiredFor(partySize);
    return `${bookingReference}: party of ${partySize} needs ${suiteCount} suites`;
  }
  return `${bookingReference}: party of ${partySize} needs 1 ${cabinType} cabin`;
}

function buildOccupancyReport(bookings) {
  const bookingLines = bookings.map(describeBooking);
  const [passengerTotal, familyCabinsAssigned, largePartyBookings] = cruise(bookings);
  const berthsBooked = bookings.reduce((runningTotal, bookingRecord) => {
    const partySize = partySizeOf(bookingRecord);
    return runningTotal + suitesRequiredFor(partySize) * suiteCapacity;
  }, 0);
  const occupancyRate = berthsBooked === 0 ? 0 : (passengerTotal / berthsBooked) * 100;
  const summaryLine =
    `Passengers: ${passengerTotal}, family cabins: ${familyCabinsAssigned}, ` +
    `multi-suite parties: ${largePartyBookings}, occupancy: ${occupancyRate.toFixed(1)}%`;
  return bookingLines.concat(summaryLine).join('\n');
}

const sampleBookings = [
  ['BK-101', 2, 0],
  ['BK-102', 2, 2],
  ['BK-103', 3, 1],
  ['BK-104', 4, 2],
  ['BK-105', 5, 4],
  ['BK-106', 1, 0],
];

console.log(buildOccupancyReport(sampleBookings));

