const vibrationConstant = 1.2;
const fractureThresholdHz = 5;

function expectedVibration(windSpeed, pitchAngle) {
  return windSpeed * vibrationConstant - pitchAngle;
}

function vibrationDeviation(windSpeed, pitchAngle, measuredVibration) {
  return measuredVibration - expectedVibration(windSpeed, pitchAngle);
}

function isMicroFracture(deviationValue) {
  return Math.abs(deviationValue) > fractureThresholdHz;
}

function validateReading(bladeReading, readingIndex) {
  if (!Array.isArray(bladeReading) || bladeReading.length !== 3) {
    throw new TypeError(`reading ${readingIndex} must hold exactly three measurements`);
  }
  bladeReading.forEach((numericField) => {
    if (typeof numericField !== 'number' || !Number.isFinite(numericField)) {
      throw new TypeError(`reading ${readingIndex} contains a non-finite measurement`);
    }
  });
}

function windmill(blades) {
  if (!Array.isArray(blades) || blades.length === 0) {
    throw new TypeError('blades must be a non-empty array of readings');
  }
  let fractureCount = 0;
  let highestVibration = -Infinity;
  let windSpeedTotal = 0;
  blades.forEach((bladeReading, readingIndex) => {
    validateReading(bladeReading, readingIndex);
    const [windSpeed, pitchAngle, measuredVibration] = bladeReading;
    if (isMicroFracture(vibrationDeviation(windSpeed, pitchAngle, measuredVibration))) {
      fractureCount += 1;
    }
    if (measuredVibration > highestVibration) {
      highestVibration = measuredVibration;
    }
    windSpeedTotal += windSpeed;
  });
  const averageWindSpeed = windSpeedTotal / blades.length;
  return [fractureCount, highestVibration, averageWindSpeed];
}

function formatStressReport(reportTuple) {
  const [fractureCount, highestVibration, averageWindSpeed] = reportTuple;
  const fractureLabel = fractureCount === 1 ? 'micro fracture' : 'micro fractures';
  return [
    `${fractureCount} potential ${fractureLabel} detected`,
    `peak measured vibration: ${highestVibration.toFixed(2)} Hz`,
    `average wind speed: ${averageWindSpeed.toFixed(2)} m/s`
  ].join('\n');
}

function runDiagnostics(sensorLog) {
  const stressSummary = windmill(sensorLog);
  console.log(formatStressReport(stressSummary));
  return stressSummary;
}

const turbineSensorLog = [
  [12, 4, 14.2],
  [18, 10, 25.9],
  [7, 2, 6.1],
  [22, 15, 3.4],
  [15, 6, 11.8]
];

runDiagnostics(turbineSensorLog);

module.exports = { windmill, formatStressReport, runDiagnostics };

