function validateTimestamps(timestamps, limit) {
  if (!Array.isArray(timestamps)) {
    throw new TypeError('timestamps must be an array of seconds');
  }
  const numericTimestamps = timestamps.map((rawTimestamp, timestampIndex) => {
    const parsedTimestamp = Number(rawTimestamp);
    if (!Number.isFinite(parsedTimestamp)) {
      throw new TypeError(`timestamp at index ${timestampIndex} is not a finite number`);
    }
    return parsedTimestamp;
  });
  for (let currentIndex = 1; currentIndex < numericTimestamps.length; currentIndex += 1) {
    if (numericTimestamps[currentIndex] < numericTimestamps[currentIndex - 1]) {
      throw new RangeError('timestamps must be sorted in ascending order');
    }
  }
  const numericLimit = Number(limit);
  if (!Number.isFinite(numericLimit) || numericLimit < 0) {
    throw new RangeError('limit must be a non-negative finite number');
  }
  return { numericTimestamps, numericLimit };
}

function buildClusters(sortedTimestamps, gapLimit) {
  const defectClusters = [];
  let pendingCluster = [];
  sortedTimestamps.forEach((currentTimestamp) => {
    if (pendingCluster.length === 0) {
      pendingCluster.push(currentTimestamp);
      return;
    }
    const previousTimestamp = pendingCluster[pendingCluster.length - 1];
    if (currentTimestamp - previousTimestamp <= gapLimit) {
      pendingCluster.push(currentTimestamp);
    } else {
      defectClusters.push(pendingCluster);
      pendingCluster = [currentTimestamp];
    }
  });
  if (pendingCluster.length > 0) {
    defectClusters.push(pendingCluster);
  }
  return defectClusters;
}

function measureClusterDuration(clusterTimestamps) {
  const firstDefectTime = clusterTimestamps[0];
  const lastDefectTime = clusterTimestamps[clusterTimestamps.length - 1];
  return lastDefectTime - firstDefectTime;
}

function countDistinctDefects(clusterTimestamps) {
  return new Set(clusterTimestamps).size;
}

function inspect(timestamps, limit) {
  const { numericTimestamps, numericLimit } = validateTimestamps(timestamps, limit);
  const defectClusters = buildClusters(numericTimestamps, numericLimit);
  let maximumClusterDuration = 0;
  let largeClusterCount = 0;
  defectClusters.forEach((clusterTimestamps) => {
    const currentDuration = measureClusterDuration(clusterTimestamps);
    if (currentDuration > maximumClusterDuration) {
      maximumClusterDuration = currentDuration;
    }
    if (countDistinctDefects(clusterTimestamps) > 3) {
      largeClusterCount += 1;
    }
  });
  return [defectClusters.length, maximumClusterDuration, largeClusterCount];
}

function formatInspectionReport(inspectionResult) {
  const [totalClusters, maximumDuration, largeClusters] = inspectionResult;
  return `clusters=${totalClusters} maxDuration=${maximumDuration}s large=${largeClusters}`;
}

function main() {
  const defectTimestamps = [1, 2.5, 3, 4, 10, 11, 30, 30, 31, 32, 33.5, 90];
  const clusterGapLimit = 2;
  const inspectionResult = inspect(defectTimestamps, clusterGapLimit);
  console.log(formatInspectionReport(inspectionResult));
}

main();

module.exports = { inspect, buildClusters, formatInspectionReport };

