function computeAmbientPressure(depthInMeters) {
  return 1 + depthInMeters / 10;
}

function buildPressureProfile(readings) {
  const pressureProfile = [];
  for (const depthReading of readings) {
    pressureProfile.push(computeAmbientPressure(depthReading));
  }
  return pressureProfile;
}

function findDangerSegments(readings, danger) {
  const dangerSegments = [];
  let segmentStartIndex = -1;
  for (let minuteIndex = 0; minuteIndex < readings.length; minuteIndex += 1) {
    const isDangerous = readings[minuteIndex] > danger;
    if (isDangerous && segmentStartIndex === -1) {
      segmentStartIndex = minuteIndex;
    } else if (!isDangerous && segmentStartIndex !== -1) {
      dangerSegments.push([segmentStartIndex, minuteIndex - 1]);
      segmentStartIndex = -1;
    }
  }
  if (segmentStartIndex !== -1) {
    dangerSegments.push([segmentStartIndex, readings.length - 1]);
  }
  return dangerSegments;
}

function summarizeDangerZones(pressureProfile, dangerSegments) {
  let totalDangerousMinutes = 0;
  let peakDangerPressure = 0;
  for (const [startMinute, endMinute] of dangerSegments) {
    totalDangerousMinutes += endMinute - startMinute + 1;
    for (let minuteIndex = startMinute; minuteIndex <= endMinute; minuteIndex += 1) {
      if (pressureProfile[minuteIndex] > peakDangerPressure) {
        peakDangerPressure = pressureProfile[minuteIndex];
      }
    }
  }
  return [totalDangerousMinutes, peakDangerPressure];
}

function evaluate(readings, danger) {
  const pressureProfile = buildPressureProfile(readings);
  const dangerSegments = findDangerSegments(readings, danger);
  return summarizeDangerZones(pressureProfile, dangerSegments);
}

function formatDiveReport(readings, danger) {
  const [dangerousMinuteCount, highestPressure] = evaluate(readings, danger);
  const segmentDescriptions = findDangerSegments(readings, danger).map(
    ([startMinute, endMinute]) => `${startMinute}-${endMinute}`
  );
  const segmentSummary = segmentDescriptions.length > 0 ? segmentDescriptions.join(', ') : 'none';
  return [
    `threshold: ${danger} m`,
    `dangerous minutes: ${dangerousMinuteCount}`,
    `peak pressure in danger: ${highestPressure.toFixed(2)} atm`,
    `segments (minute ranges): ${segmentSummary}`
  ].join('\n');
}

function main() {
  const dangerThreshold = 50;
  const diveReadings = [5, 12, 40, 85, 120, 90, 30, 8, 60, 210, 205, 15];
  console.log(formatDiveReport(diveReadings, dangerThreshold));

  const shallowSurvey = [2, 4, 6, 3, 1];
  console.log(formatDiveReport(shallowSurvey, dangerThreshold));
}

main();

