  }
  if (window > counts.length) {
    throw new RangeError('window cannot exceed the number of recorded minutes');
  }
  counts.forEach((minuteCount, minuteIndex) => {
    if (typeof minuteCount !== 'number' || !Number.isFinite(minuteCount) || minuteCount < 0) {
      throw new TypeError(`invalid meteor count at minute ${minuteIndex}`);
    }
  });
}

function computeSegmentTotals(counts, window) {
  const segmentTotals = [];
  let runningTotal = 0;
  for (let minuteIndex = 0; minuteIndex < counts.length; minuteIndex += 1) {
    runningTotal += counts[minuteIndex];
    if (minuteIndex >= window) {
      runningTotal -= counts[minuteIndex - window];
    }
    if (minuteIndex >= window - 1) {
      segmentTotals.push(runningTotal);
    }
  }
  return segmentTotals;
}

function averagePerMinute(segmentTotal, window) {
  return Math.round((segmentTotal / window) * 10) / 10;
}

function locate(counts, window) {
  validateObservations(counts, window);
  const segmentTotals = computeSegmentTotals(counts, window);
  let peakStartMinute = 0;
  let peakTotalCount = segmentTotals[0];
  for (let startMinute = 1; startMinute < segmentTotals.length; startMinute += 1) {
    if (segmentTotals[startMinute] > peakTotalCount) {
      peakTotalCount = segmentTotals[startMinute];
      peakStartMinute = startMinute;
    }
  }
  return [peakStartMinute, peakTotalCount, averagePerMinute(peakTotalCount, window)];
}

