const minorStressDropPercent = 0.1;
const moderateStressDropPercent = 1;
const overloadPenaltyDivisor = 10;
const initialIntegrityPercent = 100;

function validateSimulationInputs(forces, limit) {
  if (!Array.isArray(forces)) {
    throw new TypeError('forces must be an array of daily peak forces');
  }
  const hasInvalidForce = forces.some(
    (dailyForce) => typeof dailyForce !== 'number' || !Number.isFinite(dailyForce)
  );
  if (hasInvalidForce) {
    throw new TypeError('every daily peak force must be a finite number');
  }
  if (typeof limit !== 'number' || !(limit > 0)) {
    throw new RangeError('limit must be a positive fatigue threshold');
  }
}

function classifyDailyForce(dailyForce, fatigueLimit) {
  const halfLimitThreshold = fatigueLimit / 2;
  if (dailyForce < halfLimitThreshold) {
    return 'lowStress';
  }
  if (dailyForce <= fatigueLimit) {
    return 'moderateStress';
  }
  return 'overload';
}

function computeIntegrityDrop(dailyForce, fatigueLimit) {
  const stressCategory = classifyDailyForce(dailyForce, fatigueLimit);
  if (stressCategory === 'lowStress') {
    return minorStressDropPercent;
  }
  if (stressCategory === 'moderateStress') {
    return moderateStressDropPercent;
  }
  return (dailyForce - fatigueLimit) / overloadPenaltyDivisor;
}

function roundToTwoDecimals(numericValue) {
  return Math.round(numericValue * 100) / 100;
}

function simulate(forces, limit) {
  validateSimulationInputs(forces, limit);
  let currentIntegrity = initialIntegrityPercent;
  let daysSurvived = 0;
  for (const dailyPeakForce of forces) {
    currentIntegrity -= computeIntegrityDrop(dailyPeakForce, limit);
    daysSurvived += 1;
    if (currentIntegrity < 0) {
      break;
    }
  }
  return [daysSurvived, roundToTwoDecimals(currentIntegrity)];
}

function buildRepeatedForceSchedule(forcePattern, repeatCount) {
  const repeatedSchedule = [];
  for (let cycleIndex = 0; cycleIndex < repeatCount; cycleIndex += 1) {
    repeatedSchedule.push(...forcePattern);
  }
  return repeatedSchedule;
}

function formatSimulationReport(simulationResult, fatigueLimit) {
  const [daysSurvived, finalIntegrity] = simulationResult;
  const frameCondition = finalIntegrity < 0 ? 'collapsed' : 'still standing';
  return `limit ${fatigueLimit}: survived ${daysSurvived} day(s), `
    + `final integrity ${finalIntegrity.toFixed(2)}% (${frameCondition})`;
}

function runFrameSimulation(forceSeries, fatigueLimit) {
  const simulationResult = simulate(forceSeries, fatigueLimit);
  console.log(formatSimulationReport(simulationResult, fatigueLimit));
  return simulationResult;
}

const designFatigueLimit = 500;
const weeklyForcePattern = [180, 220, 300, 460, 510, 240, 150];
const dailyForceLog = buildRepeatedForceSchedule(weeklyForcePattern, 40);
runFrameSimulation(dailyForceLog, designFatigueLimit);

const stormSeasonForces = [600, 900, 1400, 2000];
runFrameSimulation(stormSeasonForces, designFatigueLimit);

module.exports = { simulate, classifyDailyForce, computeIntegrityDrop, buildRepeatedForceSchedule, formatSimulationReport };

