const CRITICAL_SAFETY_HEIGHT = 1000;
const TERMINAL_VELOCITY_TOLERANCE = 1;

function validateFreefallInputs(altitudeReadings, resistanceFactor) {
  if (!Array.isArray(altitudeReadings) || altitudeReadings.length < 3) {
    throw new Error('at least three altitude recordings are required');
  }
  if (typeof resistanceFactor !== 'number' || !Number.isFinite(resistanceFactor)) {
    throw new Error('resistance must be a finite number');
  }
  altitudeReadings.forEach((singleReading, readingIndex) => {
    if (typeof singleReading !== 'number' || !Number.isFinite(singleReading)) {
      throw new Error(`altitude at index ${readingIndex} is not a finite number`);
    }
  });
}

function computeDescentVelocities(altitudeReadings, resistanceFactor) {
  const descentVelocities = [];
  for (let secondIndex = 1; secondIndex < altitudeReadings.length; secondIndex += 1) {
    const heightLost = altitudeReadings[secondIndex - 1] - altitudeReadings[secondIndex];
    descentVelocities.push(heightLost * resistanceFactor);
  }
  return descentVelocities;
}

function findTerminalVelocityIndex(descentVelocities) {
  for (let velocityIndex = 1; velocityIndex < descentVelocities.length; velocityIndex += 1) {
    const velocityChange = Math.abs(descentVelocities[velocityIndex] - descentVelocities[velocityIndex - 1]);
    if (velocityChange < TERMINAL_VELOCITY_TOLERANCE) {
      return velocityIndex;
    }
  }
  return -1;
}

function findLowestAltitudeBeforeTerminal(altitudeReadings, terminalReadingIndex) {
  let lowestAltitude = altitudeReadings[0];
  for (let readingIndex = 1; readingIndex < terminalReadingIndex; readingIndex += 1) {
    if (altitudeReadings[readingIndex] < lowestAltitude) {
      lowestAltitude = altitudeReadings[readingIndex];
    }
  }
  return lowestAltitude;
}

function findDeploymentAltitude(altitudeReadings, terminalReadingIndex) {
  for (let readingIndex = terminalReadingIndex; readingIndex < altitudeReadings.length; readingIndex += 1) {
    if (altitudeReadings[readingIndex] < CRITICAL_SAFETY_HEIGHT) {
      return altitudeReadings[readingIndex];
    }
  }
  return null;
}

function calculate(altitudes, resistance) {
  validateFreefallInputs(altitudes, resistance);
  const descentVelocities = computeDescentVelocities(altitudes, resistance);
  const terminalVelocityIndex = findTerminalVelocityIndex(descentVelocities);
  if (terminalVelocityIndex === -1) {
    return [null, null];
  }
  const terminalReadingIndex = terminalVelocityIndex + 1;
  const terminalVelocity = descentVelocities[terminalVelocityIndex];
  const deploymentAltitude = findDeploymentAltitude(altitudes, terminalReadingIndex);
  return [deploymentAltitude, terminalVelocity];
}

function formatJumpReport(altitudeReadings, resistanceFactor) {
  const [deploymentAltitude, terminalVelocity] = calculate(altitudeReadings, resistanceFactor);
  if (deploymentAltitude === null) {
    const stillAcceleratingNote = terminalVelocity === null
      ? 'terminal velocity never established'
      : `terminal velocity ${terminalVelocity.toFixed(2)} m/s, but altitude stayed safe`;
    return `no deployment: ${stillAcceleratingNote}`;
  }
  const descentVelocities = computeDescentVelocities(altitudeReadings, resistanceFactor);
  const terminalReadingIndex = findTerminalVelocityIndex(descentVelocities) + 1;
  const lowestAltitudeBeforeTerminal = findLowestAltitudeBeforeTerminal(altitudeReadings, terminalReadingIndex);
  return `deployed at ${deploymentAltitude} m, terminal velocity ${terminalVelocity.toFixed(2)} m/s, `
    + `lowest free altitude ${lowestAltitudeBeforeTerminal} m`;
}

const recordedAltitudes = [4000, 3900, 3750, 3560, 3350, 3140, 2930, 2720, 1500, 900, 300];
const airResistanceFactor = 0.9;
console.log(formatJumpReport(recordedAltitudes, airResistanceFactor));
console.log(calculate(recordedAltitudes, airResistanceFactor));

module.exports = { calculate, computeDescentVelocities, findTerminalVelocityIndex, formatJumpReport };

