const growthPeriodDays = 30;
const baseDailyGrowth = 2;
const sunlightBonusThreshold = 10;
const sunlightBonusGrowth = 1;
const crowdingHeightThreshold = 50;
const crowdingGrowthPenalty = 0.1;
const tallFrondThreshold = 60;

function computeDailyGrowth(sunlightHours, currentHeight) {
  let dailyGrowth = baseDailyGrowth;
  if (sunlightHours > sunlightBonusThreshold) {
    dailyGrowth += sunlightBonusGrowth;
  }
  if (currentHeight > crowdingHeightThreshold) {
    dailyGrowth *= 1 - crowdingGrowthPenalty;
  }
  return dailyGrowth;
}

function growSingleFrond(initialHeight, sunlightHours) {
  let currentHeight = initialHeight;
  for (let dayIndex = 0; dayIndex < growthPeriodDays; dayIndex += 1) {
    currentHeight += computeDailyGrowth(sunlightHours, currentHeight);
  }
  return currentHeight;
}

function simulateAllFronds(initialHeights, sunlightHours) {
  return initialHeights.map((frondHeight) => growSingleFrond(frondHeight, sunlightHours));
}

function averageFinalHeight(finalHeights) {
  if (finalHeights.length === 0) {
    return 0;
  }
  const heightSum = finalHeights.reduce((runningTotal, frondHeight) => runningTotal + frondHeight, 0);
  return heightSum / finalHeights.length;
}

function countTallFronds(finalHeights) {
  return finalHeights.filter((frondHeight) => frondHeight > tallFrondThreshold).length;
}

function validateSimulationInput(fronds, sunlight) {
  if (!Array.isArray(fronds)) {
    throw new TypeError('fronds must be an array of initial kelp heights');
  }
  const hasInvalidHeight = fronds.some((frondHeight) => typeof frondHeight !== 'number' || Number.isNaN(frondHeight));
  if (hasInvalidHeight) {
    throw new TypeError('every initial kelp height must be a number');
  }
  if (typeof sunlight !== 'number' || Number.isNaN(sunlight) || sunlight < 0) {
    throw new RangeError('sunlight must be a non-negative number of hours');
  }
}

function project(fronds, sunlight) {
  validateSimulationInput(fronds, sunlight);
  const finalHeights = simulateAllFronds(fronds, sunlight);
  const averageHeight = averageFinalHeight(finalHeights);
  return [Math.floor(averageHeight), countTallFronds(finalHeights)];
}

function formatProjectionReport(fronds, sunlight) {
  const [averageHeightFloored, tallFrondCount] = project(fronds, sunlight);
  const bedDescription = `${fronds.length} fronds at ${sunlight}h of sunlight`;
  return `${bedDescription}: average ${averageHeightFloored} cm, ${tallFrondCount} above ${tallFrondThreshold} cm`;
}

function runProjectionDriver() {
  const shallowBedFronds = [5, 12, 40, 55];
  const deepBedFronds = [2, 8, 20];
  const shortSunlightHours = 8;
  const longSunlightHours = 14;
  console.log(formatProjectionReport(shallowBedFronds, longSunlightHours));
  console.log(formatProjectionReport(deepBedFronds, shortSunlightHours));
}

runProjectionDriver();

module.exports = { project, growSingleFrond, formatProjectionReport };

