  return initial_heights.map((frond_height) => grow_single_frond(frond_height, sunlight_hours));
}

function average_final_height(final_heights) {
  if (final_heights.length === 0) {
    return 0;
  }
  const height_sum = final_heights.reduce((running_total, frond_height) => running_total + frond_height, 0);
  return height_sum / final_heights.length;
}

function count_tall_fronds(final_heights) {
  return final_heights.filter((frond_height) => frond_height > tall_frond_threshold).length;
}

function validate_simulation_input(fronds, sunlight) {
  if (!Array.isArray(fronds)) {
    throw new TypeError('fronds must be an array of initial kelp heights');
  }
  const has_invalid_height = fronds.some((frond_height) => typeof frond_height !== 'number' || Number.isNaN(frond_height));
  if (has_invalid_height) {
    throw new TypeError('every initial kelp height must be a number');
  }
  if (typeof sunlight !== 'number' || Number.isNaN(sunlight) || sunlight < 0) {
    throw new RangeError('sunlight must be a non-negative number of hours');
  }
}

function project(fronds, sunlight) {
  validate_simulation_input(fronds, sunlight);
  const final_heights = simulate_all_fronds(fronds, sunlight);
  const average_height = average_final_height(final_heights);
  return [Math.floor(average_height), count_tall_fronds(final_heights)];
}

function format_projection_report(fronds, sunlight) {
  const [average_height_floored, tall_frond_count] = project(fronds, sunlight);
  const bed_description = `${fronds.length} fronds at ${sunlight}h of sunlight`;
  return `${bed_description}: average ${average_height_floored} cm, ${tall_frond_count} above ${tall_frond_threshold} cm`;
}

function run_projection_driver() {
  const shallow_bed_fronds = [5, 12, 40, 55];
  const deep_bed_fronds = [2, 8, 20];
