const longDurationThreshold = 100;
const shortDurationThreshold = 20;
const largeCrystalBonusRate = 0.25;
const poorCrystallizationPenaltyRate = 0.15;

function roundToTwoDecimals(rawValue) {
  return Math.round(rawValue * 100) / 100;
}

function validateGeodeEntry(geodeEntry, entryIndex) {
  if (typeof geodeEntry !== 'object' || geodeEntry === null) {
    throw new TypeError(`geode at index ${entryIndex} is not an object`);
  }
  const { volume: geodeVolume, duration: formationDuration } = geodeEntry;
  if (typeof geodeVolume !== 'number' || Number.isNaN(geodeVolume)) {
    throw new TypeError(`geode at index ${entryIndex} has an invalid volume`);
  }
  if (typeof formationDuration !== 'number' || Number.isNaN(formationDuration)) {
    throw new TypeError(`geode at index ${entryIndex} has an invalid duration`);
  }
  return { geodeVolume, formationDuration };
}

function computeCrystalWeight(geodeVolume, formationDuration, mineralConcentration) {
  let crystalWeight = geodeVolume * mineralConcentration;
  if (formationDuration > longDurationThreshold) {
    crystalWeight += crystalWeight * largeCrystalBonusRate;
  } else if (formationDuration < shortDurationThreshold) {
    crystalWeight -= crystalWeight * poorCrystallizationPenaltyRate;
  }
  return crystalWeight;
}

function extract(geodes, concentration) {
  if (!Array.isArray(geodes)) {
    throw new TypeError('geodes must be an array of geode objects');
