const angularConversionFactor = 0.1047;
const liftScalingConstant = 0.05;
const bladesPerRotor = 4;

function validateBladeConfig(bladeConfig, configIndex) {
  if (typeof bladeConfig !== 'object' || bladeConfig === null) {
    throw new TypeError(`blade configuration at index ${configIndex} is not an object`);
  }
  const { length: bladeLength, rpm: rotorRpm } = bladeConfig;
  if (!Number.isFinite(bladeLength) || bladeLength <= 0) {
    throw new RangeError(`blade length at index ${configIndex} must be a positive number`);
  }
  if (!Number.isFinite(rotorRpm) || rotorRpm < 0) {
    throw new RangeError(`blade rpm at index ${configIndex} must be a non-negative number`);
  }
  return { bladeLength, rotorRpm };
}

function calculateTipSpeed(bladeLength, rotorRpm) {
  return bladeLength * rotorRpm * angularConversionFactor;
}

function calculateSingleBladeLift(tipSpeed, airDensity) {
  return tipSpeed * tipSpeed * airDensity * liftScalingConstant;
}

function calculateRotorLift(bladeConfig, airDensity, configIndex) {
  const { bladeLength, rotorRpm } = validateBladeConfig(bladeConfig, configIndex);
  const tipSpeed = calculateTipSpeed(bladeLength, rotorRpm);
  const singleBladeLift = calculateSingleBladeLift(tipSpeed, airDensity);
  return singleBladeLift * bladesPerRotor;
}

function compute(blades, density) {
  if (!Array.isArray(blades) || blades.length === 0) {
    throw new RangeError('at least one blade configuration is required');
  }
  if (!Number.isFinite(density) || density <= 0) {
    throw new RangeError('air density must be a positive number');
  }
  const rotorLifts = blades.map((bladeConfig, configIndex) =>
    calculateRotorLift(bladeConfig, density, configIndex));
  const maximumTotalLift = rotorLifts.reduce((bestLift, currentLift) =>
    currentLift > bestLift ? currentLift : bestLift, rotorLifts[0]);
  const summedLift = rotorLifts.reduce((runningTotal, currentLift) => runningTotal + currentLift, 0);
  const averageLift = summedLift / rotorLifts.length;
  return [Math.round(maximumTotalLift), Math.round(averageLift)];
}

function formatLiftReport(bladeConfigs, airDensity) {
  const [highestLift, meanLift] = compute(bladeConfigs, airDensity);
  const reportLines = bladeConfigs.map((bladeConfig, configIndex) => {
    const rotorLift = calculateRotorLift(bladeConfig, airDensity, configIndex);
    const configLabel = `blade ${bladeConfig.length} m @ ${bladeConfig.rpm} rpm`;
    return `${configLabel}: ${rotorLift.toFixed(1)} N`;
  });
  reportLines.push(`peak rotor lift: ${highestLift} N`);
  reportLines.push(`average rotor lift: ${meanLift} N`);
  return reportLines.join('\n');
}

function main() {
  const standardAirDensity = 1.225;
  const bladeConfigurations = [
    { length: 2.5, rpm: 480 },
    { length: 3.2, rpm: 390 },
    { length: 1.8, rpm: 620 },
  ];
  console.log(formatLiftReport(bladeConfigurations, standardAirDensity));
}

main();

module.exports = { compute, calculateTipSpeed, calculateRotorLift, formatLiftReport };

