const evaporationRatePerHour = 15;

function validateBatch(rawBatch, batchIndex) {
  if (typeof rawBatch !== 'object' || rawBatch === null) {
    throw new TypeError(`batch ${batchIndex} is not an object`);
  }
  const batchVolume = Number(rawBatch.volume);
  const initialSugar = Number(rawBatch.sugar);
  if (!Number.isFinite(batchVolume) || batchVolume <= 0) {
    throw new RangeError(`batch ${batchIndex} has an invalid volume`);
  }
  if (!Number.isFinite(initialSugar) || initialSugar <= 0) {
    throw new RangeError(`batch ${batchIndex} has an invalid sugar content`);
  }
  return { batchVolume, initialSugar };
}

function validateTarget(targetPercentage) {
  const parsedTarget = Number(targetPercentage);
  if (!Number.isFinite(parsedTarget) || parsedTarget <= 0) {
    throw new RangeError('target sugar percentage must be a positive number');
  }
  return parsedTarget;
}

function finalSyrupVolume(batchVolume, initialSugar, targetPercentage) {
  return (batchVolume * initialSugar) / targetPercentage;
}

function evaporatedWaterVolume(batchVolume, syrupVolume) {
  return batchVolume - syrupVolume;
}

function boilingHours(waterToEvaporate) {
  return waterToEvaporate / evaporationRatePerHour;
}

function describeBatch(batchIndex, syrupVolume, hoursNeeded) {
  const roundedSyrup = syrupVolume.toFixed(2);
  const roundedHours = hoursNeeded.toFixed(2);
  return `batch ${batchIndex + 1}: ${roundedSyrup} L syrup after ${roundedHours} h`;
}

function boil(batches, target) {
  if (!Array.isArray(batches)) {
    throw new TypeError('batches must be an array');
  }
  const targetPercentage = validateTarget(target);
  let totalBoilingHours = 0;
  let totalSyrupVolume = 0;
  batches.forEach((rawBatch, batchIndex) => {
    const { batchVolume, initialSugar } = validateBatch(rawBatch, batchIndex);
    const syrupVolume = finalSyrupVolume(batchVolume, initialSugar, targetPercentage);
    const waterToEvaporate = evaporatedWaterVolume(batchVolume, syrupVolume);
    totalBoilingHours += boilingHours(waterToEvaporate);
    totalSyrupVolume += syrupVolume;
  });
  return [totalBoilingHours, totalSyrupVolume];
}

