const redIndexOffset = -0.02;
const blueIndexOffset = 0.02;
const outsideMediumIndex = 1;

function degreesToRadians(angleInDegrees) {
  return (angleInDegrees * Math.PI) / 180;
}

function radiansToDegrees(angleInRadians) {
  return (angleInRadians * 180) / Math.PI;
}

function computeRefractionAngle(incidentAngleRadians, refractiveIndex) {
  const sineRatio = (outsideMediumIndex * Math.sin(incidentAngleRadians)) / refractiveIndex;
  return Math.asin(sineRatio);
}

function computeSeparationAngle(incidentAngleDegrees, baseIndex) {
  const incidentAngleRadians = degreesToRadians(incidentAngleDegrees);
  const redRefractionAngle = computeRefractionAngle(incidentAngleRadians, baseIndex + redIndexOffset);
  const blueRefractionAngle = computeRefractionAngle(incidentAngleRadians, baseIndex + blueIndexOffset);
  return Math.abs(radiansToDegrees(redRefractionAngle) - radiansToDegrees(blueRefractionAngle));
}

function roundToThreeDecimals(rawValue) {
  return Math.round(rawValue * 1000) / 1000;
}

function validateInputs(angles, index) {
  if (!Array.isArray(angles) || angles.length === 0) {
    throw new Error('angles must be a non-empty list of incident angles');
  }
  angles.forEach((candidateAngle) => {
    if (typeof candidateAngle !== 'number' || Number.isNaN(candidateAngle)) {
      throw new Error(`invalid incident angle: ${candidateAngle}`);
    }
  });
  const smallestUsableIndex = 1 - redIndexOffset;
  if (typeof index !== 'number' || index <= smallestUsableIndex) {
    throw new Error('index must be a refractive index greater than the outside medium');
  }
}

function refract(angles, index) {
  validateInputs(angles, index);
  const separationAngles = angles.map((incidentAngle) => computeSeparationAngle(incidentAngle, index));
  let maximumSeparation = separationAngles[0];
  let separationTotal = 0;
  separationAngles.forEach((currentSeparation) => {
    if (currentSeparation > maximumSeparation) {
      maximumSeparation = currentSeparation;
    }
    separationTotal += currentSeparation;
  });
  const averageSeparation = separationTotal / separationAngles.length;
  return [roundToThreeDecimals(maximumSeparation), roundToThreeDecimals(averageSeparation)];
}

function formatDispersionReport(angles, index) {
  const [maximumSeparation, averageSeparation] = refract(angles, index);
  const angleListText = angles.map((incidentAngle) => `${incidentAngle}deg`).join(', ');
  return [
    `glass index ${index} over incident angles ${angleListText}`,
    `maximum separation: ${maximumSeparation} deg`,
    `average separation: ${averageSeparation} deg`,
  ].join('\n');
}

function main() {
  const crownGlassIndex = 1.52;
  const incidentAngleSamples = [0, 15, 30, 45, 60, 75, 89];
  console.log(formatDispersionReport(incidentAngleSamples, crownGlassIndex));

  const denseFlintIndex = 1.72;
  const steepAngleSamples = [40, 50, 60, 70];
  console.log(formatDispersionReport(steepAngleSamples, denseFlintIndex));
}

