function refract(angles, index) {
  validate_inputs(angles, index);
  const separation_angles = angles.map((incident_angle) => compute_separation_angle(incident_angle, index));
  let maximum_separation = separation_angles[0];
  let separation_total = 0;
  separation_angles.forEach((current_separation) => {
    if (current_separation > maximum_separation) {
      maximum_separation = current_separation;
    }
    separation_total += current_separation;
