const minimumPruningInterval = 2;
const maximumPruningInterval = 12;
const highMaintenanceThreshold = 4;

function validateTreeEntry(treeEntry, entryIndex) {
  if (treeEntry === null || typeof treeEntry !== 'object') {
    throw new TypeError(`Tree at index ${entryIndex} is not an object`);
  }
  const growthRate = Number(treeEntry.growth);
  const densityFactor = Number(treeEntry.density);
  if (!Number.isFinite(growthRate) || !Number.isFinite(densityFactor)) {
    throw new TypeError(`Tree at index ${entryIndex} has non-numeric growth or density`);
  }
  if (growthRate <= 0 || densityFactor <= 0) {
    throw new RangeError(`Tree at index ${entryIndex} must have positive growth and density`);
  }
  return { growthRate, densityFactor };
}

function clampPruningInterval(rawInterval) {
  if (rawInterval < minimumPruningInterval) {
    return minimumPruningInterval;
  }
  if (rawInterval > maximumPruningInterval) {
    return maximumPruningInterval;
  }
  return rawInterval;
}

function computePruningInterval(shapeIndex, growthRate, densityFactor) {
  return clampPruningInterval(shapeIndex / (growthRate * densityFactor));
}

function buildIntervalList(trees, shapeIndex) {
  return trees.map((treeEntry, entryIndex) => {
    const { growthRate, densityFactor } = validateTreeEntry(treeEntry, entryIndex);
    return computePruningInterval(shapeIndex, growthRate, densityFactor);
  });
}

function countHighMaintenanceTrees(intervalList) {
  return intervalList.filter((treeInterval) => treeInterval < highMaintenanceThreshold).length;
}

function averagePruningInterval(intervalList) {
  if (intervalList.length === 0) {
    return 0;
  }
  const intervalSum = intervalList.reduce((runningTotal, treeInterval) => runningTotal + treeInterval, 0);
  return intervalSum / intervalList.length;
}

function schedule(trees, shape) {
  if (!Array.isArray(trees)) {
    throw new TypeError('trees must be an array');
  }
  const shapeIndex = Number(shape);
  if (!Number.isFinite(shapeIndex) || shapeIndex <= 0) {
    throw new RangeError('shape must be a positive finite number');
  }
  const intervalList = buildIntervalList(trees, shapeIndex);
  return [averagePruningInterval(intervalList), countHighMaintenanceTrees(intervalList)];
}

function formatScheduleReport(scheduleResult, treeCount) {
  const [averageInterval, highMaintenanceCount] = scheduleResult;
  const roundedAverage = averageInterval.toFixed(2);
