const amplificationFactor = 2.5;
const highPassCap = 1000;

function amplifyReading(rawReading, noiseThreshold) {
  if (rawReading <= noiseThreshold) {
    return 0;
  }
  const amplifiedValue = (rawReading - noiseThreshold) * amplificationFactor;
  return Math.min(amplifiedValue, highPassCap);
}

function validateInputs(signals, noise) {
  if (!Array.isArray(signals)) {
    throw new TypeError('signals must be an array of readings');
  }
  const hasInvalidReading = signals.some((reading) => typeof reading !== 'number' || Number.isNaN(reading));
  if (hasInvalidReading) {
    throw new TypeError('every reading must be a finite number');
  }
  if (typeof noise !== 'number' || Number.isNaN(noise)) {
    throw new TypeError('noise threshold must be a number');
  }
}

function buildAmplificationCurve(signals, noiseThreshold) {
  return signals.map((rawReading) => amplifyReading(rawReading, noiseThreshold));
}

function findSignalBursts(amplifiedCurve) {
  const burstList = [];
  let currentBurst = [];
  amplifiedCurve.forEach((amplifiedValue) => {
    if (amplifiedValue > 0) {
      currentBurst.push(amplifiedValue);
    } else if (currentBurst.length > 0) {
      burstList.push(currentBurst);
      currentBurst = [];
    }
  });
  if (currentBurst.length > 0) {
    burstList.push(currentBurst);
  }
  return burstList;
}

function selectLongestBurst(burstList) {
  return burstList.reduce((longestSoFar, candidateBurst) => (
    candidateBurst.length > longestSoFar.length ? candidateBurst : longestSoFar
  ), []);
}

function sumBurstEnergy(burstValues) {
  return burstValues.reduce((energyTotal, amplifiedValue) => energyTotal + amplifiedValue, 0);
}

function amplify(signals, noise) {
  validateInputs(signals, noise);
  const amplifiedCurve = buildAmplificationCurve(signals, noise);
  const longestBurst = selectLongestBurst(findSignalBursts(amplifiedCurve));
  const longestBurstEnergy = sumBurstEnergy(longestBurst);
  const peakAmplifiedSignal = amplifiedCurve.reduce((highestSoFar, amplifiedValue) => (
    amplifiedValue > highestSoFar ? amplifiedValue : highestSoFar
  ), 0);
  return [longestBurstEnergy, peakAmplifiedSignal];
}

function formatAmplificationReport(signals, noise) {
