const gravityDoubled = 19.6;
const wallHeightMeters = 4;
const highAirThreshold = 2;

function validateFrictionFactor(frictionFactor) {
  if (typeof frictionFactor !== 'number' || Number.isNaN(frictionFactor)) {
    throw new TypeError('friction must be a number');
  }
  if (frictionFactor <= 0 || frictionFactor >= 1) {
    throw new RangeError('friction must lie strictly between 0 and 1');
  }
  return frictionFactor;
}

function validateRunSpeeds(runSpeeds) {
  if (!Array.isArray(runSpeeds)) {
    throw new TypeError('runs must be an array of drop-in speeds');
  }
  return runSpeeds.map((dropInSpeed, runIndex) => {
    if (typeof dropInSpeed !== 'number' || Number.isNaN(dropInSpeed) || dropInSpeed < 0) {
      throw new RangeError(`run ${runIndex} has an invalid drop-in speed`);
    }
    return dropInSpeed;
  });
}

function bottomSpeedFor(dropInSpeed, frictionFactor) {
  return dropInSpeed * frictionFactor;
}

function airAmplitudeFor(bottomSpeed) {
  const rawAmplitude = (bottomSpeed * bottomSpeed) / gravityDoubled - wallHeightMeters;
  return rawAmplitude < 0 ? 0 : rawAmplitude;
}

function amplitudesForRuns(runSpeeds, frictionFactor) {
  return runSpeeds.map((dropInSpeed) => airAmplitudeFor(bottomSpeedFor(dropInSpeed, frictionFactor)));
}

function estimate(runs, friction) {
  const frictionFactor = validateFrictionFactor(friction);
  const runSpeeds = validateRunSpeeds(runs);
  const runAmplitudes = amplitudesForRuns(runSpeeds, frictionFactor);
  let maximumAmplitude = 0;
  let highAirCount = 0;
  runAmplitudes.forEach((runAmplitude) => {
    if (runAmplitude > maximumAmplitude) {
      maximumAmplitude = runAmplitude;
    }
    if (runAmplitude > highAirThreshold) {
      highAirCount += 1;
    }
  });
  return [maximumAmplitude, highAirCount];
}

function formatSessionReport(sessionLabel, estimateResult) {
  const [maximumAmplitude, highAirCount] = estimateResult;
  const roundedMaximum = maximumAmplitude.toFixed(2);
  return `${sessionLabel}: best air ${roundedMaximum} m above the lip, ${highAirCount} run(s) over ${highAirThreshold} m`;
}

function runSessionSummary() {
  const morningRunSpeeds = [12, 14.5, 9, 17, 20];
  const afternoonRunSpeeds = [8, 10.2, 11, 13.4];
  const morningFriction = 0.92;
  const afternoonFriction = 0.78;
  const reportLines = [
    formatSessionReport('Morning', estimate(morningRunSpeeds, morningFriction)),
    formatSessionReport('Afternoon', estimate(afternoonRunSpeeds, afternoonFriction)),
  ];
  reportLines.forEach((reportLine) => console.log(reportLine));
}

runSessionSummary();

module.exports = { estimate, airAmplitudeFor, formatSessionReport };

