function validateMeasurements(volumes, time) {
  if (!Array.isArray(volumes) || volumes.length === 0) {
    throw new Error('volumes must be a non-empty array of measurements');
  }
  const initialVolume = volumes[0];
  if (typeof initialVolume !== 'number' || initialVolume <= 0) {
    throw new Error('the initial volume must be a positive number');
  }
  volumes.forEach(function (measuredVolume, measurementIndex) {
    if (typeof measuredVolume !== 'number' || Number.isNaN(measuredVolume)) {
      throw new Error('invalid measurement at index ' + measurementIndex);
    }
  });
  if (typeof time !== 'number' || time <= 0) {
    throw new Error('the interval between measurements must be positive');
  }
  return initialVolume;
}

function computeExpansionRatios(volumes, initialVolume) {
  return volumes.map(function (measuredVolume) {
    return measuredVolume / initialVolume;
  });
}

function findPeakIndex(expansionRatios) {
  let peakIndex = 0;
  for (let currentIndex = 1; currentIndex < expansionRatios.length; currentIndex += 1) {
    if (expansionRatios[currentIndex] > expansionRatios[peakIndex]) {
      peakIndex = currentIndex;
    }
  }
  return peakIndex;
}

function countHighlyActive(expansionRatios) {
  return expansionRatios.filter(function (currentRatio) {
    return currentRatio > 2.0;
  }).length;
}

function track(volumes, time) {
  const initialVolume = validateMeasurements(volumes, time);
  const expansionRatios = computeExpansionRatios(volumes, initialVolume);
  const peakIndex = findPeakIndex(expansionRatios);
  const peakRatio = expansionRatios[peakIndex];
  const timeToPeak = peakIndex * time;
  const activeCount = countHighlyActive(expansionRatios);
  return [peakRatio, timeToPeak, activeCount];
}

function formatFermentationReport(trackedResult) {
  const peakRatioText = trackedResult[0].toFixed(2) + 'x';
  const timeToPeakText = trackedResult[1].toFixed(1) + ' h';
  return 'peak ' + peakRatioText + ' after ' + timeToPeakText +
    ', highly active measurements: ' + trackedResult[2];
}

function main() {
  const measurementInterval = 1.5;
  const starterVolumes = [100, 140, 210, 260, 230, 180];
  const fermentationResult = track(starterVolumes, measurementInterval);
  console.log(formatFermentationReport(fermentationResult));

  const slowStarterVolumes = [50, 55, 60, 58];
  const slowFermentationResult = track(slowStarterVolumes, 2);
  console.log(formatFermentationReport(slowFermentationResult));
}

main();

module.exports = { track, formatFermentationReport, computeExpansionRatios, countHighlyActive };

