const startingHeight = 2.5;
const netDistanceMeters = 9;
const gravityAcceleration = 9.8;

function degreesToRadians(angleInDegrees) {
  return (angleInDegrees * Math.PI) / 180;
}

function validateStrike(strikeRecord, strikeIndex) {
  if (typeof strikeRecord !== 'object' || strikeRecord === null) {
    throw new TypeError(`strike ${strikeIndex} is not an object`);
  }
  if (!Number.isFinite(strikeRecord.speed) || strikeRecord.speed <= 0) {
    throw new RangeError(`strike ${strikeIndex} has an invalid speed`);
  }
  if (!Number.isFinite(strikeRecord.angle)) {
    throw new RangeError(`strike ${strikeIndex} has an invalid angle`);
  }
}

function heightAtNet(launchSpeed, launchAngle) {
  const angleInRadians = degreesToRadians(launchAngle);
  const horizontalVelocity = launchSpeed * Math.cos(angleInRadians);
  const verticalVelocity = launchSpeed * Math.sin(angleInRadians);
  if (horizontalVelocity <= 0) {
    return Number.NEGATIVE_INFINITY;
  }
  const timeToNet = netDistanceMeters / horizontalVelocity;
  return (
    startingHeight +
    verticalVelocity * timeToNet -
    0.5 * gravityAcceleration * timeToNet * timeToNet
  );
}

function serve(strikes, net) {
  if (!Array.isArray(strikes)) {
    throw new TypeError('strikes must be an array');
  }
  if (!Number.isFinite(net) || net < 0) {
    throw new RangeError('net height must be a non-negative number');
  }
  let successfulClears = 0;
  let maximumMargin = 0;
  strikes.forEach((strikeRecord, strikeIndex) => {
    validateStrike(strikeRecord, strikeIndex);
    const ballHeight = heightAtNet(strikeRecord.speed, strikeRecord.angle);
    if (ballHeight > net) {
      successfulClears += 1;
      const clearanceMargin = ballHeight - net;
      if (clearanceMargin > maximumMargin) {
        maximumMargin = clearanceMargin;
      }
    }
  });
  return [successfulClears, maximumMargin];
}

