const maximumCycleLimit = 75;
const baseCyclesPerIntensity = 5;
const highSpeedThreshold = 80;
const veryHighSpeedThreshold = 120;

function validateRainConditions(conditionList) {
  if (!Array.isArray(conditionList)) {
    throw new TypeError('conditions must be an array of rain intensities');
  }
  conditionList.forEach(function (rainIntensity, conditionIndex) {
    if (!Number.isInteger(rainIntensity) || rainIntensity < 1 || rainIntensity > 10) {
      throw new RangeError('intensity at index ' + conditionIndex + ' must be an integer from 1 to 10');
    }
  });
  return conditionList;
}

function computeSpeedModifier(vehicleSpeed) {
  if (vehicleSpeed > veryHighSpeedThreshold) {
    return 20;
  }
  if (vehicleSpeed > highSpeedThreshold) {
    return 10;
  }
  return 0;
}

function computeWipeFrequency(rainIntensity, vehicleSpeed) {
  const baseFrequency = rainIntensity * baseCyclesPerIntensity;
  const boostedFrequency = baseFrequency + computeSpeedModifier(vehicleSpeed);
  return Math.min(boostedFrequency, maximumCycleLimit);
}

function buildFrequencySeries(conditionList, vehicleSpeed) {
  return conditionList.map(function (rainIntensity) {
    return computeWipeFrequency(rainIntensity, vehicleSpeed);
  });
}

function averageWipeFrequency(frequencySeries) {
  if (frequencySeries.length === 0) {
    return 0;
  }
  const totalCycleCount = frequencySeries.reduce(function (runningTotal, frequency) {
    return runningTotal + frequency;
  }, 0);
  return totalCycleCount / frequencySeries.length;
}

function longestMaxedOutStreak(frequencySeries) {
  let currentStreakLength = 0;
  let longestStreakLength = 0;
  frequencySeries.forEach(function (wipeFrequency) {
    if (wipeFrequency === maximumCycleLimit) {
      currentStreakLength += 1;
      longestStreakLength = Math.max(longestStreakLength, currentStreakLength);
    } else {
      currentStreakLength = 0;
    }
  });
  return longestStreakLength;
}

function wipe(conditions, vehicle) {
  const validatedConditions = validateRainConditions(conditions);
  const frequencySeries = buildFrequencySeries(validatedConditions, vehicle);
  return [averageWipeFrequency(frequencySeries), longestMaxedOutStreak(frequencySeries)];
}

function formatWiperReport(conditions, vehicle) {
  const [averageFrequency, maxedStreakLength] = wipe(conditions, vehicle);
  return 'at ' + vehicle + ' km/h: average ' + averageFrequency.toFixed(2) +
    ' cycles/min, longest maxed-out streak ' + maxedStreakLength;
}

