const gravityAcceleration = 9.8;

function degreesToRadians(elevationDegrees) {
  return (elevationDegrees * Math.PI) / 180;
}

function effectiveVelocity(muzzleVelocity, windReduction) {
  const reducedVelocity = muzzleVelocity - windReduction;
  return reducedVelocity > 0 ? reducedVelocity : 0;
}

function velocityComponents(initialVelocity, elevationRadians) {
  return {
    horizontalVelocity: initialVelocity * Math.cos(elevationRadians),
    verticalVelocity: initialVelocity * Math.sin(elevationRadians)
  };
}

function timeOfFlight(verticalVelocity) {
  return (2 * verticalVelocity) / gravityAcceleration;
}

function horizontalRange(horizontalVelocity, flightTime) {
  return horizontalVelocity * flightTime;
}

function peakAltitude(verticalVelocity) {
  return (verticalVelocity * verticalVelocity) / (2 * gravityAcceleration);
}

function computeShot(shotDescriptor, windSpeed) {
  const elevationRadians = degreesToRadians(shotDescriptor.elevation);
  const launchVelocity = effectiveVelocity(shotDescriptor.velocity, windSpeed);
  const { horizontalVelocity, verticalVelocity } = velocityComponents(launchVelocity, elevationRadians);
  const flightTime = timeOfFlight(verticalVelocity);
  return {
    shotRange: horizontalRange(horizontalVelocity, flightTime),
    shotApex: peakAltitude(verticalVelocity)
  };
}

function fire(shots, wind) {
  const windReduction = Number(wind) || 0;
  let maximumRange = 0;
  let highestApex = 0;
  shots.forEach((shotDescriptor) => {
    const shotResult = computeShot(shotDescriptor, windReduction);
    if (shotResult.shotRange > maximumRange) {
      maximumRange = shotResult.shotRange;
    }
    if (shotResult.shotApex > highestApex) {
      highestApex = shotResult.shotApex;
    }
  });
  return [Math.round(maximumRange), Math.round(highestApex)];
}

function formatFiringReport(batteryResult) {
  const [reportedRange, reportedApex] = batteryResult;
  return `max range: ${reportedRange} m, peak altitude: ${reportedApex} m`;
}

