const mountainBaseStress = 2;
const valleyBaseStress = 1;
const longFoldThreshold = 10;
const longFoldPenalty = 5;

function baseStressForFoldType(foldType) {
  const normalizedFoldType = String(foldType).trim().toLowerCase();
  if (normalizedFoldType === 'mountain') {
    return mountainBaseStress;
  }
  if (normalizedFoldType === 'valley') {
    return valleyBaseStress;
  }
  throw new Error(`unknown fold type: ${foldType}`);
}

function validateFoldInstruction(foldInstruction, instructionIndex) {
  if (!Array.isArray(foldInstruction) || foldInstruction.length !== 3) {
    throw new Error(`instruction ${instructionIndex} must be [type, length, thickness]`);
  }
  const [, foldLength, layerThickness] = foldInstruction;
  if (typeof foldLength !== 'number' || !Number.isFinite(foldLength) || foldLength <= 0) {
    throw new Error(`instruction ${instructionIndex} has an invalid fold length`);
  }
  if (typeof layerThickness !== 'number' || !Number.isFinite(layerThickness) || layerThickness <= 0) {
    throw new Error(`instruction ${instructionIndex} has an invalid layer thickness`);
  }
}

function appliedStressForFold(foldType, foldLength, layerThickness) {
  const baseStress = baseStressForFoldType(foldType);
  let appliedStress = baseStress * layerThickness;
  if (foldLength > longFoldThreshold) {
    appliedStress += longFoldPenalty;
  }
  return appliedStress;
}

function fold(instructions) {
  if (!Array.isArray(instructions)) {
    throw new Error('instructions must be a list of folds');
  }
  let totalAccumulatedStress = 0;
  instructions.forEach((foldInstruction, instructionIndex) => {
    validateFoldInstruction(foldInstruction, instructionIndex);
    const [foldType, foldLength, layerThickness] = foldInstruction;
    totalAccumulatedStress += appliedStressForFold(foldType, foldLength, layerThickness);
  });
  return totalAccumulatedStress;
}

function describeFoldSequence(instructions) {
  const foldLines = instructions.map((foldInstruction, instructionIndex) => {
    const [foldType, foldLength, layerThickness] = foldInstruction;
    const stressOfThisFold = appliedStressForFold(foldType, foldLength, layerThickness);
    return `${instructionIndex + 1}. ${foldType} fold, ${foldLength} cm, ` +
      `${layerThickness} layer(s) -> ${stressOfThisFold} unit(s)`;
  });
  foldLines.push(`total: ${fold(instructions)} unit(s)`);
  return foldLines.join('\n');
}

function main() {
  const singleMountainSequence = [['mountain', 12, 3]];
  const mixedFoldSequence = [
    ['mountain', 4, 2],
    ['valley', 11, 5],
    ['valley', 9, 1],
    ['mountain', 20, 4],
  ];
  console.log(describeFoldSequence(singleMountainSequence));
  console.log('');
  console.log(describeFoldSequence(mixedFoldSequence));
}

main();

