const validActionNames = new Set(['hit', 'parry', 'riposte']);

function normalizeActionName(rawAction) {
  if (typeof rawAction !== 'string') {
    throw new TypeError('Each fencer action must be given as a string');
  }
  const cleanedAction = rawAction.trim().toLowerCase();
  if (!validActionNames.has(cleanedAction)) {
    throw new RangeError(`Unknown fencing action: ${rawAction}`);
  }
  return cleanedAction;
}

function parseExchangeEntry(exchangeEntry, exchangeNumber) {
  if (!Array.isArray(exchangeEntry) || exchangeEntry.length !== 3) {
    throw new TypeError(`Exchange ${exchangeNumber} must hold two actions and a priority advantage`);
  }
  const [rawFirstAction, rawSecondAction, priorityAdvantage] = exchangeEntry;
  if (priorityAdvantage !== 1 && priorityAdvantage !== 2) {
    throw new RangeError(`Exchange ${exchangeNumber} has an invalid priority advantage: ${priorityAdvantage}`);
  }
  return [
    normalizeActionName(rawFirstAction),
    normalizeActionName(rawSecondAction),
    priorityAdvantage
  ];
}

function selectPriorityAction(fencerOneAction, fencerTwoAction, priorityAdvantage) {
  return priorityAdvantage === 1 ? fencerOneAction : fencerTwoAction;
}

function pointsForPriorityAction(priorityActionName) {
  if (priorityActionName === 'riposte') {
    return 2;
  }
  return priorityActionName === 'hit' ? 1 : 0;
}

function fence(exchanges) {
  if (!Array.isArray(exchanges)) {
    throw new TypeError('fence expects a list of exchanges');
  }
  const runningScore = [0, 0];
  exchanges.forEach((exchangeEntry, exchangeIndex) => {
    const [fencerOneAction, fencerTwoAction, priorityAdvantage] =
      parseExchangeEntry(exchangeEntry, exchangeIndex + 1);
    const priorityAction = selectPriorityAction(fencerOneAction, fencerTwoAction, priorityAdvantage);
    runningScore[priorityAdvantage - 1] += pointsForPriorityAction(priorityAction);
  });
  return runningScore;
}

function describeMatchOutcome(fencerOneScore, fencerTwoScore) {
  if (fencerOneScore === fencerTwoScore) {
    return 'the bout is tied';
  }
  const leadingFencerName = fencerOneScore > fencerTwoScore ? 'fencer one' : 'fencer two';
  const scoreDifference = Math.abs(fencerOneScore - fencerTwoScore);
  return `${leadingFencerName} leads by ${scoreDifference}`;
}

function formatMatchReport(exchanges) {
  const [fencerOneScore, fencerTwoScore] = fence(exchanges);
  return `Final score ${fencerOneScore} - ${fencerTwoScore}: ${describeMatchOutcome(fencerOneScore, fencerTwoScore)}`;
}

function reportRecordedMatch(recordedExchanges) {
  console.log(formatMatchReport(recordedExchanges));
}

reportRecordedMatch([
  ['riposte', 'hit', 1],
