const valid_action_names = new Set(['hit', 'parry', 'riposte']);

function normalize_action_name(raw_action) {
  if (typeof raw_action !== 'string') {
    throw new TypeError('Each fencer action must be given as a string');
  }
  const cleaned_action = raw_action.trim().toLowerCase();
  if (!valid_action_names.has(cleaned_action)) {
    throw new RangeError(`Unknown fencing action: ${raw_action}`);
  }
  return cleaned_action;
}

function parse_exchange_entry(exchange_entry, exchange_number) {
  if (!Array.isArray(exchange_entry) || exchange_entry.length !== 3) {
    throw new TypeError(`Exchange ${exchange_number} must hold two actions and a priority advantage`);
  }
  const [raw_first_action, raw_second_action, priority_advantage] = exchange_entry;
  if (priority_advantage !== 1 && priority_advantage !== 2) {
    throw new RangeError(`Exchange ${exchange_number} has an invalid priority advantage: ${priority_advantage}`);
  }
  return [
    normalize_action_name(raw_first_action),
    normalize_action_name(raw_second_action),
    priority_advantage
  ];
}

function select_priority_action(fencer_one_action, fencer_two_action, priority_advantage) {
  return priority_advantage === 1 ? fencer_one_action : fencer_two_action;
}

function points_for_priority_action(priority_action_name) {
  if (priority_action_name === 'riposte') {
    return 2;
  }
  return priority_action_name === 'hit' ? 1 : 0;
}

function fence(exchanges) {
  if (!Array.isArray(exchanges)) {
    throw new TypeError('fence expects a list of exchanges');
  }
  const running_score = [0, 0];
  exchanges.forEach((exchange_entry, exchange_index) => {
    const [fencer_one_action, fencer_two_action, priority_advantage] =
      parse_exchange_entry(exchange_entry, exchange_index + 1);
    const priority_action = select_priority_action(fencer_one_action, fencer_two_action, priority_advantage);
    running_score[priority_advantage - 1] += points_for_priority_action(priority_action);
  });
  return running_score;
}

function describe_match_outcome(fencer_one_score, fencer_two_score) {
  if (fencer_one_score === fencer_two_score) {
    return 'the bout is tied';
  }
  const leading_fencer_name = fencer_one_score > fencer_two_score ? 'fencer one' : 'fencer two';
  const score_difference = Math.abs(fencer_one_score - fencer_two_score);
  return `${leading_fencer_name} leads by ${score_difference}`;
}

function format_match_report(exchanges) {
  const [fencer_one_score, fencer_two_score] = fence(exchanges);
  return `Final score ${fencer_one_score} - ${fencer_two_score}: ${describe_match_outcome(fencer_one_score, fencer_two_score)}`;
}

function report_recorded_match(recorded_exchanges) {
  console.log(format_match_report(recorded_exchanges));
}

report_recorded_match([
  ['riposte', 'hit', 1],
  ['hit', 'parry', 2],
  ['parry', 'riposte', 2],
  ['hit', 'hit', 1]
]);

module.exports = { fence, format_match_report };

