const tailDragFactor = 2.5;

function validateMoment(momentValues, momentIndex) {
  if (!Array.isArray(momentValues) || momentValues.length !== 3) {
    throw new TypeError(`moment ${momentIndex} must contain wind speed, area and tail length`);
  }
  momentValues.forEach((measuredValue, valuePosition) => {
    if (typeof measuredValue !== 'number' || Number.isNaN(measuredValue)) {
      throw new TypeError(`moment ${momentIndex}, value ${valuePosition} is not a number`);
    }
    if (measuredValue < 0) {
      throw new RangeError(`moment ${momentIndex}, value ${valuePosition} is negative`);
    }
  });
}

function computeBaseLift(windSpeed, surfaceArea) {
  return windSpeed * surfaceArea;
}

function computeTailDrag(tailLength) {
  return tailLength * tailDragFactor;
}

function computeNetTension(windSpeed, surfaceArea, tailLength) {
  const baseLift = computeBaseLift(windSpeed, surfaceArea);
  const tailDrag = computeTailDrag(tailLength);
  return Math.max(0, baseLift - tailDrag);
}

function fly(conditions) {
  if (!Array.isArray(conditions)) {
    throw new TypeError('conditions must be a list of moments');
  }
  let highestTension = 0;
  conditions.forEach((momentValues, momentIndex) => {
    validateMoment(momentValues, momentIndex);
    const [windSpeed, surfaceArea, tailLength] = momentValues;
    const momentTension = computeNetTension(windSpeed, surfaceArea, tailLength);
    if (momentTension > highestTension) {
      highestTension = momentTension;
    }
  });
  return highestTension;
}

function describeSession(conditions) {
  const tensionLines = conditions.map((momentValues, momentIndex) => {
    const [windSpeed, surfaceArea, tailLength] = momentValues;
    const momentTension = computeNetTension(windSpeed, surfaceArea, tailLength);
    return `moment ${momentIndex}: wind ${windSpeed}, area ${surfaceArea}, tail ${tailLength} -> ${momentTension.toFixed(1)}`;
  });
  const peakTension = fly(conditions);
  tensionLines.push(`peak tension: ${peakTension.toFixed(1)}`);
  return tensionLines.join('\n');
}

function main() {
  const sessionConditions = [
    [12, 3, 4],
    [8, 2, 10],
    [5, 1, 40],
    [20, 2, 6],
  ];
  console.log(describeSession(sessionConditions));
  const singleMomentTension = fly([[12, 3, 4]]);
  console.log(`single moment session peak: ${singleMomentTension}`);
}

main();

module.exports = { fly, computeNetTension, computeBaseLift, computeTailDrag, describeSession };

