const roughTextureMultiplier = 1.5;
const splatterPenaltyUnits = 2;
const splatterPressureThreshold = 5;

function normalizeTextureName(paperTexture) {
  if (typeof paperTexture !== 'string') {
    throw new TypeError('paper texture must be a string');
  }
  return paperTexture.trim().toLowerCase();
}

function readStrokeEntry(strokeEntry, strokeIndex) {
  if (!Array.isArray(strokeEntry) || strokeEntry.length !== 3) {
    throw new TypeError(`stroke ${strokeIndex} must be [pressure, length, texture]`);
  }
  const [brushPressure, strokeLength, rawTexture] = strokeEntry;
  if (!Number.isFinite(brushPressure) || !Number.isFinite(strokeLength)) {
    throw new TypeError(`stroke ${strokeIndex} needs numeric pressure and length`);
  }
  if (brushPressure < 0 || strokeLength < 0) {
    throw new RangeError(`stroke ${strokeIndex} cannot have negative measurements`);
  }
  return [brushPressure, strokeLength, normalizeTextureName(rawTexture)];
}

function applyTextureAdjustment(basicVolume, paperTexture) {
  return paperTexture === 'rough' ? basicVolume * roughTextureMultiplier : basicVolume;
}

function computeStrokeVolume(strokeEntry, strokeIndex) {
  const [brushPressure, strokeLength, paperTexture] = readStrokeEntry(strokeEntry, strokeIndex);
  const basicVolume = brushPressure * strokeLength;
  const adjustedVolume = applyTextureAdjustment(basicVolume, paperTexture);
  const splatterPenalty = brushPressure > splatterPressureThreshold ? splatterPenaltyUnits : 0;
  return adjustedVolume + splatterPenalty;
}

function write(strokes) {
  if (!Array.isArray(strokes)) {
    throw new TypeError('strokes must be a list of strokes');
  }
  return strokes.reduce(
    (runningTotal, strokeEntry, strokeIndex) => runningTotal + computeStrokeVolume(strokeEntry, strokeIndex),
    0,
  );
}

function formatVolumeReport(strokes) {
  const strokeLines = strokes.map((strokeEntry, strokeIndex) => {
    const [brushPressure, strokeLength, paperTexture] = readStrokeEntry(strokeEntry, strokeIndex);
    const strokeVolume = computeStrokeVolume(strokeEntry, strokeIndex);
    return `stroke ${strokeIndex + 1}: pressure ${brushPressure}, length ${strokeLength}, ` +
      `${paperTexture} paper -> ${strokeVolume.toFixed(2)} units`;
  });
  const totalInkVolume = write(strokes);
  strokeLines.push(`total pigment required: ${totalInkVolume.toFixed(2)} units`);
  return strokeLines.join('\n');
}

function main() {
  const calligraphyStrokes = [
    [6, 3, 'smooth'],
    [4, 2, 'rough'],
    [7, 1.5, 'Rough'],
  ];
  console.log(formatVolumeReport(calligraphyStrokes));
}

main();

module.exports = { write, computeStrokeVolume, formatVolumeReport };

