function isStepPerfect(stepType, timingGap) {
  if (stepType === 'shuffle') {
    return timingGap < 0.5;
  }
  if (stepType === 'flap') {
    return timingGap < 0.3;
  }
  return timingGap === 0.4;
}

function scoreSingleStep(stepEntry) {
  const [stepType, timingGap, stepComplexity, stumbleOccurred] = stepEntry;
  const stepIsPerfect = isStepPerfect(stepType, timingGap);
  let baseStepScore = stepIsPerfect ? stepComplexity * 2 : stepComplexity;
  if (stumbleOccurred) {
    baseStepScore -= 1;
  }
  return baseStepScore;
}

function validateStepEntry(stepEntry, entryIndex) {
  if (!Array.isArray(stepEntry) || stepEntry.length !== 4) {
    throw new TypeError(`step ${entryIndex} must be an array of four elements`);
  }
  const [stepType, timingGap, stepComplexity, stumbleOccurred] = stepEntry;
  if (typeof stepType !== 'string') {
    throw new TypeError(`step ${entryIndex} has a non-string step type`);
  }
  if (typeof timingGap !== 'number' || Number.isNaN(timingGap)) {
    throw new TypeError(`step ${entryIndex} has an invalid timing gap`);
  }
  if (typeof stepComplexity !== 'number' || Number.isNaN(stepComplexity)) {
    throw new TypeError(`step ${entryIndex} has an invalid step complexity`);
  }
  if (typeof stumbleOccurred !== 'boolean') {
    throw new TypeError(`step ${entryIndex} has a non-boolean stumble flag`);
  }
}

function tap(beats) {
  if (!Array.isArray(beats)) {
    throw new TypeError('beats must be an array of step entries');
  }
  let accumulatedScore = 0;
  beats.forEach((stepEntry, entryIndex) => {
    validateStepEntry(stepEntry, entryIndex);
    accumulatedScore += scoreSingleStep(stepEntry);
  });
  return accumulatedScore;
}

function describeRoutine(beats) {
  const stepReportLines = beats.map((stepEntry) => {
    const [stepType, timingGap, stepComplexity, stumbleOccurred] = stepEntry;
    const perfectLabel = isStepPerfect(stepType, timingGap) ? 'perfect' : 'off-beat';
    const stumbleLabel = stumbleOccurred ? ' (stumble)' : '';
    const singleStepScore = scoreSingleStep(stepEntry);
    return `${stepType} gap=${timingGap}s complexity=${stepComplexity} -> ${perfectLabel}${stumbleLabel}: ${singleStepScore}`;
  });
  const routineTotalScore = tap(beats);
  stepReportLines.push(`routine total: ${routineTotalScore}`);
  return stepReportLines.join('\n');
}

function main() {
  const sampleRoutine = [
    ['shuffle', 0.4, 3, false],
    ['flap', 0.25, 4, true],
    ['stomp', 0.4, 5, false],
    ['stomp', 0.6, 2, true],
  ];
  console.log(describeRoutine(sampleRoutine));
}

main();

