function validateSpot(spotEntry, spotIndex) {
  if (!Array.isArray(spotEntry) || spotEntry.length !== 3) {
    throw new TypeError(`Spot ${spotIndex} must be a list of three numbers`);
  }
  const [humidityLevel, oakTreeCount, soilAcidity] = spotEntry;
  const everyValueIsNumeric = [humidityLevel, oakTreeCount, soilAcidity]
    .every((measuredValue) => typeof measuredValue === 'number' && Number.isFinite(measuredValue));
  if (!everyValueIsNumeric) {
    throw new TypeError(`Spot ${spotIndex} contains a non-numeric measurement`);
  }
  return { humidityLevel, oakTreeCount, soilAcidity };
}

function humidityMultiplierFor(humidityLevel) {
  return humidityLevel > 80 ? 2 : 1;
}

function acidityPenaltyFor(soilAcidity) {
  return soilAcidity > 7 ? 2 : 0;
}

function spotYield(spotEntry, spotIndex) {
  const { humidityLevel, oakTreeCount, soilAcidity } = validateSpot(spotEntry, spotIndex);
  const baseYield = oakTreeCount * 3;
  const adjustedYield = baseYield * humidityMultiplierFor(humidityLevel);
  const finalYield = adjustedYield - acidityPenaltyFor(soilAcidity);
  return finalYield < 0 ? 0 : finalYield;
}

function forage(spots) {
  if (!Array.isArray(spots)) {
    throw new TypeError('forage expects a list of spots');
  }
  return spots.reduce(
    (runningTotal, spotEntry, spotIndex) => runningTotal + spotYield(spotEntry, spotIndex),
    0
  );
}

function buildHarvestReport(spots) {
  const perSpotLines = spots.map((spotEntry, spotIndex) => {
    const [humidityLevel, oakTreeCount, soilAcidity] = spotEntry;
    const harvestedUnits = spotYield(spotEntry, spotIndex);
    const conditionNote = soilAcidity > 7 ? 'acidic soil' : 'balanced soil';
    return `spot ${spotIndex + 1}: humidity ${humidityLevel}, oaks ${oakTreeCount}, `
      + `${conditionNote} -> ${harvestedUnits} units`;
  });
  const totalHarvest = forage(spots);
  perSpotLines.push(`total expected harvest: ${totalHarvest} units`);
  return perSpotLines.join('\n');
}

function main() {
  const woodlandSpots = [
    [85, 4, 6],
    [70, 5, 8],
    [95, 0, 9],
    [60, 2, 3],
