const breathDirectionModifiers = { draw: -1, blow: 1 };

function resolvePitchModifier(breathDirection) {
  const normalizedDirection = String(breathDirection).trim().toLowerCase();
  const pitchModifier = breathDirectionModifiers[normalizedDirection];
  if (pitchModifier === undefined) {
    throw new Error(`unknown breath direction: ${breathDirection}`);
  }
  return pitchModifier;
}

function validateTabEntry(tabEntry, entryIndex) {
  if (!Array.isArray(tabEntry) || tabEntry.length !== 3) {
    throw new Error(`tab ${entryIndex} must be [hole, direction, button]`);
  }
  const [holeNumber, , slideButtonPressed] = tabEntry;
  if (!Number.isInteger(holeNumber) || holeNumber < 1) {
    throw new Error(`tab ${entryIndex} has an invalid hole number: ${holeNumber}`);
  }
  if (typeof slideButtonPressed !== 'boolean') {
    throw new Error(`tab ${entryIndex} needs a boolean slide button flag`);
  }
}

function computeBasePitch(holeNumber, breathDirection) {
  return holeNumber * resolvePitchModifier(breathDirection);
}

function applySlideButton(basePitch, slideButtonPressed) {
  return slideButtonPressed ? basePitch + 0.5 : basePitch;
}

function play(tabs) {
  if (!Array.isArray(tabs)) {
    throw new Error('tabs must be a list of tab entries');
  }
  return tabs.map((tabEntry, entryIndex) => {
    validateTabEntry(tabEntry, entryIndex);
    const [holeNumber, breathDirection, slideButtonPressed] = tabEntry;
    const basePitch = computeBasePitch(holeNumber, breathDirection);
    return applySlideButton(basePitch, slideButtonPressed);
  });
}

function formatPitchValue(pitchValue) {
  return Number.isInteger(pitchValue) ? pitchValue.toFixed(0) : pitchValue.toFixed(1);
}

function describeTabEntry(tabEntry) {
  const [holeNumber, breathDirection, slideButtonPressed] = tabEntry;
  const normalizedDirection = String(breathDirection).trim().toLowerCase();
  const buttonLabel = slideButtonPressed ? 'slide' : 'open';
  return `hole ${holeNumber} ${normalizedDirection} (${buttonLabel})`;
}

function buildPitchReport(tabs) {
  const pitchValues = play(tabs);
  const reportLines = tabs.map((tabEntry, entryIndex) => {
    const formattedPitch = formatPitchValue(pitchValues[entryIndex]);
    return `${describeTabEntry(tabEntry).padEnd(24)} -> ${formattedPitch}`;
  });
  const highestPitch = Math.max(...pitchValues);
  const lowestPitch = Math.min(...pitchValues);
  reportLines.push(`range: ${formatPitchValue(lowestPitch)} .. ${formatPitchValue(highestPitch)}`);
  return reportLines.join('\n');
}

function main() {
  const melodyTabs = [
    [4, 'draw', true],
    [4, 'blow', false],
    [5, 'blow', true],
    [6, 'draw', false],
    [3, 'blow', true],
  ];
  console.log(buildPitchReport(melodyTabs));
  console.log(`pitches: ${JSON.stringify(play(melodyTabs))}`);
}

main();

