function validateEventRecord(eventRecord, recordIndex) {
  if (!Array.isArray(eventRecord)) {
    throw new TypeError(`Event ${recordIndex} must be a list of four numbers`);
  }
  if (eventRecord.length !== 4) {
    throw new RangeError(`Event ${recordIndex} needs exactly 4 values, got ${eventRecord.length}`);
  }
  eventRecord.forEach((rawValue, valueIndex) => {
    if (typeof rawValue !== 'number' || !Number.isFinite(rawValue)) {
      throw new TypeError(`Event ${recordIndex}, value ${valueIndex} is not a finite number`);
    }
  });
}

function parseEventRecord(eventRecord) {
  const [burstRadius, colorIntensity, fuseLength, launchAltitude] = eventRecord;
  return { burstRadius, colorIntensity, fuseLength, launchAltitude };
}

function computeLaunchDelay(eventRecord) {
  const { burstRadius, colorIntensity, fuseLength, launchAltitude } = parseEventRecord(eventRecord);
  return fuseLength + launchAltitude * burstRadius - colorIntensity;
}

function schedule(events) {
  if (!Array.isArray(events)) {
    throw new TypeError('schedule expects a list of event lists');
  }
  return events.map((eventRecord, recordIndex) => {
    validateEventRecord(eventRecord, recordIndex);
    return computeLaunchDelay(eventRecord);
  });
}

function formatDelaySeconds(delayValue) {
  const roundedSeconds = Math.round(delayValue * 100) / 100;
  return `${roundedSeconds}s`;
}

function buildScheduleReport(events) {
  const delayList = schedule(events);
  const reportLines = delayList.map((delayValue, recordIndex) => {
    const { burstRadius, launchAltitude } = parseEventRecord(events[recordIndex]);
    const shellLabel = `shell #${recordIndex + 1}`;
    return `${shellLabel}: radius ${burstRadius}, altitude ${launchAltitude} -> ${formatDelaySeconds(delayValue)}`;
  });
  const totalDelay = delayList.reduce((runningTotal, delayValue) => runningTotal + delayValue, 0);
  const longestDelay = delayList.length === 0 ? 0 : Math.max(...delayList);
  return {
    delayList,
    reportLines,
    totalDelay,
    longestDelay,
    averageDelay: delayList.length === 0 ? 0 : totalDelay / delayList.length,
  };
}

function runShowPlanner(plannedEvents) {
  const scheduleReport = buildScheduleReport(plannedEvents);
  scheduleReport.reportLines.forEach((reportLine) => console.log(reportLine));
  console.log(`longest delay: ${formatDelaySeconds(scheduleReport.longestDelay)}`);
  console.log(`average delay: ${formatDelaySeconds(scheduleReport.averageDelay)}`);
  return scheduleReport.delayList;
}

const plannedFireworkShow = [
  [10, 5, 2, 50],
  [4, 12, 8, 30],
  [7, 3, 1, 25],
];

runShowPlanner(plannedFireworkShow);

module.exports = { schedule, computeLaunchDelay, buildScheduleReport, runShowPlanner };

