function validateTowerSpec(towerSpec, towerIndex) {
  if (!Array.isArray(towerSpec) || towerSpec.length !== 4) {
    throw new Error(`Tower ${towerIndex} must list four numeric readings`);
  }
  const [rotationSpeed, flashDuration, bulbIntensity, horizonDistance] = towerSpec;
  const everyReadingIsNumeric = towerSpec.every(
    (readingValue) => typeof readingValue === 'number' && Number.isFinite(readingValue)
  );
  if (!everyReadingIsNumeric) {
    throw new Error(`Tower ${towerIndex} contains a non-numeric reading`);
  }
  if (bulbIntensity === 0) {
    throw new Error(`Tower ${towerIndex} has zero bulb intensity`);
  }
  return { rotationSpeed, flashDuration, bulbIntensity, horizonDistance };
}

function computeTowerOffset(towerSpec, towerIndex) {
  const { rotationSpeed, flashDuration, bulbIntensity, horizonDistance } = validateTowerSpec(
    towerSpec,
    towerIndex
  );
  const sweepReach = horizonDistance * rotationSpeed;
  return sweepReach / bulbIntensity + flashDuration;
}

function synchronize(towers) {
  if (!Array.isArray(towers)) {
    throw new Error('The beacon collection must be a list of lists');
  }
  return towers.map(computeTowerOffset);
}

function formatOffsetValue(offsetValue) {
  return Number.isInteger(offsetValue) ? String(offsetValue) : offsetValue.toFixed(2);
}

function buildSynchronizationReport(towers) {
  const offsetValues = synchronize(towers);
  const reportLines = offsetValues.map((offsetValue, towerIndex) => {
    const [rotationSpeed, flashDuration, bulbIntensity, horizonDistance] = towers[towerIndex];
    const beaconLabel = `Beacon #${towerIndex + 1}`;
    const readingSummary = `speed=${rotationSpeed} flash=${flashDuration} bulb=${bulbIntensity} horizon=${horizonDistance}`;
    return `${beaconLabel}: ${readingSummary} -> offset ${formatOffsetValue(offsetValue)}`;
  });
  const slowestBeaconOffset = offsetValues.reduce(
    (largestSoFar, offsetValue) => Math.max(largestSoFar, offsetValue),
    Number.NEGATIVE_INFINITY
  );
  const averageOffsetValue =
    offsetValues.reduce((runningTotal, offsetValue) => runningTotal + offsetValue, 0) /
    offsetValues.length;
  reportLines.push(`Largest offset: ${formatOffsetValue(slowestBeaconOffset)}`);
  reportLines.push(`Mean offset: ${formatOffsetValue(averageOffsetValue)}`);
  return reportLines.join('\n');
}

function runCoastalSurvey() {
  const coastalBeaconReadings = [
    [5, 2, 10, 20],
    [3, 1, 4, 16],
    [7, 5, 2, 9],
  ];
  const offsetValues = synchronize(coastalBeaconReadings);
  console.log(`synchronize([[5, 2, 10, 20]]) = [${synchronize([[5, 2, 10, 20]]).join(', ')}]`);
  console.log(`All offsets: [${offsetValues.map(formatOffsetValue).join(', ')}]`);
  console.log(buildSynchronizationReport(coastalBeaconReadings));
}

runCoastalSurvey();

module.exports = { synchronize, computeTowerOffset, buildSynchronizationReport };

