const fieldNames = ['developerStrength', 'stopBathTime', 'fixerDuration', 'paperGrade', 'lightIntensity'];

function parsePrintSpec(printSpec, printIndex) {
  if (!Array.isArray(printSpec) || printSpec.length !== fieldNames.length) {
    throw new RangeError(`print ${printIndex + 1} must list exactly ${fieldNames.length} values`);
  }
  const parsedSpec = {};
  fieldNames.forEach((fieldName, fieldPosition) => {
    const fieldValue = Number(printSpec[fieldPosition]);
    if (!Number.isFinite(fieldValue)) {
      throw new TypeError(`print ${printIndex + 1} has a non-numeric ${fieldName}`);
    }
    parsedSpec[fieldName] = fieldValue;
  });
  if (parsedSpec.developerStrength === 0) {
    throw new RangeError(`print ${printIndex + 1} has a developer strength of zero`);
  }
  return parsedSpec;
}

function computePrintSeconds(printSpec, printIndex) {
  const parsedSpec = parsePrintSpec(printSpec, printIndex);
  const developerSeconds = parsedSpec.lightIntensity / parsedSpec.developerStrength;
  const wetProcessSeconds = developerSeconds + parsedSpec.stopBathTime + parsedSpec.fixerDuration;
  return wetProcessSeconds * parsedSpec.paperGrade;
}

function develop(prints) {
  if (!Array.isArray(prints)) {
    throw new TypeError('prints must be an array of print specifications');
  }
  return prints.map((printSpec, printIndex) => computePrintSeconds(printSpec, printIndex));
}

function formatDurationLabel(totalSeconds) {
  const wholeMinutes = Math.floor(totalSeconds / 60);
  const remainingSeconds = Math.round((totalSeconds - wholeMinutes * 60) * 100) / 100;
  if (wholeMinutes === 0) {
    return `${remainingSeconds}s`;
  }
  return `${wholeMinutes}m ${remainingSeconds}s`;
}

function buildDarkroomReport(prints, secondsPerPrint) {
  const reportLines = prints.map((printSpec, printIndex) => {
