const field_names = ['developerStrength', 'stopBathTime', 'fixerDuration', 'paperGrade', 'lightIntensity'];

function parse_print_spec(print_spec, print_index) {
  if (!Array.isArray(print_spec) || print_spec.length !== field_names.length) {
    throw new RangeError(`print ${print_index + 1} must list exactly ${field_names.length} values`);
  }
  const parsed_spec = {};
  field_names.forEach((field_name, field_position) => {
    const field_value = Number(print_spec[field_position]);
    if (!Number.isFinite(field_value)) {
      throw new TypeError(`print ${print_index + 1} has a non-numeric ${field_name}`);
    }
    parsed_spec[field_name] = field_value;
  });
  if (parsed_spec.developerStrength === 0) {
    throw new RangeError(`print ${print_index + 1} has a developer strength of zero`);
  }
  return parsed_spec;
}

function compute_print_seconds(print_spec, print_index) {
  const parsed_spec = parse_print_spec(print_spec, print_index);
  const developer_seconds = parsed_spec.lightIntensity / parsed_spec.developerStrength;
  const wet_process_seconds = developer_seconds + parsed_spec.stopBathTime + parsed_spec.fixerDuration;
  return wet_process_seconds * parsed_spec.paperGrade;
}

function develop(prints) {
  if (!Array.isArray(prints)) {
    throw new TypeError('prints must be an array of print specifications');
  }
  return prints.map((print_spec, print_index) => compute_print_seconds(print_spec, print_index));
}

function format_duration_label(total_seconds) {
  const whole_minutes = Math.floor(total_seconds / 60);
  const remaining_seconds = Math.round((total_seconds - whole_minutes * 60) * 100) / 100;
  if (whole_minutes === 0) {
    return `${remaining_seconds}s`;
  }
  return `${whole_minutes}m ${remaining_seconds}s`;
}

function build_darkroom_report(prints, seconds_per_print) {
  const report_lines = prints.map((print_spec, print_index) => {
    const parsed_spec = parse_print_spec(print_spec, print_index);
    const duration_label = format_duration_label(seconds_per_print[print_index]);
    const grade_label = `grade ${parsed_spec.paperGrade}`;
    return `print ${print_index + 1} (${grade_label}, fixer ${parsed_spec.fixerDuration}s): ${duration_label}`;
  });
  const grand_total_seconds = seconds_per_print.reduce(
    (running_total, print_seconds) => running_total + print_seconds,
    0
  );
  report_lines.push(`total darkroom time: ${format_duration_label(grand_total_seconds)}`);
  return report_lines.join('\n');
}

function main() {
  const print_queue = [[2, 10, 30, 3, 10], [4, 8, 25, 2, 40], [5, 12, 40, 1, 100]];
