const requiredFieldCount = 4;

function describeFieldName(fieldIndex) {
  const fieldNames = [
    'mainspring tension',
    'balance wheel oscillation rate',
    'escape wheel teeth count',
    'friction coefficient'
  ];
  return fieldNames[fieldIndex];
}

function validateGearSpec(gearSpec, specIndex) {
  if (!Array.isArray(gearSpec) || gearSpec.length !== requiredFieldCount) {
    throw new TypeError(`assembly ${specIndex} must list ${requiredFieldCount} values`);
  }
  gearSpec.forEach((fieldValue, fieldIndex) => {
    if (typeof fieldValue !== 'number' || !Number.isFinite(fieldValue)) {
      throw new TypeError(`assembly ${specIndex}: ${describeFieldName(fieldIndex)} must be a finite number`);
    }
  });
  const [mainspringTension, balanceWheelRate, escapeWheelTeeth, frictionCoefficient] = gearSpec;
  if (balanceWheelRate === 0) {
    throw new RangeError(`assembly ${specIndex}: balance wheel oscillation rate must not be zero`);
  }
  return { mainspringTension, balanceWheelRate, escapeWheelTeeth, frictionCoefficient };
}

function computeDailyDrift(watchAssembly) {
  const { mainspringTension, balanceWheelRate, escapeWheelTeeth, frictionCoefficient } = watchAssembly;
  return (mainspringTension * escapeWheelTeeth) / balanceWheelRate + frictionCoefficient;
}

function calibrate(gears) {
  if (!Array.isArray(gears)) {
    throw new TypeError('gears must be a list of assemblies');
  }
  return gears.map((gearSpec, specIndex) => computeDailyDrift(validateGearSpec(gearSpec, specIndex)));
}

function classifyDrift(driftSeconds) {
  const absoluteDrift = Math.abs(driftSeconds);
  if (absoluteDrift <= 1) {
    return 'chronometer grade';
  }
  if (absoluteDrift <= 10) {
    return 'within tolerance';
  }
  if (absoluteDrift <= 60) {
    return 'needs regulation';
  }
  return 'reject movement';
}

function formatDriftReport(gears) {
  const driftValues = calibrate(gears);
  return driftValues.map((driftSeconds, specIndex) => {
    const roundedDrift = Math.round(driftSeconds * 100) / 100;
    const driftDirection = driftSeconds >= 0 ? 'fast' : 'slow';
    const qualityVerdict = classifyDrift(driftSeconds);
    return `movement ${specIndex + 1}: ${Math.abs(roundedDrift)} s/day ${driftDirection} (${qualityVerdict})`;
  });
}

function main() {
  const sampleAssemblies = [
    [15, 5, 20, 2],
    [8, 32, 4, -0.5],
    [12, 6, 15, 0.25]
  ];
  const measuredDrifts = calibrate(sampleAssemblies);
  console.log(measuredDrifts);
  formatDriftReport(sampleAssemblies).forEach(reportLine => console.log(reportLine));
}

main();

module.exports = { calibrate, computeDailyDrift, classifyDrift, formatDriftReport };

