function parsePieceSpec(pieceSpec) {
  if (!Array.isArray(pieceSpec) || pieceSpec.length !== 4) {
    throw new TypeError('each piece needs gather, rotation, temperature and crack factor');
  }
  const [gatherSize, blowpipeRotationSpeed, kilnTemperature, crackProbabilityFactor] = pieceSpec;
  const numericValues = [gatherSize, blowpipeRotationSpeed, kilnTemperature, crackProbabilityFactor];
  if (numericValues.some((paramValue) => typeof paramValue !== 'number' || Number.isNaN(paramValue))) {
    throw new TypeError('all glass making parameters must be numbers');
  }
  if (blowpipeRotationSpeed === 0) {
    throw new RangeError('blowpipe rotation speed must not be zero');
  }
  return [gatherSize, blowpipeRotationSpeed, kilnTemperature, crackProbabilityFactor];
}

function coolingDurationFor(pieceSpec) {
  const [gatherSize, blowpipeRotationSpeed, kilnTemperature, crackProbabilityFactor] = parsePieceSpec(pieceSpec);
  const heatLoad = gatherSize * kilnTemperature;
  return heatLoad / blowpipeRotationSpeed + crackProbabilityFactor;
}

function anneal(pieces) {
  if (!Array.isArray(pieces)) {
    throw new TypeError('anneal expects a list of piece specifications');
  }
  return pieces.map(coolingDurationFor);
}

function formatDuration(coolingDuration) {
  const roundedDuration = Math.round(coolingDuration * 100) / 100;
  return Number.isInteger(roundedDuration) ? String(roundedDuration) : roundedDuration.toFixed(2);
}

function describePiece(pieceSpec, coolingDuration) {
  const [gatherSize, blowpipeRotationSpeed, kilnTemperature] = parsePieceSpec(pieceSpec);
  const gatherDescription = `gather ${gatherSize} at ${kilnTemperature} deg`;
  const rotationDescription = `rotating ${blowpipeRotationSpeed} rpm`;
  return `${gatherDescription}, ${rotationDescription} -> ${formatDuration(coolingDuration)} min`;
}

function buildAnnealReport(pieces) {
  const coolingDurations = anneal(pieces);
  const reportLines = pieces.map((pieceSpec, pieceIndex) =>
    `piece ${pieceIndex + 1}: ${describePiece(pieceSpec, coolingDurations[pieceIndex])}`);
  const totalOvenTime = coolingDurations.reduce((runningTotal, durationValue) => runningTotal + durationValue, 0);
  const longestDuration = Math.max(...coolingDurations);
  reportLines.push(`total oven time: ${formatDuration(totalOvenTime)} min`);
  reportLines.push(`slowest piece: ${formatDuration(longestDuration)} min`);
  return reportLines.join('\n');
}

function runAnnealDriver(workshopBatch) {
  const computedDurations = anneal(workshopBatch);
  console.log(`durations: [${computedDurations.map(formatDuration).join(', ')}]`);
  console.log(buildAnnealReport(workshopBatch));
}

const workshopBatch = [
  [5, 10, 800, 20],
  [12, 25, 1100, 35],
  [3, 4, 950, 12.5],
];

runAnnealDriver(workshopBatch);

module.exports = { anneal, buildAnnealReport, coolingDurationFor, formatDuration };

