const expectedFieldCount = 4;

function validateSession(sessionValues, sessionIndex) {
  if (!Array.isArray(sessionValues)) {
    throw new TypeError(`session ${sessionIndex} must be a list of metrics`);
  }
  if (sessionValues.length !== expectedFieldCount) {
    throw new RangeError(
      `session ${sessionIndex} must hold exactly ${expectedFieldCount} metrics, got ${sessionValues.length}`
    );
  }
  sessionValues.forEach((metricValue, metricIndex) => {
    if (typeof metricValue !== 'number' || !Number.isFinite(metricValue)) {
      throw new TypeError(`session ${sessionIndex}, metric ${metricIndex} is not a finite number`);
    }
    if (metricValue < 0) {
      throw new RangeError(`session ${sessionIndex}, metric ${metricIndex} cannot be negative`);
    }
  });
}

function computeFadingMonths(needleDepth, pigmentDensity, sunExposureHours, skinElasticity) {
  const pigmentRetention = needleDepth * pigmentDensity;
  const environmentalWear = sunExposureHours * skinElasticity;
  const rawFadingMonths = pigmentRetention - environmentalWear;
  return rawFadingMonths < 0 ? 0 : rawFadingMonths;
}

function predict(sessions) {
  if (!Array.isArray(sessions)) {
    throw new TypeError('sessions must be a list of metric sublists');
  }
  return sessions.map((sessionValues, sessionIndex) => {
    validateSession(sessionValues, sessionIndex);
    const [needleDepth, pigmentDensity, sunExposureHours, skinElasticity] = sessionValues;
    return computeFadingMonths(needleDepth, pigmentDensity, sunExposureHours, skinElasticity);
  });
}

function describeDurability(fadingMonths) {
  if (fadingMonths === 0) {
    return 'immediate touch-up';
  }
  if (fadingMonths < 60) {
    return 'short lived';
  }
  if (fadingMonths < 120) {
    return 'average';
  }
  return 'long lasting';
}

function formatSessionReport(sessions, fadingMonths) {
  const reportLines = sessions.map((sessionValues, sessionIndex) => {
    const [needleDepth, pigmentDensity, sunExposureHours, skinElasticity] = sessionValues;
    const predictedMonths = fadingMonths[sessionIndex];
    const metricSummary = `depth=${needleDepth} density=${pigmentDensity} sun=${sunExposureHours} elasticity=${skinElasticity}`;
    return `#${sessionIndex + 1} ${metricSummary} -> ${predictedMonths} months (${describeDurability(predictedMonths)})`;
  });
  const totalMonths = fadingMonths.reduce((runningTotal, monthValue) => runningTotal + monthValue, 0);
  const averageMonths = fadingMonths.length === 0 ? 0 : totalMonths / fadingMonths.length;
  reportLines.push(`average predicted fading: ${averageMonths.toFixed(1)} months`);
  return reportLines.join('\n');
}

function main() {
  const sampleSessions = [
    [3, 50, 10, 2],
    [1, 20, 30, 4],
    [2, 40, 5, 1],
    [4, 35, 12, 3]
  ];
  const predictedFadingMonths = predict(sampleSessions);
  console.log(predictedFadingMonths);
  console.log(formatSessionReport(sampleSessions, predictedFadingMonths));
}

main();

module.exports = { predict, computeFadingMonths, formatSessionReport, describeDurability };

