function validateCylinder(cylinderEntry, cylinderIndex) {
  if (!Array.isArray(cylinderEntry)) {
    throw new TypeError(`cylinder ${cylinderIndex} must be an array of four numbers`);
  }
  if (cylinderEntry.length !== 4) {
    throw new RangeError(`cylinder ${cylinderIndex} needs exactly four values, got ${cylinderEntry.length}`);
  }
  cylinderEntry.forEach((mechanismValue, valuePosition) => {
    if (typeof mechanismValue !== 'number' || Number.isNaN(mechanismValue)) {
      throw new TypeError(`cylinder ${cylinderIndex} value at index ${valuePosition} is not a number`);
    }
  });
}

function scoreCylinder(cylinderEntry) {
  const [pinDepth, springResistance, torquePressure, falseSetCount] = cylinderEntry;
  return (pinDepth + springResistance) * torquePressure - falseSetCount;
}

function unlock(cylinders) {
  if (!Array.isArray(cylinders)) {
    throw new TypeError('cylinders must be an array of cylinder descriptions');
  }
  return cylinders.map((cylinderEntry, cylinderIndex) => {
    validateCylinder(cylinderEntry, cylinderIndex);
    return scoreCylinder(cylinderEntry);
  });
}

function hardestCylinderIndex(difficultyScores) {
  let hardestIndex = -1;
  let highestScore = -Infinity;
  difficultyScores.forEach((currentScore, scoreIndex) => {
    if (currentScore > highestScore) {
      highestScore = currentScore;
      hardestIndex = scoreIndex;
    }
  });
  return hardestIndex;
}

function formatLockReport(cylinders, difficultyScores) {
  const reportLines = cylinders.map((cylinderEntry, cylinderIndex) => {
    const [pinDepth, springResistance, torquePressure, falseSetCount] = cylinderEntry;
    const scoreText = String(difficultyScores[cylinderIndex]).padStart(5);
    return `pin ${pinDepth} | spring ${springResistance} | torque ${torquePressure} | false sets ${falseSetCount} => ${scoreText}`;
  });
  const totalDifficulty = difficultyScores.reduce((runningTotal, score) => runningTotal + score, 0);
  const averageDifficulty = difficultyScores.length === 0 ? 0 : totalDifficulty / difficultyScores.length;
  reportLines.push(`total difficulty: ${totalDifficulty}`);
  reportLines.push(`average difficulty: ${averageDifficulty.toFixed(2)}`);
  const hardestIndex = hardestCylinderIndex(difficultyScores);
  if (hardestIndex >= 0) {
    reportLines.push(`hardest cylinder: #${hardestIndex} at ${difficultyScores[hardestIndex]}`);
  }
  return reportLines.join('\n');
}

function main() {
  const singlePinLock = [[4, 6, 3, 2]];
  console.log(unlock(singlePinLock));

  const fiveCylinderLock = [
    [4, 6, 3, 2],
    [1, 2, 5, 0],
    [7, 7, 2, 9],
    [0, 3, 4, 1],
    [5, 5, 1, 3],
  ];
  const lockDifficultyScores = unlock(fiveCylinderLock);
  console.log(lockDifficultyScores);
  console.log(formatLockReport(fiveCylinderLock, lockDifficultyScores));
}

main();

module.exports = { unlock, scoreCylinder, hardestCylinderIndex, formatLockReport };

