  cylinder_entry.forEach((mechanism_value, value_position) => {
    if (typeof mechanism_value !== 'number' || Number.isNaN(mechanism_value)) {
      throw new TypeError(`cylinder ${cylinder_index} value at index ${value_position} is not a number`);
    }
  });
}

function score_cylinder(cylinder_entry) {
  const [pin_depth, spring_resistance, torque_pressure, false_set_count] = cylinder_entry;
  return (pin_depth + spring_resistance) * torque_pressure - false_set_count;
}

function unlock(cylinders) {
  if (!Array.isArray(cylinders)) {
    throw new TypeError('cylinders must be an array of cylinder descriptions');
  }
  return cylinders.map((cylinder_entry, cylinder_index) => {
    validate_cylinder(cylinder_entry, cylinder_index);
    return score_cylinder(cylinder_entry);
  });
}

function hardest_cylinder_index(difficulty_scores) {
  let hardest_index = -1;
  let highest_score = -Infinity;
  difficulty_scores.forEach((current_score, score_index) => {
    if (current_score > highest_score) {
      highest_score = current_score;
      hardest_index = score_index;
    }
  });
  return hardest_index;
}

function format_lock_report(cylinders, difficulty_scores) {
  const report_lines = cylinders.map((cylinder_entry, cylinder_index) => {
    const [pin_depth, spring_resistance, torque_pressure, false_set_count] = cylinder_entry;
    const score_text = String(difficulty_scores[cylinder_index]).padStart(5);
    return `pin ${pin_depth} | spring ${spring_resistance} | torque ${torque_pressure} | false sets ${false_set_count} => ${score_text}`;
  });
  const total_difficulty = difficulty_scores.reduce((running_total, score) => running_total + score, 0);
  const average_difficulty = difficulty_scores.length === 0 ? 0 : total_difficulty / difficulty_scores.length;
  report_lines.push(`total difficulty: ${total_difficulty}`);
  report_lines.push(`average difficulty: ${average_difficulty.toFixed(2)}`);
  const hardest_index = hardest_cylinder_index(difficulty_scores);
  if (hardest_index >= 0) {
    report_lines.push(`hardest cylinder: #${hardest_index} at ${difficulty_scores[hardest_index]}`);
  }
  return report_lines.join('\n');
}

function main() {
  const single_pin_lock = [[4, 6, 3, 2]];
  console.log(unlock(single_pin_lock));

  const five_cylinder_lock = [
    [4, 6, 3, 2],
    [1, 2, 5, 0],
    [7, 7, 2, 9],
    [0, 3, 4, 1],
    [5, 5, 1, 3],
  ];
