function validateShoeEntry(shoeEntry, entryIndex) {
  if (!Array.isArray(shoeEntry) || shoeEntry.length !== 4) {
    throw new TypeError(
      `Shoe entry at index ${entryIndex} must hold exactly four measurements`
    );
  }
  const [leatherThickness, moistureContent, pullingForce, toeBoxWidth] = shoeEntry;
  const measurementNames = ['leather thickness', 'moisture content', 'pulling force', 'toe box width'];
  shoeEntry.forEach((measurementValue, measurementIndex) => {
    if (typeof measurementValue !== 'number' || !Number.isFinite(measurementValue)) {
      throw new TypeError(
        `The ${measurementNames[measurementIndex]} of shoe ${entryIndex} must be a finite number`
      );
    }
  });
  if (leatherThickness === 0) {
    throw new RangeError(`Shoe ${entryIndex} has a leather thickness of zero`);
  }
  return { leatherThickness, moistureContent, pullingForce, toeBoxWidth };
}

function computeExpansionMillimeters(shoeMeasurements) {
  const { leatherThickness, moistureContent, pullingForce, toeBoxWidth } = shoeMeasurements;
  return (pullingForce * moistureContent) / leatherThickness + toeBoxWidth;
}

function stretch(shoes) {
  if (!Array.isArray(shoes)) {
    throw new TypeError('stretch expects a list of shoe measurement lists');
  }
  return shoes.map((shoeEntry, entryIndex) => {
    const shoeMeasurements = validateShoeEntry(shoeEntry, entryIndex);
    return computeExpansionMillimeters(shoeMeasurements);
  });
}

function formatExpansionReport(shoes) {
  const expansionValues = stretch(shoes);
  const reportLines = expansionValues.map((expansionMillimeters, shoeNumber) => {
    const roundedExpansion = Math.round(expansionMillimeters * 100) / 100;
    return `Shoe #${shoeNumber + 1}: expands to ${roundedExpansion} mm`;
  });
  const widestExpansion = expansionValues.reduce(
    (currentWidest, expansionMillimeters) => Math.max(currentWidest, expansionMillimeters),
    Number.NEGATIVE_INFINITY
  );
  const totalExpansion = expansionValues.reduce(
    (runningTotal, expansionMillimeters) => runningTotal + expansionMillimeters,
    0
  );
  const averageExpansion = Math.round((totalExpansion / expansionValues.length) * 100) / 100;
  reportLines.push(`Widest stretch: ${widestExpansion} mm`);
  reportLines.push(`Average stretch: ${averageExpansion} mm`);
  return reportLines.join('\n');
}

function main() {
  const workshopBatch = [
    [2, 5, 10, 40],
    [4, 3, 20, 35],
    [1.5, 2, 9, 12.5],
  ];
  const singleShoeBatch = [[2, 5, 10, 40]];
  console.log(stretch(singleShoeBatch).join(', '));
  console.log(formatExpansionReport(workshopBatch));
}

main();

module.exports = { stretch, computeExpansionMillimeters, formatExpansionReport };

