function validateBellSpec(bellSpec, bellIndex) {
  if (!Array.isArray(bellSpec) || bellSpec.length !== 4) {
    throw new TypeError(`bell ${bellIndex} must be a list of four numbers`);
  }
  const [bellWeight, ropeLength, swingAngle, clapperStrikeForce] = bellSpec;
  const numericValues = [bellWeight, ropeLength, swingAngle, clapperStrikeForce];
  if (numericValues.some((measuredValue) => typeof measuredValue !== 'number' || Number.isNaN(measuredValue))) {
    throw new TypeError(`bell ${bellIndex} contains a non-numeric measurement`);
  }
  if (ropeLength === 0) {
    throw new RangeError(`bell ${bellIndex} has a rope length of zero`);
  }
  return { bellWeight, ropeLength, swingAngle, clapperStrikeForce };
}

function resonanceDuration(bellSpec, bellIndex) {
  const { bellWeight, ropeLength, swingAngle, clapperStrikeForce } = validateBellSpec(bellSpec, bellIndex);
  return (bellWeight * clapperStrikeForce) / ropeLength + swingAngle;
}

function strike(bells) {
  if (!Array.isArray(bells)) {
    throw new TypeError('strike expects a list of bell measurements');
  }
  return bells.map((bellSpec, bellIndex) => resonanceDuration(bellSpec, bellIndex));
}

function longestRingingBell(bells) {
  const allDurations = strike(bells);
  let leadingIndex = -1;
  let longestDuration = -Infinity;
  allDurations.forEach((currentDuration, currentIndex) => {
    if (currentDuration > longestDuration) {
      longestDuration = currentDuration;
      leadingIndex = currentIndex;
    }
  });
  return { leadingIndex, longestDuration };
}

function formatPerformanceReport(bells) {
  const allDurations = strike(bells);
  const reportLines = allDurations.map((bellDuration, bellIndex) => {
    const [bellWeight, ropeLength, swingAngle, clapperStrikeForce] = bells[bellIndex];
    const roundedDuration = Math.round(bellDuration * 100) / 100;
    return `Bell ${bellIndex + 1}: ${bellWeight}kg on ${ropeLength}m rope, ` +
      `${swingAngle}° swing, force ${clapperStrikeForce} -> ${roundedDuration}s`;
  });
  const totalRingingTime = allDurations.reduce((runningTotal, bellDuration) => runningTotal + bellDuration, 0);
  const averageDuration = allDurations.length === 0 ? 0 : totalRingingTime / allDurations.length;
  reportLines.push(`Average resonance: ${(Math.round(averageDuration * 100) / 100)}s`);
  if (allDurations.length > 0) {
    const { leadingIndex, longestDuration } = longestRingingBell(bells);
    reportLines.push(`Longest ringer: bell ${leadingIndex + 1} at ${Math.round(longestDuration * 100) / 100}s`);
  }
  return reportLines.join('\n');
}

function main() {
  const singleBellPeal = [[500, 10, 45, 2]];
  console.log(strike(singleBellPeal));

  const fullBellTower = [
    [500, 10, 45, 2],
    [750, 12, 30, 3],
    [1200, 15, 60, 1.5],
    [300, 8, 25, 4],
  ];
  console.log(strike(fullBellTower));
  console.log(formatPerformanceReport(fullBellTower));
}

main();

module.exports = { strike, resonanceDuration, longestRingingBell, formatPerformanceReport };

