const specFieldNames = ['fiber length', 'screen mesh size', 'pressing pressure', 'sheet thickness'];

function validateSheetSpec(sheetSpec, sheetIndex) {
  if (!Array.isArray(sheetSpec) || sheetSpec.length !== specFieldNames.length) {
    throw new TypeError(`sheet ${sheetIndex} must list exactly ${specFieldNames.length} measurements`);
  }
  for (let fieldIndex = 0; fieldIndex < specFieldNames.length; fieldIndex += 1) {
    const measuredValue = sheetSpec[fieldIndex];
    if (typeof measuredValue !== 'number' || !Number.isFinite(measuredValue)) {
      throw new TypeError(`sheet ${sheetIndex}: ${specFieldNames[fieldIndex]} must be a finite number`);
    }
  }
  const pressingPressure = sheetSpec[2];
  if (pressingPressure === 0) {
    throw new RangeError(`sheet ${sheetIndex}: pressing pressure must not be zero`);
  }
}

function computeDryingHours(sheetSpec) {
  const fiberLength = sheetSpec[0];
  const screenMeshSize = sheetSpec[1];
  const pressingPressure = sheetSpec[2];
  const sheetThickness = sheetSpec[3];
  const fiberMassTerm = fiberLength * sheetThickness;
  return (fiberMassTerm + screenMeshSize) / pressingPressure;
}

function dry(sheets) {
  if (!Array.isArray(sheets)) {
    throw new TypeError('sheets must be an array of measurement lists');
  }
  return sheets.map((sheetSpec, sheetIndex) => {
    validateSheetSpec(sheetSpec, sheetIndex);
    return computeDryingHours(sheetSpec);
  });
}

function formatHourValue(hourValue) {
  const roundedHours = Math.round(hourValue * 100) / 100;
  return Number.isInteger(roundedHours) ? String(roundedHours) : roundedHours.toFixed(2);
}

function formatDryingReport(sheets, dryingHoursList) {
  const reportLines = dryingHoursList.map((dryingHours, sheetIndex) => {
    const currentSpec = sheets[sheetIndex];
    const specSummary = specFieldNames
      .map((fieldName, fieldIndex) => `${fieldName}=${currentSpec[fieldIndex]}`)
      .join(', ');
    return `Sheet ${sheetIndex + 1} [${specSummary}] -> ${formatHourValue(dryingHours)} h`;
  });
  const totalDryingHours = dryingHoursList.reduce((runningTotal, dryingHours) => runningTotal + dryingHours, 0);
  reportLines.push(`Total drying time: ${formatHourValue(totalDryingHours)} h`);
  if (dryingHoursList.length > 0) {
    const longestDryingHours = Math.max(...dryingHoursList);
    const slowestSheetNumber = dryingHoursList.indexOf(longestDryingHours) + 1;
    reportLines.push(`Slowest sheet: #${slowestSheetNumber} at ${formatHourValue(longestDryingHours)} h`);
  }
  return reportLines.join('\n');
}

