function parseBatchValues(rawBatch) {
  if (!Array.isArray(rawBatch) || rawBatch.length !== 4) {
    throw new TypeError('each batch must hold exactly four numeric values');
  }
  const [wickDiameter, waxMeltingPoint, fragranceLoadPercentage, ambientRoomTemperature] = rawBatch;
  const numericValues = [wickDiameter, waxMeltingPoint, fragranceLoadPercentage, ambientRoomTemperature];
  if (numericValues.some((batchValue) => typeof batchValue !== 'number' || Number.isNaN(batchValue))) {
    throw new TypeError('batch values must all be numbers');
  }
  return { wickDiameter, waxMeltingPoint, fragranceLoadPercentage, ambientRoomTemperature };
}

function computePourTemperature(parsedBatch) {
  const { wickDiameter, waxMeltingPoint, fragranceLoadPercentage, ambientRoomTemperature } = parsedBatch;
  const wickHeatLoss = wickDiameter * ambientRoomTemperature;
  return waxMeltingPoint + fragranceLoadPercentage - wickHeatLoss;
}

function melt(batches) {
  if (!Array.isArray(batches)) {
    throw new TypeError('batches must be a list of batch descriptions');
  }
  return batches.map((rawBatch) => computePourTemperature(parseBatchValues(rawBatch)));
}

function formatBatchReport(rawBatch, targetPourTemperature) {
  const { wickDiameter, waxMeltingPoint, fragranceLoadPercentage, ambientRoomTemperature } = parseBatchValues(rawBatch);
  const wickLabel = `wick ${wickDiameter.toFixed(1)}mm`;
  const waxLabel = `wax ${waxMeltingPoint}F`;
  const fragranceLabel = `fragrance ${fragranceLoadPercentage}%`;
  const roomLabel = `room ${ambientRoomTemperature}F`;
  const pourLabel = `pour at ${targetPourTemperature}F`;
  return `${wickLabel} | ${waxLabel} | ${fragranceLabel} | ${roomLabel} -> ${pourLabel}`;
}

function buildProductionReport(batches) {
  const pourTemperatures = melt(batches);
  const reportLines = batches.map((rawBatch, batchIndex) =>
    formatBatchReport(rawBatch, pourTemperatures[batchIndex]));
  const temperatureTotal = pourTemperatures.reduce((runningSum, pourValue) => runningSum + pourValue, 0);
  const averagePourTemperature = pourTemperatures.length === 0
    ? 0
    : temperatureTotal / pourTemperatures.length;
  const hottestPourTemperature = pourTemperatures.length === 0
    ? 0
    : Math.max(...pourTemperatures);
  reportLines.push(`average pour ${averagePourTemperature.toFixed(2)}F, hottest pour ${hottestPourTemperature}F`);
  return reportLines.join('\n');
}

function runProductionPlanner(batchCollection) {
  const pourTemperatures = melt(batchCollection);
  const plannerOutput = buildProductionReport(batchCollection);
  console.log(plannerOutput);
  console.log(`target pour temperatures: [${pourTemperatures.join(', ')}]`);
}

const plannedBatches = [
  [2, 150, 10, 20],
  [1.5, 185, 8, 22],
  [3, 160, 12, 18],
];

runProductionPlanner(plannedBatches);

module.exports = { melt, buildProductionReport, formatBatchReport, runProductionPlanner };

