    format_batch_report(raw_batch, pour_temperatures[batch_index]));
  const temperature_total = pour_temperatures.reduce((running_sum, pour_value) => running_sum + pour_value, 0);
  const average_pour_temperature = pour_temperatures.length === 0
    ? 0
    : temperature_total / pour_temperatures.length;
  const hottest_pour_temperature = pour_temperatures.length === 0
    ? 0
    : Math.max(...pour_temperatures);
  report_lines.push(`average pour ${average_pour_temperature.toFixed(2)}F, hottest pour ${hottest_pour_temperature}F`);
  return report_lines.join('\n');
}

function run_production_planner(batch_collection) {
