function validateLinkSpec(linkSpec, linkIndex) {
  if (!Array.isArray(linkSpec) || linkSpec.length !== 4) {
    throw new TypeError(`link ${linkIndex} must be [grind, fat, spice, elasticity]`);
  }
  const [meatGrindSize, fatPercentage, spiceRatio, casingElasticity] = linkSpec;
  const measuredFields = [meatGrindSize, fatPercentage, spiceRatio, casingElasticity];
  if (measuredFields.some((fieldValue) => typeof fieldValue !== 'number' || !Number.isFinite(fieldValue))) {
    throw new TypeError(`link ${linkIndex} contains a non-numeric measurement`);
  }
  if (casingElasticity === 0) {
    throw new RangeError(`link ${linkIndex} has zero casing elasticity`);
  }
  return { meatGrindSize, fatPercentage, spiceRatio, casingElasticity };
}

function computeBlowoutRisk(linkMeasurements) {
  const { meatGrindSize, fatPercentage, spiceRatio, casingElasticity } = linkMeasurements;
  const combinedMassLoad = meatGrindSize + fatPercentage;
  const spicedPressure = combinedMassLoad * spiceRatio;
  return spicedPressure / casingElasticity;
}

function stuff(links) {
  if (!Array.isArray(links)) {
    throw new TypeError('links must be an array of link specifications');
  }
  return links.map((linkSpec, linkIndex) => computeBlowoutRisk(validateLinkSpec(linkSpec, linkIndex)));
}

function classifyRiskLevel(blowoutRisk) {
  if (blowoutRisk < 10) {
    return 'safe';
  }
  if (blowoutRisk < 20) {
    return 'watch';
  }
  return 'critical';
}

function formatRiskReport(riskScores) {
  const reportLines = riskScores.map((blowoutRisk, linkIndex) => {
    const roundedRisk = Math.round(blowoutRisk * 100) / 100;
    const riskLevel = classifyRiskLevel(blowoutRisk);
    return `link ${linkIndex + 1}: risk ${roundedRisk} (${riskLevel})`;
  });
  const highestRisk = riskScores.reduce((currentMax, blowoutRisk) => Math.max(currentMax, blowoutRisk), 0);
  reportLines.push(`worst link risk: ${Math.round(highestRisk * 100) / 100}`);
  return reportLines.join('\n');
}

function countCriticalLinks(riskScores) {
  return riskScores.filter((blowoutRisk) => classifyRiskLevel(blowoutRisk) === 'critical').length;
}

function inspectSausageBatch(batchName, batchLinks) {
  const riskScores = stuff(batchLinks);
  const criticalCount = countCriticalLinks(riskScores);
  const batchVerdict = criticalCount === 0 ? 'batch approved' : `batch rejected (${criticalCount} critical links)`;
  return `${batchName}\n${formatRiskReport(riskScores)}\n${batchVerdict}`;
}

function main() {
  const morningBatchLinks = [[8, 20, 2, 4]];
  const afternoonBatchLinks = [[10, 25, 3, 5], [6, 14, 1, 10], [12, 30, 4, 3]];
  console.log(inspectSausageBatch('morning batch', morningBatchLinks));
  console.log(inspectSausageBatch('afternoon batch', afternoonBatchLinks));
}

main();

module.exports = { stuff, inspectSausageBatch };

