function validateReedSpec(reedSpec, specIndex) {
  if (!Array.isArray(reedSpec) || reedSpec.length !== 4) {
    throw new Error(`Reed spec at position ${specIndex} must list four values`);
  }
  const [reedThickness, waterTemperature, soakingHours, bendRadius] = reedSpec;
  const everyValueNumeric = reedSpec.every((value) => typeof value === 'number' && Number.isFinite(value));
  if (!everyValueNumeric) {
    throw new Error(`Reed spec at position ${specIndex} contains a non-numeric value`);
  }
  if (reedThickness === 0) {
    throw new Error(`Reed spec at position ${specIndex} has zero thickness`);
  }
  return { reedThickness, waterTemperature, soakingHours, bendRadius };
}

function computeFlexibilityIndex(reedThickness, waterTemperature, soakingHours, bendRadius) {
  return (waterTemperature * soakingHours) / reedThickness + bendRadius;
}

function soak(reeds) {
  if (!Array.isArray(reeds)) {
    throw new Error('soak expects a list of reed specs');
  }
  return reeds.map((reedSpec, specIndex) => {
    const { reedThickness, waterTemperature, soakingHours, bendRadius } = validateReedSpec(reedSpec, specIndex);
    return computeFlexibilityIndex(reedThickness, waterTemperature, soakingHours, bendRadius);
  });
}

function classifyFlexibility(flexibilityIndex) {
  if (flexibilityIndex < 15) {
    return 'brittle';
  }
  if (flexibilityIndex < 40) {
    return 'workable';
  }
  return 'highly pliable';
}

function formatIndexValue(flexibilityIndex) {
  const roundedIndex = Math.round(flexibilityIndex * 100) / 100;
  return Number.isInteger(roundedIndex) ? String(roundedIndex) : roundedIndex.toFixed(2);
}

function buildSoakReport(reeds) {
  const indexValues = soak(reeds);
  const reportLines = indexValues.map((flexibilityIndex, reedNumber) => {
    const [reedThickness, waterTemperature, soakingHours, bendRadius] = reeds[reedNumber];
    const flexibilityLabel = classifyFlexibility(flexibilityIndex);
    return `reed ${reedNumber + 1}: thickness ${reedThickness}, ${waterTemperature}° for ${soakingHours}h, `
      + `bend ${bendRadius} -> index ${formatIndexValue(flexibilityIndex)} (${flexibilityLabel})`;
  });
  const averageIndex = indexValues.reduce((runningTotal, value) => runningTotal + value, 0) / indexValues.length;
  reportLines.push(`batch average index: ${formatIndexValue(averageIndex)}`);
  return reportLines.join('\n');
}

