function validateBlock(blockValues, blockIndex) {
  if (!Array.isArray(blockValues) || blockValues.length !== 4) {
    throw new TypeError(`block ${blockIndex} must contain exactly four numbers`);
  }
  blockValues.forEach((measuredValue, valuePosition) => {
    if (typeof measuredValue !== 'number' || !Number.isFinite(measuredValue)) {
      throw new TypeError(`block ${blockIndex}, field ${valuePosition} is not a finite number`);
    }
  });
  const woodHardnessScore = blockValues[0];
  if (woodHardnessScore === 0) {
    throw new RangeError(`block ${blockIndex} has a wood hardness score of zero`);
  }
}

function computeOptimalSpeed(woodHardnessScore, latheRevolutionsLimit, chiselCuttingAngle, shavingThickness) {
  return latheRevolutionsLimit / woodHardnessScore + chiselCuttingAngle * shavingThickness;
}

function turn(blocks) {
  if (!Array.isArray(blocks)) {
    throw new TypeError('blocks must be an array of settings sublists');
  }
  return blocks.map((blockValues, blockIndex) => {
    validateBlock(blockValues, blockIndex);
    const [woodHardnessScore, latheRevolutionsLimit, chiselCuttingAngle, shavingThickness] = blockValues;
    return computeOptimalSpeed(woodHardnessScore, latheRevolutionsLimit, chiselCuttingAngle, shavingThickness);
  });
}

function formatSpeedRow(blockValues, optimalSpeed) {
  const [woodHardnessScore, latheRevolutionsLimit, chiselCuttingAngle, shavingThickness] = blockValues;
  const settingsSummary = [
    `hardness=${woodHardnessScore}`,
    `revLimit=${latheRevolutionsLimit}`,
    `angle=${chiselCuttingAngle}`,
    `shaving=${shavingThickness}`
  ].join(', ');
  const roundedSpeed = Math.round(optimalSpeed * 100) / 100;
  return `${settingsSummary} -> speed ${roundedSpeed}`;
}

function buildTurningReport(blocks) {
  const optimalSpeeds = turn(blocks);
  const reportLines = blocks.map((blockValues, blockIndex) => formatSpeedRow(blockValues, optimalSpeeds[blockIndex]));
  const fastestSpeed = optimalSpeeds.reduce((currentMax, candidateSpeed) => Math.max(currentMax, candidateSpeed), -Infinity);
  const fastestBlockIndex = optimalSpeeds.indexOf(fastestSpeed);
  reportLines.push(`fastest setting: block ${fastestBlockIndex} at ${Math.round(fastestSpeed * 100) / 100}`);
  return reportLines.join('\n');
}

