function validateJoint(jointParameters, jointIndex) {
  if (!Array.isArray(jointParameters) || jointParameters.length !== 4) {
    throw new Error(`joint ${jointIndex} must list width, heat, flux and lead-tin ratio`);
  }
  const numericValues = jointParameters.map(Number);
  const hasInvalidEntry = numericValues.some((parameterValue) => !Number.isFinite(parameterValue));
  if (hasInvalidEntry) {
    throw new Error(`joint ${jointIndex} contains a non-numeric parameter`);
  }
  const [copperFoilWidth] = numericValues;
  if (copperFoilWidth <= 0) {
    throw new Error(`joint ${jointIndex} has a copper foil width of ${copperFoilWidth}`);
  }
  return numericValues;
}

function jointStrength(copperFoilWidth, solderingIronHeat, fluxAmount, leadTinRatio) {
  return (solderingIronHeat * fluxAmount) / copperFoilWidth + leadTinRatio;
}

function solder(joints) {
  if (!Array.isArray(joints)) {
    throw new Error('solder expects a list of joints');
  }
  return joints.map((jointParameters, jointIndex) => {
    const [copperFoilWidth, solderingIronHeat, fluxAmount, leadTinRatio] = validateJoint(jointParameters, jointIndex);
    return jointStrength(copperFoilWidth, solderingIronHeat, fluxAmount, leadTinRatio);
  });
}

function classifyStrength(strengthScore) {
  if (strengthScore < 100) {
    return 'weak';
  }
  if (strengthScore < 200) {
    return 'acceptable';
  }
  return 'strong';
}

function formatJointReport(jointParameters, strengthScore) {
  const [copperFoilWidth, solderingIronHeat, fluxAmount, leadTinRatio] = jointParameters;
  const roundedScore = Math.round(strengthScore * 100) / 100;
  const strengthLabel = classifyStrength(strengthScore);
  return `foil ${copperFoilWidth}mm | iron ${solderingIronHeat}F | flux ${fluxAmount}g | `
    + `alloy ${leadTinRatio}% -> ${roundedScore} (${strengthLabel})`;
}

function buildAssemblyReport(joints) {
  const strengthScores = solder(joints);
  const reportLines = joints.map((jointParameters, jointIndex) =>
    `joint ${jointIndex + 1}: ${formatJointReport(jointParameters, strengthScores[jointIndex])}`);
  const scoreTotal = strengthScores.reduce((runningTotal, strengthScore) => runningTotal + strengthScore, 0);
  const averageStrength = Math.round((scoreTotal / strengthScores.length) * 100) / 100;
  const weakestScore = Math.min(...strengthScores);
  reportLines.push(`average strength ${averageStrength}, weakest joint ${weakestScore}`);
  return reportLines.join('\n');
}

const windowAssemblyJoints = [
  [5, 400, 2, 60],
  [8, 350, 3, 45],
  [2.5, 300, 1, 30],
];

console.log(solder(windowAssemblyJoints));
console.log(buildAssemblyReport(windowAssemblyJoints));

module.exports = { solder, jointStrength, buildAssemblyReport };

