function validateTubeSpec(tubeSpec, tubeIndex) {
  if (!Array.isArray(tubeSpec) || tubeSpec.length !== 4) {
    throw new Error(`Tube ${tubeIndex} must list exactly four properties`);
  }
  const [tubeDiameter, electrodeVoltage, vacuumPressure, expectedBrightness] = tubeSpec;
  const allNumeric = tubeSpec.every((propertyValue) => typeof propertyValue === 'number' && Number.isFinite(propertyValue));
  if (!allNumeric) {
    throw new Error(`Tube ${tubeIndex} has a non-numeric property`);
  }
  if (vacuumPressure === 0) {
    throw new Error(`Tube ${tubeIndex} has zero vacuum pressure`);
  }
  return { tubeDiameter, electrodeVoltage, vacuumPressure, expectedBrightness };
}

function computeOperationTime(tubeSpec, tubeIndex) {
  const { tubeDiameter, electrodeVoltage, vacuumPressure, expectedBrightness } = validateTubeSpec(tubeSpec, tubeIndex);
  const brightnessDrivenLoad = electrodeVoltage * expectedBrightness;
  const pressureAdjustedLoad = brightnessDrivenLoad / vacuumPressure;
  return pressureAdjustedLoad - tubeDiameter;
}

function illuminate(tubes) {
  if (!Array.isArray(tubes)) {
    throw new Error('illuminate expects a list of tube specifications');
  }
  return tubes.map((tubeSpec, tubeIndex) => computeOperationTime(tubeSpec, tubeIndex));
}

function formatOperationTime(operationTime) {
  const roundedHours = Math.round(operationTime * 100) / 100;
  return `${roundedHours} h`;
}

function describeTube(tubeSpec, operationTime) {
  const [tubeDiameter, electrodeVoltage, vacuumPressure, expectedBrightness] = tubeSpec;
  const specSummary = `d=${tubeDiameter}mm V=${electrodeVoltage} p=${vacuumPressure} b=${expectedBrightness}`;
  return `${specSummary} -> ${formatOperationTime(operationTime)}`;
}

function buildIlluminationReport(tubes) {
  const operationTimes = illuminate(tubes);
  const reportLines = tubes.map((tubeSpec, tubeIndex) => describeTube(tubeSpec, operationTimes[tubeIndex]));
  const totalOperationTime = operationTimes.reduce((runningTotal, operationTime) => runningTotal + operationTime, 0);
  const longestOperationTime = operationTimes.reduce((bestSoFar, operationTime) => Math.max(bestSoFar, operationTime), -Infinity);
  const averageOperationTime = totalOperationTime / operationTimes.length;
  reportLines.push(`average: ${formatOperationTime(averageOperationTime)}`);
  reportLines.push(`longest: ${formatOperationTime(longestOperationTime)}`);
  return reportLines.join('\n');
}

function main() {
  const tubeBatch = [
    [10, 120, 3, 50],
    [5, 90, 2, 12],
    [12.5, 240, 7.5, 30],
  ];
  const operationTimes = illuminate(tubeBatch);
  console.log(operationTimes);
  console.log(buildIlluminationReport(tubeBatch));

  const unstableTube = [8, 150, 0, 20];
  try {
    illuminate([unstableTube]);
  } catch (validationError) {
    console.log(`rejected: ${validationError.message}`);
  }
}

main();

module.exports = { illuminate, buildIlluminationReport, formatOperationTime };

