function validateWaveEntry(waveEntry, entryIndex) {
  if (!Array.isArray(waveEntry) || waveEntry.length !== 4) {
    throw new Error(`Wave entry ${entryIndex} must hold exactly four metrics`);
  }
  const [swellHeight, oceanFloorDepth, boardBuoyancyRating, paddlingSpeed] = waveEntry;
  const metricLabels = ['swell height', 'ocean floor depth', 'board buoyancy rating', 'paddling speed'];
  waveEntry.forEach((metricValue, metricIndex) => {
    if (typeof metricValue !== 'number' || !Number.isFinite(metricValue)) {
      throw new Error(`Wave entry ${entryIndex} has a non-numeric ${metricLabels[metricIndex]}`);
    }
  });
  if (boardBuoyancyRating === 0) {
    throw new Error(`Wave entry ${entryIndex} has a board buoyancy rating of zero`);
  }
  return { swellHeight, oceanFloorDepth, boardBuoyancyRating, paddlingSpeed };
}

function computeCaptureScore(waveEntry, entryIndex) {
  const { swellHeight, oceanFloorDepth, boardBuoyancyRating, paddlingSpeed } =
    validateWaveEntry(waveEntry, entryIndex);
  const combinedWaterHeight = swellHeight + oceanFloorDepth;
  return (combinedWaterHeight * paddlingSpeed) / boardBuoyancyRating;
}

function surf(waves) {
  if (!Array.isArray(waves)) {
    throw new Error('surf expects a list of wave metric sublists');
  }
  return waves.map(computeCaptureScore);
}

function describeCondition(captureScore) {
  if (captureScore >= 60) {
    return 'epic';
  }
  if (captureScore >= 30) {
    return 'rideable';
  }
  return 'flat day';
}

function formatScoreReport(waves, captureScores) {
  const reportLines = captureScores.map((captureScore, scoreIndex) => {
    const [swellHeight, oceanFloorDepth, boardBuoyancyRating, paddlingSpeed] = waves[scoreIndex];
    const roundedScore = Math.round(captureScore * 100) / 100;
    const conditionLabel = describeCondition(captureScore);
    return `swell ${swellHeight}m over ${oceanFloorDepth}m floor, buoyancy ${boardBuoyancyRating}, ` +
      `paddling ${paddlingSpeed} -> score ${roundedScore} (${conditionLabel})`;
  });
  return reportLines.join('\n');
}

function summarizeSession(captureScores) {
  const scoreTotal = captureScores.reduce((runningTotal, captureScore) => runningTotal + captureScore, 0);
  const averageCaptureScore = captureScores.length === 0 ? 0 : scoreTotal / captureScores.length;
  const bestCaptureScore = captureScores.reduce(
    (currentBest, captureScore) => (captureScore > currentBest ? captureScore : currentBest),
    Number.NEGATIVE_INFINITY
  );
  return { averageCaptureScore, bestCaptureScore };
}

function runSurfSession(waveReadings) {
  const captureScores = surf(waveReadings);
  console.log(formatScoreReport(waveReadings, captureScores));
  const { averageCaptureScore, bestCaptureScore } = summarizeSession(captureScores);
  console.log(`average ${Math.round(averageCaptureScore * 100) / 100}, best ${bestCaptureScore}`);
  return captureScores;
}

const morningReadings = [[6, 14, 5, 10], [3, 9, 4, 8], [12, 20, 8, 15]];
console.log(runSurfSession(morningReadings));
console.log(surf([[6, 14, 5, 10]]));

module.exports = { surf, computeCaptureScore, formatScoreReport, summarizeSession, runSurfSession };

