function validateDropRecord(dropRecord, recordIndex) {
  if (!Array.isArray(dropRecord) || dropRecord.length !== 4) {
    throw new Error(`Drop record ${recordIndex} must hold exactly four numbers`);
  }
  dropRecord.forEach((parameterValue, parameterIndex) => {
    if (typeof parameterValue !== 'number' || !Number.isFinite(parameterValue)) {
      throw new Error(`Drop record ${recordIndex}, slot ${parameterIndex} is not a finite number`);
    }
  });
}

function computeCordTension(jumperMass, cordRestingLength, freefallDistance, maxReboundHeight) {
  return jumperMass * freefallDistance - cordRestingLength + maxReboundHeight;
}

function jump(drops) {
  if (!Array.isArray(drops)) {
    throw new Error('jump expects a list of drop records');
  }
  return drops.map((dropRecord, recordIndex) => {
    validateDropRecord(dropRecord, recordIndex);
    const [jumperMass, cordRestingLength, freefallDistance, maxReboundHeight] = dropRecord;
    return computeCordTension(jumperMass, cordRestingLength, freefallDistance, maxReboundHeight);
  });
}

function classifyTension(cordTensionStress, safeTensionLimit) {
  if (cordTensionStress > safeTensionLimit) {
    return 'UNSAFE';
  }
  if (cordTensionStress > safeTensionLimit * 0.8) {
    return 'MARGINAL';
  }
  return 'SAFE';
}

function formatTensionReport(drops, safeTensionLimit) {
  const tensionStresses = jump(drops);
  const reportLines = tensionStresses.map((cordTensionStress, recordIndex) => {
    const [jumperMass, cordRestingLength, freefallDistance, maxReboundHeight] = drops[recordIndex];
    const safetyVerdict = classifyTension(cordTensionStress, safeTensionLimit);
    const describedInputs = `mass=${jumperMass}kg cord=${cordRestingLength}m fall=${freefallDistance}m rebound=${maxReboundHeight}m`;
    return `#${recordIndex + 1} ${describedInputs} -> stress ${cordTensionStress} [${safetyVerdict}]`;
  });
  const highestStress = tensionStresses.reduce((runningMax, currentStress) => Math.max(runningMax, currentStress), 0);
  reportLines.push(`Peak cord tension stress: ${highestStress} (limit ${safeTensionLimit})`);
  return reportLines.join('\n');
}

function runJumpChecks(dropBatches, safeTensionLimit) {
  dropBatches.forEach((dropBatch, batchIndex) => {
    console.log(`Batch ${batchIndex + 1}`);
    try {
      console.log(formatTensionReport(dropBatch, safeTensionLimit));
    } catch (validationError) {
      console.log(`Rejected batch: ${validationError.message}`);
    }
  });
}

