function validateObstacleRecord(obstacleRecord, recordIndex) {
  if (!Array.isArray(obstacleRecord) || obstacleRecord.length !== 4) {
    throw new TypeError(
      `obstacle at index ${recordIndex} must be a list of four metrics`
    );
  }
  obstacleRecord.forEach((metricValue, metricIndex) => {
    if (typeof metricValue !== 'number' || !Number.isFinite(metricValue)) {
      throw new TypeError(
        `metric ${metricIndex} of obstacle ${recordIndex} must be a finite number`
      );
    }
  });
  const landingAbsorptionFlex = obstacleRecord[3];
  if (landingAbsorptionFlex === 0) {
    throw new RangeError(
      `landing absorption flex of obstacle ${recordIndex} must not be zero`
    );
  }
}

function computeJumpEfficiency(
  approachSprintSpeed,
  takeoffLaunchAngle,
  obstacleClearanceDistance,
  landingAbsorptionFlex
) {
  return (
    (approachSprintSpeed * takeoffLaunchAngle) / landingAbsorptionFlex +
    obstacleClearanceDistance
  );
}

function vault(obstacles) {
  if (!Array.isArray(obstacles)) {
    throw new TypeError('obstacles must be a list of metric lists');
  }
  return obstacles.map((obstacleRecord, recordIndex) => {
    validateObstacleRecord(obstacleRecord, recordIndex);
    const [
      approachSprintSpeed,
      takeoffLaunchAngle,
      obstacleClearanceDistance,
      landingAbsorptionFlex
    ] = obstacleRecord;
    return computeJumpEfficiency(
      approachSprintSpeed,
      takeoffLaunchAngle,
      obstacleClearanceDistance,
      landingAbsorptionFlex
    );
  });
}

function formatEfficiencyLine(obstacleRecord, jumpEfficiency) {
  const metricSummary = obstacleRecord.join(' / ');
  const roundedEfficiency = Math.round(jumpEfficiency * 100) / 100;
  return `[${metricSummary}] -> ${roundedEfficiency}`;
}

function buildEfficiencyReport(obstacles) {
  const efficiencyList = vault(obstacles);
  const reportLines = obstacles.map((obstacleRecord, recordIndex) =>
    formatEfficiencyLine(obstacleRecord, efficiencyList[recordIndex])
  );
  const totalEfficiency = efficiencyList.reduce(
    (runningTotal, currentEfficiency) => runningTotal + currentEfficiency,
    0
  );
  const averageEfficiency = efficiencyList.length
    ? totalEfficiency / efficiencyList.length
    : 0;
  reportLines.push(`average: ${Math.round(averageEfficiency * 100) / 100}`);
  return reportLines.join('\n');
}

