const propertyLabels = [
  'string total length',
  'bearing friction coefficient',
  'downward throw velocity',
  'weight distribution ratio',
];

function validateTrick(trickProperties, trickIndex) {
  if (!Array.isArray(trickProperties)) {
    throw new TypeError(`trick ${trickIndex} must be a list of yo-yo properties`);
  }
  if (trickProperties.length !== propertyLabels.length) {
    throw new RangeError(
      `trick ${trickIndex} needs exactly ${propertyLabels.length} properties, got ${trickProperties.length}`
    );
  }
  trickProperties.forEach((propertyValue, propertyIndex) => {
    if (typeof propertyValue !== 'number' || !Number.isFinite(propertyValue)) {
      throw new TypeError(
        `trick ${trickIndex}: ${propertyLabels[propertyIndex]} must be a finite number`
      );
    }
  });
}

function computeSleepSeconds(trickProperties) {
  const [
    stringTotalLength,
    bearingFrictionCoefficient,
    downwardThrowVelocity,
    weightDistributionRatio,
  ] = trickProperties;
  return downwardThrowVelocity * weightDistributionRatio - bearingFrictionCoefficient + stringTotalLength;
}

const spinEstimator = {
  throw(tricks) {
    if (!Array.isArray(tricks)) {
      throw new TypeError('tricks must be a list of lists');
    }
    return tricks.map((trickProperties, trickIndex) => {
      validateTrick(trickProperties, trickIndex);
      return computeSleepSeconds(trickProperties);
    });
  },
};

function findLongestSpinIndex(sleepSecondsList) {
  return sleepSecondsList.reduce(
    (bestIndex, sleepSeconds, currentIndex) =>
      sleepSeconds > sleepSecondsList[bestIndex] ? currentIndex : bestIndex,
    0
  );
}

function formatSleepReport(tricks, sleepSecondsList) {
  const reportLines = tricks.map((trickProperties, trickIndex) => {
    const describedProperties = trickProperties
      .map((propertyValue, propertyIndex) => `${propertyLabels[propertyIndex]}=${propertyValue}`)
      .join(', ');
    return `trick ${trickIndex + 1}: ${describedProperties} -> ${sleepSecondsList[trickIndex].toFixed(2)} s`;
  });
  const longestSpinIndex = findLongestSpinIndex(sleepSecondsList);
  const longestSpinSeconds = sleepSecondsList[longestSpinIndex].toFixed(2);
  reportLines.push(`longest sleeper: trick ${longestSpinIndex + 1} at ${longestSpinSeconds} s`);
  return reportLines.join('\n');
}

function main() {
  const sampleTricks = [
    [40, 5, 20, 3],
    [36, 2.5, 18, 2],
    [42, 7, 25, 1.5],
  ];
  const estimatedSleepSeconds = spinEstimator.throw(sampleTricks);
  console.log(`[${estimatedSleepSeconds.join(', ')}]`);
  console.log(formatSleepReport(sampleTricks, estimatedSleepSeconds));
}

main();

module.exports = { spinEstimator, computeSleepSeconds, formatSleepReport, findLongestSpinIndex };

