const standardAbsorptionRate = 0.15;
const idealRestingTimeMinutes = 30;
const maximumIdealTemperature = 40;
const restingPenaltyPerMinute = 0.02;
const temperaturePenaltyPerDegree = 0.05;

function normalizeBatch(rawBatch) {
  const riceVolumeCups = Number(rawBatch.volume);
  const restingTimeMinutes = Number(rawBatch.restingTime);
  const batchTemperatureCelsius = Number(rawBatch.temperature);
  if (!Number.isFinite(riceVolumeCups) || riceVolumeCups < 0) {
    throw new TypeError('Rice volume must be a non-negative number of cups');
  }
  if (!Number.isFinite(restingTimeMinutes) || restingTimeMinutes < 0) {
    throw new TypeError('Resting time must be a non-negative number of minutes');
  }
  if (!Number.isFinite(batchTemperatureCelsius)) {
    throw new TypeError('Batch temperature must be a finite number of degrees celsius');
  }
  return { riceVolumeCups, restingTimeMinutes, batchTemperatureCelsius };
}

function computeBaseSaturationIndex(riceVolumeCups) {
  return riceVolumeCups * standardAbsorptionRate;
}

function restingTimeShortfall(restingTimeMinutes) {
  return Math.max(0, idealRestingTimeMinutes - restingTimeMinutes);
}

function temperatureExcess(batchTemperatureCelsius) {
  return Math.max(0, batchTemperatureCelsius - maximumIdealTemperature);
}

function computeFinalSaturationIndex(normalizedBatch) {
  const baseSaturationIndex = computeBaseSaturationIndex(normalizedBatch.riceVolumeCups);
  const missingMinutes = restingTimeShortfall(normalizedBatch.restingTimeMinutes);
  const extraDegrees = temperatureExcess(normalizedBatch.batchTemperatureCelsius);
  const restingRetentionFactor = Math.max(0, 1 - missingMinutes * restingPenaltyPerMinute);
  const temperatureRetentionFactor = Math.max(0, 1 - extraDegrees * temperaturePenaltyPerDegree);
  return baseSaturationIndex * restingRetentionFactor * temperatureRetentionFactor;
}

function marinate(batches) {
  if (!Array.isArray(batches) || batches.length === 0) {
    throw new TypeError('At least one rice batch is required');
  }
  let bestSaturationIndex = -Infinity;
  for (const rawBatch of batches) {
    const currentIndex = computeFinalSaturationIndex(normalizeBatch(rawBatch));
    if (currentIndex > bestSaturationIndex) {
      bestSaturationIndex = currentIndex;
    }
  }
  return bestSaturationIndex;
}

function describeBatch(rawBatch) {
  const normalizedBatch = normalizeBatch(rawBatch);
  const finalIndex = computeFinalSaturationIndex(normalizedBatch);
  return `${normalizedBatch.riceVolumeCups} cups / ${normalizedBatch.restingTimeMinutes} min / `
    + `${normalizedBatch.batchTemperatureCelsius} C -> ${finalIndex.toFixed(4)}`;
}

const preparedRiceBatches = [
  { volume: 8, restingTime: 45, temperature: 22 },
  { volume: 10, restingTime: 20, temperature: 38 },
  { volume: 12, restingTime: 30, temperature: 47 },
  { volume: 9, restingTime: 35, temperature: 41 }
];

for (const riceBatch of preparedRiceBatches) {
  console.log(describeBatch(riceBatch));
}
const bestOverallIndex = marinate(preparedRiceBatches);
console.log(`Best saturation index: ${bestOverallIndex.toFixed(4)}`);

module.exports = { marinate, computeFinalSaturationIndex, describeBatch };

