const standardDryingFactor = 0.04;
const slowedDryingFactor = 0.02;
const humiditySlowdownThreshold = 70;

function selectDryingFactor(ambientHumidity) {
  return ambientHumidity > humiditySlowdownThreshold
    ? slowedDryingFactor
    : standardDryingFactor;
}

function dailyMoistureLoss(initialMoisture, ambientHumidity) {
  const dryingFactor = selectDryingFactor(ambientHumidity);
  return (initialMoisture - ambientHumidity) * dryingFactor;
}

function validateLeafPile(leafPile, pileIndex) {
  if (!Array.isArray(leafPile) || leafPile.length !== 3) {
    throw new TypeError(`leaf pile ${pileIndex} must hold moisture, humidity and duration`);
