const highIntensityFactor = 1.5;
const normalIntensityFactor = 1.2;
const longPipeThresholdMeters = 3;
const resistanceAllowance = 0.1;

function validatePipeSpec(pipeSpec, pipeIndex) {
  if (pipeSpec === null || typeof pipeSpec !== 'object') {
    throw new TypeError(`Pipe at position ${pipeIndex} is not a pipe specification`);
  }
  const { length: pipeLengthMeters, diameter: pipeDiameterCentimeters } = pipeSpec;
  if (typeof pipeLengthMeters !== 'number' || !Number.isFinite(pipeLengthMeters) || pipeLengthMeters <= 0) {
    throw new RangeError(`Pipe at position ${pipeIndex} has an invalid length`);
  }
  if (typeof pipeDiameterCentimeters !== 'number' || !Number.isFinite(pipeDiameterCentimeters) || pipeDiameterCentimeters <= 0) {
    throw new RangeError(`Pipe at position ${pipeIndex} has an invalid diameter`);
  }
  return {
    pipeLengthMeters,
    pipeDiameterCentimeters,
    needsHighIntensity: Boolean(pipeSpec.highIntensity)
  };
}

function computeBaseAirVolume(pipeLengthMeters, pipeDiameterCentimeters) {
  return pipeLengthMeters * pipeDiameterCentimeters * pipeDiameterCentimeters;
}

function acousticFactorFor(needsHighIntensity) {
  return needsHighIntensity ? highIntensityFactor : normalIntensityFactor;
}

function applyResistanceAllowance(airVolume, pipeLengthMeters) {
  if (pipeLengthMeters > longPipeThresholdMeters) {
    return airVolume * (1 + resistanceAllowance);
  }
  return airVolume;
}

function computePipeDemand(pipeSpec, pipeIndex) {
  const { pipeLengthMeters, pipeDiameterCentimeters, needsHighIntensity } = validatePipeSpec(pipeSpec, pipeIndex);
  const baseAirVolume = computeBaseAirVolume(pipeLengthMeters, pipeDiameterCentimeters);
  const tonedAirVolume = baseAirVolume * acousticFactorFor(needsHighIntensity);
  return applyResistanceAllowance(tonedAirVolume, pipeLengthMeters);
}

function regulate(pipes) {
  if (!Array.isArray(pipes)) {
    throw new TypeError('regulate expects an array of pipe specifications');
  }
  return pipes.reduce((runningTotal, pipeSpec, pipeIndex) => runningTotal + computePipeDemand(pipeSpec, pipeIndex), 0);
}

function formatDemandReport(pipes) {
  const perPipeLines = pipes.map((pipeSpec, pipeIndex) => {
    const pipeDemand = computePipeDemand(pipeSpec, pipeIndex);
    const intensityLabel = pipeSpec.highIntensity ? 'loud' : 'soft';
    return `pipe ${pipeIndex + 1}: ${pipeSpec.length} m x ${pipeSpec.diameter} cm (${intensityLabel}) -> ${pipeDemand.toFixed(2)}`;
  });
  const totalWindPressureDemand = regulate(pipes);
  perPipeLines.push(`total wind pressure demand: ${totalWindPressureDemand.toFixed(2)}`);
  return perPipeLines.join('\n');
}

function main() {
  const chordPipes = [
    { length: 2, diameter: 10, highIntensity: false },
    { length: 3.5, diameter: 8, highIntensity: true },
    { length: 4.2, diameter: 12, highIntensity: false },
    { length: 1.25, diameter: 5, highIntensity: true }
  ];
  console.log(formatDemandReport(chordPipes));
}

main();

module.exports = { regulate, computePipeDemand, formatDemandReport };

