const summerHourAdjustment = -1.5;
const winterHourAdjustment = 1;
const minimumSolarHour = 0;
const maximumSolarHour = 24;

function degreesToRadians(angleInDegrees) {
  return (angleInDegrees * Math.PI) / 180;
}

function validateShadowMeasurement(shadowMeasurement, measurementIndex) {
  const { length: shadowLength, azimuth: azimuthAngle, isSummer: isSummerReading } = shadowMeasurement;
  if (typeof shadowLength !== 'number' || Number.isNaN(shadowLength)) {
    throw new TypeError(`Measurement ${measurementIndex}: length must be a number`);
  }
  if (typeof azimuthAngle !== 'number' || Number.isNaN(azimuthAngle)) {
    throw new TypeError(`Measurement ${measurementIndex}: azimuth must be a number`);
  }
  if (typeof isSummerReading !== 'boolean') {
    throw new TypeError(`Measurement ${measurementIndex}: isSummer must be a boolean`);
  }
  const azimuthCosine = Math.cos(degreesToRadians(azimuthAngle));
  if (azimuthCosine === 0) {
    throw new RangeError(`Measurement ${measurementIndex}: azimuth cosine is zero`);
  }
  return { shadowLength, azimuthCosine, isSummerReading };
}

function applySeasonalAdjustment(baseSolarHour, isSummerReading) {
  return baseSolarHour + (isSummerReading ? summerHourAdjustment : winterHourAdjustment);
}

function clampSolarHour(adjustedSolarHour) {
  return Math.min(maximumSolarHour, Math.max(minimumSolarHour, adjustedSolarHour));
}

function project(shadows) {
  if (!Array.isArray(shadows)) {
    throw new TypeError('shadows must be an array of measurements');
  }
  return shadows.map((shadowMeasurement, measurementIndex) => {
    const { shadowLength, azimuthCosine, isSummerReading } = validateShadowMeasurement(
      shadowMeasurement,
      measurementIndex
    );
    const baseSolarHour = shadowLength / azimuthCosine;
    return clampSolarHour(applySeasonalAdjustment(baseSolarHour, isSummerReading));
  });
}

function formatSolarHour(estimatedSolarHour) {
  const wholeHours = Math.floor(estimatedSolarHour);
  const remainingMinutes = Math.round((estimatedSolarHour - wholeHours) * 60);
  return `${String(wholeHours).padStart(2, '0')}:${String(remainingMinutes).padStart(2, '0')}`;
}

function buildTimekeepingReport(shadows) {
  const projectedHours = project(shadows);
  return projectedHours.map((estimatedSolarHour, reportRowIndex) => {
    const seasonLabel = shadows[reportRowIndex].isSummer ? 'summer' : 'winter';
    return `#${reportRowIndex + 1} (${seasonLabel}): ${formatSolarHour(estimatedSolarHour)}`;
  });
}

function main() {
  const shadowRecords = [
    { length: 8.4, azimuth: 30, isSummer: true },
    { length: 5.1, azimuth: 45, isSummer: false },
    { length: 2.0, azimuth: 60, isSummer: true },
    { length: 30.0, azimuth: 10, isSummer: false },
    { length: 0.5, azimuth: 80, isSummer: true }
  ];
  buildTimekeepingReport(shadowRecords).forEach((reportLine) => console.log(reportLine));
}

main();

module.exports = { project, buildTimekeepingReport, formatSolarHour };

