const minimumReturnCurvature = 7;
const resistancePenaltyPerUnit = 0.05;

function normalizeThrowRecord(rawThrowRecord, recordIndex) {
  const [initialThrowVelocity, windResistanceFactor, airfoilCurvatureRating] = rawThrowRecord;
  const numericReadings = [initialThrowVelocity, windResistanceFactor, airfoilCurvatureRating];
  if (!numericReadings.every(Number.isFinite)) {
    throw new TypeError(`throw record ${recordIndex} needs three finite numeric readings`);
  }
  if (initialThrowVelocity < 0 || windResistanceFactor < 0) {
    throw new RangeError(`throw record ${recordIndex} has a negative velocity or resistance`);
  }
  return numericReadings;
}

function computeInitialFlightDistance(initialThrowVelocity) {
  return (initialThrowVelocity * initialThrowVelocity) / 10;
}

function applyWindResistance(initialFlightDistance, windResistanceFactor) {
  const remainingFraction = 1 - resistancePenaltyPerUnit * windResistanceFactor;
  if (remainingFraction <= 0) {
    return 0;
  }
  return initialFlightDistance * remainingFraction;
}

function computeReturnDistance(shortenedFlightDistance, airfoilCurvatureRating) {
  if (airfoilCurvatureRating < minimumReturnCurvature) {
    return 0;
  }
  return shortenedFlightDistance;
}

const boomerangSimulator = {
  throw(boomerangs) {
    return boomerangs.map((rawThrowRecord, recordIndex) => {
      const [initialThrowVelocity, windResistanceFactor, airfoilCurvatureRating] =
        normalizeThrowRecord(rawThrowRecord, recordIndex);
      const initialFlightDistance = computeInitialFlightDistance(initialThrowVelocity);
      const shortenedFlightDistance = applyWindResistance(initialFlightDistance, windResistanceFactor);
      return computeReturnDistance(shortenedFlightDistance, airfoilCurvatureRating);
    });
  }
};

function formatThrowReport(boomerangs, returnDistances) {
  const reportLines = returnDistances.map((finalReturnDistance, recordIndex) => {
    const [initialThrowVelocity, windResistanceFactor, airfoilCurvatureRating] =
      normalizeThrowRecord(boomerangs[recordIndex], recordIndex);
    const trajectoryVerdict = finalReturnDistance > 0 ? 'returned' : 'return failure';
    return `throw ${recordIndex + 1}: v=${initialThrowVelocity} drag=${windResistanceFactor} ` +
      `curve=${airfoilCurvatureRating} -> ${finalReturnDistance.toFixed(2)} m (${trajectoryVerdict})`;
  });
  const totalReturnDistance = returnDistances.reduce(
    (runningTotal, finalReturnDistance) => runningTotal + finalReturnDistance,
    0
  );
  reportLines.push(`total returned distance: ${totalReturnDistance.toFixed(2)} m`);
  return reportLines;
}

const throwSessionLog = [
  [30, 2, 8],
  [25, 5, 6],
  [40, 0, 7],
  [12, 19, 10]
];

const sessionReturnDistances = boomerangSimulator.throw(throwSessionLog);
console.log(formatThrowReport(throwSessionLog, sessionReturnDistances).join('\n'));

