const SAFE_VELOCITY_LIMIT = 15;
const DAMPENING_FACTOR = 0.8;

function computeSpringConstant(coilThickness) {
  return coilThickness * coilThickness;
}

function computeStoredEnergy(coilThickness, compressionDepth) {
  return compressionDepth * computeSpringConstant(coilThickness);
}

function computeRawRecoilVelocity(coilThickness, riderMass, compressionDepth) {
  const storedKineticEnergy = computeStoredEnergy(coilThickness, compressionDepth);
  return Math.sqrt(storedKineticEnergy / riderMass);
}

function applyDampening(rawUpwardVelocity) {
  if (rawUpwardVelocity > SAFE_VELOCITY_LIMIT) {
    return rawUpwardVelocity * DAMPENING_FACTOR;
  }
  return rawUpwardVelocity;
}

function validateSpringConfig(springConfig, configIndex) {
  if (!Array.isArray(springConfig) || springConfig.length !== 3) {
    throw new TypeError(`spring ${configIndex} must list thickness, mass and depth`);
  }
  const [coilThickness, riderMass, compressionDepth] = springConfig;
  if (springConfig.some((measuredValue) => typeof measuredValue !== 'number' || Number.isNaN(measuredValue))) {
