const SAFE_VELOCITY_LIMIT = 15;
const DAMPENING_FACTOR = 0.8;

function compute_spring_constant(coil_thickness) {
  return coil_thickness * coil_thickness;
}

function compute_stored_energy(coil_thickness, compression_depth) {
  return compression_depth * compute_spring_constant(coil_thickness);
}

function compute_raw_recoil_velocity(coil_thickness, rider_mass, compression_depth) {
  const stored_kinetic_energy = compute_stored_energy(coil_thickness, compression_depth);
  return Math.sqrt(stored_kinetic_energy / rider_mass);
}

function apply_dampening(raw_upward_velocity) {
  if (raw_upward_velocity > SAFE_VELOCITY_LIMIT) {
    return raw_upward_velocity * DAMPENING_FACTOR;
  }
  return raw_upward_velocity;
}

function validate_spring_config(spring_config, config_index) {
  if (!Array.isArray(spring_config) || spring_config.length !== 3) {
    throw new TypeError(`spring ${config_index} must list thickness, mass and depth`);
  }
  const [coil_thickness, rider_mass, compression_depth] = spring_config;
  if (spring_config.some((measured_value) => typeof measured_value !== 'number' || Number.isNaN(measured_value))) {
    throw new TypeError(`spring ${config_index} must supply numeric measurements`);
  }
  if (rider_mass <= 0) {
    throw new RangeError(`spring ${config_index} needs a positive rider mass`);
  }
  if (coil_thickness < 0 || compression_depth < 0) {
    throw new RangeError(`spring ${config_index} cannot have negative geometry`);
  }
}

function measure_final_recoil_velocity(spring_config) {
  const [coil_thickness, rider_mass, compression_depth] = spring_config;
  return apply_dampening(compute_raw_recoil_velocity(coil_thickness, rider_mass, compression_depth));
}

function bounce(springs) {
  if (!Array.isArray(springs) || springs.length === 0) {
    throw new RangeError('at least one spring configuration is required');
  }
  springs.forEach(validate_spring_config);
  return springs.reduce((best_recoil_velocity, spring_config) => {
    const final_recoil_velocity = measure_final_recoil_velocity(spring_config);
    return Math.max(best_recoil_velocity, final_recoil_velocity);
