const baseYieldPercentage = 60;
const inclusionDepthThreshold = 2;
const refractiveIndexThreshold = 2.4;
const minimumViableYield = 20;
const fractureYieldFactor = 0.5;

function validateStone(rawStone, stoneIndex) {
  const requiredNumericFields = ['caratWeight', 'inclusionDepth', 'refractiveIndex'];
  for (const fieldName of requiredNumericFields) {
    const fieldValue = rawStone[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError(`Stone ${stoneIndex}: ${fieldName} must be a number`);
    }
    if (fieldValue < 0) {
      throw new RangeError(`Stone ${stoneIndex}: ${fieldName} must not be negative`);
    }
  }
  if (typeof rawStone.hasInternalFractures !== 'boolean') {
    throw new TypeError(`Stone ${stoneIndex}: hasInternalFractures must be a boolean`);
  }
  return {
    caratWeight: rawStone.caratWeight,
    inclusionDepth: rawStone.inclusionDepth,
    refractiveIndex: rawStone.refractiveIndex,
    hasInternalFractures: rawStone.hasInternalFractures
  };
}

function computeStoneYield(validatedStone) {
  let currentYield = baseYieldPercentage;
  if (validatedStone.inclusionDepth > inclusionDepthThreshold) {
    currentYield -= 5;
  }
  if (validatedStone.refractiveIndex > refractiveIndexThreshold) {
    currentYield += 10;
  }
  if (validatedStone.hasInternalFractures) {
    currentYield *= fractureYieldFactor;
  }
  return currentYield < minimumViableYield ? 0 : currentYield;
}

function analyze(stones) {
  if (!Array.isArray(stones)) {
    throw new TypeError('analyze expects an array of stones');
  }
  return stones.map((rawStone, stoneIndex) => computeStoneYield(validateStone(rawStone, stoneIndex)));
}

function formatYieldReport(stones, yieldPercentages) {
  const reportLines = yieldPercentages.map((yieldPercentage, stoneIndex) => {
    const describedStone = stones[stoneIndex];
    const fractureLabel = describedStone.hasInternalFractures ? 'fractured' : 'sound';
    const weightLabel = describedStone.caratWeight.toFixed(2);
    const verdictLabel = yieldPercentage === 0 ? 'REJECT' : `${yieldPercentage.toFixed(1)}%`;
    return `#${stoneIndex + 1} ${weightLabel}ct (${fractureLabel}) -> ${verdictLabel}`;
  });
  const cuttableStones = yieldPercentages.filter((yieldPercentage) => yieldPercentage > 0);
  const averageCuttableYield = cuttableStones.length
    ? cuttableStones.reduce((runningTotal, yieldPercentage) => runningTotal + yieldPercentage, 0) / cuttableStones.length
    : 0;
  reportLines.push(`Cuttable: ${cuttableStones.length}/${yieldPercentages.length}, average yield ${averageCuttableYield.toFixed(1)}%`);
  return reportLines.join('\n');
}

function main() {
  const parcelOfStones = [
    { caratWeight: 2, inclusionDepth: 1, refractiveIndex: 2.5, hasInternalFractures: false },
