const monthsUntilFullRegrowth = 12;
const ageThinningThreshold = 10;
const baseYieldMultiplier = 50;
const longRegrowthBonusRate = 0.1;
const ageThinningRate = 0.15;

function validateAlpacaRecord(alpacaRecord, herdIndex) {
  const requiredFields = [
    'ageInYears',
    'monthsSinceLastShearing',
    'fleeceDensityScore',
    'animalWeightKg'
  ];
  requiredFields.forEach(function (fieldName) {
    const fieldValue = alpacaRecord[fieldName];
    if (typeof fieldValue !== 'number' || !Number.isFinite(fieldValue) || fieldValue < 0) {
      throw new TypeError(
        'Alpaca at index ' + herdIndex + ' has an invalid ' + fieldName + ': ' + fieldValue
      );
    }
  });
}

function calculateExpectedYield(alpacaRecord) {
  let expectedYield =
    alpacaRecord.animalWeightKg * alpacaRecord.fleeceDensityScore * baseYieldMultiplier;
  if (alpacaRecord.monthsSinceLastShearing > monthsUntilFullRegrowth) {
    expectedYield += expectedYield * longRegrowthBonusRate;
  }
  if (alpacaRecord.ageInYears > ageThinningThreshold) {
    expectedYield -= expectedYield * ageThinningRate;
  }
  return Math.round(expectedYield);
}

function shear(herd) {
  if (!Array.isArray(herd)) {
    throw new TypeError('The herd must be provided as an array of alpaca records.');
  }
  return herd.map(function (alpacaRecord, herdIndex) {
    validateAlpacaRecord(alpacaRecord, herdIndex);
    return calculateExpectedYield(alpacaRecord);
  });
}

function formatYieldReport(herd, expectedYields) {
  const reportLines = herd.map(function (alpacaRecord, herdIndex) {
    const animalLabel = alpacaRecord.animalName || 'Alpaca #' + (herdIndex + 1);
    return (
      animalLabel +
      ': ' +
      expectedYields[herdIndex] +
      ' g (age ' +
      alpacaRecord.ageInYears +
      ', ' +
      alpacaRecord.monthsSinceLastShearing +
      ' months of regrowth)'
    );
  });
  const totalHerdYield = expectedYields.reduce(function (runningTotal, singleYield) {
    return runningTotal + singleYield;
  }, 0);
  reportLines.push('Total herd yield: ' + totalHerdYield + ' g');
  return reportLines.join('\n');
}

const sampleHerd = [
  { animalName: 'Pepita', ageInYears: 5, monthsSinceLastShearing: 14, fleeceDensityScore: 3, animalWeightKg: 60 },
  { animalName: 'Bruno', ageInYears: 12, monthsSinceLastShearing: 10, fleeceDensityScore: 2.5, animalWeightKg: 72 },
  { animalName: 'Lira', ageInYears: 11, monthsSinceLastShearing: 18, fleeceDensityScore: 4, animalWeightKg: 55 }
];

const sampleYields = shear(sampleHerd);
console.log(formatYieldReport(sampleHerd, sampleYields));

module.exports = { shear, calculateExpectedYield, formatYieldReport };

