function validateDogRecord(dogRecord, recordIndex) {
  const requiredFields = ['energyLevel', 'terrainDifficulty', 'ambientTemperature', 'trufflesFound'];
  for (const fieldName of requiredFields) {
    const fieldValue = dogRecord[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError(`Dog #${recordIndex}: "${fieldName}" must be a number`);
    }
  }
  if (dogRecord.energyLevel < 0 || dogRecord.energyLevel > 100) {
    throw new RangeError(`Dog #${recordIndex}: energy level must be within 0..100`);
  }
  if (dogRecord.terrainDifficulty < 1 || dogRecord.terrainDifficulty > 10) {
    throw new RangeError(`Dog #${recordIndex}: terrain difficulty must be within 1..10`);
  }
  if (dogRecord.trufflesFound < 0) {
    throw new RangeError(`Dog #${recordIndex}: truffles found cannot be negative`);
  }
}

function remainingSearchTime(dogRecord) {
  const energyContribution = dogRecord.energyLevel * 3;
  const terrainPenalty = dogRecord.terrainDifficulty * 5;
  const heatPenalty = dogRecord.ambientTemperature > 25 ? 20 : 0;
  const excitementBoost = dogRecord.trufflesFound * 10;
  const searchMinutes = energyContribution - terrainPenalty - heatPenalty + excitementBoost;
  return searchMinutes < 0 ? 0 : searchMinutes;
}

function evaluate(dogs) {
  if (!Array.isArray(dogs)) {
    throw new TypeError('evaluate expects an array of dog records');
  }
  return dogs.map((dogRecord, recordIndex) => {
    validateDogRecord(dogRecord, recordIndex);
    return remainingSearchTime(dogRecord);
  });
}

function formatMinutes(totalMinutes) {
  const wholeHours = Math.floor(totalMinutes / 60);
  const leftoverMinutes = totalMinutes % 60;
  if (wholeHours === 0) {
    return `${leftoverMinutes} min`;
  }
  return `${wholeHours} h ${leftoverMinutes} min`;
}

function buildEvaluationReport(dogs) {
  const searchTimes = evaluate(dogs);
  const reportLines = dogs.map((dogRecord, recordIndex) => {
    const dogLabel = dogRecord.dogName || `dog-${recordIndex}`;
    return `${dogLabel.padEnd(10)} ${formatMinutes(searchTimes[recordIndex]).padStart(10)}`;
  });
  const totalSearchTime = searchTimes.reduce((runningTotal, dogTime) => runningTotal + dogTime, 0);
  const averageSearchTime = searchTimes.length === 0 ? 0 : Math.round(totalSearchTime / searchTimes.length);
  reportLines.push(`pack average: ${formatMinutes(averageSearchTime)}`);
  return reportLines.join('\n');
}

const huntingPack = [
  { dogName: 'Bruno', energyLevel: 50, terrainDifficulty: 5, ambientTemperature: 30, trufflesFound: 3 },
  { dogName: 'Luna', energyLevel: 90, terrainDifficulty: 2, ambientTemperature: 18, trufflesFound: 0 },
