  { dogName: 'Stella', energyLevel: 70, terrainDifficulty: 8, ambientTemperature: 26, trufflesFound: 5 },
];

console.log(evaluate(huntingPack).join(', '));
console.log(buildEvaluationReport(huntingPack));

module.exports = { evaluate, remainingSearchTime, formatMinutes, buildEvaluationReport };

