  const isCoated = inkSample.paperCoating;
  if (!Number.isFinite(viscosityScore) || viscosityScore <= 0) {
    throw new RangeError(`sample ${sampleIndex} has an invalid ink viscosity score`);
  }
  if (!Number.isFinite(nibWidth) || nibWidth < 0) {
    throw new RangeError(`sample ${sampleIndex} has an invalid nib width`);
  }
  if (!Number.isFinite(paperWeight) || paperWeight < 0) {
    throw new RangeError(`sample ${sampleIndex} has an invalid paper weight`);
  }
  if (typeof isCoated !== 'boolean') {
    throw new TypeError(`sample ${sampleIndex} has a non-boolean paper coating flag`);
  }
  return { viscosityScore, nibWidth, paperWeight, isCoated };
}

function computeSeverityIndex(checkedSample) {
  const scaledNibWidth = checkedSample.nibWidth * 10;
  const paperResistance = checkedSample.paperWeight / 50;
  let severityIndex = scaledNibWidth / checkedSample.viscosityScore - paperResistance;
  if (checkedSample.isCoated) {
    severityIndex -= 2;
  }
  return severityIndex < 0 ? 0 : severityIndex;
}

function assess(inks) {
  if (!Array.isArray(inks)) {
    throw new TypeError('assess expects an array of ink samples');
  }
  return inks.map((inkSample, sampleIndex) => computeSeverityIndex(validateInkSample(inkSample, sampleIndex)));
}

function classifySeverity(severityIndex) {
  if (severityIndex === 0) {
    return 'clean';
  }
  if (severityIndex < 3) {
    return 'slight feathering';
  }
  if (severityIndex < 6) {
    return 'noticeable bleed';
  }
  return 'severe bleed';
}

function formatAssessmentReport(inks, severityIndices) {
  const reportLines = severityIndices.map((severityIndex, sampleIndex) => {
    const currentSample = inks[sampleIndex];
    const coatingLabel = currentSample.paperCoating ? 'coated' : 'uncoated';
    const roundedIndex = severityIndex.toFixed(2);
    const severityLabel = classifySeverity(severityIndex);
    return `#${sampleIndex + 1} ${coatingLabel} ${currentSample.paperWeightGrams}gsm -> ${roundedIndex} (${severityLabel})`;
  });
  const worstSeverity = severityIndices.reduce((highestSoFar, candidate) => Math.max(highestSoFar, candidate), 0);
  reportLines.push(`worst severity index: ${worstSeverity.toFixed(2)}`);
  return reportLines.join('\n');
}

