const minimumRechargePeriod = 30;

function validateObservation(geyserObservation, observationIndex) {
  const requiredFields = [
    'previousEruptionDuration',
    'undergroundChamberVolume',
    'geothermalHeatIndex',
    'currentWaterInflowRate'
  ];
  requiredFields.forEach(function (fieldName) {
    const fieldValue = geyserObservation[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError(
        'Observation ' + observationIndex + ' has an invalid ' + fieldName
      );
    }
  });
  if (geyserObservation.currentWaterInflowRate <= 0) {
    throw new RangeError(
      'Observation ' + observationIndex + ' must have a positive inflow rate'
    );
  }
}

function estimateEruptionInterval(geyserObservation) {
  const eruptionContribution = geyserObservation.previousEruptionDuration * 4;
  const rechargeContribution =
    geyserObservation.undergroundChamberVolume /
    geyserObservation.currentWaterInflowRate;
  const heatPenalty = geyserObservation.geothermalHeatIndex * 2;
  const rawInterval = eruptionContribution + rechargeContribution - heatPenalty;
  return rawInterval < minimumRechargePeriod ? minimumRechargePeriod : rawInterval;
}

function forecast(geysers) {
  if (!Array.isArray(geysers)) {
    throw new TypeError('forecast expects a list of geyser observations');
  }
  return geysers.map(function (geyserObservation, observationIndex) {
    validateObservation(geyserObservation, observationIndex);
    return estimateEruptionInterval(geyserObservation);
  });
}

function formatForecastReport(geysers, estimatedIntervals) {
  const reportLines = estimatedIntervals.map(function (intervalMinutes, geyserIndex) {
    const observedGeyser = geysers[geyserIndex];
    const geyserLabel = observedGeyser.geyserName || 'geyser #' + (geyserIndex + 1);
    const roundedInterval = Math.round(intervalMinutes * 10) / 10;
    const clampedNote = intervalMinutes === minimumRechargePeriod ? ' (minimum recharge)' : '';
    return geyserLabel + ': ' + roundedInterval + ' min' + clampedNote;
  });
  const longestWait = estimatedIntervals.reduce(function (currentMax, intervalMinutes) {
    return intervalMinutes > currentMax ? intervalMinutes : currentMax;
  }, 0);
  reportLines.push('Longest wait: ' + Math.round(longestWait * 10) / 10 + ' min');
  return reportLines.join('\n');
}

function main() {
  const observedGeysers = [
    {
      geyserName: 'Old Faithful',
      previousEruptionDuration: 10,
      undergroundChamberVolume: 500,
      geothermalHeatIndex: 5,
      currentWaterInflowRate: 10
    },
    {
      geyserName: 'Steamboat',
      previousEruptionDuration: 2,
      undergroundChamberVolume: 120,
      geothermalHeatIndex: 40,
      currentWaterInflowRate: 8
    },
    {
      geyserName: 'Strokkur',
      previousEruptionDuration: 4,
      undergroundChamberVolume: 300,
      geothermalHeatIndex: 12,
      currentWaterInflowRate: 15
    }
  ];
  const forecastIntervals = forecast(observedGeysers);
  console.log(formatForecastReport(observedGeysers, forecastIntervals));
}

main();

module.exports = { forecast, estimateEruptionInterval, formatForecastReport };

