const BASE_SEQUESTRATION_RATE = 3.5;
const HIGH_RAINFALL_THRESHOLD = 1000;
const HIGH_RAINFALL_MULTIPLIER = 1.15;
const RESTORATION_BONUS_TONS = 50;

function validateBog(bogRegion, regionIndex) {
  const requiredNumericFields = ['surfaceArea', 'averagePeatDepth', 'annualRainfall'];
  for (const fieldName of requiredNumericFields) {
    const fieldValue = bogRegion[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue) || fieldValue < 0) {
      throw new TypeError(`Region ${regionIndex}: ${fieldName} must be a non-negative number`);
    }
  }
  if (typeof bogRegion.activeRestoration !== 'boolean') {
    throw new TypeError(`Region ${regionIndex}: activeRestoration must be a boolean`);
  }
}

function sequesteredTonsFor(bogRegion) {
  const peatVolumeFactor = bogRegion.surfaceArea * bogRegion.averagePeatDepth;
  let carbonTons = peatVolumeFactor * BASE_SEQUESTRATION_RATE;
  if (bogRegion.annualRainfall > HIGH_RAINFALL_THRESHOLD) {
    carbonTons *= HIGH_RAINFALL_MULTIPLIER;
  }
  if (bogRegion.activeRestoration) {
    carbonTons += RESTORATION_BONUS_TONS;
  }
  return carbonTons;
}

function estimate(bogs) {
  if (!Array.isArray(bogs)) {
    throw new TypeError('estimate expects an array of peat bog regions');
  }
  return bogs.map((bogRegion, regionIndex) => {
    validateBog(bogRegion, regionIndex);
    return sequesteredTonsFor(bogRegion);
  });
}

function summarize(bogs) {
  const carbonTonsPerRegion = estimate(bogs);
  const totalCarbonTons = carbonTonsPerRegion.reduce((runningTotal, tons) => runningTotal + tons, 0);
  const restoredRegionCount = bogs.filter((bogRegion) => bogRegion.activeRestoration).length;
  return { carbonTonsPerRegion, totalCarbonTons, restoredRegionCount };
}

function formatReport(bogs) {
  const { carbonTonsPerRegion, totalCarbonTons, restoredRegionCount } = summarize(bogs);
  const regionLines = bogs.map((bogRegion, regionIndex) => {
    const regionLabel = bogRegion.regionName || `region ${regionIndex + 1}`;
    const roundedTons = carbonTonsPerRegion[regionIndex].toFixed(1);
    const restorationNote = bogRegion.activeRestoration ? ' (under restoration)' : '';
    return `${regionLabel}: ${roundedTons} tons/year${restorationNote}`;
  });
  const summaryLine = `total: ${totalCarbonTons.toFixed(1)} tons/year across ` +
    `${bogs.length} regions, ${restoredRegionCount} under restoration`;
  return regionLines.concat(summaryLine).join('\n');
}

const surveyedBogRegions = [
  { regionName: 'Flanders Moss', surfaceArea: 10, averagePeatDepth: 2, annualRainfall: 1200, activeRestoration: true },
  { regionName: 'Border Mires', surfaceArea: 45, averagePeatDepth: 1.5, annualRainfall: 850, activeRestoration: false },
  { regionName: 'Cors Caron', surfaceArea: 120, averagePeatDepth: 3.2, annualRainfall: 1400, activeRestoration: false },
  { regionName: 'Thorne Moors', surfaceArea: 75, averagePeatDepth: 0.8, annualRainfall: 620, activeRestoration: true },
];

console.log(formatReport(surveyedBogRegions));

module.exports = { estimate, summarize, formatReport };

