const fineGrainThreshold = 0.5;
const fineSandMultiplier = 1.3;
const vegetationDragFactor = 0.2;

function validateDune(duneRecord, recordIndex) {
  const requiredFields = ['crestHeight', 'averageWindSpeed', 'sandGrainSize', 'vegetationCover'];
  requiredFields.forEach(function (fieldName) {
    const fieldValue = duneRecord[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError('Dune ' + recordIndex + ': ' + fieldName + ' must be a number');
    }
  });
  if (duneRecord.crestHeight <= 0) {
    throw new RangeError('Dune ' + recordIndex + ': crestHeight must be greater than zero');
  }
  if (duneRecord.vegetationCover < 0 || duneRecord.vegetationCover > 100) {
    throw new RangeError('Dune ' + recordIndex + ': vegetationCover must be a percentage');
  }
}

function migrationDistanceFor(duneRecord) {
  const windSpeedSquared = duneRecord.averageWindSpeed * duneRecord.averageWindSpeed;
  let migrationDistance = windSpeedSquared / duneRecord.crestHeight;
  if (duneRecord.sandGrainSize < fineGrainThreshold) {
    migrationDistance *= fineSandMultiplier;
  }
  migrationDistance -= duneRecord.vegetationCover * vegetationDragFactor;
  return migrationDistance < 0 ? 0 : migrationDistance;
}

function calculate(dunes) {
  if (!Array.isArray(dunes)) {
    throw new TypeError('calculate expects a list of dunes');
  }
  return dunes.map(function (duneRecord, recordIndex) {
    validateDune(duneRecord, recordIndex);
    return migrationDistanceFor(duneRecord);
  });
}

function classifyMobility(migrationDistance) {
  if (migrationDistance === 0) {
    return 'stable';
  }
  if (migrationDistance < 10) {
    return 'slow';
  }
  if (migrationDistance < 60) {
    return 'moderate';
  }
  return 'highly mobile';
}

function buildMigrationReport(dunes) {
  const distanceList = calculate(dunes);
  const reportLines = distanceList.map(function (migrationDistance, duneIndex) {
    const duneLabel = dunes[duneIndex].duneName || 'dune ' + (duneIndex + 1);
    const roundedDistance = migrationDistance.toFixed(1);
    const mobilityClass = classifyMobility(migrationDistance);
    return duneLabel + ': ' + roundedDistance + ' m/year (' + mobilityClass + ')';
  });
  const totalDistance = distanceList.reduce(function (runningSum, distance) {
    return runningSum + distance;
  }, 0);
  const averageDistance = distanceList.length === 0 ? 0 : totalDistance / distanceList.length;
  reportLines.push('average migration: ' + averageDistance.toFixed(1) + ' m/year');
  return reportLines.join('\n');
}

const surveyedDunes = [
  { duneName: 'Crescent Ridge', crestHeight: 10, averageWindSpeed: 20, sandGrainSize: 0.4, vegetationCover: 10 },
  { duneName: 'Star Dune', crestHeight: 45, averageWindSpeed: 18, sandGrainSize: 0.8, vegetationCover: 35 },
  { duneName: 'Coastal Foredune', crestHeight: 6, averageWindSpeed: 12, sandGrainSize: 0.3, vegetationCover: 95 }
];

console.log(calculate(surveyedDunes).join(', '));
console.log(buildMigrationReport(surveyedDunes));

