const maximumDripRate = 100;

const requiredFormationFields = [
  'surfaceDripPoolVolume',
  'limestonePorosityScore',
  'caveHumidityPercentage',
  'seasonalRainfallMillimeters'
];

function validateFormation(candidateFormation, formationIndex) {
  if (candidateFormation === null || typeof candidateFormation !== 'object') {
    throw new TypeError(`Formation at index ${formationIndex} is not an object`);
  }
  requiredFormationFields.forEach((fieldName) => {
    const fieldValue = candidateFormation[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError(`Formation at index ${formationIndex} has an invalid ${fieldName}`);
    }
  });
}

function computeDripRate(singleFormation) {
  const poolPorosityProduct =
    singleFormation.surfaceDripPoolVolume * singleFormation.limestonePorosityScore;
  const rainfallContribution = singleFormation.seasonalRainfallMillimeters / rainfallDivisor;
  let predictedDripRate = poolPorosityProduct + rainfallContribution;
  if (singleFormation.caveHumidityPercentage > humidityEvaporationThreshold) {
    predictedDripRate -= lowEvaporationPenalty;
  }
  return Math.min(predictedDripRate, maximumDripRate);
}

function analyze(formations) {
  if (!Array.isArray(formations)) {
    throw new TypeError('analyze expects an array of formations');
  }
  return formations.map((currentFormation, currentIndex) => {
