const degreesToRadians = (angleInDegrees) => (angleInDegrees * Math.PI) / 180;

const readingFields = [
  'upperCanopyDensityPercent',
  'midLayerLeafAreaIndex',
  'sunAngleDegrees',
  'cloudCoverPercent',
];

function validatePlotReading(plotReading, plotIndex) {
  readingFields.forEach((fieldName) => {
    const fieldValue = plotReading[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError(`Plot ${plotIndex}: "${fieldName}" must be a number`);
    }
  });
}

function computeFloorIntensity(plotReading) {
  const canopyRemainder = 100 - plotReading.upperCanopyDensityPercent;
  const afterMidLayer = canopyRemainder - plotReading.midLayerLeafAreaIndex * 5;
  const sunAngleFactor = Math.sin(degreesToRadians(plotReading.sunAngleDegrees));
  const angleAdjusted = afterMidLayer * sunAngleFactor;
  const cloudPenalty = plotReading.cloudCoverPercent / 2;
  const floorIntensity = angleAdjusted - cloudPenalty;
  return floorIntensity < 0 ? 0 : floorIntensity;
}

function assess(plots) {
  return plots.map((plotReading, plotIndex) => {
    validatePlotReading(plotReading, plotIndex);
    return computeFloorIntensity(plotReading);
  });
}

function describeLightLevel(intensityPercent) {
  if (intensityPercent === 0) return 'dark floor';
  if (intensityPercent < 10) return 'deep shade';
  if (intensityPercent < 25) return 'dappled shade';
  return 'bright floor';
}

function buildAssessmentReport(plots) {
  const intensityList = assess(plots);
  const reportLines = intensityList.map((intensityPercent, plotIndex) => {
    const plotLabel = plots[plotIndex].plotName || `plot-${plotIndex + 1}`;
    const lightDescription = describeLightLevel(intensityPercent);
    return `${plotLabel}: ${intensityPercent.toFixed(1)}% (${lightDescription})`;
  });
  const totalIntensity = intensityList.reduce((runningSum, value) => runningSum + value, 0);
  const averageIntensity = intensityList.length ? totalIntensity / intensityList.length : 0;
  reportLines.push(`average: ${averageIntensity.toFixed(1)}%`);
  return reportLines.join('\n');
}

function main() {
  const surveyedPlots = [
    {
      plotName: 'ridge-oak',
      upperCanopyDensityPercent: 40,
      midLayerLeafAreaIndex: 4,
      sunAngleDegrees: 90,
