const nitrogenRainfallDivisor = 20;
const sunlightGrowthFactor = 1.5;
const matureHeightThreshold = 1000;
const maturePenaltyFactor = 0.5;

const requiredStalkFields = [
  'currentStalkHeight',
  'soilNitrogenLevel',
  'dailyRainfall',
  'sunlightExposure'
];

function validateStalk(candidateStalk, stalkIndex) {
  if (candidateStalk === null || typeof candidateStalk !== 'object') {
    throw new TypeError(`stalk at index ${stalkIndex} is not an object`);
  }
  requiredStalkFields.forEach(function (fieldName) {
    const fieldValue = candidateStalk[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError(`stalk at index ${stalkIndex} has invalid ${fieldName}`);
    }
    if (fieldValue < 0) {
      throw new RangeError(`stalk at index ${stalkIndex} has negative ${fieldName}`);
    }
  });
}

function computeDailyGrowth(singleStalk) {
  const nitrogenContribution =
    (singleStalk.soilNitrogenLevel * singleStalk.dailyRainfall) / nitrogenRainfallDivisor;
  const sunlightContribution = singleStalk.sunlightExposure * sunlightGrowthFactor;
  const combinedGrowth = nitrogenContribution + sunlightContribution;
  if (singleStalk.currentStalkHeight > matureHeightThreshold) {
    return combinedGrowth * maturePenaltyFactor;
  }
  return combinedGrowth;
}

function track(stalks) {
  if (!Array.isArray(stalks)) {
    throw new TypeError('stalks must be an array');
  }
  return stalks.map(function (eachStalk, stalkIndex) {
    validateStalk(eachStalk, stalkIndex);
    return computeDailyGrowth(eachStalk);
  });
}

function formatGrowthLine(stalkLabel, growthInCentimetres) {
  const roundedGrowth = Math.round(growthInCentimetres * 100) / 100;
  return `${stalkLabel}: ${roundedGrowth} cm/day`;
}

function buildGrowthReport(stalks) {
