const MASS_MULTIPLIER = 50;
const TEMPERATURE_FACTOR = 1.2;
const MINIMUM_DIGESTION_HOURS = 24;

function validateTrapEntry(trapEntry, entryIndex) {
  const requiredFields = ['insectMass', 'trapSize', 'ambientTemperature', 'enzymeConcentration'];
  for (const fieldName of requiredFields) {
    const fieldValue = trapEntry[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError(`Trap ${entryIndex}: "${fieldName}" must be a number`);
    }
  }
  if (trapEntry.trapSize <= 0) {
    throw new RangeError(`Trap ${entryIndex}: trap size must be greater than zero`);
  }
  if (trapEntry.enzymeConcentration <= 0) {
    throw new RangeError(`Trap ${entryIndex}: enzyme concentration must be greater than zero`);
  }
}

function computeDigestionTime(trapEntry) {
  const massWorkload = trapEntry.insectMass * MASS_MULTIPLIER;
  const sizeAdjustedTime = massWorkload / trapEntry.trapSize;
  const temperatureBonus = trapEntry.ambientTemperature * TEMPERATURE_FACTOR;
  const enzymeAdjustedTime = (sizeAdjustedTime - temperatureBonus) / trapEntry.enzymeConcentration;
  return Math.max(enzymeAdjustedTime, MINIMUM_DIGESTION_HOURS);
}

function estimate(traps) {
  if (!Array.isArray(traps)) {
    throw new TypeError('estimate expects an array of trap descriptions');
  }
  return traps.map((trapEntry, entryIndex) => {
    validateTrapEntry(trapEntry, entryIndex);
    return computeDigestionTime(trapEntry);
  });
}

function formatDigestionHours(digestionHours) {
  const roundedHours = Math.round(digestionHours * 100) / 100;
  return `${roundedHours} h`;
}

function buildDigestionReport(traps) {
  const digestionTimes = estimate(traps);
  return digestionTimes.map((digestionHours, entryIndex) => {
    const trapEntry = traps[entryIndex];
    const minimumWasEnforced = digestionHours === MINIMUM_DIGESTION_HOURS;
    const enforcementNote = minimumWasEnforced ? ' (minimum enforced)' : '';
    return `${trapEntry.insectMass} g in a ${trapEntry.trapSize} cm trap: `
      + `${formatDigestionHours(digestionHours)}${enforcementNote}`;
  });
}

function main() {
  const trapSamples = [
    { insectMass: 5, trapSize: 5, ambientTemperature: 20, enzymeConcentration: 1 },
    { insectMass: 2, trapSize: 8, ambientTemperature: 25, enzymeConcentration: 1.5 },
    { insectMass: 12, trapSize: 4, ambientTemperature: 18, enzymeConcentration: 2 }
  ];
  const reportLines = buildDigestionReport(trapSamples);
  for (const reportLine of reportLines) {
    console.log(reportLine);
  }
  const totalDigestionHours = estimate(trapSamples).reduce((runningTotal, hours) => runningTotal + hours, 0);
  console.log(`Total digestion time: ${formatDigestionHours(totalDigestionHours)}`);
}

main();

module.exports = { estimate, computeDigestionTime, buildDigestionReport, formatDigestionHours };

