function computeRestingEnergyBurned(bodyMassKilograms, hoursSleptToday) {
  return bodyMassKilograms * hoursSleptToday * 5;
}

function computeActiveEnergyBurned(hoursSleptToday, heartRateAverage) {
  return ((24 - hoursSleptToday) * heartRateAverage) / 2;
}

function validateSlothRecord(slothRecord, recordIndex) {
  const requiredFieldNames = ['bodyMass', 'hoursSlept', 'leavesConsumed', 'average_heart_rate'];
  requiredFieldNames.forEach(function (fieldName) {
    const fieldValue = slothRecord[fieldName];
    if (typeof fieldValue !== 'number' || Number.isNaN(fieldValue)) {
      throw new TypeError('Sloth ' + recordIndex + ' has an invalid ' + fieldName);
    }
  });
  if (slothRecord.hoursSlept < 0 || slothRecord.hoursSlept > 24) {
    throw new RangeError('Sloth ' + recordIndex + ' slept an impossible number of hours');
  }
