  return sloths.map(function (currentSloth, slothIndex) {
    validateSlothRecord(currentSloth, slothIndex);
    const caloricIntake = computeCaloricIntake(currentSloth.leavesConsumed);
    const restingEnergyBurned = computeRestingEnergyBurned(currentSloth.bodyMass, currentSloth.hoursSlept);
    const activeEnergyBurned = computeActiveEnergyBurned(currentSloth.hoursSlept, currentSloth.average_heart_rate);
    return caloricIntake - restingEnergyBurned - activeEnergyBurned;
