const highFrictionThreshold = 0.8;
const highFrictionMultiplier = 1.2;

function validateSegment(rawSegment, segmentIndex) {
  if (!Array.isArray(rawSegment) || rawSegment.length !== 3) {
    throw new TypeError(`segment ${segmentIndex} must be [length, hours, friction]`);
  }
  const [segmentLength, usageHours, frictionCoefficient] = rawSegment;
  if (![segmentLength, usageHours, frictionCoefficient].every(Number.isFinite)) {
    throw new TypeError(`segment ${segmentIndex} contains a non-numeric field`);
  }
  if (segmentLength < 0 || usageHours < 0) {
    throw new RangeError(`segment ${segmentIndex} has negative length or usage`);
  }
  return [segmentLength, usageHours, frictionCoefficient];
}

function hasFrictionPenalty(frictionCoefficient) {
  return frictionCoefficient > highFrictionThreshold;
}

function computeSegmentWear(rawSegment, segmentIndex) {
  const [segmentLength, usageHours, frictionCoefficient] = validateSegment(rawSegment, segmentIndex);
  const baseTrackWear = segmentLength * usageHours;
  return hasFrictionPenalty(frictionCoefficient) ? baseTrackWear * highFrictionMultiplier : baseTrackWear;
}

function assess(segments) {
  if (!Array.isArray(segments)) {
    throw new TypeError('segments must be an array of track segments');
  }
  return segments.reduce(
    (runningWearTotal, rawSegment, segmentIndex) => runningWearTotal + computeSegmentWear(rawSegment, segmentIndex),
    0,
  );
}

function formatSegmentLine(rawSegment, segmentIndex) {
  const [segmentLength, usageHours, frictionCoefficient] = validateSegment(rawSegment, segmentIndex);
  const baseTrackWear = segmentLength * usageHours;
  const adjustedTrackWear = computeSegmentWear(rawSegment, segmentIndex);
  const penaltyMarker = hasFrictionPenalty(frictionCoefficient) ? ' (+20% friction)' : '';
  return `S${segmentIndex + 1}: ${usageHours}h base ${baseTrackWear.toFixed(1)} -> ${adjustedTrackWear.toFixed(1)}${penaltyMarker}`;
}

function buildWearReport(segments) {
  const reportLines = segments.map(formatSegmentLine);
  const penalisedSegmentCount = segments.filter((rawSegment) => hasFrictionPenalty(rawSegment[2])).length;
  const totalSystemWear = assess(segments);
  reportLines.push(`penalised segments: ${penalisedSegmentCount}/${segments.length}`);
  reportLines.push(`total system wear: ${totalSystemWear.toFixed(1)}`);
  return reportLines.join('\n');
}

function main() {
  const networkSegments = [
    [10, 100, 0.5],
    [5, 200, 0.9],
    [12.5, 80, 0.81],
  ];
  console.log(buildWearReport(networkSegments));
  const exampleTotalWear = assess([[10, 100, 0.5], [5, 200, 0.9]]);
  console.log(`example total: ${exampleTotalWear}`);
}

main();

module.exports = { assess, computeSegmentWear, hasFrictionPenalty, buildWearReport };

