const noiseAmplitudeThreshold = 10;

function validatePulseRecord(pulseRecord, recordIndex) {
  if (!Array.isArray(pulseRecord) || pulseRecord.length < 3) {
    throw new TypeError(`pulse ${recordIndex} must hold an amplitude, a duration and a muscle index`);
  }
  const [pulseAmplitude, pulseDurationMs, targetMuscleIndex] = pulseRecord;
  if (!Number.isFinite(pulseAmplitude) || !Number.isFinite(pulseDurationMs)) {
    throw new TypeError(`pulse ${recordIndex} has a non-numeric amplitude or duration`);
  }
  if (!Number.isInteger(targetMuscleIndex) || targetMuscleIndex < 0) {
    throw new RangeError(`pulse ${recordIndex} targets an invalid muscle`);
  }
  return { pulseAmplitude, pulseDurationMs, targetMuscleIndex };
}

function isAboveNoiseFloor(pulseAmplitude) {
  return pulseAmplitude >= noiseAmplitudeThreshold;
}

function computeActivationEnergy(pulseAmplitude, pulseDurationMs) {
  return pulseAmplitude * pulseDurationMs;
}

function process(signals) {
  if (!Array.isArray(signals)) {
    throw new TypeError('the pulse batch must be a list');
  }
  const energyByMuscleIndex = new Map();
  let highestMuscleIndex = -1;
  signals.forEach((pulseRecord, recordIndex) => {
    const { pulseAmplitude, pulseDurationMs, targetMuscleIndex } = validatePulseRecord(pulseRecord, recordIndex);
    if (!isAboveNoiseFloor(pulseAmplitude)) {
      return;
    }
    const activationEnergy = computeActivationEnergy(pulseAmplitude, pulseDurationMs);
    const previousEnergy = energyByMuscleIndex.get(targetMuscleIndex) || 0;
    energyByMuscleIndex.set(targetMuscleIndex, previousEnergy + activationEnergy);
    if (targetMuscleIndex > highestMuscleIndex) {
      highestMuscleIndex = targetMuscleIndex;
    }
  });
  const orderedEnergies = [];
  for (let muscleIndex = 0; muscleIndex <= highestMuscleIndex; muscleIndex += 1) {
    orderedEnergies.push(energyByMuscleIndex.get(muscleIndex) || 0);
  }
  return orderedEnergies;
}

function formatActivationReport(activationEnergies) {
  if (activationEnergies.length === 0) {
    return 'no muscle activation detected';
  }
  const reportLines = activationEnergies.map((totalEnergy, muscleIndex) => {
    const energyLabel = totalEnergy === 0 ? 'idle' : `${totalEnergy} units`;
    return `muscle ${muscleIndex}: ${energyLabel}`;
  });
  const cumulativeEnergy = activationEnergies.reduce((runningTotal, value) => runningTotal + value, 0);
  reportLines.push(`total: ${cumulativeEnergy} units`);
  return reportLines.join('\n');
}

function main() {
  const incomingPulseBatch = [[12, 5, 0], [8, 10, 1], [15, 2, 0]];
  const flexorSweepBatch = [[20, 3, 2], [9, 40, 0], [11, 6, 0], [30, 1, 2]];
  [incomingPulseBatch, flexorSweepBatch].forEach((pulseBatch, batchNumber) => {
    const activationEnergies = process(pulseBatch);
    console.log(`batch ${batchNumber} -> [${activationEnergies.join(', ')}]`);
    console.log(formatActivationReport(activationEnergies));
  });
}

main();

module.exports = { process, formatActivationReport, computeActivationEnergy, isAboveNoiseFloor };

