const minimumLaunchThreshold = 10000;
const thermalThrottleLimit = 80;
const throttleFactor = 0.5;

function validateCoilReading(coilReading, coilIndex) {
  if (!Array.isArray(coilReading) || coilReading.length !== 3) {
    throw new Error(`Coil ${coilIndex} must list flux, draw and temperature.`);
  }
  const [baseMagneticFlux, currentElectricalDraw, thermalSensorReading] = coilReading;
  const everyValueIsFinite = [baseMagneticFlux, currentElectricalDraw, thermalSensorReading]
    .every((sensorValue) => typeof sensorValue === 'number' && Number.isFinite(sensorValue));
  if (!everyValueIsFinite) {
    throw new Error(`Coil ${coilIndex} carries a non-numeric reading.`);
  }
  if (baseMagneticFlux < 0 || currentElectricalDraw < 0) {
    throw new Error(`Coil ${coilIndex} reports a negative flux or draw.`);
  }
  return { baseMagneticFlux, currentElectricalDraw, thermalSensorReading };
}

function effectivePropulsionForce(coilReading, coilIndex) {
  const { baseMagneticFlux, currentElectricalDraw, thermalSensorReading } =
    validateCoilReading(coilReading, coilIndex);
  const rawPropulsionForce = baseMagneticFlux * currentElectricalDraw;
  if (thermalSensorReading > thermalThrottleLimit) {
    return rawPropulsionForce * throttleFactor;
  }
  return rawPropulsionForce;
}

function totalPropulsionForce(coils) {
  if (!Array.isArray(coils)) {
    throw new Error('The track must be supplied as a list of coils.');
  }
  return coils.reduce(
    (runningForceTotal, coilReading, coilIndex) =>
      runningForceTotal + effectivePropulsionForce(coilReading, coilIndex),
    0
  );
}

function propel(coils) {
  return totalPropulsionForce(coils) > minimumLaunchThreshold;
}

function throttledCoilCount(coils) {
  return coils.filter((coilReading) => coilReading[2] > thermalThrottleLimit).length;
}

function formatLaunchReport(trackName, coils) {
  const achievedForce = totalPropulsionForce(coils);
  const throttledCoils = throttledCoilCount(coils);
  const forceShortfall = minimumLaunchThreshold - achievedForce;
  const launchVerdict = propel(coils) ? 'LAUNCH' : 'HOLD';
  const shortfallNote = forceShortfall > 0
    ? `short by ${forceShortfall.toFixed(1)}`
    : `margin of ${(-forceShortfall).toFixed(1)}`;
  return `${trackName}: ${launchVerdict} — force ${achievedForce.toFixed(1)} ` +
    `(${shortfallNote}), ${throttledCoils} of ${coils.length} coil(s) throttled`;
}

function main() {
  const trackSegments = [
    ['Segment Alpha', [[500, 10, 70], [400, 15, 90]]],
    ['Segment Bravo', [[900, 12, 55], [700, 8, 60]]],
    ['Segment Charlie', [[1200, 20, 95], [600, 10, 40], [300, 5, 81]]]
  ];
  for (const [trackName, coilLayout] of trackSegments) {
    console.log(formatLaunchReport(trackName, coilLayout));
  }
}

main();

module.exports = { propel, totalPropulsionForce, effectivePropulsionForce, formatLaunchReport };

