const turbineEfficiencyFactor = 0.8;
const minimumOperatingRange = 2;

function validateTideCycle(tideCycle, cycleIndex) {
  if (!Array.isArray(tideCycle) || tideCycle.length !== 3) {
    throw new Error(`Cycle ${cycleIndex} must be [highTide, lowTide, basinCapacity]`);
  }
  const [highTideHeight, lowTideHeight, basinHoldingCapacity] = tideCycle;
  for (const numericValue of tideCycle) {
    if (typeof numericValue !== 'number' || !Number.isFinite(numericValue)) {
      throw new Error(`Cycle ${cycleIndex} contains a non-numeric entry`);
    }
  }
  if (highTideHeight < lowTideHeight) {
    throw new Error(`Cycle ${cycleIndex} has a high tide below its low tide`);
  }
  if (basinHoldingCapacity < 0) {
    throw new Error(`Cycle ${cycleIndex} has a negative basin capacity`);
  }
  return { highTideHeight, lowTideHeight, basinHoldingCapacity };
}

function computeTidalRange(highTideHeight, lowTideHeight) {
  return highTideHeight - lowTideHeight;
}

function computeCycleEnergy(tidalRange, basinHoldingCapacity) {
  if (tidalRange < minimumOperatingRange) {
    return 0;
  }
  return tidalRange * basinHoldingCapacity * turbineEfficiencyFactor;
}

function predict(tides) {
  if (!Array.isArray(tides)) {
    throw new Error('tides must be a list of daily cycles');
  }
  return tides.map((tideCycle, cycleIndex) => {
    const { highTideHeight, lowTideHeight, basinHoldingCapacity } = validateTideCycle(tideCycle, cycleIndex);
    const dailyTidalRange = computeTidalRange(highTideHeight, lowTideHeight);
    return computeCycleEnergy(dailyTidalRange, basinHoldingCapacity);
  });
}

function summarizeGeneration(energyValues) {
  const totalEnergyProduced = energyValues.reduce((runningTotal, dayEnergy) => runningTotal + dayEnergy, 0);
  const idleDayCount = energyValues.filter((dayEnergy) => dayEnergy === 0).length;
  const activeDayCount = energyValues.length - idleDayCount;
  const averageActiveOutput = activeDayCount === 0 ? 0 : totalEnergyProduced / activeDayCount;
  return { totalEnergyProduced, idleDayCount, activeDayCount, averageActiveOutput };
}

function formatGenerationReport(energyValues) {
  const reportLines = energyValues.map((dayEnergy, dayIndex) => {
    const dayLabel = `Day ${dayIndex + 1}`;
    const statusText = dayEnergy === 0 ? 'turbines idle' : `${dayEnergy.toFixed(1)} units`;
    return `${dayLabel}: ${statusText}`;
  });
  const { totalEnergyProduced, idleDayCount, averageActiveOutput } = summarizeGeneration(energyValues);
  reportLines.push(`Total: ${totalEnergyProduced.toFixed(1)} units`);
  reportLines.push(`Idle days: ${idleDayCount}`);
  reportLines.push(`Average output on active days: ${averageActiveOutput.toFixed(1)} units`);
  return reportLines.join('\n');
}

function main() {
  const weeklyTideReadings = [
    [5, 1, 1000],
    [2.5, 1, 1000],
    [6.2, 0.4, 2500],
    [3, 1, 1800],
    [1.9, 0.5, 4000],
  ];
  const dailyEnergyValues = predict(weeklyTideReadings);
  console.log(dailyEnergyValues.join(', '));
  console.log(formatGenerationReport(dailyEnergyValues));
}

main();

