const standardOperationalSpeed = 100;
const steepTerrainThreshold = 30;
const cautiousDrivingFactor = 1.5;
const minimumSnowDepth = 20;

function validateSectorRecord(sectorRecord, sectorIndex) {
  if (!Array.isArray(sectorRecord) || sectorRecord.length !== 3) {
    throw new TypeError(`sector ${sectorIndex} must be a list of three numbers`);
  }
  sectorRecord.forEach((measuredValue) => {
    if (typeof measuredValue !== 'number' || !Number.isFinite(measuredValue)) {
      throw new TypeError(`sector ${sectorIndex} contains a non-numeric measurement`);
    }
  });
}

function computeBaseGroomingTime(sectorPathLength) {
  return sectorPathLength / standardOperationalSpeed;
}

function isSectorGroomable(averageSnowDepth) {
  return averageSnowDepth >= minimumSnowDepth;
}

function computeSectorGroomingTime(sectorRecord) {
  const [sectorPathLength, averageSnowDepth, terrainSteepnessPercentage] = sectorRecord;
  if (!isSectorGroomable(averageSnowDepth)) {
    return 0;
  }
  const baseGroomingTime = computeBaseGroomingTime(sectorPathLength);
  if (terrainSteepnessPercentage > steepTerrainThreshold) {
    return baseGroomingTime * cautiousDrivingFactor;
  }
  return baseGroomingTime;
}

function groom(sectors) {
  if (!Array.isArray(sectors)) {
    throw new TypeError('sectors must be a list of mountain sectors');
  }
  return sectors.reduce((accumulatedGroomingTime, sectorRecord, sectorIndex) => {
    validateSectorRecord(sectorRecord, sectorIndex);
    return accumulatedGroomingTime + computeSectorGroomingTime(sectorRecord);
  }, 0);
}

function describeSectorPlan(sectorRecord, sectorIndex) {
  const [sectorPathLength, averageSnowDepth] = sectorRecord;
  const sectorGroomingTime = computeSectorGroomingTime(sectorRecord);
  const sectorLabel = `sector ${sectorIndex + 1} (${sectorPathLength} m, ${averageSnowDepth} cm)`;
  if (sectorGroomingTime === 0) {
    return `${sectorLabel}: skipped, snow too shallow`;
  }
  return `${sectorLabel}: ${sectorGroomingTime.toFixed(2)} min`;
}

function buildGroomingReport(sectors) {
  const sectorLines = sectors.map(describeSectorPlan);
  const totalGroomingTime = groom(sectors);
  sectorLines.push(`total: ${totalGroomingTime.toFixed(2)} min`);
  return sectorLines.join('\n');
}

function main() {
  const mountainSectors = [[500, 30, 40], [200, 15, 10], [300, 40, 20]];
  console.log(buildGroomingReport(mountainSectors));
}

main();

module.exports = { groom, buildGroomingReport, computeSectorGroomingTime };

