const humidityThresholdPercent = 60;
const moistureWeakeningFraction = 1 / 3;

function validateStrandMeasurements(strandMeasurements) {
  if (!Array.isArray(strandMeasurements) || strandMeasurements.length !== 3) {
    throw new TypeError('each strand needs stretch length, thickness and humidity');
  }
  strandMeasurements.forEach((measuredValue) => {
    if (typeof measuredValue !== 'number' || !Number.isFinite(measuredValue)) {
      throw new TypeError(`invalid measurement: ${measuredValue}`);
    }
  });
  if (strandMeasurements[1] === 0) {
    throw new RangeError('thread microscopic thickness cannot be zero');
  }
}

function computeBaseStrengthScore(maximumStretchLength, threadMicroscopicThickness) {
  return maximumStretchLength / threadMicroscopicThickness;
}

function applyMoisturePenalty(baseStrengthScore, ambientTestingHumidityPercent) {
  if (ambientTestingHumidityPercent > humidityThresholdPercent) {
    return baseStrengthScore - baseStrengthScore * moistureWeakeningFraction;
  }
  return baseStrengthScore;
}

function computeFinalStrengthScore(strandMeasurements) {
  validateStrandMeasurements(strandMeasurements);
  const maximumStretchLength = strandMeasurements[0];
  const threadMicroscopicThickness = strandMeasurements[1];
  const ambientTestingHumidityPercent = strandMeasurements[2];
  const baseStrengthScore = computeBaseStrengthScore(maximumStretchLength, threadMicroscopicThickness);
  return applyMoisturePenalty(baseStrengthScore, ambientTestingHumidityPercent);
}

function test(strands) {
  if (!Array.isArray(strands) || strands.length === 0) {
    throw new RangeError('at least one tested strand is required');
  }
  const finalStrengthScores = strands.map(computeFinalStrengthScore);
  const strengthScoreTotal = finalStrengthScores.reduce((runningTotal, scoreValue) => runningTotal + scoreValue, 0);
  return strengthScoreTotal / finalStrengthScores.length;
}

function formatStrandLine(strandMeasurements, strandIndex) {
  const finalStrengthScore = computeFinalStrengthScore(strandMeasurements);
  const humidityPercent = strandMeasurements[2];
  const penaltyMarker = humidityPercent > humidityThresholdPercent ? ' (weakened)' : '';
  return `strand ${strandIndex + 1}: ${finalStrengthScore.toFixed(3)}${penaltyMarker}`;
}

function buildLaboratoryReport(strands) {
  const strandLines = strands.map(formatStrandLine);
  const averageStrengthScore = test(strands);
  strandLines.push(`average final strength score: ${averageStrengthScore}`);
  return strandLines.join('\n');
}

function runLaboratoryBatch() {
  const testedStrandBatch = [
    [100, 2, 50],
    [120, 3, 75],
    [90, 1.5, 61],
    [200, 4, 20],
  ];
  console.log(buildLaboratoryReport(testedStrandBatch));
}

runLaboratoryBatch();

module.exports = { test, computeFinalStrengthScore, buildLaboratoryReport };

