const channelIndexMap = { blue: 0, green: 1, red: 2 };
const amplificationFactors = { blue: 1.2, green: 1.5, red: 1.0 };

function classifyColorChannel(photonWavelength) {
  if (photonWavelength >= 400 && photonWavelength < 500) return 'blue';
  if (photonWavelength >= 500 && photonWavelength < 600) return 'green';
  if (photonWavelength >= 600 && photonWavelength < 700) return 'red';
  return null;
}

function isValidPhotonEvent(photonEvent) {
  return Array.isArray(photonEvent) &&
    photonEvent.length === 3 &&
    photonEvent.every((eventField) => Number.isFinite(eventField));
}

function normalizeIntensityValue(rawIntensity) {
  return Math.round(rawIntensity * 1e6) / 1e6;
}

function computeEventSignal(photonEvent) {
  if (!isValidPhotonEvent(photonEvent)) return null;
  const [photonWavelength, totalPhotonCount, retinalSectorIndex] = photonEvent;
  const colorChannelName = classifyColorChannel(photonWavelength);
  if (colorChannelName === null) return null;
  const channelIntensity = totalPhotonCount * amplificationFactors[colorChannelName];
  return { colorChannelName, retinalSectorIndex, channelIntensity };
}

function translate(photons) {
  const accumulatedIntensities = [0, 0, 0];
  for (const photonEvent of photons) {
    const eventSignal = computeEventSignal(photonEvent);
    if (eventSignal === null) continue;
    accumulatedIntensities[channelIndexMap[eventSignal.colorChannelName]] += eventSignal.channelIntensity;
  }
  return accumulatedIntensities.map(normalizeIntensityValue);
}

function summarizeBySector(photons) {
  const sectorTotals = new Map();
  for (const photonEvent of photons) {
    const eventSignal = computeEventSignal(photonEvent);
    if (eventSignal === null) continue;
    const previousSectorTotal = sectorTotals.get(eventSignal.retinalSectorIndex) || 0;
    sectorTotals.set(eventSignal.retinalSectorIndex, previousSectorTotal + eventSignal.channelIntensity);
  }
  return [...sectorTotals.entries()]
    .sort((firstSectorEntry, secondSectorEntry) => firstSectorEntry[0] - secondSectorEntry[0])
    .map(([retinalSectorIndex, sectorIntensityTotal]) => ({
      retinalSectorIndex,
      sectorIntensityTotal: normalizeIntensityValue(sectorIntensityTotal),
    }));
}

function formatChannelReport(channelIntensities) {
  const channelLabels = ['blue', 'green', 'red'];
  const channelLines = channelIntensities.map(
    (intensityValue, channelPosition) => `${channelLabels[channelPosition]}: ${intensityValue}`
  );
