const channel_index_map = { blue: 0, green: 1, red: 2 };
const amplification_factors = { blue: 1.2, green: 1.5, red: 1.0 };

function classify_color_channel(photon_wavelength) {
  if (photon_wavelength >= 400 && photon_wavelength < 500) return 'blue';
  if (photon_wavelength >= 500 && photon_wavelength < 600) return 'green';
  if (photon_wavelength >= 600 && photon_wavelength < 700) return 'red';
  return null;
}

function is_valid_photon_event(photon_event) {
  return Array.isArray(photon_event) &&
    photon_event.length === 3 &&
    photon_event.every((event_field) => Number.isFinite(event_field));
}

function normalize_intensity_value(raw_intensity) {
  return Math.round(raw_intensity * 1e6) / 1e6;
}

function compute_event_signal(photon_event) {
  if (!is_valid_photon_event(photon_event)) return null;
  const [photon_wavelength, total_photon_count, retinal_sector_index] = photon_event;
  const color_channel_name = classify_color_channel(photon_wavelength);
  if (color_channel_name === null) return null;
  const channel_intensity = total_photon_count * amplification_factors[color_channel_name];
  return { color_channel_name, retinal_sector_index, channel_intensity };
}

function translate(photons) {
  const accumulated_intensities = [0, 0, 0];
  for (const photon_event of photons) {
    const event_signal = compute_event_signal(photon_event);
    if (event_signal === null) continue;
    accumulated_intensities[channel_index_map[event_signal.color_channel_name]] += event_signal.channel_intensity;
  }
  return accumulated_intensities.map(normalize_intensity_value);
}

function summarize_by_sector(photons) {
  const sector_totals = new Map();
  for (const photon_event of photons) {
    const event_signal = compute_event_signal(photon_event);
    if (event_signal === null) continue;
    const previous_sector_total = sector_totals.get(event_signal.retinal_sector_index) || 0;
    sector_totals.set(event_signal.retinal_sector_index, previous_sector_total + event_signal.channel_intensity);
  }
  return [...sector_totals.entries()]
    .sort((first_sector_entry, second_sector_entry) => first_sector_entry[0] - second_sector_entry[0])
    .map(([retinal_sector_index, sector_intensity_total]) => ({
      retinal_sector_index,
      sector_intensity_total: normalize_intensity_value(sector_intensity_total),
    }));
}

function format_channel_report(channel_intensities) {
  const channel_labels = ['blue', 'green', 'red'];
  const channel_lines = channel_intensities.map(
    (intensity_value, channel_position) => `${channel_labels[channel_position]}: ${intensity_value}`
  );
  return `channel intensities -> ${channel_lines.join(', ')}`;
}

function format_sector_report(sector_summaries) {
  const sector_lines = sector_summaries.map(
    (sector_summary) => `sector ${sector_summary.retinal_sector_index} = ${sector_summary.sector_intensity_total}`
  );
  return `sector load -> ${sector_lines.join(' | ')}`;
}

