function parseVoiceNote(rawNote, noteIndex) {
  if (!Array.isArray(rawNote) || rawNote.length !== 3) {
    throw new TypeError(`voice ${noteIndex} must be a list of three numbers`);
  }
  const [fundamentalFrequency, overtoneAmplitude, vibratoVariation] = rawNote;
  if (![fundamentalFrequency, overtoneAmplitude, vibratoVariation].every(Number.isFinite)) {
    throw new TypeError(`voice ${noteIndex} contains a non-numeric measurement`);
  }
  if (vibratoVariation === 0) {
    throw new RangeError(`voice ${noteIndex} has a zero vibrato variation metric`);
  }
  return { fundamentalFrequency, overtoneAmplitude, vibratoVariation };
}

function computePitchStability(fundamentalFrequency, vibratoVariation) {
  return fundamentalFrequency / vibratoVariation;
}

function computeHarmonicBlend(overtoneAmplitude, pitchStabilityScore) {
  return overtoneAmplitude * pitchStabilityScore;
}

function isPerfectlyBlended(pitchStabilityScore, harmonicBlendMetric) {
  return pitchStabilityScore > 50 && harmonicBlendMetric < 15;
}

function analyzeVoiceNote(rawNote, noteIndex) {
  const { fundamentalFrequency, overtoneAmplitude, vibratoVariation } = parseVoiceNote(rawNote, noteIndex);
  const pitchStabilityScore = computePitchStability(fundamentalFrequency, vibratoVariation);
  const harmonicBlendMetric = computeHarmonicBlend(overtoneAmplitude, pitchStabilityScore);
  return {
    pitchStabilityScore,
    harmonicBlendMetric,
    perfectlyBlended: isPerfectlyBlended(pitchStabilityScore, harmonicBlendMetric)
  };
}

function harmonize(voices) {
  if (!Array.isArray(voices)) {
    throw new TypeError('voices must be a list of sung notes');
  }
  let perfectlyBlendedCount = 0;
  let stabilityScoreTotal = 0;
  voices.forEach((rawNote, noteIndex) => {
    const noteAnalysis = analyzeVoiceNote(rawNote, noteIndex);
    stabilityScoreTotal += noteAnalysis.pitchStabilityScore;
    if (noteAnalysis.perfectlyBlended) {
      perfectlyBlendedCount += 1;
    }
  });
  return [perfectlyBlendedCount, stabilityScoreTotal];
}

function formatHarmonyReport(voices) {
  const reportLines = voices.map((rawNote, noteIndex) => {
    const { pitchStabilityScore, harmonicBlendMetric, perfectlyBlended } = analyzeVoiceNote(rawNote, noteIndex);
    const blendVerdict = perfectlyBlended ? 'perfectly blended' : 'needs rehearsal';
    return `voice ${noteIndex + 1}: stability=${pitchStabilityScore.toFixed(2)} ` +
      `blend=${harmonicBlendMetric.toFixed(2)} (${blendVerdict})`;
  });
  const [perfectlyBlendedCount, stabilityScoreTotal] = harmonize(voices);
  reportLines.push(`perfectly blended notes: ${perfectlyBlendedCount}`);
  reportLines.push(`total pitch stability: ${stabilityScoreTotal.toFixed(2)}`);
  return reportLines.join('\n');
}

function main() {
  const choirVoices = [
    [440, 0.2, 5],
    [880, 0.4, 20],
    [660, 0.1, 6],
    [330, 0.9, 2]
  ];
  console.log(formatHarmonyReport(choirVoices));
  const blendSummary = harmonize(choirVoices);
  console.log(`harmonize -> [${blendSummary.join(', ')}]`);
}

main();

module.exports = { harmonize, formatHarmonyReport, computePitchStability, computeHarmonicBlend };

