function calculateGrowthPriority(absoluteDistance, availableSugar, localMineralDensity) {
    const totalNutrients = availableSugar * localMineralDensity;
    const computedPriority = totalNutrients / absoluteDistance;
    return computedPriority;
}

function isViableExpansionTarget(absoluteDistance, availableSugar) {
    const viabilityThreshold = absoluteDistance;
    const isViable = availableSugar > viabilityThreshold;
    return isViable;
}

function validateDepositData(depositInfo) {
    const expectedElementCount = 3;
    const hasCorrectLength = depositInfo.length === expectedElementCount;
    if (!hasCorrectLength) {
        throw new Error("Invalid deposit data format");
    }
    const minimumAllowedDistance = 0;
    const distanceIsValid = depositInfo[0] > minimumAllowedDistance;
    if (!distanceIsValid) {
        throw new Error("Distance must be strictly positive");
    }
    return true;
}

function processSingleDeposit(depositData) {
    validateDepositData(depositData);

    const absoluteDistance = depositData[0];
    const availableSugar = depositData[1];
    const localMineralDensity = depositData[2];

    const meetsViabilityCriteria = isViableExpansionTarget(absoluteDistance, availableSugar);
    if (!meetsViabilityCriteria) {
        const defaultFailurePriority = 0;
        return defaultFailurePriority;
    }

    const calculatedPriority = calculateGrowthPriority(absoluteDistance, availableSugar, localMineralDensity);
    return calculatedPriority;
}

function route(nodes) {
    let maximumGrowthPriority = 0;

    for (let currentDepositIndex = 0; currentDepositIndex < nodes.length; currentDepositIndex++) {
        const currentDepositData = nodes[currentDepositIndex];
        const currentDepositPriority = processSingleDeposit(currentDepositData);

        const isNewMaximum = currentDepositPriority > maximumGrowthPriority;
        if (isNewMaximum) {
            maximumGrowthPriority = currentDepositPriority;
        }
    }

    return maximumGrowthPriority;
}

