function validateStrike(swingRecord, swingIndex) {
  if (!Array.isArray(swingRecord) || swingRecord.length !== 3) {
    throw new TypeError(`Swing ${swingIndex} must be [mass, velocity, angle].`);
  }
  const [treeLogMass, maximumSwingVelocity, finalImpactAngle] = swingRecord;
  if (![treeLogMass, maximumSwingVelocity, finalImpactAngle].every(Number.isFinite)) {
    throw new TypeError(`Swing ${swingIndex} contains a non-numeric value.`);
  }
  if (treeLogMass <= 0 || maximumSwingVelocity < 0) {
    throw new RangeError(`Swing ${swingIndex} has an impossible log or velocity.`);
  }
  if (finalImpactAngle < 0 || finalImpactAngle > 90) {
    throw new RangeError(`Swing ${swingIndex} angle must lie between 0 and 90 degrees.`);
  }
  return { treeLogMass, maximumSwingVelocity, finalImpactAngle };
}

function computeBaseImpactForce(treeLogMass, maximumSwingVelocity) {
  return treeLogMass * maximumSwingVelocity * maximumSwingVelocity;
}

function simplifiedAngleMultiplier(finalImpactAngle) {
  return 1 - finalImpactAngle / 90;
}

function trueStructuralDamage(swingRecord, swingIndex) {
  const validatedSwing = validateStrike(swingRecord, swingIndex);
  const baseImpactForce = computeBaseImpactForce(
    validatedSwing.treeLogMass,
    validatedSwing.maximumSwingVelocity
  );
  return baseImpactForce * simplifiedAngleMultiplier(validatedSwing.finalImpactAngle);
}

function breach(strikes) {
  if (!Array.isArray(strikes)) {
    throw new TypeError('breach expects a list of ram swings.');
  }
  return strikes.reduce(
    (runningDamageTotal, swingRecord, swingIndex) =>
      runningDamageTotal + trueStructuralDamage(swingRecord, swingIndex),
    0
  );
}

function describeStrike(swingRecord, swingIndex) {
  const [treeLogMass, maximumSwingVelocity, finalImpactAngle] = swingRecord;
  const damageForSwing = trueStructuralDamage(swingRecord, swingIndex);
  return `#${swingIndex + 1}: ${treeLogMass}kg at ${maximumSwingVelocity}m/s, `
    + `${finalImpactAngle}deg -> ${damageForSwing.toFixed(1)} damage`;
}

function buildBreachReport(strikes, gateIntegrityThreshold) {
  const grandTotalDamage = breach(strikes);
  const verdictLine = grandTotalDamage >= gateIntegrityThreshold
    ? `Gate breached: ${grandTotalDamage} >= ${gateIntegrityThreshold}`
    : `Gate holds: ${grandTotalDamage} < ${gateIntegrityThreshold}`;
  return [...strikes.map(describeStrike), verdictLine].join('\n');
}

