  const recordedStrikes = [[500, 4, 0], [500, 4, 45]];
  const siegeThreshold = 10000;
  console.log(buildBreachReport(recordedStrikes, siegeThreshold));
  const heavierAssault = [...recordedStrikes, [750, 6, 30], [900, 3, 90]];
  console.log(buildBreachReport(heavierAssault, siegeThreshold));
}

main();

module.exports = { breach, trueStructuralDamage, buildBreachReport };

