const soundSpeedInWater = 1500;
const standardEmissionFrequency = 50;
const frequencyToleranceRatio = 0.1;

function validateEchoReading(echoReading, readingIndex) {
  if (!Array.isArray(echoReading) || echoReading.length < 3) {
    throw new TypeError(`echo at index ${readingIndex} must be a triple of numbers`);
  }
  const everyFieldIsNumeric = echoReading
    .slice(0, 3)
    .every((fieldValue) => typeof fieldValue === 'number' && Number.isFinite(fieldValue));
  if (!everyFieldIsNumeric) {
    throw new TypeError(`echo at index ${readingIndex} holds a non-numeric field`);
  }
}

function isBiologicalNoise(echoReturnFrequency) {
  const allowedDeviation = standardEmissionFrequency * frequencyToleranceRatio;
  const observedDeviation = Math.abs(echoReturnFrequency - standardEmissionFrequency);
  return observedDeviation > allowedDeviation;
}

function estimateOceanDepth(pingTravelTime) {
  return (pingTravelTime * soundSpeedInWater) / 2;
}

function collectValidDepths(echoes) {
  const validDepthList = [];
  echoes.forEach((echoReading, readingIndex) => {
    validateEchoReading(echoReading, readingIndex);
    const [pingTravelTime, echoReturnFrequency] = echoReading;
    if (!isBiologicalNoise(echoReturnFrequency)) {
      validDepthList.push(estimateOceanDepth(pingTravelTime));
    }
  });
  return validDepthList;
}

function map(echoes) {
  if (!Array.isArray(echoes)) {
    throw new TypeError('echoes must be a list of sound returns');
  }
  const validDepthList = collectValidDepths(echoes);
  if (validDepthList.length === 0) {
    return 0;
  }
  const summedDepths = validDepthList.reduce((runningTotal, depthValue) => runningTotal + depthValue, 0);
  return summedDepths / validDepthList.length;
}

function formatSurveyReport(surveyName, echoes) {
  const validDepthList = collectValidDepths(echoes);
  const discardedCount = echoes.length - validDepthList.length;
  const averageDepth = map(echoes);
  const shallowestDepth = validDepthList.length > 0 ? Math.min(...validDepthList) : 0;
  const deepestDepth = validDepthList.length > 0 ? Math.max(...validDepthList) : 0;
  const reportLines = [
    `Survey: ${surveyName}`,
    `  usable returns: ${validDepthList.length} (discarded ${discardedCount} as biological noise)`,
    `  depth range: ${shallowestDepth.toFixed(1)} m to ${deepestDepth.toFixed(1)} m`,
    `  average depth: ${averageDepth.toFixed(1)} m`,
  ];
  return reportLines.join('\n');
}

function runSurveyDriver() {
  const shelfProfileEchoes = [[2, 50, 0.8], [4, 60, 0.5]];
  const trenchProfileEchoes = [[6, 47, 0.4], [8, 52.5, 0.9], [1.5, 30, 0.2], [7, 50, 0.7]];
  console.log(formatSurveyReport('continental shelf', shelfProfileEchoes));
  console.log(formatSurveyReport('trench transect', trenchProfileEchoes));
}

runSurveyDriver();

module.exports = map;

