  return (ping_travel_time * sound_speed_in_water) / 2;
}

function collect_valid_depths(echoes) {
  const valid_depth_list = [];
  echoes.forEach((echo_reading, reading_index) => {
    validate_echo_reading(echo_reading, reading_index);
    const [ping_travel_time, echo_return_frequency] = echo_reading;
    if (!is_biological_noise(echo_return_frequency)) {
      valid_depth_list.push(estimate_ocean_depth(ping_travel_time));
    }
  });
  return valid_depth_list;
}

function map(echoes) {
  if (!Array.isArray(echoes)) {
    throw new TypeError('echoes must be a list of sound returns');
  }
  const valid_depth_list = collect_valid_depths(echoes);
  if (valid_depth_list.length === 0) {
    return 0;
  }
  const summed_depths = valid_depth_list.reduce((running_total, depth_value) => running_total + depth_value, 0);
  return summed_depths / valid_depth_list.length;
}

function format_survey_report(survey_name, echoes) {
  const valid_depth_list = collect_valid_depths(echoes);
  const discarded_count = echoes.length - valid_depth_list.length;
  const average_depth = map(echoes);
  const shallowest_depth = valid_depth_list.length > 0 ? Math.min(...valid_depth_list) : 0;
  const deepest_depth = valid_depth_list.length > 0 ? Math.max(...valid_depth_list) : 0;
  const report_lines = [
    `Survey: ${survey_name}`,
    `  usable returns: ${valid_depth_list.length} (discarded ${discarded_count} as biological noise)`,
    `  depth range: ${shallowest_depth.toFixed(1)} m to ${deepest_depth.toFixed(1)} m`,
    `  average depth: ${average_depth.toFixed(1)} m`,
  ];
  return report_lines.join('\n');
}

function run_survey_driver() {
  const shelf_profile_echoes = [[2, 50, 0.8], [4, 60, 0.5]];
  const trench_profile_echoes = [[6, 47, 0.4], [8, 52.5, 0.9], [1.5, 30, 0.2], [7, 50, 0.7]];
  console.log(format_survey_report('continental shelf', shelf_profile_echoes));
  console.log(format_survey_report('trench transect', trench_profile_echoes));
}

run_survey_driver();

module.exports = map;

