const baseFiltrationRate = 50;
const turbidityThreshold = 400;
const cloggingReductionFactor = 0.8;
const hibernationTemperature = 10;

function parseColony(rawColony) {
  if (!Array.isArray(rawColony) || rawColony.length !== 3) {
    throw new TypeError('each colony must be a list of three numeric readings');
  }
  const [livingOysterCount, waterTurbidityLevel, dailyWaterTemperature] = rawColony;
  if (!Number.isFinite(livingOysterCount) || livingOysterCount < 0) {
    throw new RangeError(`invalid living oyster count: ${livingOysterCount}`);
  }
  if (!Number.isFinite(waterTurbidityLevel) || waterTurbidityLevel < 0) {
    throw new RangeError(`invalid turbidity level: ${waterTurbidityLevel}`);
  }
  if (!Number.isFinite(dailyWaterTemperature)) {
    throw new RangeError(`invalid water temperature: ${dailyWaterTemperature}`);
  }
  return { livingOysterCount, waterTurbidityLevel, dailyWaterTemperature };
}

function computeBaseFiltration(livingOysterCount) {
  return livingOysterCount * baseFiltrationRate;
}

function isHibernating(dailyWaterTemperature) {
  return dailyWaterTemperature < hibernationTemperature;
}

function hasGillClogging(waterTurbidityLevel) {
  return waterTurbidityLevel > turbidityThreshold;
}

function filtrationForColony(colonyReadings) {
  const { livingOysterCount, waterTurbidityLevel, dailyWaterTemperature } = colonyReadings;
  if (isHibernating(dailyWaterTemperature)) {
    return 0;
  }
  const baseDailyVolume = computeBaseFiltration(livingOysterCount);
  if (hasGillClogging(waterTurbidityLevel)) {
    return baseDailyVolume * cloggingReductionFactor;
  }
  return baseDailyVolume;
}

function model(beds) {
  if (!Array.isArray(beds)) {
    throw new TypeError('beds must be a list of oyster colonies');
  }
  return beds.map((rawColony) => filtrationForColony(parseColony(rawColony)));
}

function summariseFiltration(beds) {
  const volumeList = model(beds);
  const totalDailyVolume = volumeList.reduce((runningTotal, volume) => runningTotal + volume, 0);
  const dormantColonyCount = volumeList.filter((volume) => volume === 0).length;
  return { volumeList, totalDailyVolume, dormantColonyCount };
}

