const gondolaWeight = 5000;

function isValveOpen(valveStatus) {
  return valveStatus === 1;
}

function chamberGrossLift(chamber) {
  const [envelopeCapacity, internalPressure, valveStatus] = chamber;
  if (isValveOpen(valveStatus)) {
    return 0;
  }
  return envelopeCapacity * internalPressure;
}

function validateChamber(chamber, chamberIndex) {
  if (!Array.isArray(chamber) || chamber.length !== 3) {
    throw new TypeError(`chamber ${chamberIndex} must be [capacity, pressure, valve]`);
  }
  const [envelopeCapacity, internalPressure, valveStatus] = chamber;
  if (!Number.isFinite(envelopeCapacity) || envelopeCapacity < 0) {
    throw new RangeError(`chamber ${chamberIndex} has an invalid envelope capacity`);
  }
  if (!Number.isFinite(internalPressure) || internalPressure < 0) {
    throw new RangeError(`chamber ${chamberIndex} has an invalid internal pressure`);
  }
  if (valveStatus !== 0 && valveStatus !== 1) {
    throw new RangeError(`chamber ${chamberIndex} has an invalid valve status`);
  }
}

function balance(chambers) {
  if (!Array.isArray(chambers)) {
    throw new TypeError('chambers must be an array of envelope descriptors');
  }
  chambers.forEach(validateChamber);
  const grossLiftTotal = chambers.reduce(
    (runningTotal, chamber) => runningTotal + chamberGrossLift(chamber),
    0
  );
  return grossLiftTotal - gondolaWeight;
}

function describeChamber(chamber, chamberIndex) {
  const [envelopeCapacity, internalPressure, valveStatus] = chamber;
  const valveLabel = isValveOpen(valveStatus) ? 'open' : 'closed';
  const liftContribution = chamberGrossLift(chamber);
  return `#${chamberIndex + 1}: ${envelopeCapacity} m3 @ ${internalPressure} `
    + `(valve ${valveLabel}) -> ${liftContribution} N`;
}

function buildLiftReport(chambers) {
  const netBuoyancyForce = balance(chambers);
  const verdictLine = netBuoyancyForce > 0
    ? `Dirigible rises with ${netBuoyancyForce} N to spare.`
    : `Dirigible sinks; shortfall of ${Math.abs(netBuoyancyForce)} N.`;
  return [
    ...chambers.map(describeChamber),
    `Gondola weight: ${gondolaWeight} N`,
    `Net lift: ${netBuoyancyForce} N`,
    verdictLine
  ].join('\n');
}

function main() {
  const testFlightChambers = [[2000, 3, 0], [1000, 2, 1]];
  const heavyCargoChambers = [[1500, 1, 0], [800, 2, 0], [600, 4, 1]];
  console.log(buildLiftReport(testFlightChambers));
  console.log('');
  console.log(buildLiftReport(heavyCargoChambers));
}

main();

