    const index_of_equals = single_pair.indexOf('=');
    if (index_of_equals === -1) {
      continue;
    }
    const parameter_key = decodeURIComponent(single_pair.substring(0, index_of_equals));
    const parameter_value = decodeURIComponent(single_pair.substring(index_of_equals + 1));
    parameter_object[parameter_key] = parameter_value;
  }

  return parameter_object;
}

