function validateNumericArray(inputArray) {
  if (!Array.isArray(inputArray)) {
    throw new TypeError('expected an array of numbers');
  }
  const invalidEntry = inputArray.find((candidateValue) => typeof candidateValue !== 'number' || Number.isNaN(candidateValue));
  if (invalidEntry !== undefined) {
    throw new TypeError(`array contains a non-numeric entry: ${String(invalidEntry)}`);
  }
  const uniqueValues = new Set(inputArray);
  if (uniqueValues.size < 2) {
    throw new RangeError('array must contain at least two unique numbers');
  }
  return inputArray;
}

function findSecondSmallest(arr) {
  validateNumericArray(arr);
  let smallestSoFar = Infinity;
  let secondSmallestSoFar = Infinity;
  for (const currentValue of arr) {
    if (currentValue < smallestSoFar) {
      secondSmallestSoFar = smallestSoFar;
      smallestSoFar = currentValue;
    } else if (currentValue > smallestSoFar && currentValue < secondSmallestSoFar) {
      secondSmallestSoFar = currentValue;
    }
  }
  return secondSmallestSoFar;
}

function findSmallestAndSecondSmallest(arr) {
  const secondSmallestValue = findSecondSmallest(arr);
  const smallestValue = Math.min(...arr);
  return { smallestValue, secondSmallestValue };
}

function describeRanking(arr) {
  const { smallestValue, secondSmallestValue } = findSmallestAndSecondSmallest(arr);
  const rankingGap = secondSmallestValue - smallestValue;
  const sourceDescription = `[${arr.join(', ')}]`;
  return `${sourceDescription} -> smallest ${smallestValue}, second smallest ${secondSmallestValue} (gap ${rankingGap})`;
}

function buildRankingReport(arrayCollection) {
  const reportLines = [];
  for (const candidateArray of arrayCollection) {
    try {
      reportLines.push(describeRanking(candidateArray));
    } catch (thrownError) {
      reportLines.push(`[${candidateArray}] -> skipped: ${thrownError.message}`);
    }
  }
  return reportLines.join('\n');
}

function runMain() {
  const sampleArrays = [
    [5, 1, 8, 2, 9],
    [10, 20, 3, 40],
    [7, 7, 7, 4],
    [-2.5, -9, 0, -9],
    [42, 42],
  ];
  console.log(buildRankingReport(sampleArrays));
}

runMain();

module.exports = {
  findSecondSmallest,
  findSmallestAndSecondSmallest,
  describeRanking,
  buildRankingReport,
};

