function isPlainObject(candidateValue) {
  return typeof candidateValue === 'object'
    && candidateValue !== null
    && !Array.isArray(candidateValue);
}

function assertMergeable(objectLabel, objectValue) {
  if (!isPlainObject(objectValue)) {
    throw new TypeError(`${objectLabel} must be a plain object`);
  }
}

function mergeObjects(obj1, obj2) {
  assertMergeable('obj1', obj1);
  assertMergeable('obj2', obj2);
  const mergedResult = {};
  for (const baseKey of Object.keys(obj1)) {
    mergedResult[baseKey] = obj1[baseKey];
  }
  for (const overrideKey of Object.keys(obj2)) {
    mergedResult[overrideKey] = obj2[overrideKey];
  }
  return mergedResult;
}

function mergeObjectList(objectList) {
  return objectList.reduce(
    (accumulatedObject, currentObject) => mergeObjects(accumulatedObject, currentObject),
    {}
  );
}

function findOverwrittenKeys(obj1, obj2) {
  return Object.keys(obj1).filter(
    (sharedKey) => Object.prototype.hasOwnProperty.call(obj2, sharedKey)
  );
}

function describeMerge(obj1, obj2) {
  const mergedObject = mergeObjects(obj1, obj2);
  const overwrittenKeys = findOverwrittenKeys(obj1, obj2);
  const keySummary = Object.keys(mergedObject)
    .map((resultKey) => `${resultKey}=${JSON.stringify(mergedObject[resultKey])}`)
    .join(', ');
  const conflictSummary = overwrittenKeys.length
    ? `overwritten: ${overwrittenKeys.join('/')}`
    : 'no conflicts';
  return `{ ${keySummary} } (${conflictSummary})`;
}

function buildEffectiveSettings(defaultSettings, userSettings, commandLineSettings) {
  return mergeObjectList([defaultSettings, userSettings, commandLineSettings]);
}

function runMergeReport() {
  console.log(describeMerge({ a: 1, b: 2 }, { b: 3, c: 4 }));
  console.log(describeMerge({ x: 1 }, {}));

  const defaultSettings = { retries: 2, host: 'localhost', port: 80 };
  const userSettings = { port: 8080, verbose: true };
  const commandLineSettings = { retries: 5 };
  const effectiveSettings = buildEffectiveSettings(defaultSettings, userSettings, commandLineSettings);
  console.log('effective settings:', JSON.stringify(effectiveSettings));
}

runMergeReport();

module.exports = {
  mergeObjects,
  mergeObjectList,
  findOverwrittenKeys,
  describeMerge,
  buildEffectiveSettings
};

