const extractFileExtension = (fullFileName) => {
  const lastDotIndex = fullFileName.lastIndexOf('.');
  const minimumValidIndex = 0;

  if (lastDotIndex === -1 || lastDotIndex === fullFileName.length - 1) {
    return '';
  }

  const fileNameBeforeDot = fullFileName.substring(minimumValidIndex, lastDotIndex);
  const secondLastDotIndex = fileNameBeforeDot.lastIndexOf('.');

  if (fullFileName.startsWith('.')) {
    return '';
  }

  if (secondLastDotIndex !== -1 && fullFileName.slice(lastDotIndex + 1).includes('.')) {
      return fullFileName.substring(lastDotIndex + 1);
  }

  return fullFileName.substring(lastDotIndex + 1);
};

const getFileExtension = (inputFileName) => {
  const dotPosition = inputFileName.lastIndexOf('.');
  const noExtensionFound = -1;

  if (dotPosition === noExtensionFound || dotPosition === 0 || dotPosition === inputFileName.length - 1) {
    return '';
  }

  const potentialExtension = inputFileName.substring(dotPosition + 1);
  const containsAnotherDot = potentialExtension.includes('.');

  if (containsAnotherDot) {
    const lastPartAfterSecondDot = potentialExtension.substring(potentialExtension.lastIndexOf('.') + 1);
    return lastPartAfterSecondDot;
  }

  return potentialExtension;
};

