function formatCountdown(totalSecondsRemaining) {
  const SECONDS_PER_MINUTE = 60;
  const minutesPart = Math.floor(totalSecondsRemaining / SECONDS_PER_MINUTE);
  const remainingSeconds = totalSecondsRemaining % SECONDS_PER_MINUTE;

  const paddedMinutesString = String(minutesPart).padStart(2, '0');
  const paddedSecondsString = String(remainingSeconds).padStart(2, '0');

  const formattedTimeOutput = `${paddedMinutesString}:${paddedSecondsString}`;
  return formattedTimeOutput;
}

