function findLongestPalindromicSubstring(inputString) {
  if (inputString === null || inputString.length < 1) {
    return "";
  }

  let currentMaxLen = 0;
  let resultStartingIndex = 0;
  const stringLength = inputString.length;

  for (let centerIndex = 0; centerIndex < stringLength; centerIndex++) {
    let oddLengthPalindrome = expandAroundCenter(inputString, centerIndex, centerIndex);
    let evenLengthPalindrome = expandAroundCenter(inputString, centerIndex, centerIndex + 1);

    if (oddLengthPalindrome.length > currentMaxLen) {
      currentMaxLen = oddLengthPalindrome.length;
      resultStartingIndex = oddLengthPalindrome.startIndex;
    }

    if (evenLengthPalindrome.length > currentMaxLen) {
      currentMaxLen = evenLengthPalindrome.length;
      resultStartingIndex = evenLengthPalindrome.startIndex;
    }
  }

  return inputString.substring(resultStartingIndex, resultStartingIndex + currentMaxLen);
}

function expandAroundCenter(fullString, leftPointer, rightPointer) {
  let initialLeft = leftPointer;
  let initialRight = rightPointer;

  while (initialLeft >= 0 && initialRight < fullString.length && fullString.charAt(initialLeft) === fullString.charAt(initialRight)) {
    initialLeft--;
