function find_longest_palindromic_substring(input_string) {
  if (input_string === null || input_string.length < 1) {
    return "";
  }

  let current_max_len = 0;
  let result_starting_index = 0;
  const string_length = input_string.length;

  for (let center_index = 0; center_index < string_length; center_index++) {
    let odd_length_palindrome = expand_around_center(input_string, center_index, center_index);
    let even_length_palindrome = expand_around_center(input_string, center_index, center_index + 1);

    if (odd_length_palindrome.length > current_max_len) {
      current_max_len = odd_length_palindrome.length;
      result_starting_index = odd_length_palindrome.startIndex;
    }

    if (even_length_palindrome.length > current_max_len) {
      current_max_len = even_length_palindrome.length;
      result_starting_index = even_length_palindrome.startIndex;
    }
  }

  return input_string.substring(result_starting_index, result_starting_index + current_max_len);
}

function expand_around_center(full_string, left_pointer, right_pointer) {
  let initial_left = left_pointer;
  let initial_right = right_pointer;

  while (initial_left >= 0 && initial_right < full_string.length && full_string.charAt(initial_left) === full_string.charAt(initial_right)) {
    initial_left--;
    initial_right++;
  }
  let final_length = initial_right - initial_left - 1;
  let final_start_index = initial_left + 1;
  return { length: final_length, startIndex: final_start_index };
}

