function parseCsvLine(inputCsvLine) {
  const individualFieldValues = [];
  let currentAccumulatedValue = '';

  for (let characterIndex = 0; characterIndex < inputCsvLine.length; characterIndex++) {
    const currentChar = inputCsvLine[characterIndex];
    if (currentChar === ',') {
      individualFieldValues.push(currentAccumulatedValue);
      currentAccumulatedValue = '';
    } else {
      currentAccumulatedValue += currentChar;
    }
  }

  individualFieldValues.push(currentAccumulatedValue);
  return individualFieldValues;
}

