function calculateFactorial(inputNumber) {
  if (inputNumber < 0) {
    throw new Error("Negative numbers do not have a factorial.");
  }
  let currentProduct = 1;
  for (let currentIteration = 2; currentIteration <= inputNumber; currentIteration++) {
    currentProduct *= currentIteration;
  }
  return currentProduct;
}

function processAndDisplayFactorial(valueToProcess) {
  const factorialResult = calculateFactorial(valueToProcess);
  console.log(`The factorial of ${valueToProcess} is ${factorialResult}.`);
}

// Example usage demonstrating the functionality
processAndDisplayFactorial(5);
processAndDisplayFactorial(0);
processAndDisplayFactorial(7);
