const queue = [];

function enqueue(item) {
  queue.push(item);
  return queue.length;
}

function dequeue() {
  if (queue.length === 0) {
    return null;
  }
  return queue.shift();
}

function peekFrontItem() {
  return queue.length === 0 ? null : queue[0];
}

function currentQueueSize() {
  return queue.length;
}

function formatQueueState() {
  if (queue.length === 0) {
    return '(empty)';
  }
  return queue.map(String).join(' <- ');
}

function enqueueAll(itemList) {
  let itemsAccepted = 0;
  for (const nextItem of itemList) {
    if (nextItem === undefined) {
      continue;
    }
    enqueue(nextItem);
    itemsAccepted += 1;
  }
  return itemsAccepted;
}

function drainQueue(maximumItems) {
  const drainedItems = [];
  let remainingBudget = maximumItems === undefined ? Infinity : maximumItems;
  while (remainingBudget > 0) {
    const frontItem = dequeue();
    if (frontItem === null) {
      break;
    }
    drainedItems.push(frontItem);
    remainingBudget -= 1;
  }
  return drainedItems;
}

function runQueueDemo(initialItems) {
  const reportLines = [];
  const acceptedCount = enqueueAll(initialItems);
  reportLines.push(`enqueued ${acceptedCount} item(s): ${formatQueueState()}`);
  reportLines.push(`front item is ${peekFrontItem()}`);

  const firstTwoItems = drainQueue(2);
