const queue = [];

function enqueue(item) {
  queue.push(item);
  return queue.length;
}

function dequeue() {
  if (queue.length === 0) {
    return null;
  }
  return queue.shift();
}

function peek_front_item() {
  return queue.length === 0 ? null : queue[0];
}

function current_queue_size() {
  return queue.length;
}

function format_queue_state() {
  if (queue.length === 0) {
    return '(empty)';
  }
  return queue.map(String).join(' <- ');
}

function enqueue_all(item_list) {
  let items_accepted = 0;
  for (const next_item of item_list) {
    if (next_item === undefined) {
      continue;
    }
    enqueue(next_item);
    items_accepted += 1;
  }
  return items_accepted;
}

function drain_queue(maximum_items) {
  const drained_items = [];
  let remaining_budget = maximum_items === undefined ? Infinity : maximum_items;
  while (remaining_budget > 0) {
    const front_item = dequeue();
    if (front_item === null) {
      break;
    }
    drained_items.push(front_item);
    remaining_budget -= 1;
  }
  return drained_items;
}

function run_queue_demo(initial_items) {
  const report_lines = [];
  const accepted_count = enqueue_all(initial_items);
  report_lines.push(`enqueued ${accepted_count} item(s): ${format_queue_state()}`);
  report_lines.push(`front item is ${peek_front_item()}`);

  const first_two_items = drain_queue(2);
  report_lines.push(`dequeued [${first_two_items.join(', ')}], size now ${current_queue_size()}`);

  const remaining_items = drain_queue();
  report_lines.push(`drained remainder [${remaining_items.join(', ')}]`);
  report_lines.push(`dequeue on empty queue gives ${dequeue()}`);
  return report_lines;
}

for (const report_line of run_queue_demo([1, 2, 'three', undefined, 4])) {
  console.log(report_line);
}

